    const [customAmount, setCustomAmount] = useState('');

    const lastTickRef = useRef(0);
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        const unsub = subscribeToDragonTiger((state) => {
            if (!isMounted.current) return;
            setGameState(state);

            if (state.status === 'LOCKED') {
                setConfirmDrawerOpen(false);
            }

            if (state.status === 'BETTING' && state.timeLeft <= 5 && state.timeLeft > 0 && state.timeLeft !== lastTickRef.current) {
                playSound('tick');
                lastTickRef.current = state.timeLeft;
            }

            if (state.status === 'RESULT' && state.dragonCard && state.tigerCard) {
                if (myBets.length > 0) {
                    processMyResult(state);
                }
            }
        });
        return () => {
            isMounted.current = false;
            unsub();
        };
