        if (betAmount > userBalance) {
            alert("Insufficient Balance!");
            return;
        }

        if(isMounted.current) playSound('click');
        updateBalance(-betAmount, 'BET', 'Dog Road');
        setGameState('PLAYING');
        setCurrentLane(-1);
        setCrashLane(null);
    };

