                <div className="text-center">
                    <h1 className="text-xl font-black italic gold-text tracking-tighter uppercase">DRAGON TIGER</h1>
                </div>
                <div className="flex items-center gap-1.5 bg-slate-900 px-3 py-1 rounded-full border border-yellow-500/30">
                    <Wallet size={12} className="text-yellow-500" />
                    <span className="text-sm font-bold font-mono">₹{userBalance.toFixed(2)}</span>
                </div>
            </div>

            {/* Top History Strip */}
            <div className="bg-black/40 p-2 flex items-center gap-2 overflow-x-auto no-scrollbar border-b border-white/5 relative z-40">
                <History size={14} className="text-yellow-500 shrink-0"/>
                <div className="flex gap-1.5">
                    {gameState.history.map((h, i) => (
                        <span key={i} className={`w-5 h-5 rounded-full flex items-center justify-center text-[9px] font-black border border-white/10 shrink-0 ${h === 'D' ? 'bg-red-600' : h === 'T' ? 'bg-orange-600' : 'bg-green-600'} text-white`}>{h}</span>
                    ))}
                </div>
            </div>

            {/* Stage */}
            <div className="flex-1 bg-gradient-to-b from-[#064e3b] via-[#0a0f1d] to-[#0a0f1d] relative overflow-hidden flex flex-col pt-4">
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-40 w-full pointer-events-none">
                    {gameState.status === 'LOCKED' && (
                        <div className="bg-red-600/90 text-white text-center py-4 font-black text-2xl animate-in zoom-in uppercase tracking-[0.2em] shadow-2xl">BETS LOCKED</div>
                    )}
                </div>

                <div className="flex justify-center z-30">
                    <div className={`w-20 h-20 rounded-full border-4 flex flex-col items-center justify-center font-black shadow-[0_0_30px_rgba(0,0,0,0.6)] relative transition-all duration-300 bg-black/40 backdrop-blur-md ${gameState.status === 'BETTING' ? 'border-green-500 text-green-500' : 'border-red-600 text-red-600 animate-pulse'}`}>
                        <span className="text-[10px] uppercase opacity-60">TIME</span>
                        <span className="text-3xl leading-none font-mono">{gameState.timeLeft}</span>
                    </div>
                </div>

                <div className="flex justify-center items-center gap-10 mt-8 px-4 h-64 relative z-10">
                    {/* DRAGON CARD */}
                    <div className="flex flex-col items-center gap-3">
                        <div className={`relative w-32 h-48 rounded-2xl border-4 transition-all duration-700 perspective-1000 ${showDragon ? 'rotate-y-180 border-red-500 scale-105 shadow-red-500/50' : 'border-white/10 bg-[#1e293b]'}`}>
                           <div className={`absolute inset-0 w-full h-full backface-hidden flex items-center justify-center rounded-xl bg-[#2d3748]`}>
                               <div className="w-16 h-24 border-2 border-white/5 rounded-lg flex items-center justify-center text-4xl opacity-10 font-black">?</div>
                           </div>
                           <div className={`absolute inset-0 w-full h-full backface-hidden rotate-y-180 flex items-center justify-center bg-white rounded-xl`}>
                               <div className="text-6xl font-black text-red-600">{getCardRank(gameState.dragonCard)}</div>
                           </div>
                           <div className="absolute -bottom-5 left-1/2 -translate-x-1/2 bg-red-600 px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest border-2 border-red-400 shadow-xl z-20">DRAGON</div>
                        </div>
                    </div>

                    <div className="text-4xl font-black italic gold-text drop-shadow-2xl animate-pulse z-20">VS</div>

                    {/* TIGER CARD */}
                    <div className="flex flex-col items-center gap-3">
                        <div className={`relative w-32 h-48 rounded-2xl border-4 transition-all duration-700 perspective-1000 ${showTiger ? 'rotate-y-180 border-orange-500 scale-105 shadow-orange-500/50' : 'border-white/10 bg-[#1e293b]'}`}>
                           <div className={`absolute inset-0 w-full h-full backface-hidden flex items-center justify-center rounded-xl bg-[#2d3748]`}>
                               <div className="w-16 h-24 border-2 border-white/5 rounded-lg flex items-center justify-center text-4xl opacity-10 font-black">?</div>
                           </div>
                           <div className={`absolute inset-0 w-full h-full backface-hidden rotate-y-180 flex items-center justify-center bg-white rounded-xl`}>
                               <div className="text-6xl font-black text-black">{getCardRank(gameState.tigerCard)}</div>
                           </div>
