                        <span className="text-[9px] font-black text-slate-400 uppercase mt-1">2.0x</span>
                        {groupedBets['D'] > 0 && (
                            <div className="mt-4 bg-yellow-500 text-black px-4 py-1.5 rounded-full shadow-lg text-[10px] font-black">₹{groupedBets['D']}</div>
                        )}
                    </button>

                    <button 
                        onClick={() => handleTargetClick('Tie')}
                        disabled={gameState.status !== 'BETTING'}
                        className={`h-40 rounded-3xl border-b-[8px] flex flex-col items-center justify-center transition-all active:scale-95 ${gameState.status === 'BETTING' ? 'bg-green-900/40 border-green-700 shadow-2xl' : 'bg-slate-800/40 border-slate-900 opacity-30 grayscale'}`}
                    >
                        <span className="text-xl font-black text-green-500 drop-shadow-lg">TIE</span>
                        <span className="text-[9px] font-black text-slate-400 uppercase mt-1">9.0x</span>
                        {groupedBets['Tie'] > 0 && (
                            <div className="mt-4 bg-yellow-500 text-black px-4 py-1.5 rounded-full shadow-lg text-[10px] font-black">₹{groupedBets['Tie']}</div>
                        )}
                    </button>

                    <button 
                        onClick={() => handleTargetClick('T')}
                        disabled={gameState.status !== 'BETTING'}
                        className={`h-40 rounded-3xl border-b-[8px] flex flex-col items-center justify-center transition-all active:scale-95 ${gameState.status === 'BETTING' ? 'bg-orange-900/40 border-orange-700 shadow-2xl' : 'bg-slate-800/40 border-slate-900 opacity-30 grayscale'}`}
                    >
                        <span className="text-xl font-black text-orange-500 drop-shadow-lg">TIGER</span>
                        <span className="text-[9px] font-black text-slate-400 uppercase mt-1">2.0x</span>
                        {groupedBets['T'] > 0 && (
                            <div className="mt-4 bg-yellow-500 text-black px-4 py-1.5 rounded-full shadow-lg text-[10px] font-black">₹{groupedBets['T']}</div>
                        )}
                    </button>
                </div>

                {/* Aggregated Pending Bets */}
                {Object.keys(groupedBets).length > 0 && gameState.status === 'BETTING' && (
                    <div className="absolute left-0 right-0 bottom-[140px] px-4 flex gap-2 overflow-x-auto no-scrollbar z-40 pb-2">
                        {Object.entries(groupedBets).map(([target, amount]) => (
                            <div key={target} className="bg-black/60 backdrop-blur-md border border-white/10 rounded-2xl p-3 flex items-center gap-4 min-w-[130px] animate-in slide-in-from-left">
                                <div className={`w-2.5 h-2.5 rounded-full ${target === 'D' ? 'bg-red-600' : target === 'T' ? 'bg-orange-600' : 'bg-green-600'}`}></div>
                                <div className="flex-1">
                                    <div className="text-[8px] text-slate-400 uppercase font-bold">{target === 'D' ? 'DRAGON' : target === 'T' ? 'TIGER' : 'TIE'}</div>
                                    <div className="text-xs font-black">₹{amount}</div>
                                </div>
                                <button onClick={() => cancelBet(target)} className="p-1.5 bg-red-600/20 text-red-500 rounded-lg hover:bg-red-500/30 transition-colors"><RotateCcw size={14}/></button>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="bg-[#111827] border-t border-slate-800 p-6 shadow-[0_-20px_50px_rgba(0,0,0,0.8)] relative z-50">
                <div className="flex justify-between items-center gap-3 overflow-x-auto no-scrollbar pb-2">
                    {[10, 50, 100, 500, 1000, 5000].map(chip => (
                        <button 
                            key={chip}
                            onClick={() => setSelectedChip(chip)}
                            className={`flex-shrink-0 w-16 h-16 rounded-full border-4 flex items-center justify-center font-black text-xs transition-all duration-300 ${selectedChip === chip ? 'bg-yellow-500 border-white text-black scale-110 shadow-[0_0_20px_rgba(255,255,255,0.3)] z-10' : 'bg-slate-800 border-slate-700 text-slate-500 hover:text-slate-300'}`}
                        >
                            {chip >= 1000 ? `${chip/1000}K` : chip}
                        </button>
                    ))}
                </div>
            </div>

            {confirmDrawerOpen && (
                <div className="fixed inset-0 z-[100] flex items-end justify-center bg-black/80 backdrop-blur-md p-0">
                    <div className="bg-[#111827] w-full max-w-md rounded-t-[3rem] p-8 border-t border-yellow-500/30 animate-in slide-in-from-bottom duration-300">
                        <div className="flex justify-between items-center mb-8">
                            <div>
                                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Placing Stake</p>
                                <h3 className="text-2xl font-black italic gold-text">Stake on {confirmTarget === 'D' ? 'DRAGON' : confirmTarget === 'T' ? 'TIGER' : 'TIE'}</h3>
                            </div>
                            <button onClick={() => setConfirmDrawerOpen(false)} className="p-3 bg-slate-800 rounded-full"><X size={20}/></button>
                        </div>

                        <div className="space-y-6 mb-8">
                            <div className="grid grid-cols-4 gap-2">
                                {[10, 50, 100, 500].map(amt => (
                                    <button 
                                        key={amt} 
                                        onClick={() => { setConfirmAmount(amt); setCustomAmount(''); }}
                                        className={`py-3 rounded-xl font-black text-xs border transition-all ${confirmAmount === amt && !customAmount ? 'bg-yellow-500 text-black border-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}
                                    >
                                        ₹{amt}
                                    </button>
                                ))}
                            </div>

                            <div className="relative">
                                <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest absolute -top-2 left-4 bg-[#111827] px-2 z-10">Custom Stake</p>
                                <input 
                                    type="number"
                                    placeholder="Enter custom amount"
                                    value={customAmount}
                                    onChange={(e) => {
                                        setCustomAmount(e.target.value);
                                        setConfirmAmount(0);
                                    }}
                                    className="w-full bg-slate-900/50 border border-slate-700 rounded-2xl p-4 text-white font-black text-lg outline-none focus:border-yellow-500 transition-all shadow-inner"
                                />
                            </div>
                        </div>

                        <button 
                            onClick={confirmBetAction}
                            className="w-full py-5 rounded-[1.5rem] bg-gradient-to-r from-yellow-500 to-yellow-600 text-black font-black uppercase tracking-[0.2em] shadow-xl shadow-yellow-900/40 active:scale-95 transition-all"
                        >
                            Confirm Stake ₹{customAmount ? parseFloat(customAmount) : confirmAmount}
                        </button>
                    </div>
                </div>
            )}

            <style>{`
                .rotate-y-180 { transform: rotateY(180deg); }
                .perspective-1000 { perspective: 1000px; }
                .backface-hidden { backface-visibility: hidden; -webkit-backface-visibility: hidden; }
                .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

