import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, History, Loader2, PlayCircle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

interface Ball {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  row: number;
  col: number;
  path: number[]; // 0 for left, 1 for right
  targetSlot: number;
  bet: number;
  status: 'DROPPING' | 'DONE';
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 8;
const PIN_RADIUS = 4;
const BALL_RADIUS = 6;
const SLOT_COUNT = ROWS + 1; // 9 slots for 8 rows

const Plinko: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [balls, setBalls] = useState<Ball[]>([]);
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const requestRef = useRef<number>(0);

  useEffect(() => {
    ballsRef.current = balls;
  }, [balls]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      drawBoard(ctx, canvas.width, canvas.height);
      updateAndDrawBalls(ctx, canvas.width, canvas.height);
      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, []);

  const drawBoard = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
    ctx.clearRect(0, 0, width, height);

    const startY = 60;
    const rowSpacing = 40;
    const colSpacing = 35;

    // Draw Pins
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 3;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (width - rowWidth) / 2;

      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing;
        const py = startY + r * rowSpacing;

        ctx.beginPath();
        ctx.arc(px, py, PIN_RADIUS, 0, Math.PI * 2);
        ctx.fillStyle = '#E0F2FE';
        ctx.shadowBlur = 5;
        ctx.shadowColor = '#38BDF8';
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }

    // Draw Slots
    const slotY = startY + ROWS * rowSpacing + 20;
    const slotWidth = colSpacing - 5;
    const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (width - totalSlotWidth + 5) / 2;

    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      const color = getSlotColor(m);

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 40, 8);
      ctx.fill();

      ctx.fillStyle = m >= 2 ? '#000' : '#fff';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + slotWidth / 2, slotY + 25);
    });
  };

  const getSlotColor = (m: number) => {
    if (m >= 10) return '#ef4444'; // Red
    if (m >= 5) return '#f97316'; // Orange
    if (m >= 2) return '#eab308'; // Yellow
    if (m >= 1) return '#22c55e'; // Green
    return '#3b82f6'; // Blue
  };

  const updateAndDrawBalls = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
    const currentBalls = ballsRef.current;
    if (currentBalls.length === 0) return;

    const startY = 60;
    const rowSpacing = 40;
    const colSpacing = 35;
    const slotY = startY + ROWS * rowSpacing + 20;

    const nextBalls = currentBalls.map(ball => {
      if (ball.status === 'DONE') return ball;

      // Simple physics/path interpolation
      const targetY = startY + ball.row * rowSpacing;
      const pinsInRow = ball.row + 3;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const targetX = ((width - rowWidth) / 2) + ball.col * colSpacing;

      // Move towards target point
      const dx = targetX - ball.x;
      const dy = targetY - ball.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < 5) {
        // Reached a pin
        if (ball.row < ROWS - 1) {
            playSound('tick');
            const direction = Math.random() > 0.5 ? 1 : 0;
            return {
                ...ball,
                row: ball.row + 1,
                col: ball.col + direction,
                x: targetX,
                y: targetY
            };
        } else {
            // Reached the end, heading for slot
            if (ball.y < slotY) {
                return { ...ball, y: ball.y + 4 };
            } else {
                handleBallLand(ball);
                return { ...ball, status: 'DONE' };
            }
        }
      }

      const speed = 4;
      return {
        ...ball,
        x: ball.x + (dx / dist) * speed,
        y: ball.y + (dy / dist) * speed,
      };
    });

    // Cleanup finished balls
    const filtered = nextBalls.filter(b => b.status === 'DROPPING');
    if (filtered.length !== currentBalls.length) {
        ballsRef.current = filtered;
        setBalls(filtered);
    }

    // Draw
    nextBalls.forEach(ball => {
      if (ball.status === 'DONE') return;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#FACC15';
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#FACC15';
      ctx.fill();
      ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    // Calculate final slot based on final col
    // The columns grow: Row 0 has 3 pins, Row 7 has 10 pins.
    // Indexing is tricky, let's map col directly to multiplier array
    const slotIdx = ball.col; 
    const multiplier = MULTIPLIERS[slotIdx] || 1;
    const winAmount = ball.bet * multiplier;

    if (winAmount > 0) {
      updateBalance(winAmount, 'WIN', 'Plinko Win');
      playSound(multiplier >= 1 ? 'win' : 'click');
      onResult({
        win: multiplier >= 1,
        amount: winAmount,
        game: 'Plinko',
        resultDetails: [{ label: 'Multiplier', value: `${multiplier}x` }]
      });
    }
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) {
      alert("Insufficient Balance!");
      return;
    }

    playSound('click');
    updateBalance(-betAmount, 'BET', 'Plinko Stake');

    const newBall: Ball = {
      id: Math.random().toString(36).substr(2, 9),
      x: 180, // Center of 360 wide canvas
      y: 10,
      vx: 0,
      vy: 2,
      row: 0,
      col: 1, // Start middle of first row (3 pins: 0, 1, 2)
      path: [],
      targetSlot: 0,
      bet: betAmount,
      status: 'DROPPING'
    };

    setBalls(prev => [...prev, newBall]);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-yellow-500/20 shadow-2xl relative z-50">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black italic gold-text tracking-tighter uppercase">PLINKO</h1>
        <div className="flex items-center gap-1.5 bg-slate-900 px-3 py-1 rounded-full border border-yellow-500/30">
          <Wallet size={12} className="text-yellow-500" />
          <span className="text-sm font-bold font-mono">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Game Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative bg-gradient-to-b from-[#0f172a] to-[#4c1d95]">
        <canvas 
          ref={canvasRef} 
          width={360} 
          height={450} 
          className="max-w-full rounded-3xl bg-black/20 backdrop-blur-sm border border-white/5 shadow-2xl"
        />

        {/* Drop Button Overlay (Visual hint) */}
        {balls.length === 0 && (
            <div className="absolute top-[10%] animate-bounce opacity-40 flex flex-col items-center pointer-events-none">
                <PlayCircle size={40} className="text-yellow-500 rotate-90" />
                <span className="text-[10px] font-black uppercase tracking-widest mt-2">Drop Here</span>
            </div>
        )}
      </div>

      {/* Controls */}
      <div className="bg-[#111827] border-t border-slate-800 p-6 shadow-[0_-20px_50px_rgba(0,0,0,0.8)] relative z-50">
        <div className="flex justify-between items-center mb-6">
            <div>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Stake Amount</p>
                <div className="text-2xl font-black text-white">₹{betAmount}</div>
            </div>
            <button 
              onClick={() => setMuted(toggleMute())}
              className="p-3 bg-slate-800 rounded-full text-slate-400"
            >
                {muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}
            </button>
        </div>

        <div className="grid grid-cols-4 gap-2 mb-6">
            {[10, 50, 100, 500].map(amt => (
                <button 
                    key={amt} 
                    onClick={() => setBetAmount(amt)}
                    className={`py-3 rounded-xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}
                >
                    ₹{amt}
                </button>
            ))}
        </div>

        <button 
            onClick={dropBall}
