import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, PlayCircle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

interface Ball {
  id: string;
  x: number;
  y: number;
  row: number;
  col: number;
  bet: number;
  status: 'DROPPING' | 'DONE';
  finalSlot: number;
}

// Multipliers: Center 0.5 is index 4. The path leads balls there more often.
const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 8;
const PIN_RADIUS = 4;
const BALL_RADIUS = 7;
const CANVAS_WIDTH = 360;
const CANVAS_HEIGHT = 480;

const Plinko: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [balls, setBalls] = useState<Ball[]>([]);
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const requestRef = useRef<number>(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      cancelAnimationFrame(requestRef.current);
    };
  }, []);

  // Synchronize ref with state for use in the animation frame without closures
  useEffect(() => {
    ballsRef.current = balls;
  }, [balls]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      if (!isMounted.current) return;
      draw(ctx);
      updateBalls();
      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, []);

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const startY = 80;
    const rowSpacing = 40;
    const colSpacing = 34;

    // Draw Pins
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 3;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;

      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing;
        const py = startY + r * rowSpacing;

        ctx.beginPath();
        ctx.arc(px, py, PIN_RADIUS, 0, Math.PI * 2);
        ctx.fillStyle = '#E0F2FE';
        ctx.shadowBlur = 4;
        ctx.shadowColor = '#38BDF8';
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }

    // Draw Slots at bottom
    const slotY = startY + ROWS * rowSpacing + 20;
    const slotWidth = colSpacing - 6;
    const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 6) / 2;

    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      const color = getSlotColor(m);

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 35, 8);
      ctx.fill();

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 9px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + slotWidth / 2, slotY + 22);
    });

    // Draw Active Balls
    ballsRef.current.forEach(ball => {
      if (ball.status === 'DROPPING') {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
        ctx.fillStyle = '#FACC15';
        ctx.shadowBlur = 10;
        ctx.shadowColor = '#FACC15';
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    });
  };

  const getSlotColor = (m: number) => {
    if (m >= 10) return '#ef4444';
    if (m >= 5) return '#f97316';
    if (m >= 2) return '#eab308';
    if (m >= 1) return '#22c55e';
    return '#3b82f6'; // Center slots (0.5x) are blue
  };

  const updateBalls = () => {
    const startY = 80;
    const rowSpacing = 40;
    const colSpacing = 34;
    const slotY = startY + ROWS * rowSpacing + 20;

    let changed = false;
    const nextBalls = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;

      // Calculate the visual target coordinate based on current row and col
      const pinsInRow = ball.row + 3;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;
      const targetX = startX + ball.col * colSpacing;
      const targetY = startY + ball.row * rowSpacing;

      const dx = targetX - ball.x;
      const dy = targetY - ball.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      // Speed of the ball
      const speed = 6;

      if (dist < 5) {
        // Ball has reached a pin
        if (ball.row < ROWS - 1) {
          playSound('tick');
          // House Advantage: Probability of falling towards the middle (0.5x slot)
          // Binomial walk: naturally tends to center. 
          // At each step, choice is 0 (left) or 1 (right). 
          const moveRight = Math.random() > 0.5 ? 1 : 0;
          return {
            ...ball,
            row: ball.row + 1,
            col: ball.col + moveRight,
            x: targetX,
            y: targetY
          };
        } else {
          // Reached the last row, move into slot
          if (ball.y < slotY) {
             return { ...ball, y: ball.y + speed };
          } else {
             // Landed!
             changed = true;
             handleBallLand(ball);
             return { ...ball, status: 'DONE' };
          }
        }
      }

      // Linear interpolation for movement towards target
      return {
        ...ball,
        x: ball.x + (dx / dist) * speed,
        y: ball.y + (dy / dist) * speed,
      };
    });

    const activeBalls = nextBalls.filter(b => b.status === 'DROPPING');
    if (activeBalls.length !== ballsRef.current.length || changed) {
       ballsRef.current = activeBalls;
       setBalls(activeBalls);
    }
  };

  const handleBallLand = (ball: Ball) => {
    // Final slot index is equivalent to the final column index reached in last row
    // Row 0 has col range 0..2. Row 7 (last row) has col range 0..9.
    // However, our multipliers are 9. Let's clamp or align correctly.
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;

    if (winAmount >= ball.bet) {
      updateBalance(winAmount, 'WIN', 'Plinko Win');
      playSound('win');
      onResult({
        win: true,
        amount: winAmount,
        game: 'Plinko',
        resultDetails: [{ label: 'Multiplier', value: `${multiplier}x` }]
      });
    } else {
      // 0.5x case or lower: considered a loss of portion of stake
      playSound('loss');
      updateBalance(winAmount, 'WIN', 'Plinko Small Win'); // Still add the remaining amount back
      onResult({
        win: false,
        amount: ball.bet, // Display the original bet as lost/staked in the loss popup
        game: 'Plinko',
        resultDetails: [{ label: 'Returned', value: `₹${winAmount.toFixed(2)} (${multiplier}x)` }]
      });
    }
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) {
      alert("Insufficient Balance!");
      return;
    }

    playSound('click');
    updateBalance(-betAmount, 'BET', 'Plinko Stake');

    const newBall: Ball = {
      id: Math.random().toString(36).substr(2, 9),
      x: CANVAS_WIDTH / 2, // Start at horizontal center
      y: 20, // Start above the pins
      row: 0,
      col: 1, // Start middle pin of row 0 (which has 3 pins: 0, 1, 2)
      bet: betAmount,
      status: 'DROPPING',
      finalSlot: 0
    };

    setBalls(prev => [...prev, newBall]);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-yellow-500/20 shadow-2xl relative z-50">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black italic gold-text tracking-tighter uppercase">PLINKO</h1>
        <div className="flex items-center gap-1.5 bg-slate-900 px-3 py-1 rounded-full border border-yellow-500/30">
          <Wallet size={12} className="text-yellow-500" />
          <span className="text-sm font-bold font-mono">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 relative bg-gradient-to-b from-[#0f172a] to-[#4c1d95]">
        <canvas 
          ref={canvasRef} 
          width={CANVAS_WIDTH} 
          height={CANVAS_HEIGHT} 
          className="max-w-full rounded-3xl bg-black/20 backdrop-blur-sm border border-white/5 shadow-2xl"
        />

        {balls.length === 0 && (
            <div className="absolute top-[10%] animate-bounce opacity-40 flex flex-col items-center pointer-events-none">
                <PlayCircle size={40} className="text-yellow-500 rotate-90" />
                <span className="text-[10px] font-black uppercase tracking-widest mt-2 text-yellow-500">Tap Drop Ball</span>
            </div>
        )}
      </div>

      <div className="bg-[#111827] border-t border-slate-800 p-6 shadow-[0_-20px_50px_rgba(0,0,0,0.8)] relative z-50">
        <div className="flex justify-between items-center mb-6">
            <div>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Stake Amount</p>
                <div className="text-2xl font-black text-white">₹{betAmount}</div>
            </div>
            <button 
              onClick={() => setMuted(toggleMute())}
              className="p-3 bg-slate-800 rounded-full text-slate-400"
            >
                {muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}
            </button>
        </div>

        <div className="grid grid-cols-4 gap-2 mb-6">
            {[10, 50, 100, 500].map(amt => (
                <button 
                    key={amt} 
                    onClick={() => setBetAmount(amt)}
                    className={`py-3 rounded-xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}
                >
                    ₹{amt}
                </button>
            ))}
        </div>

        <button 
            onClick={dropBall}
            className="w-full py-5 rounded-[1.5rem] bg-gradient-to-r from-yellow-500 to-yellow-600 text-black font-black uppercase tracking-[0.2em] shadow-xl shadow-yellow-900/40 active:scale-95 transition-all flex items-center justify-center gap-3"
        >
            <PlayCircle size={24} />
            Drop Ball
        </button>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
      `}</style>
    </div>
  );
};

