import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, PlayCircle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

interface Ball {
  id: string;
  x: number;
  y: number;
  row: number; // Current row (0 to ROWS-1)
  col: number; // Current column in that row
  bet: number;
  status: 'DROPPING' | 'DONE';
  targetX: number;
  targetY: number;
  isMovingToTarget: boolean;
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 8;
const PIN_RADIUS = 4;
const BALL_RADIUS = 7;
const CANVAS_WIDTH = 360;
const CANVAS_HEIGHT = 500;

const Plinko: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const requestRef = useRef<number>(0);
  const [activeBallCount, setActiveBallCount] = useState(0);

  // Constants for layout
  const startY = 80;
  const rowSpacing = 42;
  const colSpacing = 34;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      updatePhysics();
      draw(ctx);
      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, []);

  const getPinCoords = (row: number, col: number) => {
    const pinsInRow = row + 3;
    const rowWidth = (pinsInRow - 1) * colSpacing;
    const startX = (CANVAS_WIDTH - rowWidth) / 2;
    return {
      x: startX + col * colSpacing,
      y: startY + row * rowSpacing
    };
  };

  const updatePhysics = () => {
    const slotY = startY + ROWS * rowSpacing + 25;

    ballsRef.current = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;

      // Move ball toward its current targetX, targetY
      const dx = ball.targetX - ball.x;
      const dy = ball.targetY - ball.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      // Speed - slow and deliberate for realistic feel
      const speed = 4.5;

      if (distance < speed) {
        // Reached the current target (a pin)
        ball.x = ball.targetX;
        ball.y = ball.targetY;

        if (ball.row < ROWS - 1) {
          // Determine next target pin in the next row
          playSound('tick');
          const nextRow = ball.row + 1;
          // Normal Plinko uses a binomial distribution (50/50 left/right)
          // We add a slight bias to center to favor the 0.5x multipliers
          const bias = 0.5; 
          const moveRight = Math.random() > bias ? 1 : 0;
          const nextCol = ball.col + moveRight;
          const coords = getPinCoords(nextRow, nextCol);

          return {
            ...ball,
            row: nextRow,
            col: nextCol,
            targetX: coords.x,
            targetY: coords.y
          };
        } else {
          // Reached the last row of pins, now head to the slot
          if (ball.y < slotY) {
            return {
              ...ball,
              targetY: slotY + 10,
              targetX: ball.x // Drop straight down into slot
            };
          } else {
            // Landed in slot!
            handleBallLand(ball);
            return { ...ball, status: 'DONE' };
          }
        }
      }

      // Smooth movement
      const velX = (dx / distance) * speed;
      const velY = (dy / distance) * speed;

      return {
        ...ball,
        x: ball.x + velX,
        y: ball.y + velY
      };
    }).filter(b => b.status === 'DROPPING');

    if (ballsRef.current.length !== activeBallCount) {
      setActiveBallCount(ballsRef.current.length);
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // 1. Draw Pins
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 3;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;

      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing;
        const py = startY + r * rowSpacing;

        ctx.beginPath();
        ctx.arc(px, py, PIN_RADIUS, 0, Math.PI * 2);
        ctx.fillStyle = '#E0F2FE';
        ctx.shadowBlur = 6;
        ctx.shadowColor = '#38BDF8';
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }

    // 2. Draw Slots
    const slotY = startY + ROWS * rowSpacing + 25;
    const slotWidth = colSpacing - 6;
    const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 6) / 2;

    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      const color = m >= 2 ? '#ef4444' : m >= 1 ? '#22c55e' : '#3b82f6';

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 35, 8);
      ctx.fill();

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 10px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + slotWidth / 2, slotY + 22);
    });

    // 3. Draw Active Balls
    ballsRef.current.forEach(ball => {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#FACC15'; // Bright Yellow
      ctx.shadowBlur = 12;
      ctx.shadowColor = '#FACC15';
      ctx.fill();

      // Ball Shine
      ctx.beginPath();
      ctx.arc(ball.x - 2, ball.y - 2, 2, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.8)';
      ctx.fill();

      ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;

    if (multiplier >= 1) {
      updateBalance(winAmount, 'WIN', 'Plinko Win');
      playSound('win');
      onResult({
        win: true,
        amount: winAmount,
        game: 'Plinko',
        resultDetails: [{ label: 'Multiplier', value: `${multiplier}x` }]
      });
    } else {
      // Small Return / House Win
      updateBalance(winAmount, 'WIN', 'Plinko Small Return');
      playSound('loss');
      onResult({
        win: false,
        amount: ball.bet,
        game: 'Plinko',
        resultDetails: [{ label: 'Returned', value: `₹${winAmount.toFixed(2)} (${multiplier}x)` }]
      });
    }
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) {
      alert("Insufficient Balance!");
      return;
    }

    playSound('click');
    updateBalance(-betAmount, 'BET', 'Plinko Stake');

    // Initial position above the first row center pin
    const startCoords = getPinCoords(0, 1);

    const newBall: Ball = {
      id: Math.random().toString(36).substr(2, 9),
      x: CANVAS_WIDTH / 2,
      y: 10,
      row: 0,
      col: 1, // Start at the center pin of the first row (which has 3 pins: 0, 1, 2)
      bet: betAmount,
      status: 'DROPPING',
      targetX: startCoords.x,
      targetY: startCoords.y,
      isMovingToTarget: true
    };

    ballsRef.current.push(newBall);
    setActiveBallCount(ballsRef.current.length);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-yellow-500/20 shadow-2xl relative z-50">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors active:scale-90"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black italic gold-text tracking-tighter uppercase">PLINKO</h1>
        <div className="flex items-center gap-1.5 bg-slate-900 px-3 py-1 rounded-full border border-yellow-500/30">
          <Wallet size={12} className="text-yellow-500" />
          <span className="text-sm font-bold font-mono">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 relative bg-gradient-to-b from-[#0f172a] to-[#4c1d95]">
        <canvas 
          ref={canvasRef} 
          width={CANVAS_WIDTH} 
          height={CANVAS_HEIGHT} 
          className="max-w-full rounded-3xl bg-black/30 backdrop-blur-md border border-white/10 shadow-2xl"
        />

        {activeBallCount === 0 && (
            <div className="absolute top-[10%] animate-bounce opacity-50 flex flex-col items-center pointer-events-none">
                <PlayCircle size={40} className="text-yellow-500 rotate-90" />
                <span className="text-[10px] font-black uppercase tracking-widest mt-2 text-yellow-500">Tap to Drop</span>
            </div>
        )}
      </div>

      <div className="bg-[#111827] border-t border-slate-800 p-6 shadow-[0_-20px_50px_rgba(0,0,0,0.8)] relative z-50">
        <div className="flex justify-between items-center mb-6">
            <div>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Stake Amount</p>
                <div className="text-2xl font-black text-white">₹{betAmount}</div>
            </div>
            <button 
              onClick={() => setMuted(toggleMute())}
              className="p-3 bg-slate-800 rounded-full text-slate-400 active:scale-90"
            >
                {muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}
            </button>
        </div>

        <div className="grid grid-cols-4 gap-2 mb-6">
            {[10, 50, 100, 500].map(amt => (
                <button 
                    key={amt} 
                    onClick={() => setBetAmount(amt)}
                    className={`py-3 rounded-xl font-black text-xs border transition-all active:scale-95 ${betAmount === amt ? 'bg-yellow-500 text-black border-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-400'}`}
                >
                    ₹{amt}
                </button>
            ))}
        </div>

        <button 
            onClick={dropBall}
            className="w-full py-5 rounded-[1.5rem] bg-gradient-to-r from-yellow-500 to-yellow-600 text-black font-black uppercase tracking-[0.2em] shadow-xl shadow-yellow-900/40 active:scale-95 transition-all flex items-center justify-center gap-3"
        >
            <PlayCircle size={24} />
            Drop Ball
        </button>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
      `}</style>
    </div>
  );
};

export default Plinko;

