import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, PlayCircle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

interface Ball {
  id: string;
  x: number;
  y: number;
  row: number;
  col: number;
  bet: number;
  status: 'DROPPING' | 'DONE';
  targetX: number;
  targetY: number;
  progress: number; // 0 to 1 for the current arc movement
  startPos: { x: number; y: number };
}

interface PinPulse {
  row: number;
  col: number;
  startTime: number;
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 8;
const PIN_RADIUS = 5;
const BALL_RADIUS = 8;
const CANVAS_WIDTH = 380;
const CANVAS_HEIGHT = 520;

const Plinko: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const pulsesRef = useRef<PinPulse[]>([]);
  const requestRef = useRef<number>(0);
  const [activeBallCount, setActiveBallCount] = useState(0);

  // Constants for layout
  const startY = 90;
  const rowSpacing = 45;
  const colSpacing = 36;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      updatePhysics();
      draw(ctx);
      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, []);

  const getPinCoords = (row: number, col: number) => {
    // Triangular arrangement: Row 0 has 1 pin, Row 1 has 2 pins...
    const pinsInRow = row + 1;
    const rowWidth = (pinsInRow - 1) * colSpacing;
    const startX = (CANVAS_WIDTH - rowWidth) / 2;
    return {
      x: startX + col * colSpacing,
      y: startY + row * rowSpacing
    };
  };

  const updatePhysics = () => {
    const slotY = startY + ROWS * rowSpacing + 30;
    const speed = 0.035; // Lower = Slower/Smoother movement

    ballsRef.current = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;

      ball.progress += speed;

      if (ball.progress >= 1) {
        // Ball reached its current target (a pin collision point)
        ball.x = ball.targetX;
        ball.y = ball.targetY;
        ball.progress = 0;
        ball.startPos = { x: ball.x, y: ball.y };

        if (ball.row < ROWS - 1) {
          // Trigger pin animation
          pulsesRef.current.push({ row: ball.row, col: ball.col, startTime: Date.now() });
          playSound('tick');

          const nextRow = ball.row + 1;
          // Probability: slight bias to center (0.5x slot)
          const moveRight = Math.random() > 0.48 ? 1 : 0;
          const nextCol = ball.col + moveRight;
          const coords = getPinCoords(nextRow, nextCol);

          return {
            ...ball,
            row: nextRow,
            col: nextCol,
            targetX: coords.x,
            targetY: coords.y
          };
        } else {
          // Final leg: drop to slot
          if (ball.y < slotY) {
            return {
              ...ball,
              targetY: slotY + 15,
              targetX: ball.x 
            };
          } else {
            handleBallLand(ball);
            return { ...ball, status: 'DONE' };
          }
        }
      }

      // Parabolic Arc movement for high-quality feel
      const t = ball.progress;
      const arcHeight = 15; // Vertical "bounce" height

      // Linear X interpolation
      ball.x = ball.startPos.x + (ball.targetX - ball.startPos.x) * t;

      // Vertical movement with a slight parabolic "bump" when hitting pins
      const linearY = ball.startPos.y + (ball.targetY - ball.startPos.y) * t;
      // Parabolic offset: -4 * h * t * (t - 1)
      const offset = -4 * arcHeight * t * (t - 1);
      ball.y = linearY - offset;

      return ball;
    }).filter(b => b.status === 'DROPPING');

    // Clean up old pulses
    pulsesRef.current = pulsesRef.current.filter(p => Date.now() - p.startTime < 500);

    if (ballsRef.current.length !== activeBallCount) {
      setActiveBallCount(ballsRef.current.length);
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // 1. Draw Pins (Galton Board Style)
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 1;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;

      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing;
        const py = startY + r * rowSpacing;

        // Check for pulse animation
        const pulse = pulsesRef.current.find(pulse => pulse.row === r && pulse.col === p);
        const scale = pulse ? 1 + 0.5 * Math.sin((Date.now() - pulse.startTime) / 50) : 1;
        const alpha = pulse ? 1 : 0.6;

        ctx.beginPath();
        ctx.arc(px, py, PIN_RADIUS * scale, 0, Math.PI * 2);
        ctx.fillStyle = pulse ? '#38BDF8' : '#E0F2FE';
        ctx.globalAlpha = alpha;
        ctx.shadowBlur = pulse ? 15 : 4;
        ctx.shadowColor = '#38BDF8';
        ctx.fill();
        ctx.globalAlpha = 1;
        ctx.shadowBlur = 0;
      }
    }

    // 2. Draw Multiplier Slots
    const slotY = startY + ROWS * rowSpacing + 30;
    const slotWidth = colSpacing - 6;
    const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 6) / 2;

    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      const color = m >= 5 ? '#ef4444' : m >= 1.2 ? '#f97316' : m >= 1 ? '#22c55e' : '#3b82f6';

      // Shadow for slot
      ctx.shadowBlur = 10;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 40, 10);
      ctx.fill();

      ctx.shadowBlur = 0;

      // Text inside slot
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + slotWidth / 2, slotY + 25);
    });

    // 3. Draw Active Balls (High Quality Glow)
    ballsRef.current.forEach(ball => {
      // Glow trail/halo
      const grad = ctx.createRadialGradient(ball.x, ball.y, 0, ball.x, ball.y, BALL_RADIUS * 2.5);
      grad.addColorStop(0, 'rgba(250, 204, 21, 0.4)');
      grad.addColorStop(1, 'rgba(250, 204, 21, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS * 2.5, 0, Math.PI * 2);
      ctx.fill();

      // Main Ball
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#FACC15'; 
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#FACC15';
      ctx.fill();

      // High-quality shine
      ctx.beginPath();
      ctx.arc(ball.x - 3, ball.y - 3, 2.5, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.fill();

      ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;

    // Logic: 0.5x (Loss cases) should not show big popup, just update balance
    if (multiplier >= 1) {
      updateBalance(winAmount, 'WIN', 'Plinko Win');
      playSound('win');
      onResult({
        win: true,
        amount: winAmount,
        game: 'Plinko',
        resultDetails: [{ label: 'Multiplier', value: `${multiplier}x` }]
      });
    } else {
      // User said: "Koi perform nahin aaega utna hi amount milega and vah loss nahin hoga"
      // Partial Return (0.5x case) - Silent update, no loss popup
      updateBalance(winAmount, 'WIN', 'Plinko Partial Return');
      playSound('click');
      // We skip onResult() to avoid the "Better Luck Next Time" popup
    }
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) {
        alert("Insufficient Balance!");
        return;
    }

    playSound('click');
    updateBalance(-betAmount, 'BET', 'Plinko Stake');

    // Start above the first pin
    const startCoords = getPinCoords(0, 0);

    const newBall: Ball = {
      id: Math.random().toString(36).substr(2, 9),
      x: CANVAS_WIDTH / 2,
      y: 20,
      row: 0,
      col: 0, 
      bet: betAmount,
      status: 'DROPPING',
      targetX: startCoords.x,
      targetY: startCoords.y,
      progress: 0,
      startPos: { x: CANVAS_WIDTH / 2, y: 20 }
    };

    ballsRef.current.push(newBall);
    setActiveBallCount(ballsRef.current.length);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      {/* Premium Header */}
      <div className="p-4 flex justify-between items-center bg-[#111827]/80 backdrop-blur-xl border-b border-white/10 shadow-2xl relative z-50">
        <button onClick={onBack} className="p-2.5 bg-slate-800/50 rounded-2xl hover:bg-slate-700 transition-all active:scale-90 border border-white/5"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">PLINKO</h1>
            <p className="text-[8px] text-slate-500 font-bold uppercase tracking-[0.4em]">Elite Series</p>
        </div>
        <div className="flex items-center gap-2 bg-black/40 px-4 py-1.5 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* High Quality Game Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative bg-gradient-to-b from-[#0f172a] via-[#1e1b4b] to-[#0a0f1d]">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10 pointer-events-none"></div>

        <div className="relative group">
            {/* Ambient Background Glow */}
            <div className="absolute -inset-10 bg-blue-500/10 blur-[60px] rounded-full pointer-events-none"></div>

            <canvas 
              ref={canvasRef} 
              width={CANVAS_WIDTH} 
              height={CANVAS_HEIGHT} 
              className="max-w-full rounded-[2.5rem] bg-[#0f172a]/60 backdrop-blur-2xl border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.5)]"
            />

            {activeBallCount === 0 && (
                <div className="absolute top-[8%] left-1/2 -translate-x-1/2 animate-bounce opacity-40 flex flex-col items-center pointer-events-none">
                    <div className="w-12 h-12 bg-yellow-500/20 rounded-full flex items-center justify-center border border-yellow-500/30">
                        <PlayCircle size={32} className="text-yellow-500 rotate-90" />
                    </div>
                    <span className="text-[9px] font-black uppercase tracking-[0.3em] mt-3 text-yellow-500/80">Ready to Drop</span>
                </div>
            )}
        </div>
      </div>

      {/* Betting Panel */}
      <div className="bg-[#111827] border-t border-white/5 p-6 shadow-[0_-20px_60px_rgba(0,0,0,0.9)] relative z-50">
        <div className="flex justify-between items-end mb-6 px-2">
            <div>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mb-2">Stake Select</p>
                <div className="text-3xl font-black text-white italic tracking-tighter">₹{betAmount}</div>
            </div>
            <button 
              onClick={() => setMuted(toggleMute())}
              className="p-3.5 bg-slate-800/50 rounded-2xl text-slate-400 active:scale-90 transition-all border border-white/5"
            >
                {muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}
            </button>
        </div>

        <div className="grid grid-cols-4 gap-3 mb-8">
            {[10, 50, 100, 500].map(amt => (
                <button 
                    key={amt} 
                    onClick={() => setBetAmount(amt)}
                    className={`py-4 rounded-2xl font-black text-xs border transition-all duration-300 active:scale-95 ${betAmount === amt ? 'bg-yellow-500 text-slate-950 border-white shadow-[0_0_20px_rgba(234,179,8,0.4)]' : 'bg-slate-800/40 border-white/5 text-slate-400 hover:border-white/10'}`}
                >
                    ₹{amt}
                </button>
            ))}
        </div>

        <button 
            onClick={dropBall}
            className="w-full py-6 rounded-[2rem] bg-gradient-to-r from-yellow-500 via-orange-500 to-yellow-600 text-slate-950 font-black uppercase tracking-[0.3em] shadow-2xl shadow-yellow-900/40 active:scale-95 transition-all flex items-center justify-center gap-4 text-lg border-t-2 border-white/20"
        >
            <PlayCircle size={26} className="fill-slate-950/20" />
            DROP BALL
        </button>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
      `}</style>
    </div>
  );
};

export default Plinko;

