export default DragonTiger;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, PlayCircle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

interface Ball {
  id: string;
  x: number;
  y: number;
  row: number;
  col: number;
  bet: number;
  status: 'DROPPING' | 'DONE';
  targetX: number;
  targetY: number;
  progress: number;
  startPos: { x: number; y: number };
}

interface PinPulse {
  row: number;
  col: number;
  startTime: number;
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 8;
const PIN_RADIUS = 5;
const BALL_RADIUS = 8;
const CANVAS_WIDTH = 380;
const CANVAS_HEIGHT = 520;

const Plinko: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const pulsesRef = useRef<PinPulse[]>([]);
  const requestRef = useRef<number>(0);
  const [activeBallCount, setActiveBallCount] = useState(0);

  // Constants for layout
  const startY = 100;
  const rowSpacing = 42;
  const colSpacing = 36;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      updatePhysics();
      draw(ctx);
      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, []);

  const getPinCoords = (row: number, col: number) => {
    const pinsInRow = row + 1;
    const rowWidth = (pinsInRow - 1) * colSpacing;
    const startX = (CANVAS_WIDTH - rowWidth) / 2;
    return {
      x: startX + col * colSpacing,
      y: startY + row * rowSpacing
    };
  };

  const updatePhysics = () => {
    // Corrected Slot Y position for collision
    const slotY = startY + ROWS * rowSpacing + 30;
    const speed = 0.038;

    ballsRef.current = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;

      ball.progress += speed;

      if (ball.progress >= 1) {
        ball.x = ball.targetX;
        ball.y = ball.targetY;
        ball.progress = 0;
        ball.startPos = { x: ball.x, y: ball.y };

        if (ball.row < ROWS - 1) {
          pulsesRef.current.push({ row: ball.row, col: ball.col, startTime: Date.now() });
          playSound('tick');

          const nextRow = ball.row + 1;
          const moveRight = Math.random() > 0.49 ? 1 : 0;
          const nextCol = ball.col + moveRight;
          const coords = getPinCoords(nextRow, nextCol);

          return {
            ...ball,
            row: nextRow,
            col: nextCol,
            targetX: coords.x,
            targetY: coords.y
          };
        } else {
          // Detect landing in slot accurately
          if (ball.y < slotY) {
            return {
              ...ball,
              targetY: slotY + 20, // Move ball deep into slot
              targetX: ball.x 
            };
          } else {
            handleBallLand(ball);
            return { ...ball, status: 'DONE' };
          }
        }
      }

      const t = ball.progress;
      const arcHeight = 12; 
      ball.x = ball.startPos.x + (ball.targetX - ball.startPos.x) * t;
      const linearY = ball.startPos.y + (ball.targetY - ball.startPos.y) * t;
      const offset = -4 * arcHeight * t * (t - 1);
      ball.y = linearY - offset;

      return ball;
    }).filter(b => b.status === 'DROPPING');

    pulsesRef.current = pulsesRef.current.filter(p => Date.now() - p.startTime < 500);

    if (ballsRef.current.length !== activeBallCount) {
      setActiveBallCount(ballsRef.current.length);
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // 1. Draw Glassmorphism Board Outline
    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(10, 80, CANVAS_WIDTH - 20, CANVAS_HEIGHT - 100, 40);
    ctx.stroke();

    // 2. Draw Pins
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 1;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;

      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing;
        const py = startY + r * rowSpacing;

        const pulse = pulsesRef.current.find(pulse => pulse.row === r && pulse.col === p);
        const scale = pulse ? 1 + 0.4 * Math.sin((Date.now() - pulse.startTime) / 40) : 1;

        ctx.beginPath();
        ctx.arc(px, py, PIN_RADIUS * scale, 0, Math.PI * 2);
        ctx.fillStyle = pulse ? '#60A5FA' : '#cbd5e1';
        ctx.shadowBlur = pulse ? 20 : 0;
        ctx.shadowColor = '#60A5FA';
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }

    // 3. Draw Slots (Bottom Objects)
    const slotY = startY + ROWS * rowSpacing + 30;
    const slotWidth = colSpacing - 6;
    const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 6) / 2;

    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      const color = m >= 5 ? '#ef4444' : m >= 1.2 ? '#f97316' : m >= 1 ? '#22c55e' : '#3b82f6';

      // Slot shadow for depth
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath();
      ctx.roundRect(sx + 3, slotY + 3, slotWidth, 45, 12);
      ctx.fill();

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 45, 12);
      ctx.fill();

      // Slot Shine
      ctx.fillStyle = 'rgba(255,255,255,0.1)';
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 15, 12);
      ctx.fill();

      ctx.fillStyle = '#fff';
      ctx.font = 'black 14px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + slotWidth / 2, slotY + 28);
    });

    // 4. Draw Active Balls
    ballsRef.current.forEach(ball => {
      // Outer Glow
      const grad = ctx.createRadialGradient(ball.x, ball.y, 0, ball.x, ball.y, BALL_RADIUS * 2.5);
      grad.addColorStop(0, 'rgba(251, 191, 36, 0.5)');
      grad.addColorStop(1, 'rgba(251, 191, 36, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS * 2.5, 0, Math.PI * 2);
      ctx.fill();

      // Main Ball
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#fbbf24'; 
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#f59e0b';
      ctx.fill();

      // Inner Shine
      ctx.beginPath();
      ctx.arc(ball.x - 3, ball.y - 3, 2.5, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.8)';
      ctx.fill();

      ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;

    if (multiplier >= 1) {
      updateBalance(winAmount, 'WIN', 'Plinko Win');
      playSound('win');
      onResult({
        win: true,
        amount: winAmount,
        game: 'Plinko',
        resultDetails: [{ label: 'Win X', value: `${multiplier}x` }]
      });
    } else {
      updateBalance(winAmount, 'WIN', 'Plinko Return');
      playSound('click');
      // Returns balance but no win popup for 0.5x
    }
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) {
        alert("Insufficient Balance!");
        return;
    }

    playSound('click');
    updateBalance(-betAmount, 'BET', 'Plinko Stake');

