import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Coins, Volume2, VolumeX, ArrowDown } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface VortexProps {
    onBack: () => void;
    userBalance: number;
    onResult: (result: GameResult) => void;
}

const SEGMENTS = [
    { label: '50X', value: 50, bg: '#E11D48', text: 'white' },
    { label: 'LOSE', value: 0, bg: '#1E293B', text: '#94A3B8' }, 
    { label: '2X', value: 2, bg: '#F59E0B', text: 'black' },
    { label: 'LOSE', value: 0, bg: '#1E293B', text: '#94A3B8' },
    { label: '10X', value: 10, bg: '#10B981', text: 'white' },
    { label: 'LOSE', value: 0, bg: '#1E293B', text: '#94A3B8' },
    { label: '5X', value: 5, bg: '#3B82F6', text: 'white' },
    { label: 'LOSE', value: 0, bg: '#1E293B', text: '#94A3B8' },
];

const Spinner: React.FC<VortexProps> = ({ onBack, userBalance, onResult }) => {
    const [betAmount, setBetAmount] = useState(10);
    const [isSpinning, setIsSpinning] = useState(false);
    const [rotation, setRotation] = useState(0); 
    const [muted, setMuted] = useState(getMuteStatus());
    const [lastWinIndex, setLastWinIndex] = useState<number | null>(null);

    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        return () => {
            isMounted.current = false;
            stopAllSounds();
        };
    }, []);

    const startSpin = () => {
        if (isSpinning) return;
        if (betAmount > userBalance) {
            alert("Insufficient Balance");
            return;
        }

        playSound('click');
        playSound('spin'); 
        updateBalance(-betAmount, 'BET', 'Lucky Spin');
        setIsSpinning(true);
        setLastWinIndex(null);

        const rand = Math.random();
        let targetIndex = 0;

        if (rand < 0.5) { 
             const loseIndices = [1, 3, 5, 7];
             targetIndex = loseIndices[Math.floor(Math.random() * loseIndices.length)];
        } else if (rand < 0.8) { 
             targetIndex = 2;
        } else if (rand < 0.9) { 
             targetIndex = 6;
        } else if (rand < 0.98) { 
             targetIndex = 4;
        } else { 
             targetIndex = 0;
        }

        const segmentAngle = 360 / SEGMENTS.length;
        const spins = 5; 
        const currentRot = rotation;
        const minSpin = 360 * spins;
        const targetAngle = -(targetIndex * segmentAngle); 

        const nextRot = Math.floor((currentRot - minSpin - targetAngle) / 360) * 360 + targetAngle;
        setRotation(nextRot);

        setTimeout(() => {
            if (!isMounted.current) return;
            setIsSpinning(false);
            stopAllSounds();
            handleResult(SEGMENTS[targetIndex]);
            setLastWinIndex(targetIndex);
        }, 4000); 
    };

    const handleResult = (segment: typeof SEGMENTS[0]) => {
        if (!isMounted.current) return;
        const winAmount = betAmount * segment.value;
        if (winAmount > 0) {
            playSound('win');
            updateBalance(winAmount, 'WIN', 'Wheel Win');
            onResult({
                win: true,
                amount: winAmount,
                game: 'Lucky Spin',
                resultDetails: [{ label: 'Multiplier', value: segment.label, color: 'bg-green-500' }]
            });
            addGameHistory('Lucky Spin', betAmount, winAmount, `Hit ${segment.label}`);
        } else {
            playSound('loss');
            onResult({
                win: false,
                amount: betAmount,
                game: 'Lucky Spin',
                resultDetails: [{ label: 'Result', value: 'Loss', color: 'bg-red-500' }]
            });
            addGameHistory('Lucky Spin', betAmount, 0, `Hit Lose`);
        }
    };

    return (
        <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white overflow-hidden relative">
             <div className="p-4 flex items-center justify-between z-10 bg-[#111827] border-b border-white/5 shadow-2xl relative">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="p-2 bg-slate-800 rounded-2xl active:scale-90 transition-all"><ArrowLeft className="text-white" /></button>
                    <h1 className="text-xl font-black italic tracking-widest uppercase gold-text">VORTEX <span className="text-purple-400">SPIN</span></h1>
                </div>
                <div className="flex items-center gap-3">
                     <div className="flex items-center gap-2 bg-black/40 px-3 py-1 rounded-2xl border border-yellow-500/20">
                         <Coins size={14} className="text-yellow-500"/>
                         <span className="text-sm font-black text-white">₹{userBalance.toFixed(2)}</span>
                    </div>
                    <button onClick={() => setMuted(toggleMute())} className="p-2 bg-slate-800 rounded-2xl">
                        {muted ? <VolumeX size={20} className="text-slate-400"/> : <Volume2 size={20} className="text-slate-400"/>}
                    </button>
                </div>
            </div>

            <div className="flex-1 flex flex-col items-center justify-center relative">
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(139,92,246,0.1)_0%,_transparent_70%)] pointer-events-none"></div>

                <div className="absolute top-[50%] left-1/2 -translate-x-1/2 z-40 mt-[-195px] md:mt-[-225px] filter drop-shadow-2xl pointer-events-none animate-bounce">
                     <ArrowDown size={64} className="text-yellow-500 fill-yellow-500 stroke-[4px] stroke-black"/>
                </div>

                <div className="relative w-[320px] h-[320px] md:w-[380px] md:h-[380px] rounded-full p-6 bg-gradient-to-b from-[#fde68a] via-[#ca8a04] to-[#fde68a] shadow-[0_0_80px_rgba(234,179,8,0.2)] flex items-center justify-center">
                    <div className="absolute inset-0 rounded-full border-[12px] border-black/40"></div>

                    <div className="relative w-full h-full rounded-full bg-black overflow-hidden border-[6px] border-black shadow-inner">
                        <div 
                            className="w-full h-full rounded-full"
                            style={{ 
                                transform: `rotate(${rotation}deg)`,
                                transition: isSpinning ? 'transform 4s cubic-bezier(0.15, 0, 0.15, 1)' : 'none'
                            }}
                        >
                            <div 
                                className="absolute inset-0 w-full h-full rounded-full"
                                style={{
                                    background: `conic-gradient(from -22.5deg,
                                        ${SEGMENTS.map((s, i) => `${s.bg} ${i * 45}deg ${(i + 1) * 45}deg`).join(', ')}
                                    )`
                                }}
                            ></div>

                            {SEGMENTS.map((seg, i) => {
                                const angle = 360 / SEGMENTS.length;
                                const rotationAngle = angle * i;
                                return (
                                    <div 
                                        key={i}
                                        className="absolute w-full h-full top-0 left-0 flex justify-center pt-8"
                                        style={{ transform: `rotate(${rotationAngle}deg)` }}
                                    >
                                        <div className="text-center transform origin-bottom">
                                            <span 
                                                className="block font-black text-2xl md:text-3xl drop-shadow-2xl tracking-tighter"
                                                style={{ color: seg.text }}
                                            >
                                                {seg.label}
                                            </span>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    </div>

                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-24 bg-gradient-to-br from-yellow-300 via-orange-500 to-yellow-600 rounded-full border-4 border-black shadow-[0_0_30px_rgba(0,0,0,0.8)] flex items-center justify-center z-20">
                        <div className="w-16 h-16 rounded-full bg-black flex items-center justify-center border-2 border-yellow-500/20 shadow-inner">
                             <div className="w-2 h-2 bg-yellow-500 rounded-full animate-pulse"></div>
                        </div>
                    </div>
                </div>

                {lastWinIndex !== null && !isSpinning && (
                    <div className="mt-12 bg-black/60 backdrop-blur-md text-yellow-400 font-black px-10 py-4 rounded-full shadow-2xl animate-in zoom-in border border-yellow-500/20 uppercase tracking-[0.2em]">
                        {SEGMENTS[lastWinIndex].label === 'LOSE' ? 'TRY AGAIN' : `WON ${SEGMENTS[lastWinIndex].label}`}
                    </div>
                )}
            </div>

            <div className="bg-[#111827] border-t border-white/5 p-6 shadow-[0_-20px_60px_rgba(0,0,0,1)] relative z-50 pb-10">
                <div className="flex justify-between items-end mb-6 px-2">
                    <div>
                        <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mb-2">Stake</p>
                        <div className="text-3xl font-black text-white italic tracking-tighter">₹{betAmount}</div>
                    </div>
                    <div className="grid grid-cols-4 gap-2">
                        {[10, 50, 100, 500].map(amt => (
                            <button 
                                key={amt}
                                onClick={() => !isSpinning && setBetAmount(amt)}
                                className={`px-4 py-2 rounded-xl font-bold text-[10px] border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white' : 'bg-slate-800 text-slate-500 border-white/5'}`}
                            >
                                ₹{amt}
                            </button>
                        ))}
                    </div>
                </div>

                <button 
                    onClick={startSpin}
                    disabled={isSpinning}
                    className={`w-full py-6 rounded-[2.5rem] font-black uppercase tracking-[0.5em] shadow-2xl transition-all active:scale-95 text-lg border-t-2 border-white/20 ${isSpinning ? 'bg-slate-700 text-slate-500 opacity-50 grayscale cursor-not-allowed' : 'bg-gradient-to-r from-yellow-400 via-orange-500 to-yellow-600 text-black'}`}
                >
                    {isSpinning ? 'SPINNING...' : 'SPIN NOW'}
                </button>
            </div>

            <style>{`
                .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
            `}</style>
        </div>
    );
};

