import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, ShieldAlert, Circle, Square, Triangle, ChevronDown, Flame } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

type Shape = 'CIRCLE' | 'TRIANGLE' | 'SQUARE';

// Real-world accurate multipliers
const PATH_CONFIG = {
  CIRCLE: {
    multipliers: [1.1, 1.25, 1.55, 1.9, 2.5, 3.9, 5.2, 8.5],
    risk: 0.94,
    color: 'emerald'
  },
  TRIANGLE: {
    multipliers: [1.5, 2.5, 4.85, 7.7, 12.5, 20.5, 44, 85],
    risk: 0.82,
    color: 'blue'
  },
  SQUARE: {
    multipliers: [2.5, 4.85, 10, 27.5, 52, 85, 133, 200],
    risk: 0.70,
    color: 'rose'
  }
};

const Vortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [selectedShape, setSelectedShape] = useState<Shape>('TRIANGLE');
  const [isHolding, setIsHolding] = useState(false);
  const [currentLevel, setCurrentLevel] = useState(-1);
  const [isCrashed, setIsCrashed] = useState(false);
  const [history, setHistory] = useState<Shape[]>(['CIRCLE', 'SQUARE', 'TRIANGLE']);
  const [multiplier, setMultiplier] = useState(1.0);

  const holdIntervalRef = useRef<number | null>(null);
  const crashPointRef = useRef(10);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (holdIntervalRef.current) clearInterval(holdIntervalRef.current);
      stopAllSounds();
    };
  }, []);

  const handleStartHold = () => {
    if (userBalance < betAmount || isCrashed || isHolding) return;

    setIsHolding(true);
    setIsCrashed(false);
    setMultiplier(1.0);
    setCurrentLevel(-1);
    playSound('click');
    updateBalance(-betAmount, 'BET', 'Vortex Stake');

    // Determine Crash Level (Predetermined for consistency)
    const config = PATH_CONFIG[selectedShape];
    let cp = 10;
    for(let i=0; i < config.multipliers.length; i++) {
        if (Math.random() > config.risk) {
            cp = i;
            break;
        }
    }
    crashPointRef.current = cp;

    let startTime = Date.now();
    holdIntervalRef.current = window.setInterval(() => {
      const elapsed = (Date.now() - startTime) / 1000;
      // Character walks across levels
      const level = Math.floor(elapsed * 2.0); 

      if (level > crashPointRef.current) {
        handleCrash();
      } else if (level < config.multipliers.length) {
        if (level !== currentLevel) {
            setCurrentLevel(level);
            setMultiplier(config.multipliers[level]);
            playSound('tick');
        }
      } else {
          // Reached the max level
          stopHolding();
          handleCollect();
      }
    }, 50);
  };

  const handleCrash = () => {
    stopHolding();
    setIsCrashed(true);
    playSound('loss');

    onResult({
      win: false,
      amount: betAmount,
      game: 'Vortex',
      resultDetails: [{ label: 'Status', value: 'ELIMINATED', color: 'text-red-500' }]
    });

    addGameHistory('Vortex', betAmount, 0, `Eliminated on ${selectedShape}`);
    setTimeout(() => { if (isMounted.current) setIsCrashed(false); }, 2500);
  };

  const stopHolding = () => {
    if (holdIntervalRef.current) { 
        clearInterval(holdIntervalRef.current); 
        holdIntervalRef.current = null; 
    }
    setIsHolding(false);
  };

  const handleCollect = () => {
    if (!isHolding || isCrashed || currentLevel < 0) return;

    const winAmount = betAmount * multiplier;
    stopHolding();
    updateBalance(winAmount, 'WIN', 'Vortex Win');
    playSound('win');

    onResult({
      win: true,
      amount: winAmount,
      game: 'Vortex',
      resultDetails: [
          { label: 'Won', value: `${multiplier}x`, color: 'text-green-400' },
          { label: 'Path', value: selectedShape }
      ]
    });

    addGameHistory('Vortex', betAmount, winAmount, `Victory ${multiplier}x`);
    setHistory(prev => [selectedShape, ...prev].slice(0, 10));
    setMultiplier(1.0);
    setCurrentLevel(-1);
  };

  const getRingClass = (idx: number) => {
    const config = PATH_CONFIG[selectedShape];
    if (currentLevel >= idx) {
        return `border-${config.color}-500 shadow-[0_0_30px_rgba(34,197,94,0.4)] scale-105 bg-${config.color}-500/10`;
    }
    return 'border-white/5 opacity-20';
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      {/* Background Red Flash on Crash */}
      <div className={`absolute inset-0 transition-colors duration-300 pointer-events-none z-10 ${isCrashed ? 'bg-red-950/40 backdrop-blur-sm' : 'bg-transparent'}`}></div>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(59,130,246,0.05)_0%,_transparent_70%)] pointer-events-none"></div>

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-[#111827]/90 backdrop-blur-xl border-b border-white/5 shadow-2xl relative z-50">
        <button onClick={onBack} className="p-2.5 bg-slate-800/80 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">VORTEX</h1>
            <p className="text-[8px] text-slate-500 font-bold uppercase tracking-[0.3em]">Survival of the Fittest</p>
        </div>
        <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {/* Risk Level Selector */}
        <div className="flex gap-12 mb-16 relative z-20">
            {(['SQUARE', 'TRIANGLE', 'CIRCLE'] as Shape[]).map(s => (
                <button 
                    key={s}
                    onClick={() => !isHolding && setSelectedShape(s)}
                    className={`flex flex-col items-center gap-2 transition-all transform ${selectedShape === s ? 'scale-125 opacity-100' : 'opacity-40 scale-90'}`}
                >
                    <div className={`w-14 h-14 flex items-center justify-center rounded-full border-2 transition-all ${selectedShape === s ? 'border-yellow-400 bg-yellow-500/20 shadow-[0_0_20px_rgba(234,179,8,0.4)]' : 'border-white/20 bg-white/5'}`}>
                        {s === 'SQUARE' && <Square size={24} className="text-white" />}
                        {s === 'TRIANGLE' && <Triangle size={24} className="text-white" />}
                        {s === 'CIRCLE' && <Circle size={24} className="text-white" />}
                    </div>
                    <span className="text-[9px] font-black tracking-widest uppercase text-slate-400">{s}</span>
                </button>
            ))}
        </div>

        {/* Central Arena */}
        <div className="relative w-80 h-80 flex items-center justify-center">
            {/* Elimination Effect */}
            {isCrashed && (
                <div className="absolute inset-0 z-40 flex flex-col items-center justify-center animate-in zoom-in">
                    <div className="bg-red-600 px-8 py-2 rotate-[-10deg] border-4 border-white shadow-2xl">
                        <h2 className="text-4xl font-black italic text-white tracking-tighter">WASTED</h2>
                    </div>
                    <ShieldAlert size={64} className="text-red-500 mt-4 animate-bounce" />
                </div>
            )}

            {/* Current Multiplier Display */}
            {isHolding && !isCrashed && (
                <div className="absolute -top-16 left-1/2 -translate-x-1/2 z-50 text-center animate-in zoom-in">
                    <div className="text-[10px] font-black text-yellow-500 uppercase tracking-widest mb-1 flex items-center gap-2 justify-center">
                        <Flame size={12} className="animate-pulse" /> Live Multiplier
                    </div>
                    <div className="text-7xl font-black italic gold-text drop-shadow-2xl">{multiplier.toFixed(2)}x</div>
                </div>
            )}

            {/* Concentric Rings (Progress Levels) */}
            {[0, 1, 2, 3, 4].map(idx => (
                <div 
                    key={idx}
                    className={`absolute rounded-full border-2 transition-all duration-500 flex items-center justify-center ${getRingClass(idx)}`}
                    style={{ width: `${100 - idx * 18}%`, height: `${100 - idx * 18}%` }}
                >
                    <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-[#0a0f1d] px-2 text-[9px] font-black text-white/40 uppercase">
                        {PATH_CONFIG[selectedShape].multipliers[idx]}x
                    </div>
                </div>
            ))}

            {/* Core Character (School Girl) */}
            <div className={`relative w-24 h-24 rounded-full flex items-center justify-center z-30 transition-all duration-300 ${isCrashed ? 'opacity-0 scale-50' : 'opacity-100'}`}>
                <div className={`transition-all duration-300 ${isHolding ? 'scale-110' : 'scale-90 grayscale opacity-40'}`}>
                    <img 
                        src="https://api.dicebear.com/7.x/avataaars/svg?seed=Zoey&skinColor=f8d25c&clothing=blazerAndShirt&clothingColor=3c4d5b&top=longHair&topColor=262e33" 
                        className={`w-20 h-20 object-contain drop-shadow-2xl ${isHolding ? 'animate-[bounce_0.5s_infinite]' : ''}`} 
                        alt="Girl" 
                    />
                </div>
                {/* Character Reflection */}
                <div className="absolute -bottom-2 w-10 h-3 bg-black/40 blur-sm rounded-full"></div>
            </div>
        </div>

        {/* History Area */}
        <div className="mt-12 flex gap-2 opacity-20">
            {history.map((s, i) => (
                <div key={i} className="p-2 bg-white/5 border border-white/10 rounded-lg">
                    {s === 'SQUARE' ? <Square size={10}/> : s === 'TRIANGLE' ? <Triangle size={10}/> : <Circle size={10}/>}
                </div>
            ))}
        </div>
      </div>

      {/* Controls */}
      <div className="bg-[#111827] border-t border-white/5 p-6 shadow-[0_-20px_60px_rgba(0,0,0,1)] relative z-50 pb-10">
        <div className="flex justify-between items-center mb-6">
            <div>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mb-1">Staked Amount</p>
                <div className="text-3xl font-black text-white italic tracking-tighter">₹{betAmount}</div>
            </div>
            <div className="flex gap-2">
                {[10, 50, 100, 500].map(amt => (
                    <button 
                        key={amt} 
                        onClick={() => !isHolding && setBetAmount(amt)}
                        className={`w-12 h-10 rounded-xl font-black text-[10px] border transition-all ${betAmount === amt ? 'bg-yellow-500 border-yellow-400 text-black shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}
                    >
                        {amt}
                    </button>
                ))}
            </div>
        </div>

        <button 
            onMouseDown={handleStartHold}
            onMouseUp={handleCollect}
            onTouchStart={handleStartHold}
            onTouchEnd={handleCollect}
            disabled={isCrashed}
            className={`w-full py-7 rounded-[2.5rem] font-black uppercase tracking-[0.5em] shadow-2xl transition-all active:scale-95 text-xl flex flex-col items-center justify-center gap-1 border-t-2 border-white/10 ${isHolding ? 'bg-orange-500 text-white scale-105 shadow-orange-500/30' : 'bg-gradient-to-r from-blue-600 to-indigo-700 text-white'}`}
        >
            {isHolding ? 'RELEASE TO WIN' : (
                <>
                    <span>HOLD TO WALK</span>
                    <ChevronDown size={14} className="animate-bounce" />
                </>
            )}
        </button>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
      `}</style>
    </div>
  );
};

