import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Play, Volume2, VolumeX, Info, ShieldAlert } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

// Multipliers arranged by angle (in degrees) to match the visual segments
const SEGMENTS = [
    { angle: 0, mult: 3.9, label: '3.9X', color: '#fde68a' },
    { angle: 30, mult: 12.5, label: '12.5X', color: '#ffffff' },
    { angle: 60, mult: 28, label: '28X', color: '#ffffff' },
    { angle: 90, mult: 52, label: '52X', color: '#ffffff' },
    { angle: 120, mult: 16, label: '16X', color: '#ffffff' },
    { angle: 150, mult: 4.85, label: '4.85X', color: '#ffffff' },
    { angle: 180, mult: 85, label: '85X', color: '#ffffff' },
    { angle: 210, mult: 27.5, label: '27.5X', color: '#ffffff' },
    { angle: 240, mult: 10, label: '10X', color: '#ffffff' },
    { angle: 270, mult: 44, label: '44X', color: '#ffffff' },
    { angle: 300, mult: 7, label: '7X', color: '#ffffff' },
    { angle: 330, mult: 1.55, label: '1.55X', color: '#ffffff' },
];

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [isHolding, setIsHolding] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());

  const spinInterval = useRef<number | null>(null);
  const currentRotation = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (spinInterval.current) clearInterval(spinInterval.current);
      stopAllSounds();
    };
  }, []);

  const startHolding = () => {
    if (userBalance < betAmount || isSpinning) return;
    setIsHolding(true);
    setIsSpinning(true);
    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Squid Vortex Stake');

    spinInterval.current = window.setInterval(() => {
        currentRotation.current += 15; // Fast rotation speed
        setRotation(currentRotation.current);
    }, 30);
  };

  const stopHolding = () => {
    if (!isHolding) return;
    setIsHolding(false);
    if (spinInterval.current) {
        clearInterval(spinInterval.current);
        spinInterval.current = null;
    }

    // Physics Easing: Add a random extra rotation before stopping
    const extraDegrees = 500 + Math.random() * 1000;
    const finalRotation = currentRotation.current + extraDegrees;

    setRotation(finalRotation);
    currentRotation.current = finalRotation;

    setTimeout(() => {
        if (!isMounted.current) return;
        setIsSpinning(false);
        calculateResult(finalRotation);
    }, 2000); // Wait for CSS transition
  };

  const calculateResult = (deg: number) => {
    // Standardize degree to 0-360
    // Result is at the top (0 deg). Since wheel rotates, we check what segment is currently at 0.
    const normalized = (360 - (deg % 360)) % 360;
    const segmentWidth = 30;
    const index = Math.floor((normalized + segmentWidth / 2) / segmentWidth) % 12;
    const result = SEGMENTS[index];

    const winAmount = betAmount * result.mult;
    updateBalance(winAmount, 'WIN', 'Vortex Win');
    playSound('win');

    onResult({
      win: true,
      amount: winAmount,
      game: 'Squid Vortex',
      resultDetails: [{ label: 'Landed', value: result.label, color: 'text-yellow-400' }]
    });

    addGameHistory('Squid Vortex', betAmount, winAmount, `Hit ${result.label}`);
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      {/* Background Grid Pattern */}
      <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#ffffff_1px,transparent_1px)] [background-size:20px_20px] pointer-events-none"></div>

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/80 backdrop-blur-md border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-xl active:scale-90"><ArrowLeft size={20}/></button>
        <div className="flex gap-4">
            <div className="flex items-center gap-2 bg-zinc-900/50 px-4 py-1.5 rounded-full border border-white/10">
                <Wallet size={14} className="text-yellow-500" />
                <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
            <button onClick={() => setMuted(toggleMute())} className="p-2 bg-zinc-900 rounded-xl">
                {muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}
            </button>
        </div>
      </div>

      {/* Bonus Symbols Strip */}
      <div className="flex justify-center gap-8 py-4 opacity-50 relative z-10">
          <div className="w-10 h-10 rounded-full border-2 border-white flex items-center justify-center"><div className="w-6 h-6 rounded-full border-2 border-white"></div></div>
          <div className="w-10 h-10 rounded-full border-2 border-white flex items-center justify-center rotate-45"><div className="w-6 h-6 border-t-2 border-l-2 border-white"></div></div>
          <div className="w-10 h-10 rounded-full border-2 border-white flex items-center justify-center"><div className="w-5 h-5 border-2 border-white"></div></div>
      </div>

      {/* Main Game Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {/* Top Indicator */}
        <div className="absolute top-[15%] left-1/2 -translate-x-1/2 z-40 flex flex-col items-center">
            <div className="w-1 h-10 bg-red-600 shadow-[0_0_15px_rgba(220,38,38,0.8)] rounded-full mb-2"></div>
            <div className="bg-red-600/20 px-3 py-0.5 rounded-full border border-red-600/50 text-[8px] font-black uppercase tracking-widest text-red-500">Selection</div>
        </div>

        {/* The Vortex Wheel */}
        <div className="relative w-80 h-80 md:w-96 md:h-96 flex items-center justify-center">

            {/* Spinning Container */}
            <div 
                className="w-full h-full rounded-full border-[10px] border-zinc-800 shadow-[0_0_50px_rgba(0,0,0,1)] relative overflow-hidden"
                style={{ 
                    transform: `rotate(${rotation}deg)`, 
                    transition: isHolding ? 'none' : 'transform 2s cubic-bezier(0.1, 0, 0.1, 1)' 
                }}
            >
                {/* Visual Rings Background */}
                <div className="absolute inset-0 rounded-full border-[2px] border-white/5 m-4"></div>
                <div className="absolute inset-0 rounded-full border-[2px] border-white/5 m-12"></div>
                <div className="absolute inset-0 rounded-full border-[2px] border-white/5 m-20"></div>

                {/* Multipliers */}
                {SEGMENTS.map((seg, i) => (
                    <div 
                        key={i}
                        className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-6 origin-bottom"
                        style={{ transform: `rotate(${seg.angle}deg)` }}
                    >
                        <span className={`text-lg md:text-xl font-black italic tracking-tighter ${seg.mult >= 50 ? 'text-yellow-400 drop-shadow-[0_0_8px_rgba(234,179,8,0.6)]' : 'text-white/80'}`}>
                            {seg.label}
                        </span>

                        {/* Connecting Radial Lines */}
                        <div className="w-[1px] h-full bg-white/5 mt-2"></div>
                    </div>
                ))}
            </div>

            {/* Fixed Center Core - Squid Game Character */}
            <div className="absolute inset-0 flex items-center justify-center z-30 pointer-events-none">
                <div className="w-24 h-24 rounded-full bg-gradient-to-br from-yellow-500 to-yellow-600 p-1 shadow-[0_0_40px_rgba(234,179,8,0.4)]">
                    <div className="w-full h-full rounded-full bg-zinc-900 flex flex-col items-center justify-center border-4 border-zinc-800">
                        {/* Squid Guard Icon */}
                        <div className="w-14 h-14 bg-red-600 rounded-[30%_30%_50%_50%] relative flex flex-col items-center">
                            <div className="w-10 h-8 bg-zinc-950 rounded-full mt-1 flex items-center justify-center">
                                <div className="w-4 h-4 border-2 border-white"></div> {/* Square Mask */}
                            </div>
                            <div className="w-8 h-1 bg-zinc-950 rounded-full mt-2"></div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        {/* Bottom Description */}
        <div className="mt-12 text-center">
            <h2 className="text-2xl font-black italic gold-text tracking-tighter uppercase mb-1">SQUID VORTEX</h2>
            <p className="text-[9px] text-zinc-500 font-bold uppercase tracking-[0.4em]">The Elite Circle of Fortune</p>
        </div>
      </div>

      {/* Interaction Panel */}
      <div className="bg-zinc-950 border-t border-white/5 p-6 pb-12 z-50">
          <div className="flex justify-between items-center mb-6 px-2">
              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button 
                        key={amt}
                        onClick={() => !isSpinning && setBetAmount(amt)}
                        className={`w-12 h-10 rounded-xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}
                      >
                        {amt}
                      </button>
                  ))}
              </div>
              <div className="text-right">
                  <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Bet Amount</p>
                  <div className="text-2xl font-black text-white italic">₹{betAmount}</div>
              </div>
          </div>

          <div className="flex gap-4">
              <button 
                onMouseDown={startHolding}
                onMouseUp={stopHolding}
                onTouchStart={startHolding}
                onTouchEnd={stopHolding}
                disabled={!isHolding && isSpinning}
                className={`flex-1 h-20 rounded-[2rem] flex items-center justify-center gap-4 transition-all active:scale-95 border-t-2 border-white/20 shadow-2xl ${
                    isHolding 
                    ? 'bg-red-600 shadow-red-900/40 animate-pulse' 
                    : (!isHolding && isSpinning) 
                        ? 'bg-zinc-800 text-zinc-500' 
                        : 'bg-green-600 shadow-green-900/40'
                }`}
              >
                  <div className="w-10 h-10 rounded-full bg-black/20 flex items-center justify-center">
                      <Play size={20} className={`fill-current ${isHolding ? 'hidden' : ''}`} />
                      {isHolding && <div className="w-4 h-4 bg-white rounded-sm"></div>}
                  </div>
                  <span className="font-black uppercase tracking-[0.3em] text-lg">
                      {isHolding ? 'STOP' : 'HOLD'}
                  </span>
              </button>

              <button className="w-20 h-20 bg-zinc-900 rounded-[2rem] flex flex-col items-center justify-center text-zinc-500 border border-white/5">
                  <Info size={20}/>
                  <span className="text-[8px] font-black uppercase mt-1">Info</span>
              </button>
          </div>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
      `}</style>
    </div>
  );
};

