    { angle: 240, mult: 10, label: '10X', tier: 'Inner' },
    { angle: 270, mult: 44, label: '44X', tier: 'Outer' },
    { angle: 300, mult: 7.7, label: '7.7X', tier: 'Mid' },
    { angle: 330, mult: 1.55, label: '1.55X', tier: 'Inner' },
];

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [isHolding, setIsHolding] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());
  const [winningId, setWinningId] = useState<number | null>(null);

  const spinInterval = useRef<number | null>(null);
  const currentRotation = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (spinInterval.current) clearInterval(spinInterval.current);
      stopAllSounds();
    };
  }, []);

  const startHolding = () => {
    if (userBalance < betAmount || isSpinning) return;
    setIsHolding(true);
    setIsSpinning(true);
    setWinningId(null);
    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Squid Vortex Stake');

    spinInterval.current = window.setInterval(() => {
        currentRotation.current += 18; // Constant speed while holding
        setRotation(currentRotation.current);
    }, 30);
  };

  const stopHolding = () => {
    if (!isHolding) return;
    setIsHolding(false);
    if (spinInterval.current) {
        clearInterval(spinInterval.current);
        spinInterval.current = null;
    }

    // Release Easing: Simulate friction
    const extraDegrees = 720 + Math.random() * 1080;
    const finalRotation = currentRotation.current + extraDegrees;

    setRotation(finalRotation);
    currentRotation.current = finalRotation;

    // The wheel stops after 2s due to CSS transition
    setTimeout(() => {
        if (!isMounted.current) return;
        setIsSpinning(false);
        processFinalResult(finalRotation);
    }, 2000);
  };

  const processFinalResult = (deg: number) => {
    // 0 degrees is the indicator at 12 o'clock
    const normalized = (360 - (deg % 360)) % 360;
    const segmentWidth = 30;
    const index = Math.floor((normalized + 15) / segmentWidth) % 12;
    const result = SEGMENTS[index];

    setWinningId(index);
    const winAmount = betAmount * result.mult;
    updateBalance(winAmount, 'WIN', 'Squid Vortex Win');
    playSound('win');

    onResult({
      win: true,
      amount: winAmount,
      game: 'Squid Vortex',
      resultDetails: [
          { label: 'Result', value: result.label, color: 'text-yellow-400' },
          { label: 'Zone', value: result.tier }
      ]
    });

    addGameHistory('Squid Vortex', betAmount, winAmount, `Multiplier ${result.label} hit`);
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      {/* Background Dark Gradient */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(220,38,38,0.05)_0%,_transparent_70%)] pointer-events-none"></div>

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/60 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 transition-all border border-white/5"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-lg font-black tracking-widest uppercase italic gold-text">VORTEX</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Elite Squid Arena</p>
        </div>
        <div className="flex items-center gap-2 bg-zinc-900/50 px-4 py-2 rounded-2xl border border-yellow-500/10">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Bonus Area (Screenshot ⭕ 🔺 ⬛) */}
      <div className="flex justify-center items-center gap-10 py-6 relative z-10 opacity-60">
          <div className="flex flex-col items-center gap-1">
              <div className="w-10 h-10 rounded-full border-2 border-pink-500 flex items-center justify-center"><Circle size={20} className="text-pink-500" /></div>
              <span className="text-[8px] font-black text-pink-500 uppercase">Circle</span>
          </div>
          <div className="flex flex-col items-center gap-1">
              <div className="w-10 h-10 border-2 border-pink-500 flex items-center justify-center rotate-45"><Triangle size={20} className="text-pink-500 -rotate-45 translate-y-[-1px]" /></div>
              <span className="text-[8px] font-black text-pink-500 uppercase">Bonus</span>
          </div>
          <div className="flex flex-col items-center gap-1">
              <div className="w-10 h-10 border-2 border-pink-500 flex items-center justify-center"><Square size={20} className="text-pink-500" /></div>
              <span className="text-[8px] font-black text-pink-500 uppercase">Square</span>
          </div>
      </div>

      {/* Main Vortex Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {/* Top Result Indicator */}
        <div className="absolute top-[5%] left-1/2 -translate-x-1/2 z-40 flex flex-col items-center">
             <div className="w-6 h-6 bg-red-600 rounded-full border-2 border-white shadow-[0_0_20px_rgba(220,38,38,1)] flex items-center justify-center">
                 <div className="w-2 h-2 bg-white rounded-full"></div>
             </div>
             <div className="w-1 h-8 bg-gradient-to-b from-red-600 to-transparent"></div>
        </div>

        {/* The Spinning Arena */}
        <div className="relative w-80 h-80 md:w-96 md:h-96 flex items-center justify-center">

            {/* Rotating Rings Container */}
            <div 
                className="w-full h-full relative"
                style={{ 
                    transform: `rotate(${rotation}deg)`, 
                    transition: isHolding ? 'none' : 'transform 2.5s cubic-bezier(0.1, 0, 0.1, 1)' 
                }}
            >
                {/* Visual Rings Backdrop */}
                <div className="absolute inset-0 rounded-full border-[6px] border-zinc-800 shadow-[0_0_60px_rgba(0,0,0,1)]"></div>
                <div className="absolute inset-[15%] rounded-full border-2 border-white/5"></div>
                <div className="absolute inset-[30%] rounded-full border-2 border-white/5"></div>

                {/* Multilipliers mapped around the circle */}
                {SEGMENTS.map((seg, i) => (
                    <div 
                        key={i}
                        className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-8 origin-bottom"
                        style={{ transform: `rotate(${seg.angle}deg)` }}
                    >
                        <div className={`transition-all duration-300 ${winningId === i ? 'scale-150 drop-shadow-[0_0_12px_rgba(251,191,36,0.8)]' : ''}`}>
                            <span className={`text-xl font-black italic tracking-tighter ${
                                seg.tier === 'Extreme' ? 'text-yellow-500' : 
                                seg.tier === 'Outer' ? 'text-white' : 'text-zinc-400'
                            }`}>
                                {seg.label}
                            </span>
                        </div>

                        {/* Radial separator line */}
                        <div className="w-[1px] h-32 bg-white/5 mt-4"></div>
                    </div>
                ))}
            </div>

            {/* Static Center Core - Squid Game Character */}
            <div className="absolute inset-0 flex items-center justify-center z-30 pointer-events-none">
                <div className="w-28 h-28 rounded-full bg-zinc-900 border-4 border-zinc-800 shadow-[inset_0_0_30px_rgba(0,0,0,0.8)] flex items-center justify-center relative overflow-hidden">
                    <div className="absolute inset-0 bg-gradient-to-br from-zinc-800/50 to-transparent"></div>
                    {/* Squid Game Girl Icon Placeholder */}
                    <div className="relative w-20 h-20 bg-yellow-400/10 rounded-full flex items-center justify-center">
                         <img 
                            src="https://api.dicebear.com/7.x/avataaars/svg?seed=Squid&skinColor=f8d25c&clothing=blazerAndShirt&clothingColor=3c4d5b&top=longHair&topColor=262e33" 
                            className="w-16 h-16 object-contain drop-shadow-2xl" 
                            alt="Squid" 
                        />
                    </div>
                </div>
            </div>
        </div>

        {/* Bottom Game Label */}
        <div className="mt-10 text-center">
            <h2 className="text-2xl font-black italic gold-text tracking-tighter uppercase mb-1">SQUID VORTEX</h2>
            <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Fortune favors the brave</p>
        </div>
      </div>

      {/* Control Board */}
      <div className="bg-[#0a0a0a] border-t border-white/5 p-6 pb-12 z-50">
          <div className="flex justify-between items-end mb-6 px-2">
              <div className="flex flex-col gap-2">
                  <span className="text-[9px] text-zinc-500 font-black uppercase tracking-widest">Select Bet</span>
                  <div className="flex gap-2">
                      {[10, 50, 100, 500].map(amt => (
                          <button 
                            key={amt}
                            onClick={() => !isSpinning && setBetAmount(amt)}
                            className={`w-12 h-10 rounded-xl font-black text-[10px] border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}
                          >
                            {amt}
                          </button>
                      ))}
                  </div>
              </div>
              <div className="text-right">
                  <p className="text-[10px] text-zinc-500 font-black uppercase tracking-widest mb-1">Balance</p>
