import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, ShieldAlert, Circle, Square, Triangle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

// 3 Rings Data Structure
const RING_CONFIG = [
    { 
        id: 'inner', 
        radius: '30%', 
        multipliers: [
            { label: '1.55X', val: 1.55, type: 'win' },
            { label: '7X', val: 7, type: 'win' },
            { label: '10X', val: 10, type: 'win' },
            { label: 'MASK', val: 0, type: 'loss' } // Black Shooter
        ]
    },
    { 
        id: 'mid', 
        radius: '55%', 
        multipliers: [
            { label: '2.5X', val: 2.5, type: 'win' },
            { label: '7.7X', val: 7.7, type: 'win' },
            { label: '16X', val: 16, type: 'win' },
            { label: '27.5X', val: 27.5, type: 'win' },
            { label: 'MASK', val: 0, type: 'loss' }
        ]
    },
    { 
        id: 'outer', 
        radius: '80%', 
        multipliers: [
            { label: '3.9X', val: 3.9, type: 'win' },
            { label: '12.5X', val: 12.5, type: 'win' },
            { label: '28X', val: 28, type: 'win' },
            { label: '52X', val: 52, type: 'win' },
            { label: '85X', val: 85, type: 'win' },
            { label: '133X', val: 133, type: 'win' },
            { label: '200X', val: 200, type: 'win' },
            { label: 'BONUS', val: 5, type: 'win' }
        ]
    }
];

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [isHolding, setIsHolding] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());

  const spinInterval = useRef<number | null>(null);
  const currentRotation = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (spinInterval.current) clearInterval(spinInterval.current);
      stopAllSounds();
    };
  }, []);

  const startHolding = () => {
    if (userBalance < betAmount || isSpinning) return;
    setIsHolding(true);
    setIsSpinning(true);
    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Squid Vortex Stake');

    spinInterval.current = window.setInterval(() => {
        currentRotation.current += 20; 
        setRotation(currentRotation.current);
    }, 30);
  };

  const stopHolding = () => {
    if (!isHolding) return;
    setIsHolding(false);
    if (spinInterval.current) {
        clearInterval(spinInterval.current);
        spinInterval.current = null;
    }

    const extraDegrees = 1000 + Math.random() * 1500;
    const finalRotation = currentRotation.current + extraDegrees;

    setRotation(finalRotation);
    currentRotation.current = finalRotation;

    setTimeout(() => {
        if (!isMounted.current) return;
        setIsSpinning(false);
        calculateResult(finalRotation);
    }, 2500); 
  };

  const calculateResult = (deg: number) => {
    const normalized = (360 - (deg % 360)) % 360;

    // Result is based on the Outer Ring for the main multiplier
    const outerRing = RING_CONFIG[2].multipliers;
    const segmentWidth = 360 / outerRing.length;
    const index = Math.floor((normalized + (segmentWidth/2)) / segmentWidth) % outerRing.length;
    const result = outerRing[index];

    if (result.type === 'loss' || Math.random() < 0.2) { // 20% natural fail rate for Squid Game tension
        playSound('loss');
        onResult({
            win: false,
            amount: betAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Result', value: 'ELIMINATED', color: 'text-red-500' }]
        });
        addGameHistory('Squid Vortex', betAmount, 0, 'Eliminated by Guard');
    } else {
        const winAmount = betAmount * result.val;
        updateBalance(winAmount, 'WIN', 'Vortex Win');
        playSound('win');
        onResult({
            win: true,
            amount: winAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Landed', value: result.label, color: 'text-yellow-400' }]
        });
