const RING_DATA = {
    outer: ['200X', 'BONUS', '3.9X', '12.5X', '28X', '52X', '16X', '4.85X', '85X', '27.5X', '10X', '44X'],
    mid: ['+20.5X', '2.5X', '7.7X', '1.55X', 'MASK', '10X', '2.5X', '7.7X', '+20.5X', '16X', 'MASK', '4.85X'],
    inner: ['+7X', '1.55X', '10X', 'MASK', '2.5X', '7.7X', '+7X', '1.55X', '10X', 'MASK', '16X', '2.5X']
};

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
