import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, ShieldAlert, Circle, Square, Triangle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

// Fixed board configuration
// 12 Segments per circle
const BOARD_DATA = {
    outer: ['200X', '150X', '120X', '100X', 'MASK', '133X', '90X', '85X', '75X', '66X', 'MASK', '50X'],
    mid: ['44X', '27.5X', 'MASK', '52X', '16X', '12.5X', '20.5X', '10X', '33X', 'MASK', '27.5X', '3.9X'],
    inner: ['7.7X', '4.85X', '7X', '1.55X', '2.5X', '7.7X', 'MASK', '1.55X', '2.5X', '7.7X', '1.55X', 'MASK']
};

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [beamRotation, setBeamRotation] = useState(0); 
  const [charRotation, setCharRotation] = useState(0);
  const [isHolding, setIsHolding] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<string[]>(['12.5X', '16X', '44X']);

  const spinInterval = useRef<number | null>(null);
  const currentBeamRotation = useRef(0);
  const currentCharRotation = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (spinInterval.current) clearInterval(spinInterval.current);
      stopAllSounds();
    };
  }, []);

  const startHolding = () => {
    if (userBalance < betAmount || isSpinning) return;
    setIsHolding(true);
    setIsSpinning(true);
    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Squid Vortex Stake');

    spinInterval.current = window.setInterval(() => {
        currentBeamRotation.current += 25; 
        currentCharRotation.current += 15;
        setBeamRotation(currentBeamRotation.current);
        setCharRotation(currentCharRotation.current);
    }, 30);
  };

  const stopHolding = () => {
    if (!isHolding) return;
    setIsHolding(false);
    if (spinInterval.current) {
        clearInterval(spinInterval.current);
        spinInterval.current = null;
    }

    const extraBeam = 1200 + Math.random() * 1000;
    const finalBeam = currentBeamRotation.current + extraBeam;

    setBeamRotation(finalBeam);
    currentBeamRotation.current = finalBeam;

    setTimeout(() => {
        if (!isMounted.current) return;
        setIsSpinning(false);
        calculateResult(finalBeam);
    }, 2500); 
  };

  const calculateResult = (deg: number) => {
    const normalized = deg % 360;
    const segmentWidth = 30; // 360 / 12
    const index = Math.floor((normalized + 15) / segmentWidth) % 12;

    // Check all rings at this index
    const outerRes = BOARD_DATA.outer[index];
    const midRes = BOARD_DATA.mid[index];
    const innerRes = BOARD_DATA.inner[index];

    // Priority: If any ring has MASK, you might lose. But usually it points to the rings hierarchical result.
    // We will pick the result based on some internal weighted logic or just Outer for high stakes feel.
    // The visual beam crosses all 3 rings.
    const resultLabel = outerRes; 

    if (outerRes === 'MASK' || midRes === 'MASK' || innerRes === 'MASK' || Math.random() < 0.1) {
        playSound('loss');
        onResult({
            win: false,
            amount: betAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Result', value: 'ELIMINATED', color: 'text-red-500' }]
        });
        addGameHistory('Squid Vortex', betAmount, 0, 'Eliminated by Guard');
    } else {
        const valStr = resultLabel.replace('X', '');
        const multiplier = parseFloat(valStr);
        const winAmount = betAmount * multiplier;

        updateBalance(winAmount, 'WIN', 'Vortex Win');
        playSound('win');
        setHistory(prev => [resultLabel, ...prev].slice(0, 10));
        onResult({
            win: true,
            amount: winAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Landed', value: resultLabel, color: 'text-yellow-400' }]
        });
        addGameHistory('Squid Vortex', betAmount, winAmount, `Hit ${resultLabel}`);
    }
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(220,38,38,0.05)_0%,_transparent_70%)] pointer-events-none"></div>

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/80 backdrop-blur-md border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-xl active:scale-90 border border-white/5"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-lg font-black tracking-widest uppercase italic gold-text">SQUID VORTEX</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Elite Arena</p>
        </div>
        <div className="flex items-center gap-2 bg-zinc-900/50 px-4 py-1.5 rounded-full border border-white/10">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Symbols Decoration */}
      <div className="flex justify-center gap-10 py-6 relative z-10 opacity-30">
          <div className="w-10 h-10 border-2 border-white rounded-full flex items-center justify-center"><Circle size={18}/></div>
          <div className="w-10 h-10 border-2 border-white flex items-center justify-center rotate-45"><Triangle size={18} className="-rotate-45"/></div>
          <div className="w-10 h-10 border-2 border-white flex items-center justify-center"><Square size={18}/></div>
      </div>

      {/* Game Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {/* The Fixed Board Container */}
        <div className="relative w-80 h-80 md:w-96 md:h-96 flex items-center justify-center">

            {/* STATIC BOARD WITH 3 RINGS */}
            <div className="absolute inset-0 rounded-full border-[10px] border-zinc-800 shadow-[0_0_60px_rgba(0,0,0,1)] bg-[#0a0a0a]">
                <div className="absolute inset-[18%] rounded-full border-[2px] border-white/5"></div>
                <div className="absolute inset-[35%] rounded-full border-[2px] border-white/5"></div>

                {/* Outer Ring (Highest Multipliers) */}
                {BOARD_DATA.outer.map((label, i) => (
                    <div key={`o-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-4 origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        {label === 'MASK' ? <ShieldAlert size={14} className="text-red-500" /> : <span className="text-xs font-black italic text-white/60 drop-shadow-lg">{label}</span>}
                    </div>
                ))}

                {/* Middle Ring (Medium Multipliers) */}
                {BOARD_DATA.mid.map((label, i) => (
                    <div key={`m-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-[90px] origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                         {label === 'MASK' ? <ShieldAlert size={10} className="text-red-500/50" /> : <span className="text-[10px] font-black italic text-zinc-500">{label}</span>}
                    </div>
                ))}

                {/* Inner Ring (Lowest Multipliers) */}
                {BOARD_DATA.inner.map((label, i) => (
                    <div key={`i-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-[140px] origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                         {label === 'MASK' ? <ShieldAlert size={8} className="text-red-500/30" /> : <span className="text-[9px] font-bold text-zinc-700">{label}</span>}
                    </div>
                ))}
            </div>

            {/* ROTATING SELECTOR BEAM */}
            <div 
                className="absolute inset-0 pointer-events-none z-20"
                style={{ 
                    transform: `rotate(${beamRotation}deg)`,
                    transition: isHolding ? 'none' : 'transform 2.5s cubic-bezier(0.1, 0, 0.1, 1)' 
                }}
            >
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[3px] h-1/2 bg-gradient-to-b from-red-500 via-red-500/40 to-transparent"></div>
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-4 h-4 bg-red-600 rounded-full blur-[2px] border-2 border-white shadow-[0_0_15px_red]"></div>
            </div>

            {/* ROTATING CENTER CORE (Doll) */}
            <div className="absolute inset-0 flex items-center justify-center z-30 pointer-events-none">
                <div 
                    className="w-24 h-24 rounded-full bg-zinc-900 border-4 border-zinc-800 shadow-[inset_0_0_20px_rgba(0,0,0,1)] flex items-center justify-center overflow-hidden"
                    style={{ 
                        transform: `rotate(${charRotation}deg)`,
                        transition: isHolding ? 'none' : 'transform 0.5s ease-out'
                    }}
                >
                    <img 
                        src="https://api.dicebear.com/7.x/avataaars/svg?seed=SquidDoll&backgroundColor=b6e3f4&top=longHair&hairColor=262e33&skinColor=f8d25c" 
                        className="w-20 h-20 object-contain" 
                        alt="Squid Doll" 
                    />
                </div>
            </div>
        </div>

        <div className="mt-12 text-center">
            <h2 className="text-2xl font-black italic gold-text tracking-tighter uppercase mb-1">VORTEX ARENA</h2>
            <div className="flex gap-2 justify-center opacity-40">
                {history.map((h, i) => <span key={i} className="text-[8px] font-black text-white">{h}</span>)}
            </div>
        </div>
      </div>

      {/* Controls */}
      <div className="bg-zinc-950 border-t border-white/5 p-6 pb-12 z-50">
          <div className="flex justify-between items-center mb-6 px-2">
              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button 
                        key={amt}
                        onClick={() => !isSpinning && setBetAmount(amt)}
                        className={`w-12 h-10 rounded-xl font-black text-[10px] border transition-all ${betAmount === amt ? 'bg-red-600 text-white border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}
                      >
                        {amt}
                      </button>
                  ))}
              </div>
              <div className="text-right">
                  <p className="text-[10px] text-zinc-500 font-black uppercase tracking-widest mb-1">Stake</p>
                  <div className="text-2xl font-black text-white italic tracking-tighter">₹{betAmount}</div>
              </div>
          </div>

          <div className="grid grid-cols-1 gap-4">
              <button 
                onMouseDown={startHolding}
                onMouseUp={stopHolding}
                onTouchStart={startHolding}
                onTouchEnd={stopHolding}
                disabled={!isHolding && isSpinning}
                className={`h-24 rounded-[2rem] flex flex-col items-center justify-center gap-1 transition-all active:scale-95 border-t-2 border-white/10 shadow-2xl ${
                    isHolding 
                    ? 'bg-red-600 shadow-red-900/40 animate-pulse' 
                    : (!isHolding && isSpinning) 
                        ? 'bg-zinc-800 text-zinc-600 border-none' 
                        : 'bg-gradient-to-r from-red-600 to-red-800'
                }`}
              >
                  <span className="font-black uppercase tracking-[0.2em] text-lg leading-none">
                      {isHolding ? 'RELEASE' : 'HOLD TO SPIN'}
                  </span>
                  <span className="text-[8px] font-bold opacity-60 uppercase">Don't Hit the Guard</span>
              </button>
          </div>
      </div>
    </div>
  );
};

