import React, { useState, useEffect } from 'react';
import NavBar from './components/NavBar';
import Home from './pages/Home';
import WinGo from './pages/WinGo';
import Aviator from './pages/Aviator';
import Mines from './pages/Mines';
import DogRoad from './pages/DogRoad';
import Vortex from './pages/Vortex';
import LuckyWheel from './pages/LuckyWheel';
import DragonTiger from './pages/DragonTiger';
import Plinko from './pages/Plinko';
import HeadTails from './pages/HeadTails';
import Profile from './pages/Profile';
import Referral from './pages/Referral';
import Promotion from './pages/Promotion';
import Deposit from './pages/Deposit';
import Withdraw from './pages/Withdraw';
import Wallet from './pages/Wallet';
import SafetyCenter from './pages/SafetyCenter';
import GameStatistics from './pages/GameStatistics';
import Auth from './pages/Auth';
import GameResultPopup from './components/GameResultPopup';
import { View, UserProfile, GameResult } from './types';
import { subscribeToBalance, startWinGoGame, stopAllSounds } from './services/mockFirebase';

export default function App() {
  const [currentView, setCurrentView] = useState<View>('HOME');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [gameResult, setGameResult] = useState<GameResult | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => { 
      startWinGoGame(); 
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToBalance((updatedUser) => {
        setUser(updatedUser);
        setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    stopAllSounds(); 
  }, [currentView]);

  if (isLoading) return <div className="min-h-screen bg-[#0a0f1d] flex items-center justify-center"><div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;

  if (!user) return <Auth />;

  const handleGameResult = (result: GameResult) => {
    // Suppress global popup for Aviator and Plinko as requested
    if (result.game === 'Aviator' || result.game === 'Plinko') {
        return; 
    }
    setGameResult(result);
  };

  const renderContent = () => {
    switch (currentView) {
      case 'HOME': return <Home setView={setCurrentView} />;
      case 'GAME_WINGO': return <WinGo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} onDeposit={() => setCurrentView('DEPOSIT')} />;
      case 'GAME_AVIATOR': return <Aviator onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_MINES': return <Mines onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_DOG': return <DogRoad onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_VORTEX': return <Vortex onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_LUCKY_WHEEL': return <LuckyWheel onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_DRAGON_TIGER': return <DragonTiger onBack={() => setCurrentView('HOME')} userBalance={user.balance} username={user.username} onResult={handleGameResult} />;
      case 'GAME_PLINKO': return <Plinko onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_HEAD_TAILS': return <HeadTails onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'ACCOUNT': return <Profile user={user} setView={setCurrentView} />;
      case 'REFERRAL': return <Referral />;
      case 'PROMOTION': return <Promotion />;
      case 'WALLET': return <Wallet setView={setCurrentView} userBalance={user.balance} />;
      case 'DEPOSIT': return <Deposit onBack={() => setCurrentView('WALLET')} />;
      case 'WITHDRAW': return <Withdraw onBack={() => setCurrentView('WALLET')} userBalance={user.balance} />;
      case 'SAFETY': return <SafetyCenter setView={setCurrentView} user={user} />;
      case 'STATISTICS': return <GameStatistics setView={setCurrentView} />;
      default: return <Home setView={setCurrentView} />;
    }
  };

  const showNavBar = ['HOME', 'REFERRAL', 'PROMOTION', 'WALLET', 'ACCOUNT'].includes(currentView);

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0a0f1d] shadow-2xl relative overflow-hidden font-sans">
      {renderContent()}
      <GameResultPopup result={gameResult} onClose={() => setGameResult(null)} />
      {showNavBar && <NavBar currentView={currentView} setView={setCurrentView} />}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Menu, Volume2, VolumeX, Wallet, History, Loader2, TrendingUp, TrendingDown } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, getGameHistory } from '../services/mockFirebase';
import { GameResult } from '../types';

interface AviatorProps {
  onBack: () => void;
  userBalance: number;
  onResult: (result: GameResult) => void;
}

type GamePhase = 'WAITING' | 'FLYING' | 'CRASHED';

const Aviator: React.FC<AviatorProps> = ({ onBack, userBalance, onResult }) => {
  const [phase, setPhase] = useState<GamePhase>('WAITING');
  const [multiplier, setMultiplier] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<number[]>([1.22, 2.45, 1.05, 8.12, 1.11, 3.44, 12.01, 1.00]);

  // Local result bar state
  const [localResult, setLocalResult] = useState<{ win: boolean; amount: number; show: boolean } | null>(null);

  const activeBetRef = useRef(false);
  const [activeBet, setActiveBet] = useState(false); 

  const nextRoundBetRef = useRef(false);
  const [nextRoundBet, setNextRoundBet] = useState(false);

  const [waitTime, setWaitTime] = useState(5); 

  const crashPointRef = useRef(0);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    const prevGames = getGameHistory('Aviator');
    if (prevGames.length > 0) {
        const points = prevGames.map(g => {
            const match = g.details.match(/@ ([\d\.]+)x/);
            return match ? parseFloat(match[1]) : 1.00;
        }).slice(0, 15);
        if (points.length > 0) setHistory(points);
    }

    startWaitingPhase();
    return () => {
        isMounted.current = false;
        if (animationRef.current) cancelAnimationFrame(animationRef.current);
        stopAllSounds();
    }
  }, []);

  const handleToggleMute = () => {
      setMuted(toggleMute());
  };

  const startWaitingPhase = () => {
      if (!isMounted.current) return;
      setPhase('WAITING');
      setMultiplier(1.00);
      setWaitTime(5);

      const canvas = canvasRef.current;
      if (canvas) {
          const ctx = canvas.getContext('2d');
          if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
      }

      if (activeBetRef.current) {
          activeBetRef.current = false;
          setActiveBet(false);
      }

      let t = 5;
      const interval = setInterval(() => {
          if (!isMounted.current) {
              clearInterval(interval);
              return;
          }
          t -= 0.1;
          setWaitTime(Math.max(0, t));
          if (t <= 0) {
              clearInterval(interval);
              startFlyingPhase();
          }
      }, 100);
  };

  const startFlyingPhase = () => {
      if (!isMounted.current) return;
      setLocalResult(null); // Clear previous notification

      if (nextRoundBetRef.current) {
          if (userBalance < betAmount) {
              nextRoundBetRef.current = false;
              setNextRoundBet(false);
              alert("Insufficient Balance for queued bet!");
          } else {
              activeBetRef.current = true;
              setActiveBet(true);
              nextRoundBetRef.current = false;
              setNextRoundBet(false);
              updateBalance(-betAmount, 'BET', 'Aviator');
              playSound('click');
          }
      }

      setPhase('FLYING');
      playSound('plane'); 

      const r = Math.random();
      let cp = 1.0;
      if (r < 0.3) cp = 1.0 + Math.random() * 0.5;
      else if (r < 0.6) cp = 1.5 + Math.random();
      else cp = 1.0 + Math.random() * 10; 
      crashPointRef.current = parseFloat(cp.toFixed(2));

      startTimeRef.current = Date.now();
      animateGame();
  };

  const animateGame = () => {
    if (!isMounted.current) return;
    const now = Date.now();
    const elapsed = (now - startTimeRef.current) / 1000;
    const currentMult = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.08);

    if (currentMult >= crashPointRef.current) {
        handleCrash(crashPointRef.current);
    } else {
        setMultiplier(currentMult);
        drawGraph(currentMult, elapsed, false);
        animationRef.current = requestAnimationFrame(animateGame);
    }
  };

  const handleCrash = (finalMult: number) => {
      if (!isMounted.current) return;
      setPhase('CRASHED');
      setMultiplier(finalMult);
      const finalElapsed = (Date.now() - startTimeRef.current) / 1000;
      drawGraph(finalMult, finalElapsed, true);
      playSound('loss');
      setHistory(prev => [finalMult, ...prev].slice(0, 15));

      if (activeBetRef.current) {
          activeBetRef.current = false;
          setActiveBet(false);
          addGameHistory('Aviator', betAmount, 0, `Crashed @ ${finalMult.toFixed(2)}x`);

          // Local top result
          setLocalResult({ win: false, amount: betAmount, show: true });

          onResult({
              win: false,
              amount: betAmount,
              game: 'Aviator',
              period: Date.now().toString(),
              resultDetails: [{label: 'Crash', value: `${finalMult.toFixed(2)}x`, color: 'bg-red-500'}]
          });
      }

      setTimeout(() => {
          if (isMounted.current) startWaitingPhase();
      }, 3000);
  };

  const handleBetAction = () => {
      if (phase === 'WAITING' || phase === 'CRASHED') {
          const newState = !nextRoundBetRef.current;
          if (newState && betAmount > userBalance) {
              alert("Insufficient Balance!");
              return;
          }
          nextRoundBetRef.current = newState;
          setNextRoundBet(newState);
      } else if (phase === 'FLYING') {
          if (activeBetRef.current) {
              const winAmount = betAmount * multiplier;
              updateBalance(winAmount, 'WIN', 'Aviator Win');
              activeBetRef.current = false;
              setActiveBet(false);
              playSound('win');
              addGameHistory('Aviator', betAmount, winAmount, `Cashed @ ${multiplier.toFixed(2)}x`);

              // Local top result
              setLocalResult({ win: true, amount: winAmount, show: true });

              onResult({
                win: true,
                amount: winAmount,
                game: 'Aviator',
                period: Date.now().toString(),
                resultDetails: [{label: 'Cashout', value: `${multiplier.toFixed(2)}x`, color: 'bg-green-500'}]
            });
          } else {
              const newState = !nextRoundBetRef.current;
              if (newState && betAmount > userBalance) {
                  alert("Insufficient Balance!");
                  return;
              }
              nextRoundBetRef.current = newState;
              setNextRoundBet(newState);
          }
      }
  };

  const drawGraph = (currentMult: number, elapsed: number, isCrash: boolean) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      canvas.width = window.innerWidth;
      const width = canvas.width;
      const height = canvas.height;

      ctx.clearRect(0, 0, width, height);
      const timeScale = Math.max(5, elapsed * 1.3); 
      const multScale = Math.max(2, currentMult * 1.3);

      const getX = (t: number) => (t / timeScale) * width;
      const getY = (m: number) => height - ((m - 1) / (multScale - 1)) * height;

      // Draw Grid
      ctx.strokeStyle = '#333';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      const step = Math.ceil(multScale / 5);
      for(let i=1; i<multScale; i+=step) {
          const y = getY(i);
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.fillStyle = '#666';
          ctx.font = '10px Arial';
          ctx.fillText(`${i}x`, 5, y - 5);
      }
      ctx.stroke();

      // Draw Curve
      ctx.beginPath();
      ctx.moveTo(0, height); 
      const plotStep = 0.05;
      for (let t = 0; t <= elapsed; t += plotStep) {
          const m = 1 + (t * 0.1) + (Math.pow(t, 2) * 0.08);
          ctx.lineTo(getX(t), getY(m));
      }

      const endX = getX(elapsed);
      const endY = getY(currentMult);
      ctx.lineTo(endX, endY);

      if (!isCrash) {
        ctx.lineTo(endX, height);
        ctx.lineTo(0, height);
        ctx.closePath();
        const gradient = ctx.createLinearGradient(0, endY, 0, height);
        gradient.addColorStop(0, 'rgba(239, 68, 68, 0.7)');
        gradient.addColorStop(1, 'rgba(127, 29, 29, 0.1)');
        ctx.fillStyle = gradient;
        ctx.fill();
      }

      ctx.beginPath();
      ctx.moveTo(0, height);
      for (let t = 0; t <= elapsed; t += plotStep) {
          const m = 1 + (t * 0.1) + (Math.pow(t, 2) * 0.08);
          ctx.lineTo(getX(t), getY(m));
      }
      ctx.lineTo(endX, endY);
      ctx.strokeStyle = '#ef4444'; 
      ctx.lineWidth = 4;
      ctx.stroke();

      if (!isCrash) {
        ctx.save();
        ctx.translate(endX, endY);
        const prevT = Math.max(0, elapsed - 0.1);
        const prevM = 1 + (prevT * 0.1) + (Math.pow(prevT, 2) * 0.08);
        const dy = getY(currentMult) - getY(prevM);
        const dx = getX(elapsed) - getX(prevT);
        const angle = Math.atan2(dy, dx);
        ctx.rotate(angle); 
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        ctx.moveTo(15, 0); ctx.lineTo(-10, 8); ctx.lineTo(-5, 0); ctx.lineTo(-10, -8);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white relative">
       {/* Animated Result Banner at Top */}
       {localResult && (
           <div className="absolute top-16 left-0 w-full z-[100] px-4 pointer-events-none animate-in slide-in-from-top duration-500">
               <div className={`flex items-center justify-between p-4 rounded-2xl shadow-2xl border backdrop-blur-md ${localResult.win ? 'bg-green-600/80 border-green-400 shadow-green-900/40' : 'bg-red-600/80 border-red-400 shadow-red-900/40'}`}>
                   <div className="flex items-center gap-3">
                       <div className="bg-white/20 p-2 rounded-full">
                           {localResult.win ? <TrendingUp size={24}/> : <TrendingDown size={24}/>}
                       </div>
                       <div>
                           <p className="text-[10px] font-black uppercase tracking-widest opacity-80">{localResult.win ? 'You Cashed Out' : 'Round Over'}</p>
                           <h4 className="text-xl font-black italic">{localResult.win ? 'WINNER' : 'ELIMINATED'}</h4>
                       </div>
                   </div>
                   <div className="text-right">
                       <p className="text-[10px] font-black uppercase opacity-60">Amount</p>
                       <p className="text-2xl font-black font-mono">₹{localResult.amount.toFixed(2)}</p>
                   </div>
               </div>
           </div>
       )}

       {/* Header */}
       <div className="bg-black p-2 flex items-center justify-between border-b border-gray-800 z-10">
        <div className="flex items-center gap-2">
            <button onClick={onBack} className="p-2 hover:bg-slate-800 rounded-full"><ArrowLeft className="text-gray-400" size={18}/></button>
            <span className="text-red-600 font-black italic text-2xl tracking-wider uppercase">Aviator</span>
        </div>
        <div className="flex gap-4 items-center">
             <div className="flex items-center gap-2 bg-gray-900 px-3 py-1 rounded-full border border-gray-700">
                 <Wallet size={14} className="text-green-500" />
                 <span className="text-sm font-bold">₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={handleToggleMute} className="p-1">
                 {muted ? <VolumeX size={20} className="text-gray-400" /> : <Volume2 size={20} className="text-gray-400" />}
             </button>
             <Menu size={20} className="text-gray-400"/>
        </div>
      </div>

      <div className="bg-[#1a1a1a] p-1 flex gap-1 overflow-x-auto no-scrollbar border-b border-gray-800">
          {history.map((m, i) => (
              <div key={i} className={`flex-shrink-0 px-3 py-1 rounded text-xs font-black font-mono bg-gray-800 border border-gray-700 ${m < 2 ? 'text-blue-400' : m < 10 ? 'text-purple-400' : 'text-pink-500'}`}>
                  {m.toFixed(2)}x
              </div>
          ))}
      </div>

      <div className="relative flex-1 bg-black flex flex-col overflow-hidden">
        {phase === 'WAITING' && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-[1px]">
                 <div className="text-xl font-black uppercase tracking-[0.3em] text-gray-400 mb-4 animate-pulse">Waiting for next round</div>
                 <div className="w-64 h-1.5 bg-gray-800 rounded-full overflow-hidden border border-white/5">
                     <div className="h-full bg-red-600 transition-all duration-100 ease-linear shadow-[0_0_10px_rgba(220,38,38,0.5)]" style={{ width: `${(waitTime / 5) * 100}%` }}></div>
                 </div>
            </div>
        )}

        {(phase === 'FLYING' || phase === 'CRASHED') && (
             <div className="absolute top-[20%] left-1/2 -translate-x-1/2 z-20 text-center">
                 {phase === 'CRASHED' && <div className="text-red-600 font-black text-2xl uppercase mb-1 tracking-widest animate-in zoom-in duration-200">FLEW AWAY!</div>}
                 <div className={`text-7xl sm:text-8xl font-black drop-shadow-2xl font-mono tracking-tighter ${phase === 'CRASHED' ? 'text-red-600' : 'text-white'}`}>
                     {multiplier.toFixed(2)}x
                 </div>
             </div>
        )}

        <canvas ref={canvasRef} height={400} className="absolute inset-0 z-10 w-full h-full" />
      </div>

      <div className="bg-[#151515] p-2 sm:p-4 border-t-2 border-red-600 z-30 shadow-[0_-10px_30px_rgba(0,0,0,0.5)]">
          <div className="bg-[#0a0a0a] rounded-2xl p-3 border border-white/5 relative overflow-hidden">
               <div className="flex flex-row gap-3 h-auto items-stretch">
                   <div className="flex-[2] flex flex-col justify-center min-w-0">
                       <div className="flex items-center bg-[#1a1a1a] rounded-xl border border-gray-800 h-12 sm:h-14 relative shadow-inner">
                           <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} disabled={activeBet} className="w-10 sm:w-12 h-full text-gray-500 text-2xl font-black">-</button>
                           <input type="number" value={betAmount} readOnly className="flex-1 bg-transparent text-center text-white font-black text-lg sm:text-xl outline-none" />
                           <button onClick={() => setBetAmount(betAmount + 10)} disabled={activeBet} className="w-10 sm:w-12 h-full text-gray-500 text-2xl font-black">+</button>
                       </div>
                       <div className="flex gap-1.5 mt-2">
                           {[100, 500, 1000].map(amt => (
                               <button key={amt} onClick={() => !activeBet && setBetAmount(amt)} className="flex-1 py-2 bg-[#1a1a1a] rounded-lg text-[10px] font-black text-gray-500 border border-gray-800 hover:text-white transition-all">{amt}</button>
                           ))}
                       </div>
                   </div>

                   <button 
                        onClick={handleBetAction}
                        className={`flex-[2] sm:w-48 rounded-xl flex flex-col items-center justify-center shadow-2xl transition-all active:scale-95 px-2 py-3 border-b-4 ${
                            activeBet && phase === 'FLYING'
                            ? 'bg-orange-500 border-orange-700 hover:bg-orange-400' 
                            : activeBet || nextRoundBet 
                                ? 'bg-red-700 border-red-900 shadow-none translate-y-0.5' 
                                : 'bg-green-600 border-green-800 hover:bg-green-500' 
                        }`}
                   >
                        <span className="text-white font-black text-xs sm:text-sm uppercase leading-none mb-1 tracking-widest">
                            {activeBet && phase === 'FLYING' ? 'CASH OUT' : (activeBet || nextRoundBet ? 'CANCEL' : 'STAKE BET')}
                        </span>
                        {activeBet && phase === 'FLYING' ? (
                            <span className="text-white font-black text-lg sm:text-2xl leading-none font-mono">₹{(betAmount * multiplier).toFixed(2)}</span>
                        ) : (
                            <span className="text-white/80 font-black text-sm sm:text-lg leading-none font-mono">{betAmount} INR</span>
                        )}
                   </button>
               </div>

               {nextRoundBet && phase !== 'WAITING' && (
                   <div className="absolute inset-0 bg-black/90 backdrop-blur-[2px] flex items-center justify-center z-10 animate-in fade-in">
                       <div className="text-red-500 font-black uppercase tracking-[0.2em] text-xs border-2 border-red-500 px-6 py-2 rounded-full bg-black shadow-[0_0_20px_rgba(239,68,68,0.3)]">Queued for next round</div>
                   </div>
               )}
          </div>
      </div>
    </div>
  );
};

export default Aviator;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, PlayCircle } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

interface Ball {
  id: string;
  x: number;
  y: number;
  row: number;
  col: number;
  bet: number;
  status: 'DROPPING' | 'DONE';
  targetX: number;
  targetY: number;
  progress: number;
  startPos: { x: number; y: number };
}

interface PinPulse {
  row: number;
  col: number;
  startTime: number;
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 9; 
const PIN_RADIUS = 5;
const BALL_RADIUS = 8;
const CANVAS_WIDTH = 380;
const CANVAS_HEIGHT = 540;

const Plinko: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const pulsesRef = useRef<PinPulse[]>([]);
  const requestRef = useRef<number>(0);
  const [activeBallCount, setActiveBallCount] = useState(0);

  // Local floating result state
  const [floatingResult, setFloatingResult] = useState<{ id: string; mult: number; amount: number } | null>(null);

  const startY = 110;
  const rowSpacing = 40;
  const colSpacing = 36;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      updatePhysics();
      draw(ctx);
      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, []);

  const getPinCoords = (row: number, col: number) => {
    const pinsInRow = row + 1;
    const rowWidth = (pinsInRow - 1) * colSpacing;
    const startX = (CANVAS_WIDTH - rowWidth) / 2;
    return {
      x: startX + col * colSpacing,
      y: startY + row * rowSpacing
    };
  };

  const updatePhysics = () => {
    const slotY = startY + ROWS * rowSpacing + 20;
    const speed = 0.12; 

    ballsRef.current = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;

      ball.progress += speed;

      if (ball.progress >= 1) {
        ball.x = ball.targetX;
        ball.y = ball.targetY;
        ball.progress = 0;
        ball.startPos = { x: ball.x, y: ball.y };

        if (ball.row < ROWS - 1) {
          pulsesRef.current.push({ row: ball.row, col: ball.col, startTime: Date.now() });
          playSound('tick');

          const nextRow = ball.row + 1;
          const moveRight = Math.random() > 0.49 ? 1 : 0;
          const nextCol = ball.col + moveRight;
          const coords = getPinCoords(nextRow, nextCol);

          return {
            ...ball,
            row: nextRow,
            col: nextCol,
            targetX: coords.x,
            targetY: coords.y
          };
        } else {
          if (ball.y < slotY) {
            pulsesRef.current.push({ row: ball.row, col: ball.col, startTime: Date.now() });
            playSound('tick');
            return {
              ...ball,
              targetY: slotY + 25, 
              targetX: ball.x,
              row: ROWS 
            };
          } else {
            handleBallLand(ball);
            return { ...ball, status: 'DONE' };
          }
        }
      }

      const t = ball.progress;
      const arcHeight = 10; 
      ball.x = ball.startPos.x + (ball.targetX - ball.startPos.x) * t;
      const linearY = ball.startPos.y + (ball.targetY - ball.startPos.y) * t;
      const offset = -4 * arcHeight * t * (t - 1);
      ball.y = linearY - offset;

      return ball;
    }).filter(b => b.status === 'DROPPING');

    pulsesRef.current = pulsesRef.current.filter(p => Date.now() - p.startTime < 400);
    if (ballsRef.current.length !== activeBallCount) setActiveBallCount(ballsRef.current.length);
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 1;
      const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;

      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing;
        const py = startY + r * rowSpacing;

        const pulse = pulsesRef.current.find(pulse => pulse.row === r && pulse.col === p);
        const scale = pulse ? 1 + 0.5 * Math.sin((Date.now() - pulse.startTime) / 40) : 1;

        ctx.beginPath();
        ctx.arc(px, py, PIN_RADIUS * scale, 0, Math.PI * 2);
        ctx.fillStyle = pulse ? '#60A5FA' : 'rgba(203, 213, 225, 0.8)';
        ctx.shadowBlur = pulse ? 25 : 4;
        ctx.shadowColor = '#60A5FA';
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }

    const slotY = startY + ROWS * rowSpacing + 20;
    const slotWidth = colSpacing - 4;
    const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 4) / 2;

    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      const color = m >= 5 ? '#ef4444' : m >= 1.2 ? '#f97316' : m >= 1 ? '#22c55e' : '#3b82f6';

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(sx, slotY, slotWidth, 40, 8);
      ctx.fill();

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + slotWidth / 2, slotY + 25);
    });

    ballsRef.current.forEach(ball => {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#fbbf24'; 
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#f59e0b';
      ctx.fill();
      ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;

    updateBalance(winAmount, 'WIN', `Plinko ${multiplier}x`);
    playSound(multiplier >= 1 ? 'win' : 'click');

    // Show local floating result
    const rid = Math.random().toString(36).substr(2, 5);
    setFloatingResult({ id: rid, mult: multiplier, amount: winAmount });
    setTimeout(() => {
        setFloatingResult(null);
    }, 2500);

    onResult({
        win: multiplier >= 1,
        amount: winAmount,
        game: 'Plinko',
        resultDetails: [{ label: 'Multiplier', value: `${multiplier}x` }]
    });

    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) { alert("Insufficient Balance!"); return; }
    playSound('click');
    updateBalance(-betAmount, 'BET', 'Plinko Stake');
    const startCoords = getPinCoords(0, 0);
    const newBall: Ball = {
      id: Math.random().toString(36).substr(2, 9),
      x: CANVAS_WIDTH / 2,
      y: 30,
      row: 0,
      col: 0, 
      bet: betAmount,
      status: 'DROPPING',
      targetX: startCoords.x,
      targetY: startCoords.y,
      progress: 0,
      startPos: { x: CANVAS_WIDTH / 2, y: 30 }
    };
    ballsRef.current.push(newBall);
    setActiveBallCount(ballsRef.current.length);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      {/* Local Top Result Notification */}
      {floatingResult && (
          <div className="absolute top-20 left-1/2 -translate-x-1/2 z-[100] w-full px-10 pointer-events-none animate-in fade-in zoom-in duration-300">
               <div className={`py-4 px-6 rounded-full border-2 shadow-2xl flex items-center justify-center gap-4 backdrop-blur-md ${floatingResult.mult >= 1 ? 'bg-green-600/80 border-green-400 shadow-green-500/20' : 'bg-red-600/80 border-red-400 shadow-red-500/20'}`}>
                   <span className="font-black italic text-xl tracking-tighter">{floatingResult.mult}x</span>
                   <div className="w-[1px] h-6 bg-white/20"></div>
                   <span className="font-black text-2xl">₹{floatingResult.amount.toFixed(2)}</span>
               </div>
          </div>
      )}

      <div className="p-4 flex justify-between items-center bg-[#111827]/95 backdrop-blur-xl border-b border-white/5 shadow-2xl relative z-50">
        <button onClick={onBack} className="p-2.5 bg-slate-800/80 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">PLINKO</h1>
            <p className="text-[8px] text-slate-500 font-bold uppercase tracking-[0.2em]">Fast Fidelity Arena</p>
        </div>
