import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, ShieldAlert, Circle, Square, Triangle, Zap } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

// 12 Segments per ring - Hierarchy based on position
const BOARD_CONFIG = {
    outer: ['200X', '150X', 'MASK', '120X', '100X', 'MASK', '180X', '90X', 'MASK', '133X', '50X', 'MASK'],
    mid: ['44X', '30X', '20X', 'MASK', '25X', '15X', '40X', 'MASK', '35X', '12X', 'MASK', '28X'],
    inner: ['7.7X', '5.5X', '3.2X', '1.5X', 'MASK', '6.8X', '4.4X', '2.5X', 'MASK', '7.0X', '3.9X', 'MASK']
};

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [beamRotation, setBeamRotation] = useState(0); 
  const [isHolding, setIsHolding] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<string[]>(['120X', '1.5X', '44X']);

  const spinInterval = useRef<number | null>(null);
  const currentRotation = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (spinInterval.current) clearInterval(spinInterval.current);
      stopAllSounds();
    };
  }, []);

  const handleStartHold = () => {
    if (userBalance < betAmount || isSpinning) return;
    setIsHolding(true);
    setIsSpinning(true);
    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Squid Vortex Stake');

    spinInterval.current = window.setInterval(() => {
        currentRotation.current += 30; // Speed of rotation
        setBeamRotation(currentRotation.current);
    }, 20);
  };

  const handleRelease = () => {
    if (!isHolding) return;
    setIsHolding(false);
    if (spinInterval.current) {
        clearInterval(spinInterval.current);
        spinInterval.current = null;
    }

    // Smooth deceleration
    const extraDegrees = 1200 + Math.random() * 800;
    const finalRotation = currentRotation.current + extraDegrees;

    setBeamRotation(finalRotation);
    currentRotation.current = finalRotation;

    setTimeout(() => {
        if (!isMounted.current) return;
        setIsSpinning(false);
        calculateFinalResult(finalRotation);
    }, 2500); 
  };

  const calculateFinalResult = (deg: number) => {
    const normalized = (deg % 360);
    // The pointer starts at top (0 deg). 12 segments = 30 deg each.
    const segmentWidth = 30;
    const index = Math.floor((normalized + 15) / segmentWidth) % 12;

    // Result logic: We use the Outer Ring as the primary win indicator
    const resultLabel = BOARD_CONFIG.outer[index];

    if (resultLabel === 'MASK' || Math.random() < 0.1) {
        playSound('loss');
        onResult({
            win: false,
            amount: betAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Result', value: 'ELIMINATED', color: 'text-red-500' }]
        });
        addGameHistory('Squid Vortex', betAmount, 0, 'Eliminated');
    } else {
        const multiplier = parseFloat(resultLabel.replace('X', ''));
        const winAmount = betAmount * multiplier;
        updateBalance(winAmount, 'WIN', 'Vortex Win');
        playSound('win');
        setHistory(prev => [resultLabel, ...prev].slice(0, 10));
        onResult({
            win: true,
            amount: winAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Landed', value: resultLabel, color: 'text-yellow-400' }]
        });
        addGameHistory('SquidVortex', betAmount, winAmount, `Hit ${resultLabel}`);
    }
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      {/* Dynamic Background */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(220,38,38,0.1)_0%,_transparent_70%)] pointer-events-none"></div>

      {/* Top Header */}
      <div className="p-4 flex justify-between items-center bg-black/80 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 border border-white/10 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-lg font-black tracking-[0.2em] uppercase italic gold-text">VORTEX ARENA</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Multi-Ring High Payout</p>
        </div>
        <div className="flex items-center gap-2 bg-zinc-900/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Symbols Decor */}
      <div className="flex justify-center gap-12 py-4 relative z-10 opacity-20">
          <Circle size={20}/>
          <Triangle size={20} className="rotate-12"/>
          <Square size={20}/>
      </div>

      {/* Main Game Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {/* Fixed Red Pointer Bar (Target) */}
        <div className="absolute top-[5%] left-1/2 -translate-x-1/2 z-40 flex flex-col items-center">
             <div className="w-8 h-8 bg-red-600 rounded-full border-4 border-white shadow-[0_0_30px_rgba(220,38,38,1)] flex items-center justify-center animate-pulse">
                 <div className="w-2 h-2 bg-white rounded-full"></div>
             </div>
             <div className="w-1.5 h-12 bg-gradient-to-b from-red-600 to-transparent"></div>
        </div>

        {/* Triple Ring Board Container */}
        <div className="relative w-[340px] h-[340px] md:w-[400px] md:h-[400px] flex items-center justify-center">

            {/* STATIC BOARD STRUCTURE */}
            <div className="absolute inset-0 rounded-full border-[12px] border-zinc-800 shadow-[0_0_80px_rgba(0,0,0,1)] bg-[#080808] overflow-hidden">
                {/* Visual Ring Dividers */}
                <div className="absolute inset-[15%] rounded-full border border-white/5 bg-zinc-900/20"></div>
                <div className="absolute inset-[35%] rounded-full border border-white/5 bg-zinc-900/40"></div>

                {/* Outer Ring Multipliers (Static) */}
                {BOARD_CONFIG.outer.map((label, i) => (
                    <div key={`outer-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-5 origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        {label === 'MASK' ? <ShieldAlert size={16} className="text-red-600" /> : <span className="text-xs font-black italic tracking-tighter text-white/80">{label}</span>}
                    </div>
                ))}

                {/* Middle Ring Multipliers (Static) */}
                {BOARD_CONFIG.mid.map((label, i) => (
                    <div key={`mid-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-[100px] origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        {label === 'MASK' ? <ShieldAlert size={12} className="text-red-600/40" /> : <span className="text-[10px] font-black italic text-zinc-500">{label}</span>}
                    </div>
                ))}

                {/* Inner Ring Multipliers (Static) */}
                {BOARD_CONFIG.inner.map((label, i) => (
                    <div key={`inner-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-[155px] origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        {label === 'MASK' ? <ShieldAlert size={10} className="text-red-600/20" /> : <span className="text-[9px] font-bold text-zinc-700">{label}</span>}
                    </div>
                ))}
            </div>

            {/* ROTATING NEON BEAM (SELECTOR) */}
            <div 
                className="absolute inset-0 pointer-events-none z-20"
                style={{ 
                    transform: `rotate(${beamRotation}deg)`,
                    transition: isHolding ? 'none' : 'transform 2.5s cubic-bezier(0.1, 0, 0.1, 1)' 
                }}
            >
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[4px] h-1/2 bg-gradient-to-b from-yellow-400 via-yellow-500/20 to-transparent shadow-[0_0_20px_rgba(234,179,8,0.5)]"></div>
                <div className="absolute top-2 left-1/2 -translate-x-1/2 w-4 h-4 bg-yellow-400 rounded-full blur-md"></div>
            </div>

            {/* ROTATING CENTER CORE (CHARACTER) */}
            <div className="absolute inset-0 flex items-center justify-center z-30 pointer-events-none">
                <div 
                    className="w-28 h-28 rounded-full bg-zinc-900 border-4 border-zinc-800 shadow-[inset_0_0_30px_rgba(0,0,0,1),0_0_40px_rgba(0,0,0,0.5)] flex items-center justify-center overflow-hidden"
                    style={{ 
                        transform: `rotate(${beamRotation * 1.2}deg)`,
                        transition: isHolding ? 'none' : 'transform 0.8s ease-out'
                    }}
                >
                    <img 
                        src="https://api.dicebear.com/7.x/avataaars/svg?seed=SquidDoll&backgroundColor=b6e3f4&top=longHair&hairColor=262e33&skinColor=f8d25c" 
                        className="w-24 h-24 object-contain" 
                        alt="Squid Doll" 
                    />
                </div>
            </div>
        </div>

        {/* History Display */}
        <div className="mt-12 text-center">
            <h2 className="text-2xl font-black italic gold-text tracking-tighter uppercase mb-2">SQUID VORTEX</h2>
            <div className="flex gap-2 justify-center">
                {history.map((h, i) => (
                    <span key={i} className={`text-[9px] font-black px-2 py-0.5 rounded-md border border-white/5 ${h.includes('X') ? 'text-green-500 bg-green-500/5' : 'text-red-500 bg-red-500/5'}`}>{h}</span>
                ))}
            </div>
        </div>
      </div>

      {/* Control Panel */}
      <div className="bg-[#0a0a0a] border-t border-white/5 p-6 pb-12 z-50 shadow-[0_-20px_50px_rgba(0,0,0,0.8)]">
          <div className="flex justify-between items-center mb-6 px-2">
              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button 
                        key={amt}
                        onClick={() => !isSpinning && setBetAmount(amt)}
                        className={`w-14 h-11 rounded-2xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-red-600 text-white border-red-400 shadow-xl' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}
                      >
                        {amt}
