import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

// 12 Segments - These are STATIC on the board
const BOARD_DATA = {
    outer: ['200X', '150X', 'MASK', '120X', '100X', 'MASK', '180X', '90X', 'MASK', '133X', '50X', 'MASK'],
    mid: ['44X', '30X', '20X', 'MASK', '25X', '15X', '40X', 'MASK', '35X', '12X', 'MASK', '28X'],
    inner: ['7.7X', '5.5X', '3.2X', '1.5X', 'MASK', '6.8X', '4.4X', '2.5X', 'MASK', '7.0X', '3.9X', 'MASK']
};

const SquidVortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [isHolding, setIsHolding] = useState(false);
  const [beamRotation, setBeamRotation] = useState(0); 
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<string[]>(['120X', '1.5X', 'MASK']);
  const [localResult, setLocalResult] = useState<{ win: boolean; amount: number; mult: string } | null>(null);

  const spinRef = useRef<number>(0);
  const velocityRef = useRef<number>(0);
  const requestRef = useRef<number>(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    const animate = () => {
        if (isHolding) {
            // Accelerate while holding
            velocityRef.current = Math.min(velocityRef.current + 0.8, 25);
        } else {
            // Decelerate when released
            velocityRef.current *= 0.985;
            if (velocityRef.current < 0.1 && isSpinning) {
                velocityRef.current = 0;
                finalizeGame();
            }
        }

        spinRef.current += velocityRef.current;
        setBeamRotation(spinRef.current);
        requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      isMounted.current = false;
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, [isHolding, isSpinning]);

  const startHolding = () => {
    if (userBalance < betAmount || isSpinning) return;
    setLocalResult(null);
    setIsHolding(true);
    setIsSpinning(true);
    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Squid Vortex Stake');
  };

  const stopHolding = () => {
    if (!isHolding) return;
    setIsHolding(false);
    // Game is still "isSpinning: true" until velocity hits 0 in the animation loop
  };

  const finalizeGame = () => {
    if (!isMounted.current) return;
    setIsSpinning(false);

    // Calculate which of the 12 segments the beam is pointing at
    const normalizedRotation = (spinRef.current % 360);
    const segmentWidth = 30; // 360 / 12
    const index = Math.floor((normalizedRotation + 15) / segmentWidth) % 12;

    // Result based on Outer Ring (Primary)
    const resultLabel = BOARD_DATA.outer[index];

    if (resultLabel === 'MASK' || Math.random() < 0.12) {
        playSound('loss');
        setLocalResult({ win: false, amount: betAmount, mult: 'ELIMINATED' });
        onResult({
            win: false,
            amount: betAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Result', value: 'MASK', color: 'text-red-500' }]
        });
        addGameHistory('Squid Vortex', betAmount, 0, 'Hit MASK Guard');
    } else {
        const multVal = parseFloat(resultLabel.replace('X', ''));
        const winAmount = betAmount * multVal;

        updateBalance(winAmount, 'WIN', 'Vortex Win');
        playSound('win');
        setHistory(prev => [resultLabel, ...prev].slice(0, 8));
        setLocalResult({ win: true, amount: winAmount, mult: resultLabel });

        onResult({
            win: true,
            amount: winAmount,
            game: 'Squid Vortex',
            resultDetails: [{ label: 'Landed', value: resultLabel, color: 'text-yellow-400' }]
        });
        addGameHistory('Squid Vortex', betAmount, winAmount, `Hit ${resultLabel}`);
    }

    // Clear notification after few seconds
    setTimeout(() => {
        if(isMounted.current) setLocalResult(null);
    }, 3000);
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      {/* Animated Top Result Banner (Same as Aviator style) */}
      {localResult && (
          <div className="absolute top-16 left-0 w-full z-[100] px-4 pointer-events-none animate-in slide-in-from-top duration-500">
               <div className={`flex items-center justify-between p-4 rounded-2xl shadow-2xl border backdrop-blur-md ${localResult.win ? 'bg-green-600/90 border-green-400 shadow-green-900/40' : 'bg-red-600/90 border-red-400 shadow-red-900/40'}`}>
                   <div className="flex items-center gap-3">
                       <div className="bg-white/20 p-2 rounded-full">
                           {localResult.win ? <TrendingUp size={24}/> : <TrendingDown size={24}/>}
                       </div>
                       <div>
                           <p className="text-[10px] font-black uppercase tracking-widest opacity-80">{localResult.win ? 'Vortex Victory' : 'Game Over'}</p>
                           <h4 className="text-xl font-black italic">{localResult.mult}</h4>
                       </div>
                   </div>
                   <div className="text-right">
                       <p className="text-[10px] font-black uppercase opacity-60">Payout</p>
                       <p className="text-2xl font-black font-mono">₹{localResult.amount.toFixed(2)}</p>
                   </div>
               </div>
          </div>
      )}

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/80 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-lg font-black tracking-[0.2em] uppercase italic gold-text">VORTEX ARENA</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Elite Squid Challenge</p>
        </div>
        <div className="flex items-center gap-2 bg-zinc-900/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Symbols Decoration */}
      <div className="flex justify-center gap-12 py-4 relative z-10 opacity-20">
          <div className="w-8 h-8 border-2 border-white rounded-full"></div>
          <div className="w-8 h-8 border-2 border-white rotate-45"></div>
          <div className="w-8 h-8 border-2 border-white"></div>
      </div>

      {/* Main Game Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">

        {/* The Board (Static) */}
        <div className="relative w-80 h-80 md:w-96 md:h-96 flex items-center justify-center">

            {/* STATIC RINGS */}
            <div className="absolute inset-0 rounded-full border-[12px] border-zinc-800 shadow-[0_0_80px_rgba(0,0,0,1)] bg-[#080808] overflow-hidden">
                {/* Visual Dividers */}
                <div className="absolute inset-[18%] rounded-full border border-white/5 bg-zinc-900/20"></div>
                <div className="absolute inset-[38%] rounded-full border border-white/5 bg-zinc-900/40"></div>

                {/* Outer Ring Labels (Static) */}
                {BOARD_DATA.outer.map((label, i) => (
                    <div key={`o-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-5 origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        {label === 'MASK' ? <ShieldAlert size={16} className="text-red-600 animate-pulse" /> : <span className="text-xs font-black italic text-white/60 drop-shadow-md">{label}</span>}
                    </div>
                ))}

                {/* Mid Ring Labels (Static) */}
                {BOARD_DATA.mid.map((label, i) => (
                    <div key={`m-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-[100px] origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        {label === 'MASK' ? <ShieldAlert size={12} className="text-red-600/40" /> : <span className="text-[10px] font-black italic text-zinc-600">{label}</span>}
