const SYMBOLS = ['💎', '🎰', '🔔', '🍒', '🍋', '🍇', '7️⃣'];
const REEL_COUNT = 3;

const SlotMachine: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [reels, setReels] = useState<string[]>(['💎', '7️⃣', '💎']);
  const [history, setHistory] = useState<string[]>([]);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      stopAllSounds();
    };
  }, []);

  const spin = async () => {
    if (isSpinning || userBalance < betAmount) return;

    setIsSpinning(true);
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Slot Machine Spin');

    // Reel animation simulation
    let count = 0;
    const interval = setInterval(() => {
        setReels([
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
        ]);
        count++;
        if (count > 20) {
            clearInterval(interval);
            finalizeSpin();
        }
    }, 100);
  };

  const finalizeSpin = () => {
    if (!isMounted.current) return;

    const result = [
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
    ];
    setReels(result);
    setIsSpinning(false);

    // Winning Logic
    const isJackpot = result[0] === result[1] && result[1] === result[2];
    const isPair = result[0] === result[1] || result[1] === result[2] || result[0] === result[2];

    let multiplier = 0;
    if (isJackpot) {
        multiplier = result[0] === '7️⃣' ? 50 : 20;
    } else if (isPair) {
        multiplier = 2;
    }

    const winAmount = betAmount * multiplier;
    if (winAmount > 0) {
        updateBalance(winAmount, 'WIN', 'Slot Machine Win');
        playSound('win');
        onResult({
            win: true,
            amount: winAmount,
            game: 'Slot Machine',
            resultDetails: [{ label: 'Result', value: isJackpot ? 'JACKPOT!' : 'PAIR!' }]
        });
    } else {
        playSound('loss');
        onResult({
            win: false,
            amount: betAmount,
            game: 'Slot Machine',
            resultDetails: [{ label: 'Landed', value: 'Better Luck' }]
        });
    }

    setHistory(prev => [result.join(' '), ...prev].slice(0, 5));
    addGameHistory('Slot Machine', betAmount, winAmount, `Landed ${result.join(' ')}`);
  };

  return (
    <div className="bg-[#111111] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
