      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,_rgba(139,92,246,0.15)_0%,_transparent_60%)] pointer-events-none"></div>

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/60 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">VEGAS SLOTS</h1>
        </div>
        <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6">
        {/* Machine Housing */}
        <div className="w-full max-w-sm bg-gradient-to-b from-zinc-800 to-zinc-950 p-6 rounded-[3rem] border-[8px] border-zinc-700 shadow-[0_0_80px_rgba(0,0,0,1)] relative overflow-hidden">
             <div className="absolute top-2 left-1/2 -translate-x-1/2 flex gap-4">
                 <Star size={16} className="text-yellow-500 fill-yellow-500 animate-pulse" />
                 <Star size={16} className="text-yellow-500 fill-yellow-500 animate-pulse delay-75" />
                 <Star size={16} className="text-yellow-500 fill-yellow-500 animate-pulse delay-150" />
             </div>

             {/* Reels Display */}
             <div className="bg-black/90 p-4 rounded-[2rem] flex justify-between gap-3 border-4 border-yellow-500/20 shadow-inner mt-4">
                {reels.map((symbol, i) => (
                    <div key={i} className="flex-1 h-32 bg-white rounded-2xl flex items-center justify-center text-5xl shadow-2xl animate-in zoom-in duration-300">
                        {symbol}
                    </div>
                ))}
             </div>

             <div className="mt-8 flex justify-center">
                 <div className="bg-yellow-500/10 px-8 py-2 rounded-full border border-yellow-500/30">
                    <p className="text-[10px] font-black uppercase text-yellow-500 tracking-[0.3em] text-center">Winning Line</p>
                 </div>
