                    <span className="text-yellow-500">2X</span>
                </div>
            </div>
        </div>
      </div>

      {/* Controls */}
      <div className="bg-[#111111] p-6 pb-12 border-t border-white/10 shadow-[0_-10px_40px_rgba(0,0,0,1)]">
