              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button 
                        key={amt} 
                        onClick={() => !isSpinning && setBetAmount(amt)}
                        className={`w-14 h-11 rounded-xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-600 text-black border-white shadow-lg' : 'bg-zinc-900 text-slate-500 border-white/5'}`}
