import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Timer, Trophy, History, Zap, Bike } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

type GameState = 'BETTING' | 'RACING' | 'RESULT';

const BIKES = [1, 2, 3, 4, 5, 6];
const COLORS = ['#ef4444', '#3b82f6', '#22c55e', '#eab308', '#a855f7', '#f97316'];

// Custom Motorcycle SVG Component
const Motorbike = ({ color, isRacing }: { color: string, isRacing: boolean }) => (
  <div className={`relative transition-transform duration-300 ${isRacing ? 'rotate-[-5deg] scale-110' : ''}`}>
    <svg width="48" height="32" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M19 15C19 16.6569 17.6569 18 16 18C14.3431 18 13 16.6569 13 15C13 13.3431 14.3431 12 16 12C17.6569 12 19 13.3431 19 15Z" fill={color} />
        <path d="M7 15C7 16.6569 5.65685 18 4 18C2.34315 18 1 16.6569 1 15C1 13.3431 2.34315 12 4 12C5.65685 12 7 13.3431 7 15Z" fill={color} />
        <path d="M16 15L10 15L8 9L15 9L16 15Z" fill={color} opacity="0.8"/>
        <path d="M8 9H12L13 5H10L8 9Z" fill="white" />
        <path d="M13 5L15 3H18" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
