        </div>
    )}
  </div>
);

const MotoRacing: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [gameState, setGameState] = useState<GameState>('BETTING');
  const [timeLeft, setTimeLeft] = useState(10);
  const [selectedBike, setSelectedBike] = useState<number | null>(null);
  const [betAmount, setBetAmount] = useState(10);
  const [betPlaced, setBetPlaced] = useState(false);
  const [bikePositions, setBikePositions] = useState<number[]>(new Array(6).fill(0));
  const [winner, setWinner] = useState<number | null>(null);
  // Pre-populate fake history
  const [history, setHistory] = useState<number[]>([]);

  const raceInterval = useRef<number | null>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    // Generate 12 initial history items
    const fakeHistory = Array.from({ length: 12 }, () => Math.floor(Math.random() * 6) + 1);
    setHistory(fakeHistory);

    startNewRound();
    return () => {
      isMounted.current = false;
      if (raceInterval.current) clearInterval(raceInterval.current);
      stopAllSounds();
    };
  }, []);

  const startNewRound = () => {
    if (!isMounted.current) return;
    setGameState('BETTING');
    setTimeLeft(10);
    setBikePositions(new Array(6).fill(0));
    setWinner(null);
    setSelectedBike(null);
    setBetPlaced(false);
  };

  useEffect(() => {
    if (gameState === 'BETTING' && timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(prev => prev - 1), 1000);
      if (timeLeft <= 3) playSound('tick');
      return () => clearTimeout(timer);
    } else if (gameState === 'BETTING' && timeLeft === 0) {
      startRace();
    }
  }, [timeLeft, gameState]);

  const placeBet = () => {
    if (!selectedBike || betPlaced || userBalance < betAmount) return;
    playSound('click');
    updateBalance(-betAmount, 'BET', `Moto Racing Bike ${selectedBike}`);
    setBetPlaced(true);
  };

  const startRace = () => {
    if (!isMounted.current) return;
    setGameState('RACING');
    playSound('spin');

    const interval = window.setInterval(() => {
      setBikePositions(prev => {
        const next = [...prev];
        let foundWinner = false;

        for (let i = 0; i < 6; i++) {
          // Dynamic acceleration: start slow, build up, tiny random variations
          const baseSpeed = 0.6;
          const accel = Math.random() * 0.9;
          const jitter = Math.random() * 0.3;
          next[i] += baseSpeed + accel + jitter;

          if (next[i] >= 88) { // Checked Finish Line starts at ~88%
            foundWinner = true;
            finishRace(i + 1);
            break;
          }
        }
        return foundWinner ? prev : next;
      });
    }, 50); 
    raceInterval.current = interval;
  };

  const finishRace = (bikeNum: number) => {
    if (raceInterval.current) {
        clearInterval(raceInterval.current);
        raceInterval.current = null;
    }

    setGameState('RESULT');
    setWinner(bikeNum);
    setHistory(prev => [bikeNum, ...prev].slice(0, 12));

    if (betPlaced && selectedBike === bikeNum) {
      const winAmount = betAmount * 5;
      updateBalance(winAmount, 'WIN', 'Moto Racing Victory');
      playSound('win');
      onResult({
        win: true,
        amount: winAmount,
        game: 'Moto Racing',
        resultDetails: [{ label: 'Winner', value: `Bike ${bikeNum}` }]
      });
    } else if (betPlaced) {
      playSound('loss');
      onResult({
        win: false,
        amount: betAmount,
        game: 'Moto Racing',
        resultDetails: [{ label: 'Winner', value: `Bike ${bikeNum}` }]
      });
    }

    addGameHistory('Moto Racing', betPlaced ? betAmount : 0, (betPlaced && selectedBike === bikeNum) ? betAmount * 5 : 0, `Bike ${bikeNum} Won`);

    setTimeout(() => {
      if (isMounted.current) startNewRound();
    }, 5000);
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-white/5 z-50 shadow-xl">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 transition-all border border-white/10"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black gold-text italic tracking-widest uppercase">MOTO GP CLUB</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Elite Racing Arena</p>
        </div>
        <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Racetrack View */}
      <div className="flex-1 bg-[#111] p-4 flex flex-col gap-2 relative overflow-hidden justify-center">
        {/* Track Markings */}
        <div className="absolute inset-0 pointer-events-none opacity-5">
            {Array.from({length: 15}).map((_, i) => (
                <div key={i} className="h-full w-[1px] bg-white absolute top-0" style={{ left: `${(i+1)*6.66}%` }}></div>
            ))}
        </div>

        {BIKES.map((bike, idx) => (
          <div key={bike} className="h-16 bg-[#1a1a1a] rounded-xl relative flex items-center border border-white/5 overflow-hidden shadow-inner">
            <div className="w-12 h-full flex items-center justify-center text-sm font-black text-zinc-700 border-r border-white/5 z-10 bg-[#222] italic">{bike}</div>

            {/* The Bike Sprite */}
            <div 
              className="absolute h-10 w-16 flex items-center justify-center transition-all duration-75 ease-linear"
              style={{ left: `calc(48px + ${bikePositions[idx]}%)`, transform: 'translateY(-50%)', top: '50%' }}
            >
              <Motorbike color={COLORS[idx]} isRacing={gameState === 'RACING'} />
            </div>

            {gameState === 'RESULT' && winner === bike && (
                <div className="absolute right-12 text-yellow-500 animate-bounce flex items-center gap-2 z-20">
                    <Trophy size={28} className="fill-yellow-500/20 shadow-yellow-500/50" />
                </div>
            )}

            {/* CHECKERED FINISH LINE ZONE */}
            <div className="absolute right-0 h-full w-20 flex flex-wrap opacity-40">
                {Array.from({length: 24}).map((_, i) => (
                    <div key={i} className={`w-5 h-4 ${ (Math.floor(i/4) + (i%4)) % 2 === 0 ? 'bg-white' : 'bg-black'}`}></div>
                ))}
            </div>
            <div className="absolute right-0 h-full w-[4px] bg-red-600"></div>
          </div>
        ))}

        {/* Starting Gate Line */}
        <div className="absolute left-[60px] top-0 h-full w-[2px] bg-yellow-500/20 border-r border-dashed border-yellow-500/40"></div>

        {gameState === 'BETTING' && (
            <div className="absolute inset-0 bg-black/50 backdrop-blur-[1px] z-20 flex flex-col items-center justify-center">
                <div className="w-28 h-28 rounded-full border-[6px] border-yellow-500 flex flex-col items-center justify-center bg-black/90 shadow-[0_0_50px_rgba(234,179,8,0.4)] scale-110">
                    <Timer size={36} className="text-yellow-500 mb-1" />
                    <span className="text-3xl font-black font-mono tracking-tighter">{timeLeft}s</span>
                </div>
                <p className="mt-8 text-[10px] font-black uppercase tracking-[0.4em] text-yellow-500 animate-pulse bg-black/60 px-6 py-2 rounded-full border border-yellow-500/20">Race in Progress</p>
            </div>
        )}
      </div>

      {/* Betting Panel */}
      <div className="bg-[#0a0a0a] p-6 pb-12 border-t border-white/5 shadow-[0_-20px_60px_rgba(0,0,0,1)] z-50">
        <div className="flex justify-between items-center mb-6">
            <h3 className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Pick Bike to Win</h3>
            <div className="flex gap-1.5 overflow-hidden">
                {history.map((h, i) => (
                    <span key={i} className={`w-5 h-5 rounded-full flex items-center justify-center text-[9px] font-black border border-white/10 text-white shrink-0`} style={{ backgroundColor: COLORS[h-1] }}>{h}</span>
                ))}
            </div>
        </div>

        <div className="grid grid-cols-6 gap-2 mb-8">
            {BIKES.map((bike, idx) => (
                <button 
                  key={bike}
                  disabled={gameState !== 'BETTING' || betPlaced}
                  onClick={() => setSelectedBike(bike)}
                  className={`aspect-square rounded-2xl flex flex-col items-center justify-center border-2 transition-all active:scale-90 ${selectedBike === bike ? 'bg-yellow-500 border-white text-black shadow-[0_0_20px_rgba(234,179,8,0.3)] scale-110' : 'bg-zinc-900 border-white/5 text-zinc-500'}`}
                >
                    <span className="text-xl font-black italic">{bike}</span>
                    <span className="text-[8px] font-bold opacity-60">5X</span>
                </button>
            ))}
        </div>

        <div className="flex items-center gap-4">
             <div className="flex-1 bg-black/50 p-2.5 rounded-2xl flex gap-2 overflow-x-auto no-scrollbar border border-white/5 shadow-inner">
                {[10, 50, 100, 500, 1000].map(amt => (
                    <button 
                      key={amt}
                      disabled={betPlaced || gameState !== 'BETTING'}
                      onClick={() => setBetAmount(amt)}
                      className={`flex-shrink-0 px-5 py-2.5 rounded-xl text-[10px] font-black transition-all ${betAmount === amt ? 'bg-white text-black shadow-lg' : 'text-zinc-500 hover:text-white'}`}
                    >
                        ₹{amt}
                    </button>
                ))}
             </div>
             <button 
                onClick={placeBet}
                disabled={!selectedBike || gameState !== 'BETTING' || betPlaced}
                className={`px-10 py-5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all active:scale-95 flex items-center gap-2 ${betPlaced ? 'bg-green-600 text-white shadow-lg border border-green-400' : (!selectedBike || gameState !== 'BETTING') ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' : 'bg-gradient-to-r from-yellow-500 to-orange-500 text-black shadow-xl'}`}
             >
                {betPlaced ? <><Zap size={16} fill="currentColor"/> LOCKED</> : gameState === 'BETTING' ? 'Bet Now' : 'Racing...'}
             </button>
        </div>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

