import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, Trophy, History, Zap, TrendingUp, TrendingDown } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

const SYMBOLS = ['💎', '🎰', '🔔', '🍒', '🍋', '🍇', '7️⃣'];

const SlotMachine: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [reels, setReels] = useState<string[]>(['💎', '7️⃣', '💎']);
  const [history, setHistory] = useState<string[]>([]);
  const [localNotification, setLocalNotification] = useState<{ win: boolean; amount: number; text: string } | null>(null);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      stopAllSounds();
    };
  }, []);

  const spin = async () => {
    if (isSpinning || userBalance < betAmount) return;

    setLocalNotification(null);
    setIsSpinning(true);
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Slot Machine Spin');

    // High-speed cycling animation (Clean and Bright)
    let count = 0;
    const maxCycles = 30;
    const interval = setInterval(() => {
        setReels([
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
        ]);
        count++;
        if (count > maxCycles) {
            clearInterval(interval);
            finalizeSpin();
        }
    }, 60);
  };

  const finalizeSpin = () => {
    if (!isMounted.current) return;

    const forceWin = Math.random() < 0.15;
    let result = [
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
    ];

    if (forceWin) {
        const winSym = SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)];
        result = [winSym, winSym, winSym];
    }

    setReels(result);
    setIsSpinning(false);

    const isJackpot = result[0] === result[1] && result[1] === result[2];
    const isPair = result[0] === result[1] || result[1] === result[2] || result[0] === result[2];

    let multiplier = 0;
    if (isJackpot) {
        multiplier = result[0] === '7️⃣' ? 50 : 20;
    } else if (isPair) {
        multiplier = 2;
    }

    const winAmount = betAmount * multiplier;

    if (winAmount > 0) {
        updateBalance(winAmount, 'WIN', 'Slot Machine Win');
        playSound('win');
        setLocalNotification({ win: true, amount: winAmount, text: isJackpot ? 'JACKPOT!' : 'PAIR WIN' });
    } else {
        playSound('loss');
        setLocalNotification({ win: false, amount: betAmount, text: 'TRY AGAIN' });
    }

    onResult({
        win: winAmount > 0,
        amount: winAmount > 0 ? winAmount : betAmount,
        game: 'Slot Machine'
    });

    setHistory(prev => [result.join(''), ...prev].slice(0, 5));
    addGameHistory('Slot Machine', betAmount, winAmount, `Landed ${result.join(' ')}`);

    setTimeout(() => {
        if(isMounted.current) setLocalNotification(null);
    }, 3000);
  };

  return (
    <div className="bg-[#0a0a0a] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,_rgba(220,38,38,0.1)_0%,_transparent_70%)] pointer-events-none"></div>

      {localNotification && (
          <div className="absolute top-24 left-0 w-full z-[100] px-10 pointer-events-none animate-in fade-in zoom-in slide-in-from-top-4 duration-500">
               <div className={`flex items-center justify-between p-4 rounded-3xl border shadow-2xl backdrop-blur-md ${localNotification.win ? 'bg-green-600/90 border-green-400 shadow-green-900/40' : 'bg-zinc-800/90 border-zinc-700 shadow-black'}`}>
                    <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-full ${localNotification.win ? 'bg-white/20' : 'bg-zinc-700'}`}>
                            {localNotification.win ? <TrendingUp size={20}/> : <TrendingDown size={20} className="text-zinc-400"/>}
                        </div>
                        <div>
                            <p className="text-[8px] font-black uppercase tracking-widest opacity-60">{localNotification.win ? 'Winner' : 'Game Over'}</p>
                            <h4 className="text-sm font-black italic">{localNotification.text}</h4>
                        </div>
                    </div>
                    <div className="text-right">
                        <p className={`text-xl font-black font-mono ${localNotification.win ? 'text-white' : 'text-zinc-500'}`}>
                            {localNotification.win ? `+₹${localNotification.amount.toFixed(2)}` : `-₹${localNotification.amount}`}
                        </p>
                    </div>
               </div>
          </div>
      )}

      <div className="p-4 flex justify-between items-center bg-black/60 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">ROYAL SLOTS</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">Elite Payouts</p>
        </div>
        <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-sm bg-gradient-to-b from-zinc-800 to-zinc-950 p-6 rounded-[3.5rem] border-[8px] border-zinc-800 shadow-[0_0_80px_rgba(0,0,0,1)] relative overflow-hidden">
             <div className="absolute top-2 left-1/2 -translate-x-1/2 flex gap-4">
                 <div className="w-2 h-2 rounded-full bg-red-500 shadow-[0_0_10px_red]"></div>
                 <div className="w-2 h-2 rounded-full bg-yellow-500 shadow-[0_0_10px_yellow]"></div>
                 <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_10px_blue]"></div>
             </div>

             <div className="bg-[#111] p-4 rounded-[2.5rem] flex justify-between gap-3 border-4 border-zinc-800 shadow-inner mt-4">
                {reels.map((symbol, i) => (
                    <div key={i} className={`flex-1 h-36 bg-zinc-50 rounded-3xl flex items-center justify-center text-5xl shadow-2xl transition-transform ${isSpinning ? 'scale-95 duration-100' : 'animate-in zoom-in'}`}>
                        {symbol}
                    </div>
                ))}
             </div>

             <div className="mt-8 flex justify-center">
                 <div className="bg-yellow-500/10 px-8 py-2 rounded-full border border-yellow-500/30">
                    <p className="text-[9px] font-black uppercase text-yellow-500 tracking-[0.4em] text-center">Elite Line</p>
                 </div>
             </div>
        </div>

        <div className="mt-12 w-full max-w-xs">
            <div className="flex justify-between items-center bg-zinc-900/60 p-4 rounded-2xl border border-white/5 shadow-xl">
                <div className="flex items-center gap-3">
                    <Trophy size={18} className="text-yellow-500"/>
                    <span className="text-xs font-black uppercase tracking-widest">History</span>
                </div>
                <div className="flex gap-2">
                    {history.map((h, i) => (
                        <div key={i} className="px-2 py-1 bg-zinc-800 rounded-lg text-[10px] font-black text-zinc-300 border border-white/5">{h}</div>
                    ))}
                </div>
            </div>
        </div>
      </div>

      <div className="bg-[#0a0a0a] p-6 pb-12 border-t border-white/5 shadow-[0_-20px_60px_rgba(0,0,0,1)]">
          <div className="flex justify-between items-center mb-8 px-2">
              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button 
                        key={amt} 
                        onClick={() => !isSpinning && setBetAmount(amt)}
                        className={`w-14 h-11 rounded-2xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}
                      >
                        ₹{amt}
                      </button>
                  ))}
              </div>
              <div className="text-right">
                  <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest mb-1">Stake</p>
                  <p className="text-2xl font-black text-white italic tracking-tighter">₹{betAmount}</p>
              </div>
          </div>

          <button 
            onClick={spin}
            disabled={isSpinning}
            className={`w-full py-6 rounded-[2.5rem] font-black uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 text-xl border-t-2 border-white/10 ${isSpinning ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed opacity-50' : 'bg-gradient-to-r from-red-600 via-orange-600 to-red-600 text-white shadow-red-900/40'}`}
          >
            <RotateCw size={28} className={isSpinning ? 'animate-spin' : ''} />
            {isSpinning ? 'SPINNING' : 'SPIN REELS'}
          </button>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

