import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, ShieldAlert, Zap, TrendingUp, TrendingDown, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

// 12 Segments per Ring
const RING_LEVELS = {
    outer: ['100X', '20X', 'ZERO', '50X', '15X', 'ZERO', '80X', '10X', 'ZERO', '40X', '5X', 'ZERO'],
    mid: ['10X', '5X', 'ZERO', '8.5X', '4X', 'ZERO', '7X', '3X', 'ZERO', '6X', '2.5X', 'ZERO'],
    inner: ['5X', '2.5X', '1.2X', '4X', '2X', '1.1X', '3.5X', '1.8X', '1.0X', '3X', '1.5X', 'ZERO']
};

const Vortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [pulseRotation, setPulseRotation] = useState(0); 
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<string[]>(['10X', 'ZERO', '5X', '1.2X']);
  const [localResult, setLocalResult] = useState<{ win: boolean; amount: number; mult: string } | null>(null);
  const [activeRing, setActiveRing] = useState<'outer' | 'mid' | 'inner'>('mid');

  const rotationRef = useRef<number>(0);
  const velocityRef = useRef<number>(0);
  const requestRef = useRef<number>(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    const animate = () => {
        if (isSpinning) {
            if (velocityRef.current > 0.1) {
                velocityRef.current *= 0.988; // Physics Friction
            } else {
                velocityRef.current = 0;
                setIsSpinning(false);
                finalizeVortex();
            }
        }

        rotationRef.current += velocityRef.current;
        setPulseRotation(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      isMounted.current = false;
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, [isSpinning]);

  const startVortex = () => {
    if (userBalance < betAmount || isSpinning) return;
    setLocalResult(null);
    setIsSpinning(true);

    // Choose a ring level randomly for the round
    const rings: ('outer' | 'mid' | 'inner')[] = ['outer', 'mid', 'inner'];
    setActiveRing(rings[Math.floor(Math.random() * rings.length)]);

    playSound('click');
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Vortex Stake');

    // Set high initial velocity
    velocityRef.current = 25 + Math.random() * 15;
  };

  const finalizeVortex = () => {
    if (!isMounted.current) return;

    const normalizedRotation = (rotationRef.current % 360);
    const segmentWidth = 30; // 360 / 12
    const index = Math.floor((normalizedRotation + 15) / segmentWidth) % 12;

    const resultLabel = RING_LEVELS[activeRing][index];

    if (resultLabel === 'ZERO') {
        playSound('loss');
        setLocalResult({ win: false, amount: betAmount, mult: 'REJECTED' });
        onResult({
            win: false,
            amount: betAmount,
            game: 'Vortex',
            resultDetails: [{ label: 'Vortex Zone', value: 'DEAD ZONE', color: 'text-red-500' }]
        });
        addGameHistory('Vortex', betAmount, 0, 'Hit Dead Zone');
    } else {
        const multVal = parseFloat(resultLabel.replace('X', ''));
        const winAmount = betAmount * multVal;

        updateBalance(winAmount, 'WIN', 'Vortex Victory');
        playSound('win');
        setHistory(prev => [resultLabel, ...prev].slice(0, 10));
        setLocalResult({ win: true, amount: winAmount, mult: resultLabel });

        onResult({
            win: true,
            amount: winAmount,
            game: 'Vortex',
            resultDetails: [{ label: 'Vortex Hit', value: resultLabel, color: 'text-yellow-400' }]
        });
        addGameHistory('Vortex', betAmount, winAmount, `Vortex Payout ${resultLabel}`);
    }

    setTimeout(() => {
        if(isMounted.current) setLocalResult(null);
    }, 4000);
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      {/* Floating Victory Banner */}
      {localResult && (
          <div className="absolute top-20 left-0 w-full z-[100] px-6 pointer-events-none animate-in slide-in-from-top duration-500">
               <div className={`flex items-center justify-between p-5 rounded-[2rem] shadow-2xl border backdrop-blur-xl ${localResult.win ? 'bg-green-600/90 border-green-400' : 'bg-red-600/90 border-red-400'}`}>
                   <div className="flex items-center gap-3">
                       <div className="bg-white/20 p-2 rounded-full">
                           {localResult.win ? <TrendingUp size={24}/> : <TrendingDown size={24}/>}
                       </div>
                       <div>
                           <p className="text-[10px] font-black uppercase tracking-widest opacity-80">{localResult.win ? 'Vortex Capture' : 'Energy Loss'}</p>
                           <h4 className="text-xl font-black italic">{localResult.mult}</h4>
                       </div>
                   </div>
                   <div className="text-right">
                       <p className="text-[10px] font-black uppercase opacity-60">Result</p>
                       <p className="text-2xl font-black font-mono">₹{localResult.amount.toFixed(2)}</p>
                   </div>
               </div>
          </div>
      )}

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/80 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">THE VORTEX</h1>
            <p className="text-[7px] text-zinc-500 font-bold uppercase tracking-[0.4em]">High Precision Arena</p>
        </div>
        <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      {/* Arena Stage */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">
        <div className="relative w-80 h-80 md:w-[22rem] md:h-[22rem] flex items-center justify-center">

            {/* STATIC RINGS SYSTEM */}
            <div className="absolute inset-0 rounded-full border-[10px] border-zinc-900 shadow-[0_0_100px_rgba(0,0,0,1)] bg-[#080808]">

                {/* Visual Depth Rings */}
                <div className="absolute inset-[15%] rounded-full border border-white/5 bg-zinc-900/10"></div>
                <div className="absolute inset-[35%] rounded-full border border-white/5 bg-zinc-900/20 shadow-inner"></div>

                {/* Outer Ring Mults */}
                {RING_LEVELS.outer.map((label, i) => (
                    <div key={`o-${i}`} className="absolute top-0 left-1/2 -translate-x-1/2 h-full flex flex-col items-center pt-4 origin-bottom" style={{ transform: `rotate(${i * 30}deg)` }}>
                        <span className={`text-[10px] font-black italic tracking-tighter ${label === 'ZERO' ? 'text-red-600 opacity-40' : 'text-white/40'}`}>{label}</span>
                    </div>
                ))}

                {/* Mid Ring Mults */}
