import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, Trophy, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

const SYMBOLS = ['💎', '🎰', '🔔', '🍒', '🍋', '🍇', '7️⃣'];

const SlotMachine: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [reels, setReels] = useState<string[]>(['💎', '7️⃣', '💎']);
  const [history, setHistory] = useState<string[]>([]);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      stopAllSounds();
    };
  }, []);

  const spin = async () => {
    if (isSpinning || userBalance < betAmount) return;

    setIsSpinning(true);
    playSound('spin');
    updateBalance(-betAmount, 'BET', 'Slot Machine Spin');

    let count = 0;
    const maxCycles = 25;
    const interval = setInterval(() => {
        setReels([
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
        ]);
        count++;
        if (count > maxCycles) {
            clearInterval(interval);
            finalizeSpin();
        }
    }, 80);
  };

  const finalizeSpin = () => {
    if (!isMounted.current) return;

    const outcome = [
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
    ];

    setReels(outcome);
    setIsSpinning(false);

    const isJackpot = outcome[0] === outcome[1] && outcome[1] === outcome[2];
    const isPair = outcome[0] === outcome[1] || outcome[1] === outcome[2] || outcome[0] === outcome[2];

    let multiplier = 0;
    if (isJackpot) multiplier = outcome[0] === '7️⃣' ? 50 : 20;
    else if (isPair) multiplier = 2;

    const winAmount = betAmount * multiplier;

    if (winAmount > 0) {
        updateBalance(winAmount, 'WIN', 'Slot Machine Win');
        playSound('win');
    } else {
        playSound('loss');
    }

    onResult({
        win: winAmount > 0,
        amount: winAmount > 0 ? winAmount : betAmount,
        game: 'Slot Machine'
    });

    setHistory(prev => [outcome.join(''), ...prev].slice(0, 5));
    addGameHistory('Slot Machine', betAmount, winAmount, `Landed ${outcome.join(' ')}`);
  };

  return (
    <div className="bg-[#0a0a0a] min-h-screen flex flex-col font-sans text-white relative overflow-hidden select-none">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,_rgba(220,38,38,0.1)_0%,_transparent_70%)] pointer-events-none"></div>

      <div className="p-4 flex justify-between items-center bg-black/60 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/10 active:scale-90 transition-all"><ArrowLeft size={20}/></button>
        <div className="text-center">
            <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">ROYAL SLOTS</h1>
        </div>
        <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
          <Wallet size={14} className="text-yellow-500" />
          <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-sm bg-gradient-to-b from-zinc-800 to-zinc-950 p-6 rounded-[3.5rem] border-[8px] border-zinc-800 shadow-[0_0_80px_rgba(0,0,0,1)] relative overflow-hidden">
             <div className="bg-[#111] p-4 rounded-[2.5rem] flex justify-between gap-3 border-4 border-zinc-800 shadow-inner mt-4">
                {reels.map((symbol, i) => (
                    <div key={i} className={`flex-1 h-36 bg-zinc-50 rounded-3xl flex items-center justify-center text-5xl shadow-2xl transition-transform ${isSpinning ? 'scale-95 duration-100' : 'animate-in zoom-in'}`}>
                        {symbol}
                    </div>
                ))}
             </div>
        </div>
        <div className="mt-12 w-full max-w-xs">
            <div className="flex justify-between items-center bg-zinc-900/60 p-4 rounded-2xl border border-white/5 shadow-xl">
                <History size={18} className="text-yellow-500"/>
                <div className="flex gap-2">
                    {history.map((h, i) => (
                        <div key={i} className="px-2 py-1 bg-zinc-800 rounded-lg text-[10px] font-black text-zinc-300 border border-white/5">{h}</div>
                    ))}
                </div>
            </div>
        </div>
      </div>

      <div className="bg-[#0a0a0a] p-6 pb-12 border-t border-white/5 shadow-[0_-20px_60px_rgba(0,0,0,1)]">
          <div className="flex justify-between items-center mb-8 px-2">
              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button key={amt} onClick={() => !isSpinning && setBetAmount(amt)} className={`w-14 h-11 rounded-2xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}>₹{amt}</button>
                  ))}
              </div>
              <p className="text-2xl font-black text-white italic">₹{betAmount}</p>
          </div>
          <button onClick={spin} disabled={isSpinning} className={`w-full py-6 rounded-[2.5rem] font-black uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 text-xl border-t-2 border-white/10 ${isSpinning ? 'bg-zinc-800 text-zinc-500 opacity-50' : 'bg-gradient-to-r from-red-600 to-orange-600 text-white shadow-red-900/40'}`}>
            <RotateCw size={28} className={isSpinning ? 'animate-spin' : ''} />
            {isSpinning ? 'SPINNING' : 'SPIN REELS'}
          </button>
      </div>

      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

export default SlotMachine;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Timer, Trophy, History, Zap } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const COLORS = ['#ef4444', '#3b82f6', '#22c55e', '#eab308', '#a855f7', '#f97316'];

const Motorbike = ({ color, isRacing }: { color: string, isRacing: boolean }) => (
  <div className={`relative transition-transform duration-300 ${isRacing ? 'rotate-[-5deg] scale-110' : ''}`}>
    <svg width="48" height="32" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M19 15C19 16.6569 17.6569 18 16 18C14.3431 18 13 16.6569 13 15C13 13.3431 14.3431 12 16 12C17.6569 12 19 13.3431 19 15Z" fill={color} />
        <path d="M7 15C7 16.6569 5.65685 18 4 18C2.34315 18 1 16.6569 1 15C1 13.3431 2.34315 12 4 12C5.65685 12 7 13.3431 7 15Z" fill={color} />
        <path d="M16 15L10 15L8 9L15 9L16 15Z" fill={color} opacity="0.8"/>
        <path d="M8 9H12L13 5H10L8 9Z" fill="white" />
        <path d="M13 5L15 3H18" stroke="white" strokeWidth="1.5" strokeLinecap="round" />
        <circle cx="16" cy="15" r="2" fill="black" />
        <circle cx="4" cy="15" r="2" fill="black" />
    </svg>
  </div>
);

const MotoRacing: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [gameState, setGameState] = useState<'BETTING' | 'RACING' | 'RESULT'>('BETTING');
  const [timeLeft, setTimeLeft] = useState(10);
  const [selectedBike, setSelectedBike] = useState<number | null>(null);
  const [betAmount, setBetAmount] = useState(10);
  const [betPlaced, setBetPlaced] = useState(false);
  const [bikePositions, setBikePositions] = useState<number[]>(new Array(6).fill(0));
  const [winner, setWinner] = useState<number | null>(null);
  const [history, setHistory] = useState<number[]>([]);

  const raceInterval = useRef<number | null>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    setHistory(Array.from({ length: 10 }, () => Math.floor(Math.random() * 6) + 1));
    startNewRound();
    return () => { isMounted.current = false; if (raceInterval.current) clearInterval(raceInterval.current); stopAllSounds(); };
  }, []);

  const startNewRound = () => {
    if (!isMounted.current) return;
    setGameState('BETTING'); setTimeLeft(10); setBikePositions(new Array(6).fill(0));
    setWinner(null); setSelectedBike(null); setBetPlaced(false);
  };

  useEffect(() => {
    if (gameState === 'BETTING' && timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(prev => prev - 1), 1000);
      return () => clearTimeout(timer);
    } else if (gameState === 'BETTING' && timeLeft === 0) {
      startRace();
    }
  }, [timeLeft, gameState]);

  const placeBet = () => {
    if (!selectedBike || betPlaced || userBalance < betAmount) return;
    updateBalance(-betAmount, 'BET', `Bike ${selectedBike}`);
    setBetPlaced(true);
    playSound('click');
  };

  const startRace = () => {
    setGameState('RACING');
    playSound('spin');
    const interval = window.setInterval(() => {
      setBikePositions(prev => {
        const next = [...prev];
        let won = -1;
        for (let i = 0; i < 6; i++) {
          next[i] += 0.5 + Math.random() * 1.2;
          if (next[i] >= 85) { won = i + 1; break; }
        }
        if (won !== -1) { clearInterval(interval); finishRace(won); return prev; }
        return next;
      });
    }, 50);
    raceInterval.current = interval;
  };

  const finishRace = (bikeNum: number) => {
    setGameState('RESULT'); setWinner(bikeNum);
    setHistory(prev => [bikeNum, ...prev].slice(0, 10));
    const win = betPlaced && selectedBike === bikeNum;
    const winAmount = win ? betAmount * 5 : 0;
    if (win) { updateBalance(winAmount, 'WIN', 'Moto Racing Win'); playSound('win'); } else if (betPlaced) playSound('loss');
    onResult({ win, amount: win ? winAmount : betAmount, game: 'Moto Racing', resultDetails: [{label: 'Winner', value: `Bike ${bikeNum}`}] });
    addGameHistory('Moto Racing', betPlaced ? betAmount : 0, winAmount, `Bike ${bikeNum} Won`);
    setTimeout(() => isMounted.current && startNewRound(), 5000);
  };

  return (
    <div className="bg-black min-h-screen flex flex-col text-white font-sans overflow-hidden">
      <div className="p-4 flex justify-between items-center bg-[#111] border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2 bg-zinc-900 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text italic tracking-widest uppercase">MOTO GP</h1>
        <div className="bg-zinc-900 px-4 py-1.5 rounded-xl border border-yellow-500/20 text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
      </div>

      <div className="flex-1 bg-[#111] p-4 flex flex-col gap-1 relative overflow-hidden justify-center">
        {[1,2,3,4,5,6].map((bike, idx) => (
          <div key={bike} className="h-14 bg-zinc-900 rounded-lg relative flex items-center overflow-hidden border border-white/5 shadow-inner">
            <div className="w-10 h-full flex items-center justify-center font-black bg-zinc-800 italic z-10">{bike}</div>
            <div className="absolute transition-all duration-75 ease-linear" style={{ left: `calc(40px + ${bikePositions[idx]}%)`, top: '50%', transform: 'translateY(-50%)' }}>
              <Motorbike color={COLORS[idx]} isRacing={gameState === 'RACING'} />
            </div>
            <div className="absolute right-0 h-full w-12 flex flex-wrap opacity-40">
                {Array.from({length: 12}).map((_, i) => <div key={i} className={`w-4 h-4 ${ (Math.floor(i/3) + (i%3)) % 2 === 0 ? 'bg-white' : 'bg-black'}`}></div>)}
            </div>
            <div className="absolute right-0 h-full w-1 bg-red-600"></div>
          </div>
        ))}
        {gameState === 'BETTING' && (
            <div className="absolute inset-0 bg-black/40 backdrop-blur-sm z-20 flex flex-col items-center justify-center">
                <div className="w-24 h-24 rounded-full border-4 border-yellow-500 flex flex-col items-center justify-center bg-black/90 shadow-[0_0_40px_rgba(234,179,8,0.4)]">
                    <Timer size={30} className="text-yellow-500 mb-1" />
                    <span className="text-3xl font-black font-mono">{timeLeft}s</span>
                </div>
            </div>
        )}
      </div>

      <div className="bg-zinc-950 p-6 pb-10 border-t border-white/5 z-50">
        <div className="flex justify-between items-center mb-4">
            <span className="text-[10px] font-black uppercase text-zinc-500 tracking-widest">History</span>
            <div className="flex gap-1">
                {history.map((h, i) => <span key={i} className={`w-5 h-5 rounded-full flex items-center justify-center text-[9px] font-black`} style={{ backgroundColor: COLORS[h-1] }}>{h}</span>)}
            </div>
        </div>
