import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, RotateCcw } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

const POCKETS = [
    { mult: 0, color: '#1e293b' }, { mult: 2, color: '#f59e0b' }, { mult: 0, color: '#1e293b' },
    { mult: 5, color: '#10b981' }, { mult: 0, color: '#1e293b' }, { mult: 10, color: '#ef4444' },
    { mult: 0, color: '#1e293b' }, { mult: 2, color: '#f59e0b' }, { mult: 0, color: '#1e293b' },
    { mult: 50, color: '#8b5cf6' }, { mult: 0, color: '#1e293b' }, { mult: 5, color: '#10b981' }
];

const Vortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [gameState, setGameState] = useState<'IDLE' | 'SPINNING' | 'LOCKED'>('IDLE');
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<string[]>(['10X', '0X', '5X', '2X', '0X']);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const isMounted = useRef(true);

  // Physics State
  const bowlRotation = useRef(0);
  const ballAngle = useRef(0);
  const ballRadius = useRef(150); // Initial outer radius
  const ballSpeed = useRef(0);
  const spiralStage = useRef(0); // 0: stable, 1: spiraling in, 2: locked in pocket

  useEffect(() => {
    isMounted.current = true;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
        updatePhysics();
        draw(ctx);
        requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      isMounted.current = false;
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, []);

  const updatePhysics = () => {
    bowlRotation.current += 0.01; // Constant bowl rotation

    if (gameState === 'SPINNING') {
        ballAngle.current += ballSpeed.current;

        if (spiralStage.current === 0) {
            ballSpeed.current *= 0.995; // Drag
            if (ballSpeed.current < 0.08) spiralStage.current = 1;
        } else if (spiralStage.current === 1) {
            ballRadius.current -= 1.2; // Spiral inward
            ballSpeed.current *= 0.99;
            if (ballRadius.current <= 80) finalizeVortex();
        }
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const w = 380, h = 380;
    ctx.clearRect(0, 0, w, h);
    const cx = w/2, cy = h/2;

    // Draw Outer Bowl
    ctx.beginPath();
    ctx.arc(cx, cy, 170, 0, Math.PI * 2);
    ctx.fillStyle = '#0f172a';
    ctx.shadowBlur = 20;
    ctx.shadowColor = '#000';
    ctx.fill();

    // Draw Spinning Center Ring with Pockets
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(bowlRotation.current);
    POCKETS.forEach((p, i) => {
        const angle = (Math.PI * 2 / POCKETS.length) * i;
        ctx.save();
        ctx.rotate(angle);

        ctx.beginPath();
        ctx.moveTo(40, -10); ctx.lineTo(80, -20); ctx.lineTo(80, 20); ctx.lineTo(40, 10);
        ctx.closePath();
        ctx.fillStyle = p.color;
        ctx.fill();
        ctx.strokeStyle = '#fff2'; ctx.stroke();

        ctx.fillStyle = '#fff';
        ctx.font = 'bold 10px Inter';
        ctx.textAlign = 'center';
        ctx.fillText(p.mult + 'X', 60, 5);
        ctx.restore();
    });
    ctx.restore();

    // Draw Ball
    if (gameState === 'SPINNING') {
        const bx = cx + Math.cos(ballAngle.current) * ballRadius.current;
        const by = cy + Math.sin(ballAngle.current) * ballRadius.current;
        ctx.beginPath();
        ctx.arc(bx, by, 8, 0, Math.PI * 2);
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 15; ctx.shadowColor = '#fff';
        ctx.fill();
    }
  };

  const launch = () => {
    if (gameState !== 'IDLE' || userBalance < betAmount) return;
    setGameState('SPINNING');
    updateBalance(-betAmount, 'BET', 'Vortex');
    playSound('click'); playSound('spin');

    ballAngle.current = Math.random() * Math.PI * 2;
    ballRadius.current = 160;
    ballSpeed.current = 0.25 + Math.random() * 0.1;
    spiralStage.current = 0;
  };

  const finalizeVortex = () => {
    if (gameState !== 'SPINNING') return;
    setGameState('LOCKED');

    // Calculate which pocket it hit based on angle relative to bowl rotation
    const relativeAngle = (ballAngle.current - bowlRotation.current) % (Math.PI * 2);
    const normalized = relativeAngle < 0 ? relativeAngle + Math.PI * 2 : relativeAngle;
    const idx = Math.floor( (normalized / (Math.PI * 2)) * POCKETS.length ) % POCKETS.length;

    const result = POCKETS[idx];
    const winAmt = betAmount * result.mult;

    setTimeout(() => {
        if (!isMounted.current) return;
        if (winAmt > 0) { updateBalance(winAmt, 'WIN', 'Vortex Win'); playSound('win'); } else { playSound('loss'); }
        setHistory(prev => [result.mult + 'X', ...prev].slice(0, 8));
        onResult({ win: winAmt > 0, amount: winAmt > 0 ? winAmt : betAmount, game: 'Vortex' });
        setGameState('IDLE');
    }, 1000);
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white select-none overflow-hidden">
      <div className="p-4 flex justify-between items-center bg-[#111] border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2 bg-zinc-900 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text tracking-widest uppercase">VORTEX</h1>
        <div className="bg-black/50 px-4 py-1.5 rounded-xl border border-yellow-500/20 text-yellow-500">₹{userBalance.toFixed(2)}</div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_#1e1b4b_0%,_transparent_70%)] opacity-30 pointer-events-none"></div>
        <canvas ref={canvasRef} width={380} height={380} className="max-w-full rounded-full shadow-[0_0_100px_rgba(0,0,0,1)] bg-black" />
        <div className="mt-8 flex gap-2 overflow-hidden">
            {history.map((h, i) => <span key={i} className="px-3 py-1 bg-zinc-900 rounded-full text-[10px] font-black text-zinc-500 italic border border-white/5">{h}</span>)}
        </div>
      </div>

      <div className="bg-zinc-950 p-6 pb-12 border-t border-white/5 shadow-[0_-20px_60px_rgba(0,0,0,1)]">
          <div className="flex justify-between items-end mb-6">
              <div className="flex gap-2">
                  {[10, 50, 100, 500].map(amt => (
                      <button key={amt} onClick={() => gameState === 'IDLE' && setBetAmount(amt)} className={`w-14 h-11 rounded-xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}>₹{amt}</button>
                  ))}
              </div>
              <button onClick={() => setMuted(toggleMute())} className="p-3 bg-zinc-900 rounded-xl text-zinc-400">
                  {muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}
              </button>
          </div>
          <button onClick={launch} disabled={gameState !== 'IDLE'} className={`w-full py-6 rounded-3xl font-black uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all text-xl border-t-2 border-white/10 ${gameState !== 'IDLE' ? 'bg-zinc-800 text-zinc-600' : 'bg-gradient-to-r from-yellow-500 via-orange-500 to-yellow-600 text-black'}`}>
            {gameState === 'IDLE' ? 'LAUNCH BALL' : 'VORTEX ACTIVE'}
          </button>
      </div>
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

