  const [tickerItems, setTickerItems] = useState<string[]>([]);
  const [activeCategory, setActiveCategory] = useState<Category>('Popular');

  const generateFakeWinner = () => {
      const id = Math.floor(10000 + Math.random() * 90000);
      const suffix = Math.floor(10 + Math.random() * 90);
      const amount = (Math.random() * 5000 + 100).toFixed(2);
      const games = ['WinGo', 'Aviator', 'Mines', 'Moto Racing', 'Slot Machine', 'Dragon Tiger', 'Vortex', 'Andar Bahar', 'Lucky Wheel', 'Plinko', 'Head Tails'];
      const game = games[Math.floor(Math.random() * games.length)];
      return `Member ID: ${id}***${suffix} Won ₹${amount} in ${game}!`;
  };

  useEffect(() => {
      const initialItems = Array(5).fill(null).map(generateFakeWinner);
      setTickerItems(initialItems);
      const unsub = subscribeToBalance(() => {});
      const interval = setInterval(() => {
          setTickerItems(prev => [generateFakeWinner(), ...prev].slice(0, 20));
      }, 3000);
      return () => { clearInterval(interval); unsub(); }
  }, []);

  const handleShare = async () => {
      if (navigator.share) {
          try { await navigator.share({ title: 'CLUB 61', text: 'Join the elite club!', url: window.location.origin }); } catch (err) {}
      } else { alert('Link copied!'); }
