            <span className={`text-xs font-black uppercase tracking-[0.2em] ${gameState === 'RESULT' ? 'text-yellow-400' : 'text-white'}`}>{message}</span>
        </div>

        {/* Joker Slot */}
        <div className="mt-2 flex flex-col items-center gap-2 relative">
            <div className="w-28 h-40 rounded-2xl border-4 border-dashed border-yellow-500/30 flex items-center justify-center relative bg-black/30 overflow-hidden shadow-inner">
