  useEffect(() => { 
      startWinGoGame(); 
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToBalance((updatedUser) => {
        setUser(updatedUser);
        setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    stopAllSounds(); 
