import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Rocket, Zap } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const Limbo: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [targetMult, setTargetMult] = useState(2.0);
  const [gameState, setGameState] = useState<'IDLE' | 'RISING' | 'DONE'>('IDLE');
  const [resultMult, setResultMult] = useState(1.0);
  const [history, setHistory] = useState<number[]>([]);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const startRound = () => {
    if (gameState === 'RISING' || userBalance < betAmount) return;

    updateBalance(-betAmount, 'BET', 'Limbo Stake');
    playSound('click');
    setGameState('RISING');

    // Provably fair generation (simulated)
    const r = Math.random();
    const outcome = Math.max(1, 0.99 / (1 - r));
    const cappedOutcome = Math.min(10000, outcome);

    let current = 1.0;
    const interval = setInterval(() => {
        if (!isMounted.current) { clearInterval(interval); return; }
        current *= 1.2;
        if (current >= cappedOutcome) {
            clearInterval(interval);
            setResultMult(cappedOutcome);
            setGameState('DONE');
            finalize(cappedOutcome);
        } else {
            setResultMult(current);
        }
    }, 50);
  };

  const finalize = (outcome: number) => {
    const isWin = outcome >= targetMult;
    const winAmt = isWin ? betAmount * targetMult : 0;

    if (isWin) {
        updateBalance(winAmt, 'WIN', 'Limbo Win');
        playSound('win');
    } else {
        playSound('loss');
    }

    setHistory(prev => [outcome, ...prev].slice(0, 10));
    onResult({ win: isWin, amount: isWin ? winAmt : betAmount, game: 'Limbo' });
    addGameHistory('Limbo', betAmount, winAmt, `Target ${targetMult}x | Got ${outcome.toFixed(2)}x`);

    setTimeout(() => {
        if(isMounted.current) setGameState('IDLE');
    }, 1500);
  };

  return (
    <div className="bg-[#0f172a] min-h-screen flex flex-col font-sans text-white relative">
      <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text italic tracking-widest">LIMBO ARENA</h1>
        <div className="bg-black/50 px-4 py-2 rounded-2xl text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6 bg-[radial-gradient(circle_at_50%_50%,_#1e293b_0%,_transparent_70%)]">
        <div className={`text-7xl font-black mb-8 italic tracking-tighter ${gameState === 'DONE' ? (resultMult >= targetMult ? 'text-green-500' : 'text-red-500') : 'text-white'}`}>
            {resultMult.toFixed(2)}x
        </div>

        <div className={`w-32 h-32 rounded-full flex items-center justify-center bg-blue-600/10 border-4 border-blue-500/20 shadow-[0_0_50px_rgba(59,130,246,0.2)] ${gameState === 'RISING' ? 'animate-bounce' : ''}`}>
             <Rocket size={64} className="text-blue-500 -rotate-45" />
        </div>

        <div className="mt-12 flex gap-2 overflow-x-auto no-scrollbar max-w-full px-4">
            {history.map((h, i) => (
                <span key={i} className={`px-4 py-1.5 rounded-full text-[10px] font-black border border-white/5 ${h >= 2 ? 'text-green-400 bg-green-500/10' : 'text-red-400 bg-red-500/10'}`}>{h.toFixed(2)}x</span>
            ))}
        </div>
      </div>

      <div className="bg-[#111] p-6 border-t border-white/5 pb-12">
        <div className="grid grid-cols-2 gap-4 mb-6">
            <div className="space-y-2">
                <label className="text-[10px] text-slate-500 font-black uppercase">Stake Amount</label>
                <div className="bg-black rounded-xl p-3 flex items-center gap-2 border border-white/10">
                    <span className="text-yellow-500">₹</span>
                    <input type="number" value={betAmount} onChange={e => setBetAmount(Number(e.target.value))} className="bg-transparent w-full outline-none font-bold" />
                </div>
            </div>
            <div className="space-y-2">
                <label className="text-[10px] text-slate-500 font-black uppercase">Target Multiplier</label>
                <div className="bg-black rounded-xl p-3 flex items-center gap-2 border border-white/10">
                    <span className="text-blue-500">x</span>
                    <input type="number" step="0.1" value={targetMult} onChange={e => setTargetMult(Number(e.target.value))} className="bg-transparent w-full outline-none font-bold" />
                </div>
            </div>
        </div>

        <button onClick={startRound} disabled={gameState === 'RISING'} className="w-full py-6 rounded-3xl bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-black text-xl active:scale-95 transition-all shadow-xl">
            {gameState === 'RISING' ? 'BOOSTING...' : 'BET'}
        </button>
      </div>
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

export default Limbo;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Goal, ShieldAlert } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const MULTIPLIERS = [1.92, 3.84, 7.68, 15.36, 30.72];

const Penalty: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [round, setRound] = useState(0);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'SHOOTING' | 'DONE'>('IDLE');
  const [lastShot, setLastShot] = useState<number | null>(null);
  const [keeperPos, setKeeperPos] = useState<number | null>(null);

  const kick = (target: number) => {
    if (gameState === 'SHOOTING' || gameState === 'DONE') return;

    if (round === 0) {
        if (userBalance < betAmount) return;
        updateBalance(-betAmount, 'BET', 'Penalty Stake');
    }

    setGameState('SHOOTING');
    setLastShot(target);
    playSound('click');

    const kPos = Math.floor(Math.random() * 5);
    setKeeperPos(kPos);

    setTimeout(() => {
        if (target !== kPos) {
            // GOAL
            playSound('win');
            setRound(prev => prev + 1);
            setGameState('PLAYING');
            if (round + 1 === MULTIPLIERS.length) cashOut(true);
        } else {
            // SAVED
            playSound('loss');
            setGameState('DONE');
            addGameHistory('Penalty', betAmount, 0, `Saved at ${MULTIPLIERS[round]}x`);
            onResult({ win: false, amount: betAmount, game: 'Penalty Shootout' });
            setTimeout(() => {
                setGameState('IDLE');
                setRound(0);
            }, 3000);
        }
    }, 1000);
  };

  const cashOut = (auto = false) => {
      const winAmt = betAmount * MULTIPLIERS[round - 1];
      updateBalance(winAmt, 'WIN', 'Penalty Cashout');
      playSound('win');
      onResult({ win: true, amount: winAmt, game: 'Penalty Shootout', resultDetails: [{label: 'Level', value: `${round} Goals`}] });
      setGameState('IDLE');
      setRound(0);
  };

  return (
    <div className="bg-[#064e3b] min-h-screen flex flex-col font-sans text-white relative">
      <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text tracking-widest italic">PENALTY KING</h1>
        <div className="bg-black/50 px-4 py-2 rounded-2xl text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6 relative">
          <div className="w-full h-64 border-4 border-white/40 rounded-t-3xl relative overflow-hidden bg-black/20">
               {/* Goal Areas */}
               <div className="grid grid-cols-5 h-full relative z-10">
                   {[0,1,2,3,4].map(i => (
                       <button 
                         key={i} 
                         onClick={() => kick(i)}
                         disabled={gameState !== 'IDLE' && gameState !== 'PLAYING'}
                         className="border-r border-white/10 hover:bg-white/10 flex items-center justify-center text-4xl opacity-0 hover:opacity-100 transition-all"
                       >
                           🎯
                       </button>
                   ))}
               </div>

               {/* Keeper */}
               <div 
                 className="absolute bottom-4 w-12 h-12 bg-red-500 rounded-full border-4 border-white flex items-center justify-center transition-all duration-500"
                 style={{ left: keeperPos !== null ? `${keeperPos * 20 + 10}%` : '50%', transform: 'translateX(-50%)' }}
               >
                   <ShieldAlert size={24} />
               </div>
          </div>

          <div className="mt-8 flex gap-3">
              {MULTIPLIERS.map((m, i) => (
                  <div key={i} className={`px-4 py-2 rounded-xl font-black text-xs border ${round > i ? 'bg-green-500 border-green-400' : round === i ? 'bg-yellow-500 text-black border-white' : 'bg-black/40 border-white/10 text-slate-500'}`}>
                      {m}x
                  </div>
              ))}
          </div>
      </div>

      <div className="bg-[#111] p-6 border-t border-white/5 pb-12">
        <div className="flex justify-between items-center mb-6">
            <div>
                <p className="text-[10px] text-slate-500 uppercase font-black">Stake</p>
                <input type="number" value={betAmount} onChange={e => setBetAmount(Number(e.target.value))} className="bg-transparent text-2xl font-black outline-none" />
            </div>
            {round > 0 && (
                <button onClick={() => cashOut()} className="bg-yellow-500 text-black px-8 py-4 rounded-2xl font-black shadow-xl active:scale-95">
                    COLLECT ₹{(betAmount * MULTIPLIERS[round-1]).toFixed(2)}
                </button>
            )}
        </div>
        <p className="text-center text-[10px] text-slate-400 uppercase tracking-widest">Select a target on the goal to start</p>
      </div>
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

export default Penalty;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw } from 'lucide-react';
