import { GameResult } from '../types';

const FRUITS = ['🍎', '🍓', '🍋', '🍉', '🍇', '🍒', '🍊'];

const FruitSlot: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [reels, setReels] = useState(['🍎', '🍎', '🍎']);
  const [spinning, setSpinning] = useState(false);

  const spin = () => {
    if (spinning || userBalance < bet) return;
    updateBalance(-bet, 'BET', 'Fruit Slots');
    setSpinning(true);
    playSound('spin');

    let count = 0;
    const interval = setInterval(() => {
        setReels([
            FRUITS[Math.floor(Math.random() * FRUITS.length)],
            FRUITS[Math.floor(Math.random() * FRUITS.length)],
            FRUITS[Math.floor(Math.random() * FRUITS.length)]
        ]);
        count++;
        if (count > 20) {
            clearInterval(interval);
            finalize();
        }
    }, 100);
  };

  const finalize = () => {
    const outcome = [
        FRUITS[Math.floor(Math.random() * FRUITS.length)],
        FRUITS[Math.floor(Math.random() * FRUITS.length)],
        FRUITS[Math.floor(Math.random() * FRUITS.length)]
    ];
    setReels(outcome);
    setSpinning(false);

    const isMatch3 = outcome[0] === outcome[1] && outcome[1] === outcome[2];
    const isMatch2 = outcome[0] === outcome[1] || outcome[1] === outcome[2] || outcome[0] === outcome[2];

    let mult = 0;
    if (isMatch3) mult = 20;
    else if (isMatch2) mult = 2;

    if (mult > 0) {
        updateBalance(bet * mult, 'WIN', 'Fruit Slot Win');
        playSound('win');
    } else {
        playSound('loss');
    }
  };

  return (
    <div className="bg-[#1e0a11] min-h-screen flex flex-col font-sans text-white">
        <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5">
            <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
            <h1 className="text-xl font-black text-pink-500 italic uppercase">FRUIT PARTY</h1>
            <div className="text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
        </div>
        <div className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="w-full max-w-sm bg-gradient-to-b from-pink-900 to-pink-950 p-6 rounded-[2.5rem] border-[8px] border-pink-700 shadow-[0_0_50px_rgba(236,72,153,0.3)]">
                 <div className="bg-black/60 p-4 rounded-[2rem] flex justify-between gap-2">
                    {reels.map((r, i) => (
                        <div key={i} className="flex-1 h-32 bg-white rounded-2xl flex items-center justify-center text-4xl shadow-inner">
                            {r}
                        </div>
                    ))}
                 </div>
            </div>
            <div className="mt-10 flex gap-2">
                {[10, 50, 100].map(a => <button key={a} onClick={() => setBet(a)} className={`px-6 py-2 rounded-xl font-black ${bet === a ? 'bg-pink-500' : 'bg-slate-800'}`}>₹{a}</button>)}
            </div>
            <button onClick={spin} className="mt-10 w-full max-w-xs py-5 bg-gradient-to-r from-pink-500 to-rose-600 rounded-2xl font-black text-xl shadow-xl active:scale-95">SPIN NOW</button>
        </div>
    </div>
  );
};

