import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, Trash2 } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const DiceDuel: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [target, setTarget] = useState<'BIG' | 'SMALL' | null>(null);
  const [isRolling, setIsRolling] = useState(false);
  const [dice, setDice] = useState([1, 1]);
  const [history, setHistory] = useState<number[]>([]);

  const roll = () => {
    if (isRolling || !target || userBalance < bet) return;

    updateBalance(-bet, 'BET', 'Dice Duel');
    setIsRolling(true);
    playSound('spin');

    let count = 0;
    const interval = setInterval(() => {
        setDice([Math.floor(Math.random() * 6) + 1, Math.floor(Math.random() * 6) + 1]);
        count++;
        if (count > 15) {
            clearInterval(interval);
            finalize();
        }
    }, 80);
  };

  const finalize = () => {
    const d1 = Math.floor(Math.random() * 6) + 1;
    const d2 = Math.floor(Math.random() * 6) + 1;
    const sum = d1 + d2;
    setDice([d1, d2]);
    setIsRolling(false);

    const outcome = sum >= 7 ? 'BIG' : 'SMALL';
    const isWin = target === outcome;
    const winAmt = isWin ? bet * 1.95 : 0;

    if (isWin) {
        updateBalance(winAmt, 'WIN', 'Dice Win');
        playSound('win');
    } else {
        playSound('loss');
    }

    setHistory(prev => [sum, ...prev].slice(0, 10));
    onResult({ win: isWin, amount: isWin ? winAmt : bet, game: 'Dice Duel', resultDetails: [{label: 'Sum', value: sum.toString()}] });
    addGameHistory('Dice Duel', bet, winAmt, `Bet ${target} | Sum ${sum}`);
  };

  return (
    <div className="bg-[#111] min-h-screen flex flex-col font-sans text-white">
        <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5">
            <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
            <h1 className="text-xl font-black gold-text italic tracking-widest">DICE DUEL</h1>
            <div className="text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="flex gap-6 mb-12">
                {dice.map((v, i) => (
                    <div key={i} className={`w-24 h-24 bg-white rounded-3xl flex items-center justify-center text-5xl text-black shadow-2xl border-b-[8px] border-slate-300 transition-transform ${isRolling ? 'rotate-12 scale-90' : ''}`}>
                        {v}
                    </div>
                ))}
            </div>

            <div className="grid grid-cols-2 gap-4 w-full max-w-xs mb-8">
                <button onClick={() => setTarget('SMALL')} className={`py-6 rounded-2xl font-black text-xl border-b-8 transition-all ${target === 'SMALL' ? 'bg-blue-600 border-blue-800 scale-105 shadow-xl' : 'bg-slate-800 border-slate-900 opacity-60'}`}>
                    SMALL <p className="text-[10px] opacity-60">(2-6)</p>
                </button>
                <button onClick={() => setTarget('BIG')} className={`py-6 rounded-2xl font-black text-xl border-b-8 transition-all ${target === 'BIG' ? 'bg-orange-600 border-orange-800 scale-105 shadow-xl' : 'bg-slate-800 border-slate-900 opacity-60'}`}>
                    BIG <p className="text-[10px] opacity-60">(7-12)</p>
                </button>
            </div>
        </div>

        <div className="bg-black p-6 pb-12 border-t border-white/5">
            <div className="flex gap-2 mb-6 overflow-x-auto no-scrollbar pb-2">
                {[10, 50, 100, 500, 1000].map(a => <button key={a} onClick={() => setBet(a)} className={`px-5 py-2 rounded-xl font-black text-xs ${bet === a ? 'bg-yellow-500 text-black' : 'bg-zinc-800 text-zinc-500'}`}>₹{a}</button>)}
            </div>
            <button onClick={roll} disabled={!target || isRolling} className="w-full py-6 rounded-3xl bg-gradient-to-r from-red-600 to-orange-600 font-black text-2xl uppercase shadow-xl active:scale-95 transition-all">ROLL DICE</button>
        </div>
        <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

