import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Rocket, Zap, HelpCircle, X } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const Limbo: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [targetMult, setTargetMult] = useState(2.0); 
  const [gameState, setGameState] = useState<'IDLE' | 'RISING' | 'DONE'>('IDLE');
  const [resultMult, setResultMult] = useState(1.0);
  const [history, setHistory] = useState<number[]>([]);
  const [showRules, setShowRules] = useState(false);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const handleTargetChange = (val: string) => {
      const num = parseFloat(val);
      if (isNaN(num)) {
          setTargetMult(1.1);
          return;
      }
      setTargetMult(num);
  };

  const startRound = () => {
    if (gameState === 'RISING' || userBalance < betAmount) return;

    const finalTarget = Math.max(1.1, targetMult);

    updateBalance(-betAmount, 'BET', 'Limbo Stake');
    playSound('click');
    setGameState('RISING');

    // Provably fair generation (simulated)
    const r = Math.random();
    const outcome = Math.max(1, 0.99 / (1 - r));
    const cappedOutcome = Math.min(10000, outcome);

    let current = 1.0;
    const interval = setInterval(() => {
        if (!isMounted.current) { clearInterval(interval); return; }
        current *= 1.25;
        if (current >= cappedOutcome) {
            clearInterval(interval);
            setResultMult(cappedOutcome);
            setGameState('DONE');
            finalize(cappedOutcome, finalTarget);
        } else {
            setResultMult(current);
        }
    }, 50);
  };

  const finalize = (outcome: number, target: number) => {
    const isWin = outcome >= target;
    const winAmt = isWin ? betAmount * target : 0;

    if (isWin) {
        updateBalance(winAmt, 'WIN', 'Limbo Win');
        playSound('win');
    } else {
        playSound('loss');
    }

    setHistory(prev => [outcome, ...prev].slice(0, 10));
    onResult({ win: isWin, amount: isWin ? winAmt : betAmount, game: 'Limbo' });
    addGameHistory('Limbo', betAmount, winAmt, `Target ${target}x | Got ${outcome.toFixed(2)}x`);

    setTimeout(() => {
        if(isMounted.current) setGameState('IDLE');
    }, 1500);
  };

  return (
    <div className="bg-[#0f172a] min-h-screen flex flex-col font-sans text-white relative">
      <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text italic tracking-widest">LIMBO ARENA</h1>
        <button onClick={() => setShowRules(true)} className="p-2 bg-blue-500/20 rounded-xl text-blue-400"><HelpCircle size={20}/></button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6 bg-[radial-gradient(circle_at_50%_50%,_#1e293b_0%,_transparent_70%)]">
        <div className={`text-7xl font-black mb-8 italic tracking-tighter ${gameState === 'DONE' ? (resultMult >= targetMult ? 'text-green-500' : 'text-red-500') : 'text-white'}`}>
            {resultMult.toFixed(2)}x
        </div>

        <div className={`w-32 h-32 rounded-full flex items-center justify-center bg-blue-600/10 border-4 border-blue-500/20 shadow-[0_0_50px_rgba(59,130,246,0.2)] ${gameState === 'RISING' ? 'animate-bounce' : ''}`}>
             <Rocket size={64} className="text-blue-500 -rotate-45" />
        </div>

        <div className="mt-12 flex gap-2 overflow-x-auto no-scrollbar max-w-full px-4">
            {history.map((h, i) => (
                <span key={i} className={`px-4 py-1.5 rounded-full text-[10px] font-black border border-white/5 ${h >= targetMult ? 'text-green-400 bg-green-500/10' : 'text-red-400 bg-red-500/10'}`}>{h.toFixed(2)}x</span>
            ))}
        </div>
      </div>

      <div className="bg-[#111] p-6 border-t border-white/5 pb-12">
        <div className="grid grid-cols-2 gap-4 mb-6">
            <div className="space-y-2">
                <label className="text-[10px] text-slate-500 font-black uppercase">Stake Amount</label>
                <div className="bg-black rounded-xl p-3 flex items-center gap-2 border border-white/10">
                    <span className="text-yellow-500">₹</span>
                    <input type="number" value={betAmount} onChange={e => setBetAmount(Number(e.target.value))} className="bg-transparent w-full outline-none font-bold" />
                </div>
            </div>
            <div className="space-y-2">
                <label className="text-[10px] text-slate-500 font-black uppercase">Target Multiplier</label>
                <div className="bg-black rounded-xl p-3 flex items-center gap-2 border border-white/10">
                    <span className="text-blue-500">x</span>
                    <input 
                        type="number" 
                        step="0.1" 
                        value={targetMult} 
                        onChange={e => handleTargetChange(e.target.value)} 
                        className="bg-transparent w-full outline-none font-bold" 
                    />
                </div>
            </div>
        </div>

        <button onClick={startRound} disabled={gameState === 'RISING'} className="w-full py-6 rounded-3xl bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-black text-xl active:scale-95 transition-all shadow-xl">
            {gameState === 'RISING' ? 'BOOSTING...' : 'START JET'}
        </button>
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
              <div className="bg-slate-900 border border-slate-700 w-full max-w-sm p-6 rounded-3xl animate-in zoom-in">
                   <div className="flex justify-between items-center mb-6">
                       <h2 className="text-xl font-black gold-text">LIMBO RULES</h2>
                       <button onClick={() => setShowRules(false)}><X/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-400">
                       <p>1. Set your <span className="text-white font-bold">Stake</span> and any <span className="text-blue-400 font-bold">Target Multiplier</span> (Min 1.1x).</p>
                       <p>2. If the rocket crashes <span className="text-green-500 font-bold">AFTER</span> your target, you win your target payout.</p>
                       <p>3. If it crashes <span className="text-red-500 font-bold">BEFORE</span>, you lose your stake.</p>
                       <div className="bg-black/50 p-4 rounded-xl border border-white/5">
                           <p className="text-xs italic text-yellow-500">Ex: Target 5.0x, Rocket hits 7.0x. You win 5x your bet!</p>
                       </div>
                   </div>
              </div>
          </div>
      )}
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

export default Limbo;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, HelpCircle, X, Lock, Flame, Sparkles } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const LEVELS = [1.32, 1.76, 2.35, 3.12, 4.20, 5.60, 7.50, 10.0, 13.5, 18.0, 24.0, 32.0];

const DragonTower: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [currentLv, setCurrentLv] = useState(-1);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'REVEALING' | 'LOST'>('IDLE');
  const [showRules, setShowRules] = useState(false);
  const [revealedIdx, setRevealedIdx] = useState<number | null>(null);
  const [gridData, setGridData] = useState<number[][]>([]); // stores trap positions

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const start = () => {
    if (userBalance < bet) return;
    updateBalance(-bet, 'BET', 'Dragon Tower');
    playSound('click');

    // Pre-generate traps for all levels (1 out of 4)
    const newGrid = LEVELS.map(() => Math.floor(Math.random() * 4));
    setGridData(newGrid as any);

    setGameState('PLAYING');
    setCurrentLv(-1);
    setRevealedIdx(null);
  };

  const pick = async (idx: number) => {
    if (gameState !== 'PLAYING') return;
    setGameState('REVEALING');
    setRevealedIdx(idx);
    playSound('tick');

    await new Promise(r => setTimeout(r, 800));

    const trapIdx = gridData[currentLv + 1];
    const isWin = idx !== trapIdx;

    if (isWin) {
        playSound('win');
        setCurrentLv(prev => prev + 1);
        setGameState('PLAYING');
        setRevealedIdx(null);
        if (currentLv + 1 === LEVELS.length - 1) cashout(true);
    } else {
        playSound('loss');
        setGameState('LOST');
        addGameHistory('Dragon Tower', bet, 0, `Burned at Level ${currentLv + 2}`);
        setTimeout(() => {
            if(isMounted.current) {
                setGameState('IDLE');
                setCurrentLv(-1);
            }
        }, 2000);
    }
  };

  const cashout = (auto = false) => {
    if (currentLv === -1) return;
    const winAmt = bet * LEVELS[currentLv];
    updateBalance(winAmt, 'WIN', 'Dragon Tower Cashout');
    playSound('win');
    onResult({ win: true, amount: winAmt, game: 'Dragon Tower', resultDetails: [{label: 'Level', value: `${currentLv + 1}`}]});
    setGameState('IDLE');
    setCurrentLv(-1);
  };

  return (
    <div className="bg-[#0c0a1a] min-h-screen flex flex-col font-sans text-white overflow-hidden relative">
      <div className="p-4 flex justify-between items-center bg-black/60 border-b border-yellow-500/20 relative z-50">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text italic tracking-widest uppercase">DRAGON TOWER</h1>
        <button onClick={() => setShowRules(true)} className="p-2 bg-orange-500/20 text-orange-400 rounded-xl"><HelpCircle size={20}/></button>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar p-4 flex flex-col-reverse gap-3 bg-[url('https://images.unsplash.com/photo-1614850523459-c2f4c699c52e?auto=format&fit=crop&q=80&w=800')] bg-cover">
          <div className="absolute inset-0 bg-black/60 pointer-events-none"></div>
          {LEVELS.map((m, i) => (
              <div key={i} className={`h-14 w-full rounded-2xl border-2 flex items-center justify-between px-4 transition-all duration-500 relative z-10 ${currentLv === i ? 'bg-orange-600/40 border-orange-400 shadow-[0_0_20px_rgba(249,115,22,0.4)] scale-[1.02]' : i === currentLv + 1 ? 'bg-slate-800/90 border-slate-600' : 'bg-black/40 border-white/5 opacity-40'}`}>
                  <span className="font-black text-sm italic w-12">{m}x</span>
                  <div className="flex-1 flex justify-end gap-2">
                      {[0,1,2,3].map(tileIdx => {
                          const isPicked = i === currentLv + 1 && revealedIdx === tileIdx;
                          const isTrap = gameState === 'LOST' && i === currentLv + 1 && tileIdx === gridData[i];

                          return (
                              <button 
                                key={tileIdx} 
                                onClick={() => pick(tileIdx)}
                                disabled={i !== currentLv + 1 || gameState !== 'PLAYING'}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center transition-all border shadow-lg ${
                                    isTrap ? 'bg-red-600 border-red-400 animate-bounce' :
                                    isPicked ? 'bg-yellow-500 border-white scale-110' :
                                    i === currentLv + 1 ? 'bg-slate-700 border-slate-500 hover:bg-slate-600' :
                                    currentLv >= i ? 'bg-green-600/20 border-green-500/40' : 'bg-black/20 border-white/5'
                                }`}
                              >
                                  {isTrap ? <Flame size={20} className="fill-white"/> : 
                                   currentLv >= i ? <Sparkles size={14} className="text-yellow-400"/> : 
                                   i === currentLv + 1 ? '?' : <Lock size={12} className="text-slate-600"/>}
                              </button>
                          );
                      })}
                  </div>
              </div>
          ))}
      </div>

      <div className="bg-[#111] p-6 border-t border-white/10 pb-12 z-50 shadow-[0_-10px_40px_rgba(0,0,0,1)]">
        {gameState === 'IDLE' ? (
            <div className="space-y-4">
                <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
                    {[10, 100, 500, 1000].map(a => <button key={a} onClick={() => setBet(a)} className={`flex-shrink-0 px-6 py-2 rounded-xl font-black border transition-all ${bet === a ? 'bg-yellow-500 text-black border-white' : 'bg-slate-900 text-slate-500 border-white/5'}`}>₹{a}</button>)}
                </div>
                <button onClick={start} className="w-full py-5 bg-gradient-to-r from-orange-600 to-red-600 rounded-[2rem] font-black text-xl shadow-xl active:scale-95 transition-all uppercase tracking-widest">CLIMB TOWER</button>
            </div>
        ) : (
            <div className="space-y-4">
                <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
                    <span className="text-[10px] text-slate-500 uppercase tracking-widest font-black">Current Reward</span>
                    <h3 className="text-2xl font-black gold-text">₹{(bet * (currentLv === -1 ? 0 : LEVELS[currentLv])).toFixed(2)}</h3>
                </div>
                <button onClick={() => cashout()} disabled={currentLv === -1 || gameState === 'REVEALING'} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-xl transition-all uppercase tracking-widest ${currentLv === -1 ? 'bg-zinc-800 text-zinc-600' : 'bg-yellow-500 text-black shadow-yellow-500/40'}`}>
                    {currentLv === -1 ? 'PICK A TILE' : `CASH OUT`}
                </button>
            </div>
        )}
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 border border-orange-500/30 w-full max-w-sm p-8 rounded-[2.5rem] shadow-2xl">
                   <div className="flex justify-between items-center mb-8">
                       <h2 className="text-2xl font-black italic gold-text">TOWER RULES</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 leading-relaxed">
                       <p>1. Each level has **4 tiles**.</p>
                       <p>2. One tile contains a <span className="text-red-500 font-bold">Dragon Fire Trap</span>.</p>
                       <p>3. Choose any of the 3 safe tiles to advance and multiply your winnings.</p>
                       <p>4. You can <span className="text-yellow-500 font-bold">Cash Out</span> anytime after the first successful pick.</p>
                       <p>5. If you hit the Fire, you lose your entire stake!</p>
                   </div>
              </div>
          </div>
      )}
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

