import React, { useState, useEffect } from 'react';
import NavBar from './components/NavBar';
import Home from './pages/Home';
import WinGo from './pages/WinGo';
import Aviator from './pages/Aviator';
import Mines from './pages/Mines';
import DogRoad from './pages/DogRoad';
import LuckyWheel from './pages/LuckyWheel';
import DragonTiger from './pages/DragonTiger';
import Plinko from './pages/Plinko';
import HeadTails from './pages/HeadTails';
import MotoRacing from './pages/MotoRacing';
import SlotMachine from './pages/SlotMachine';
import AndarBahar from './pages/AndarBahar';
import HiLo from './pages/HiLo';
import Limbo from './pages/Limbo';
import DragonTower from './pages/DragonTower';
import Keno from './pages/Keno';
import FruitSlot from './pages/FruitSlot';
import EgyptSlot from './pages/EgyptSlot';
import DiceDuel from './pages/DiceDuel';
import Profile from './pages/Profile';
import Referral from './pages/Referral';
import Promotion from './pages/Promotion';
import Deposit from './pages/Deposit';
import Withdraw from './pages/Withdraw';
import Wallet from './pages/Wallet';
import SafetyCenter from './pages/SafetyCenter';
import GameStatistics from './pages/GameStatistics';
import Auth from './pages/Auth';
import GameResultPopup from './components/GameResultPopup';
import { View, UserProfile, GameResult } from './types';
import { subscribeToBalance, startWinGoGame, stopAllSounds } from './services/mockFirebase';

export default function App() {
  const [currentView, setCurrentView] = useState<View>('HOME');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [gameResult, setGameResult] = useState<GameResult | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => { 
      startWinGoGame(); 
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToBalance((updatedUser) => {
        setUser(updatedUser);
        setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    stopAllSounds(); 
  }, [currentView]);

  if (isLoading) return <div className="min-h-screen bg-[#0a0f1d] flex items-center justify-center"><div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;

  if (!user) return <Auth />;

  const handleGameResult = (result: GameResult) => {
    const hiddenPopupGames = ['Aviator', 'Plinko', 'Slot Machine', 'Hi-Lo Royale', 'Fruit Slot', 'Egyptian Gold', 'Limbo', 'Dragon Tower', 'Keno Elite', 'Dice Duel'];
    if (hiddenPopupGames.includes(result.game)) {
        return; 
    }
    setGameResult(result);
  };

  const renderContent = () => {
    switch (currentView) {
      case 'HOME': return <Home setView={setCurrentView} />;
      case 'GAME_WINGO': return <WinGo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} onDeposit={() => setCurrentView('DEPOSIT')} />;
      case 'GAME_AVIATOR': return <Aviator onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_MINES': return <Mines onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_DOG': return <DogRoad onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_LUCKY_WHEEL': return <LuckyWheel onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_DRAGON_TIGER': return <DragonTiger onBack={() => setCurrentView('HOME')} userBalance={user.balance} username={user.username} onResult={handleGameResult} />;
      case 'GAME_PLINKO': return <Plinko onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_HEAD_TAILS': return <HeadTails onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_MOTO_RACING': return <MotoRacing onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_SLOTS': return <SlotMachine onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_ANDAR_BAHAR': return <AndarBahar onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_HILO': return <HiLo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_LIMBO': return <Limbo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_DRAGON_TOWER': return <DragonTower onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_KENO': return <Keno onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_FRUIT_SLOT': return <FruitSlot onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_EGYPT_SLOT': return <EgyptSlot onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'GAME_DICE': return <DiceDuel onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={handleGameResult} />;
      case 'ACCOUNT': return <Profile user={user} setView={setCurrentView} />;
      case 'REFERRAL': return <Referral />;
      case 'PROMOTION': return <Promotion />;
      case 'WALLET': return <Wallet setView={setCurrentView} userBalance={user.balance} />;
      case 'DEPOSIT': return <Deposit onBack={() => setCurrentView('WALLET')} />;
      case 'WITHDRAW': return <Withdraw onBack={() => setCurrentView('WALLET')} userBalance={user.balance} />;
      case 'SAFETY': return <SafetyCenter setView={setCurrentView} user={user} />;
      case 'STATISTICS': return <GameStatistics setView={setCurrentView} />;
      default: return <Home setView={setCurrentView} />;
    }
  };

  const showNavBar = ['HOME', 'REFERRAL', 'PROMOTION', 'WALLET', 'ACCOUNT'].includes(currentView);

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0a0f1d] shadow-2xl relative overflow-hidden font-sans">
      {renderContent()}
      <GameResultPopup result={gameResult} onClose={() => setGameResult(null)} />
      {showNavBar && <NavBar currentView={currentView} setView={setCurrentView} />}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, HelpCircle, X } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const SYMBOLS = ['🏺', '👁️', '🐈', '☥', '🪲', '🪙', '👸'];

const EgyptSlot: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [reels, setReels] = useState(['🏺', '🏺', '🏺']);
  const [spinning, setSpinning] = useState(false);
  const [showRules, setShowRules] = useState(false);
  const [floating, setFloating] = useState<{ text: string; color: string; id: number } | null>(null);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const triggerFloating = (text: string, color: string) => {
      setFloating({ text, color, id: Date.now() });
      setTimeout(() => setFloating(null), 1500);
  };

  const spin = () => {
    if (spinning || userBalance < bet) return;
    updateBalance(-bet, 'BET', 'Egyptian Gold');
    setSpinning(true);
    playSound('spin');

    let count = 0;
    const interval = setInterval(() => {
        setReels([
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
            SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
        ]);
        count++;
        if (count > 30) {
            clearInterval(interval);
            finalize();
        }
    }, 60);
  };

  const finalize = () => {
    if (!isMounted.current) return;
    const outcome = [
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)],
        SYMBOLS[Math.floor(Math.random() * SYMBOLS.length)]
    ];
    setReels(outcome);
    setSpinning(false);

    const isMatch3 = outcome[0] === outcome[1] && outcome[1] === outcome[2];
    const isMatch2 = outcome[0] === outcome[1] || outcome[1] === outcome[2] || outcome[0] === outcome[2];

    let mult = 0;
    if (isMatch3) mult = outcome[0] === '🏺' ? 100 : 40;
    else if (isMatch2) mult = 3.0;

    if (mult > 0) {
        const win = bet * mult;
        updateBalance(win, 'WIN', 'Egyptian Win');
        playSound('win');
        triggerFloating(`+₹${win.toFixed(2)}`, 'text-yellow-400');
    } else {
        playSound('loss');
        triggerFloating(`-₹${bet.toFixed(2)}`, 'text-red-500');
    }
  };

  return (
    <div className="bg-[#1a1200] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
        {floating && (
            <div key={floating.id} className={`fixed top-1/2 left-1/2 -translate-x-1/2 z-[100] font-black text-5xl italic pointer-events-none animate-float-up ${floating.color}`} style={{ textShadow: '0 0 20px rgba(0,0,0,0.5)' }}>
                {floating.text}
            </div>
        )}

        <div className="p-4 flex justify-between items-center bg-black/40 border-b border-yellow-500/20">
            <button onClick={onBack} className="p-2 bg-zinc-900 rounded-xl"><ArrowLeft size={20}/></button>
            <h1 className="text-xl font-black gold-text italic uppercase">EGYPT GOLD</h1>
            <button onClick={() => setShowRules(true)} className="p-2 bg-yellow-500/10 text-yellow-500 rounded-xl"><HelpCircle size={20}/></button>
        </div>
        <div className="flex-1 flex flex-col items-center justify-center p-6">
            <div className="w-full max-w-sm bg-gradient-to-b from-yellow-700 to-yellow-950 p-6 rounded-[2.5rem] border-[8px] border-yellow-600 shadow-[0_0_80px_rgba(234,179,8,0.2)]">
                 <div className="bg-[#111] p-4 rounded-[2rem] flex justify-between gap-3 shadow-inner">
                    {reels.map((r, i) => (
                        <div key={i} className={`flex-1 h-36 bg-zinc-100 rounded-2xl flex items-center justify-center text-5xl border-4 border-yellow-500/30 transition-all ${spinning ? 'scale-90 opacity-50' : 'animate-in zoom-in'}`}>
                            {r}
                        </div>
                    ))}
                 </div>
            </div>
            <div className="mt-12 w-full max-w-xs space-y-6">
                <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-yellow-500/20">
                    <span className="text-xs font-black uppercase text-yellow-500/60 tracking-widest">Balance</span>
                    <span className="font-black text-yellow-500 text-xl font-mono">₹{userBalance.toFixed(2)}</span>
                </div>
                <button onClick={spin} disabled={spinning} className="w-full py-6 bg-gradient-to-r from-yellow-500 to-yellow-700 text-black font-black text-2xl rounded-3xl shadow-xl shadow-yellow-900/40 active:scale-95 transition-all border-t-2 border-white/20">
                   {spinning ? 'BLESSING REELS...' : `STAKE ₹${bet}`}
                </button>
            </div>
        </div>

        {showRules && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-sm">
                <div className="bg-[#1a1200] border-2 border-yellow-500/30 w-full max-w-sm p-8 rounded-[2.5rem] shadow-2xl">
                     <div className="flex justify-between items-center mb-10">
                         <h2 className="text-2xl font-black gold-text italic uppercase">ANCIENT PAYOUTS</h2>
                         <button onClick={() => setShowRules(false)} className="p-2 bg-zinc-900 rounded-full"><X/></button>
                     </div>
                     <div className="space-y-4">
                         <div className="flex justify-between items-center bg-zinc-900/80 p-4 rounded-2xl border border-yellow-500/10">
                             <div className="flex gap-2 text-2xl">🏺🏺🏺</div>
                             <div className="text-2xl font-black text-yellow-400">100X</div>
                         </div>
                         <div className="flex justify-between items-center bg-zinc-900/80 p-4 rounded-2xl border border-yellow-500/10">
                             <div className="flex gap-2 text-2xl">👁️👁️👁️</div>
                             <div className="text-2xl font-black text-yellow-400">40X</div>
                         </div>
                     </div>
                </div>
            </div>
        )}
        <style>{`
            .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
            @keyframes float-up {
                0% { transform: translate(-50%, 0); opacity: 0; scale: 0.5; }
                20% { opacity: 1; scale: 1.2; }
                100% { transform: translate(-50%, -150px); opacity: 0; scale: 1.5; }
            }
            .animate-float-up { animation: float-up 1.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
        `}</style>
    </div>
  );
};

