import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, HelpCircle, X, Lock, Flame, Sparkles } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const LEVELS = [1.32, 1.76, 2.35, 3.12, 4.20, 5.60, 7.50, 10.0, 13.5, 18.0, 24.0, 32.0];

const DragonTower: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [currentLv, setCurrentLv] = useState(-1);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'REVEALING' | 'LOST'>('IDLE');
  const [showRules, setShowRules] = useState(false);
  const [revealedIdx, setRevealedIdx] = useState<number | null>(null);
  const [gridData, setGridData] = useState<number[]>([]); // stores trap positions per row

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const start = () => {
    if (userBalance < bet) return;
    updateBalance(-bet, 'BET', 'Dragon Tower');
    playSound('click');

    // Pre-generate traps for all levels (1 out of 4)
    const newGrid = LEVELS.map(() => Math.floor(Math.random() * 4));
    setGridData(newGrid);

    setGameState('PLAYING');
    setCurrentLv(-1);
    setRevealedIdx(null);
  };

  const pick = async (idx: number) => {
    if (gameState !== 'PLAYING') return;
    setGameState('REVEALING');
    setRevealedIdx(idx);
    playSound('tick');

    await new Promise(r => setTimeout(r, 800));

    const trapIdx = gridData[currentLv + 1];
    const isWin = idx !== trapIdx;

    if (isWin) {
        playSound('win');
        setCurrentLv(prev => prev + 1);
        setGameState('PLAYING');
        setRevealedIdx(null);
        if (currentLv + 1 === LEVELS.length - 1) cashout(true);
    } else {
        playSound('loss');
        setGameState('LOST');
        addGameHistory('Dragon Tower', bet, 0, `Burned at Level ${currentLv + 2}`);
        setTimeout(() => {
            if(isMounted.current) {
                setGameState('IDLE');
                setCurrentLv(-1);
            }
        }, 3000);
    }
  };

  const cashout = (auto = false) => {
    // CRITICAL FIX: Can only cash out if game is actively PLAYING and not LOST
    if (gameState !== 'PLAYING' || currentLv === -1) return;

    const winAmt = bet * LEVELS[currentLv];
    updateBalance(winAmt, 'WIN', 'Dragon Tower Cashout');
    playSound('win');
    onResult({ win: true, amount: winAmt, game: 'Dragon Tower', resultDetails: [{label: 'Level', value: `${currentLv + 1}`}]});
    setGameState('IDLE');
    setCurrentLv(-1);
  };

  return (
    <div className="bg-[#0c0a1a] min-h-screen flex flex-col font-sans text-white overflow-hidden relative">
      <div className="p-4 flex justify-between items-center bg-black/60 border-b border-yellow-500/20 relative z-50">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
                <Wallet size={14} className="text-yellow-500" />
                <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
        <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">DRAGON TOWER</h1>
        <button onClick={() => setShowRules(true)} className="p-2 bg-orange-500/20 text-orange-400 rounded-xl"><HelpCircle size={20}/></button>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar p-4 flex flex-col-reverse gap-4 bg-[url('https://images.unsplash.com/photo-1614850523459-c2f4c699c52e?auto=format&fit=crop&q=80&w=800')] bg-cover">
          <div className="absolute inset-0 bg-black/70 pointer-events-none"></div>
          {LEVELS.map((m, i) => (
              <div key={i} className={`h-20 w-full rounded-3xl border-2 flex items-center justify-between px-6 transition-all duration-500 relative z-10 ${currentLv === i ? 'bg-orange-600/30 border-orange-400 shadow-[0_0_30px_rgba(249,115,22,0.3)] scale-[1.03]' : i === currentLv + 1 ? 'bg-slate-800/90 border-slate-500' : 'bg-black/40 border-white/5 opacity-40'}`}>
                  <span className="font-black text-lg italic w-14 text-yellow-500">{m}x</span>
                  <div className="flex-1 flex justify-end gap-3">
                      {[0,1,2,3].map(tileIdx => {
                          const isCurrentRow = i === currentLv + 1;
                          const isPassedRow = currentLv >= i;
                          const isPicked = isCurrentRow && revealedIdx === tileIdx;
                          const isTrap = (gameState === 'LOST' && isCurrentRow && tileIdx === gridData[i]) || (isPassedRow && tileIdx === gridData[i]);
                          const isSafeLanded = isPassedRow && tileIdx !== gridData[i];

                          return (
                              <button 
                                key={tileIdx} 
                                onClick={() => pick(tileIdx)}
                                disabled={!isCurrentRow || gameState !== 'PLAYING'}
                                className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all border-2 shadow-2xl ${
                                    isTrap ? 'bg-red-900/60 border-red-500/50' :
                                    isPicked ? 'bg-yellow-500 border-white scale-110' :
                                    isCurrentRow ? 'bg-slate-700 border-slate-500 hover:bg-slate-600' :
                                    isSafeLanded ? 'bg-green-900/30 border-green-500/30' :
                                    'bg-black/20 border-white/5'
                                }`}
                              >
                                  {isTrap ? <Flame size={28} className="fill-orange-500 text-red-500 animate-pulse"/> : 
                                   isSafeLanded ? <Sparkles size={20} className="text-yellow-400/40"/> : 
                                   isCurrentRow ? <span className="font-black text-xl opacity-30">?</span> : <Lock size={16} className="text-slate-700"/>}
                              </button>
                          );
                      })}
                  </div>
              </div>
          ))}
      </div>

      <div className="bg-[#111] p-6 border-t border-white/10 pb-12 z-50 shadow-[0_-10px_40px_rgba(0,0,0,1)]">
        {gameState === 'IDLE' ? (
            <div className="space-y-4">
                <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
                    {[10, 100, 500, 1000, 5000].map(a => <button key={a} onClick={() => setBet(a)} className={`flex-shrink-0 px-6 py-2 rounded-xl font-black border transition-all ${bet === a ? 'bg-yellow-500 text-black border-white' : 'bg-slate-900 text-slate-500 border-white/5'}`}>₹{a >= 1000 ? (a/1000)+'K' : a}</button>)}
                </div>
                <button onClick={start} className="w-full py-6 bg-gradient-to-r from-orange-600 to-red-600 rounded-[2.5rem] font-black text-xl shadow-xl active:scale-95 transition-all uppercase tracking-widest border-t-2 border-white/10">CLIMB TOWER</button>
            </div>
        ) : (
            <div className="space-y-4">
                <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
                    <span className="text-[10px] text-slate-500 uppercase tracking-widest font-black">Mafia Profit</span>
                    <h3 className="text-2xl font-black gold-text">₹{(bet * (currentLv === -1 ? 0 : LEVELS[currentLv])).toFixed(2)}</h3>
                </div>
                <button 
                    onClick={() => cashout()} 
                    disabled={currentLv === -1 || gameState !== 'PLAYING'} 
                    className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-xl transition-all uppercase tracking-widest ${currentLv === -1 || gameState !== 'PLAYING' ? 'bg-zinc-800 text-zinc-600' : 'bg-yellow-500 text-black shadow-yellow-500/40'}`}
                >
                    {gameState === 'LOST' ? 'ELIMINATED' : currentLv === -1 ? 'PICK A TILE' : `CASH OUT`}
                </button>
            </div>
        )}
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 border border-orange-500/30 w-full max-w-sm p-8 rounded-[2.5rem] shadow-2xl">
                   <div className="flex justify-between items-center mb-8">
                       <h2 className="text-2xl font-black italic gold-text uppercase">How to Win</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 leading-relaxed font-medium">
                       <p>1. Every floor has <span className="text-white font-bold">4 Tiles</span>. Behind one tile hides the <span className="text-red-500 font-bold">Dragon's Fire</span>.</p>
                       <p>2. Choose any safe tile to move up the tower and multiply your winnings.</p>
                       <p>3. As you progress, previous floors will <span className="text-yellow-500 font-bold">Reveal the Fire</span> location to help you track the luck.</p>
                       <p>4. Cash out any time or aim for the <span className="text-yellow-500 font-bold">32X Jackpot</span> at the top!</p>
                   </div>
              </div>
          </div>
      )}
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

export default DragonTower;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, HelpCircle, X } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
