            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
                <Wallet size={14} className="text-yellow-500" />
                <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
        <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">DRAGON TOWER</h1>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar p-4 flex flex-col-reverse gap-4 bg-[#0a0f1d]">
          {LEVELS.map((m, i) => (
              <div key={i} className={`h-20 w-full rounded-3xl border-2 flex items-center justify-between px-6 transition-all duration-500 relative z-10 ${currentLv === i ? 'bg-orange-600/30 border-orange-400 shadow-[0_0_30px_rgba(249,115,22,0.3)] scale-[1.03]' : i === currentLv + 1 ? 'bg-slate-800/90 border-slate-500' : 'bg-black/40 border-white/5 opacity-40'}`}>
                  <span className="font-black text-lg italic w-14 text-yellow-500">{m}x</span>
                  <div className="flex-1 flex justify-end gap-3">
                      {[0,1,2,3].map(tileIdx => {
                          const isCurrentRow = i === currentLv + 1;
                          const isTrap = gridData[i] === tileIdx;
                          const isPicked = isCurrentRow && revealedIdx === tileIdx;

                          // Show logic: 
                          // - If picked and safe, show empty/success
                          // - If picked and bomb, show bomb + shake
                          // - If game over (lost), show all bombs for this row
                          const shouldShowBomb = (isPicked && isTrap) || (gameState === 'LOST' && isTrap && i <= currentLv + 1);

                          return (
                              <button 
                                key={tileIdx} 
                                onClick={() => pick(tileIdx)}
                                disabled={!isCurrentRow || gameState !== 'PLAYING'}
                                className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all border-2 relative overflow-hidden ${
                                    shouldShowBomb 
                                        ? 'bg-red-600 border-red-400 animate-shake' 
                                        : isPicked 
                                            ? 'bg-green-600 border-green-400' 
                                            : isCurrentRow 
                                                ? 'bg-slate-700 border-slate-500 shadow-lg' 
                                                : 'bg-black/20 border-white/5'
                                }`}
                              >
                                  {shouldShowBomb ? (
                                      <Bomb size={24} className="text-white drop-shadow-md" />
                                  ) : isCurrentRow ? (
                                      <span className="text-slate-400 font-black text-xl opacity-30">?</span>
                                  ) : currentLv >= i ? (
                                      <Sparkles size={20} className="text-yellow-400" />
                                  ) : (
                                      <Lock size={16} className="text-slate-700"/>
                                  )}
                              </button>
                          );
                      })}
                  </div>
              </div>
          ))}
      </div>

      <div className="bg-[#111] p-6 border-t border-white/10 pb-12 z-50">
        {gameState === 'IDLE' ? (
            <div className="space-y-4">
