                    ))}
                </div>
                <button onClick={start} className="w-full py-6 bg-gradient-to-r from-orange-600 to-red-600 rounded-[2.5rem] font-black text-xl shadow-xl active:scale-95 transition-all">CLIMB TOWER</button>
            </div>
        ) : (
            <button onClick={() => cashout()} disabled={currentLv === -1 || gameState !== 'PLAYING'} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-xl transition-all ${currentLv === -1 ? 'bg-slate-800 text-slate-600 cursor-not-allowed' : 'bg-yellow-500 text-black shadow-yellow-500/20'}`}>
                {currentLv === -1 ? 'PICK FIRST TILE' : `CASH OUT ₹${(bet * LEVELS[currentLv]).toFixed(2)}`}
            </button>
        )}
      </div>
      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-shake { animation: shake 0.15s infinite; }
      `}</style>
    </div>
  );
};

