import React, { useState, useEffect } from 'react';
import { ArrowLeft, Wallet, Building2, Smartphone, AlertCircle, ShieldCheck, Lock } from 'lucide-react';
import { handleWithdraw, subscribeToBalance } from '../services/mockFirebase';
import { UserProfile } from '../types';

interface Props {
    onBack: () => void;
    userBalance: number;
}

const Withdraw: React.FC<Props> = ({ onBack, userBalance }) => {
    const [amount, setAmount] = useState('');
    const [password, setPassword] = useState('');
    const [method, setMethod] = useState<'BANK' | 'UPI' | 'PHONEPE'>('BANK');
    const [message, setMessage] = useState('');
    const [user, setUser] = useState<UserProfile | null>(null);
    const [details, setDetails] = useState<any>({
        accountName: '',
        accountNo: '',
        ifsc: '',
        upiId: '',
        phoneNumber: ''
    });

    useEffect(() => {
        const unsub = subscribeToBalance(u => setUser(u));
        return unsub;
    }, []);

    const onSubmit = async () => {
        if (!user) return;

        // NEW: Check if user has ever deposited
        if (user.totalDeposit <= 0) {
            setMessage('First-time withdrawal requires at least one previous deposit.');
            return;
        }

        const val = parseFloat(amount);
        if (isNaN(val) || val < 110) {
            setMessage('Minimum withdrawal is ₹110');
            return;
        }

        if (user.wagerRequired > 0) {
            setMessage(`Turnover incomplete! ₹${user.wagerRequired.toFixed(2)} remaining.`);
            return;
        }

        if (!password || password.length < 6) {
            setMessage('Please enter your 6-digit withdrawal PIN');
            return;
        }

        if (method === 'BANK' && (!details.accountNo || !details.ifsc)) {
            setMessage('Please fill all bank details');
            return;
        }

        const res = await handleWithdraw(val, method, password, details);
        if (res.success) {
            setMessage('Request Submitted! Processing (10-30 mins)');
            setAmount('');
            setPassword('');
        } else {
            setMessage(res.message || 'Withdrawal failed');
        }
    };

    return (
        <div className="bg-[#0a0f1d] min-h-screen text-white font-sans flex flex-col pb-10">
            <div className="p-4 bg-[#111827] flex items-center justify-between border-b border-slate-800 sticky top-0 z-50">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="p-2 bg-slate-800 rounded-full"><ArrowLeft size={18}/></button>
                    <h1 className="font-bold">Withdraw Assets</h1>
                </div>
            </div>

            <div className="p-6 space-y-6">
                <div className="bg-gradient-to-br from-blue-600 to-indigo-900 rounded-2xl p-6 border border-white/10 shadow-xl">
                    <p className="text-blue-200 text-sm mb-1 uppercase tracking-widest font-black">Available Balance</p>
                    <h2 className="text-4xl font-black">₹{userBalance.toFixed(2)}</h2>

                    <div className="mt-4 flex gap-4">
                         <div className="bg-black/30 p-2 rounded-lg border border-white/5 flex-1">
                            <p className="text-[8px] text-slate-500 uppercase font-black">Total Deposits</p>
                            <p className="text-sm font-bold text-green-500">₹{user?.totalDeposit?.toFixed(2) || '0.00'}</p>
                         </div>
                         <div className="bg-black/30 p-2 rounded-lg border border-white/5 flex-1">
                            <p className="text-[8px] text-slate-500 uppercase font-black">Withdraw Limit</p>
                            <p className="text-sm font-bold text-white">₹50,000</p>
                         </div>
                    </div>
                </div>

                <div className="space-y-4">
                    <h3 className="text-xs font-black uppercase text-slate-500 tracking-widest">Withdrawal Method</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['BANK', 'UPI', 'PHONEPE'] as const).map(m => (
                            <button 
                                key={m}
                                onClick={() => setMethod(m)}
                                className={`py-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all ${method === m ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 bg-[#111827] text-slate-500'}`}
                            >
                                {m === 'BANK' && <Building2 size={24}/>}
                                {m === 'UPI' && <Smartphone size={24}/>}
                                {m === 'PHONEPE' && <div className="w-6 h-6 bg-purple-600 rounded flex items-center justify-center text-[10px] font-black text-white">Pe</div>}
                                <span className="text-[10px] font-black">{m}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="bg-[#111827] border border-slate-800 rounded-2xl p-5 space-y-4 shadow-inner">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Account Holder Name</label>
                        <input 
                            type="text" 
                            placeholder="Full Name as per Bank"
                            value={details.accountName}
                            onChange={e => setDetails({...details, accountName: e.target.value})}
                            className="w-full bg-[#0a0f1d] border border-slate-800 rounded-xl p-3.5 text-sm text-white outline-none focus:border-blue-500 transition-colors"
                        />
                    </div>

                    {method === 'BANK' && (
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Account No.</label>
                                <input 
                                    type="text" 
                                    placeholder="Number"
                                    value={details.accountNo}
                                    onChange={e => setDetails({...details, accountNo: e.target.value})}
                                    className="w-full bg-[#0a0f1d] border border-slate-800 rounded-xl p-3.5 text-sm text-white outline-none focus:border-blue-500"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase text-slate-500 ml-1">IFSC Code</label>
                                <input 
                                    type="text" 
                                    placeholder="IFSC"
                                    value={details.ifsc}
                                    onChange={e => setDetails({...details, ifsc: e.target.value})}
                                    className="w-full bg-[#0a0f1d] border border-slate-800 rounded-xl p-3.5 text-sm text-white outline-none focus:border-blue-500"
                                />
                            </div>
                        </div>
                    )}

                    {method === 'UPI' && (
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">UPI Address</label>
                            <input 
                                type="text" 
                                placeholder="example@upi"
                                value={details.upiId}
                                onChange={e => setDetails({...details, upiId: e.target.value})}
                                className="w-full bg-[#0a0f1d] border border-slate-800 rounded-xl p-3.5 text-sm text-white outline-none focus:border-blue-500"
                            />
                        </div>
                    )}

                    {method === 'PHONEPE' && (
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">PhonePe Mobile No.</label>
                            <input 
                                type="tel" 
                                placeholder="+91"
                                value={details.phoneNumber}
                                onChange={e => setDetails({...details, phoneNumber: e.target.value})}
                                className="w-full bg-[#0a0f1d] border border-slate-800 rounded-xl p-3.5 text-sm text-white outline-none focus:border-blue-500"
                            />
                        </div>
                    )}
                </div>

                <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Withdraw Amount</label>
                            <div className="bg-[#111827] border border-slate-800 rounded-xl p-3 flex items-center gap-2">
                                <span className="text-yellow-500 font-bold">₹</span>
                                <input 
                                    type="number" 
                                    value={amount} 
                                    onChange={e => setAmount(e.target.value)} 
                                    placeholder="Min 110" 
                                    className="bg-transparent w-full outline-none font-bold text-white"
                                />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-slate-500 ml-1">Withdrawal PIN</label>
                            <div className="bg-[#111827] border border-slate-800 rounded-xl p-3 flex items-center gap-2">
                                <ShieldCheck size={18} className="text-slate-600" />
                                <input 
                                    type="password" 
                                    value={password} 
                                    onChange={e => setPassword(e.target.value.replace(/\D/g,''))} 
                                    placeholder="6-digit" 
                                    maxLength={6}
                                    className="bg-transparent w-full outline-none font-bold tracking-[0.3em] text-white"
                                />
                            </div>
                        </div>
                    </div>

                    {message && (
                        <div className={`p-4 rounded-xl flex items-start gap-3 animate-in fade-in slide-in-from-top-1 ${message.includes('Submitted') ? 'bg-green-500/10 text-green-400 border border-green-500/20' : 'bg-red-500/10 text-red-400 border border-red-500/20'}`}>
                            <AlertCircle size={20} className="shrink-0" />
                            <p className="text-xs font-bold">{message}</p>
                        </div>
                    )}

                    <button 
                        onClick={onSubmit}
                        className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white py-5 rounded-2xl font-black uppercase tracking-[0.2em] transition-all active:scale-95 shadow-xl shadow-blue-900/30"
                    >
                        Confirm Withdrawal
                    </button>
                </div>
            </div>
        </div>
    );
};

