import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, History, Trophy, Trash2, Volume2, VolumeX } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult, RouletteBet } from '../types';

const WHEEL_ORDER = [0, 32, 15, 19, 4, 21, 2, 25, 17, 34, 6, 27, 13, 36, 11, 30, 8, 23, 10, 5, 24, 16, 33, 1, 20, 14, 31, 9, 22, 18, 29, 7, 28, 12, 35, 3, 26];
const REDS = [1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36];

const Roulette: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bets, setBets] = useState<RouletteBet[]>([]);
  const [isSpinning, setIsSpinning] = useState(false);
  const [wheelRotation, setWheelRotation] = useState(0);
  const [history, setHistory] = useState<number[]>([]);
  const [selectedChip, setSelectedChip] = useState(10);
  const [lastResult, setLastResult] = useState<number | null>(null);
  const [muted, setMuted] = useState(getMuteStatus());

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const addBet = (type: RouletteBet['type'], value: string | number) => {
    if (isSpinning) return;
    if (userBalance < selectedChip) return alert("Insufficient Balance");

    updateBalance(-selectedChip, 'BET', `Roulette Bet: ${value}`);
    playSound('click');

    const existingIdx = bets.findIndex(b => b.type === type && b.value === value);
    if (existingIdx > -1) {
        const newBets = [...bets];
        newBets[existingIdx].amount += selectedChip;
        setBets(newBets);
    } else {
        setBets([...bets, { type, value, amount: selectedChip }]);
    }
  };

  const clearBets = () => {
    if (isSpinning) return;
    const totalRefund = bets.reduce((acc, b) => acc + b.amount, 0);
    if (totalRefund > 0) {
        updateBalance(totalRefund, 'GIFT', 'Roulette Refund');
        setBets([]);
        playSound('click');
    }
  };

  const spin = () => {
    if (isSpinning || bets.length === 0) return;
    setIsSpinning(true);
    playSound('spin');

    const result = WHEEL_ORDER[Math.floor(Math.random() * WHEEL_ORDER.length)];
    const resultIdx = WHEEL_ORDER.indexOf(result);
    const segmentAngle = 360 / WHEEL_ORDER.length;

    // Multiple rotations + calculated offset to land on the number
    const extraRots = 360 * 10;
    const offset = resultIdx * segmentAngle;
    const finalRotation = wheelRotation + extraRots + (360 - (wheelRotation % 360)) - offset;

    setWheelRotation(finalRotation);

    setTimeout(() => finalize(result), 5000);
  };

  const finalize = (num: number) => {
    if (!isMounted.current) return;
    setIsSpinning(false);
    setLastResult(num);
    setHistory(prev => [num, ...prev].slice(0, 10));

    let totalWin = 0;
    const isRed = REDS.includes(num);
    const isEven = num !== 0 && num % 2 === 0;

    bets.forEach(bet => {
        if (bet.type === 'NUMBER' && bet.value === num) totalWin += bet.amount * 36;
        if (bet.type === 'COLOR') {
            if (bet.value === 'RED' && isRed) totalWin += bet.amount * 2;
            if (bet.value === 'BLACK' && !isRed && num !== 0) totalWin += bet.amount * 2;
        }
        if (bet.type === 'ODD_EVEN') {
            if (bet.value === 'EVEN' && isEven) totalWin += bet.amount * 2;
            if (bet.value === 'ODD' && !isEven && num !== 0) totalWin += bet.amount * 2;
        }
        if (bet.type === 'RANGE') {
            if (bet.value === '1-18' && num >= 1 && num <= 18) totalWin += bet.amount * 2;
            if (bet.value === '19-36' && num >= 19 && num <= 36) totalWin += bet.amount * 2;
        }
    });

    if (totalWin > 0) {
        updateBalance(totalWin, 'WIN', 'Roulette Win');
        playSound('win');
        onResult({ win: true, amount: totalWin, game: 'Mafia Roulette', resultDetails: [{label: 'Number', value: num.toString(), color: isRed ? 'text-red-500' : num === 0 ? 'text-green-500' : 'text-slate-400'}] });
    } else {
        playSound('loss');
        onResult({ win: false, amount: bets.reduce((acc,b)=>acc+b.amount,0), game: 'Mafia Roulette', resultDetails: [{label: 'Landed', value: num.toString()}] });
    }

    setBets([]);
    addGameHistory('Mafia Roulette', bets.reduce((acc,b)=>acc+b.amount,0), totalWin, `Landed ${num}`);
  };

  const getNumColor = (n: number) => n === 0 ? 'bg-green-600' : REDS.includes(n) ? 'bg-red-600' : 'bg-slate-900';

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white overflow-hidden relative">
      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-black/40 border-b border-yellow-500/20 z-50 shadow-2xl">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl active:scale-90"><ArrowLeft size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20">
                <Wallet size={14} className="text-yellow-500" />
                <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
        <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">MAFIA ROULETTE</h1>
        <button onClick={() => setMuted(toggleMute())} className="p-2 bg-zinc-900 rounded-xl">
            {muted ? <VolumeX size={18}/> : <Volume2 size={18}/>}
        </button>
      </div>

      {/* Arena */}
      <div className="flex-1 overflow-y-auto no-scrollbar flex flex-col items-center py-6 gap-8">
          {/* Visual Wheel */}
          <div className="relative w-64 h-64 flex items-center justify-center">
              <div className="absolute top-[-10px] left-1/2 -translate-x-1/2 z-20 w-8 h-8 bg-yellow-500 shadow-xl" style={{ clipPath: 'polygon(50% 100%, 0 0, 100% 0)' }}></div>
              <div 
                className="w-full h-full rounded-full border-8 border-zinc-800 shadow-[0_0_60px_rgba(0,0,0,0.8)] transition-transform duration-[5000ms] cubic-bezier(0.1, 0, 0.1, 1)"
                style={{ 
                    transform: `rotate(${wheelRotation}deg)`,
                    background: `conic-gradient(${WHEEL_ORDER.map((n, i) => `${n===0?'#16a34a':REDS.includes(n)?'#dc2626':'#111'} ${i*(360/37)}deg ${(i+1)*(360/37)}deg`).join(', ')})` 
                }}
              >
                 {WHEEL_ORDER.map((n, i) => (
                     <div key={i} className="absolute top-0 left-1/2 -translate-x-1/2 h-1/2 origin-bottom flex items-center justify-center pt-2" style={{ transform: `translateX(-50%) rotate(${i*(360/37) + (360/37/2)}deg)` }}>
                        <span className="text-[7px] font-black text-white/40">{n}</span>
                     </div>
                 ))}
              </div>
              <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-16 h-16 rounded-full bg-zinc-900 border-4 border-zinc-800 shadow-inner flex flex-col items-center justify-center">
                      <div className={`text-xl font-black ${lastResult===0?'text-green-500':REDS.includes(lastResult||-1)?'text-red-500':'text-white'}`}>{lastResult !== null ? lastResult : '?'}</div>
                  </div>
              </div>
          </div>

          {/* History */}
          <div className="flex gap-1.5 px-4 overflow-x-auto no-scrollbar w-full justify-center">
              {history.map((h, i) => <span key={i} className={`w-6 h-6 rounded-full flex items-center justify-center text-[9px] font-black border border-white/5 ${getNumColor(h)}`}>{h}</span>)}
          </div>

          {/* Betting Grid */}
          <div className="w-full px-4 grid grid-cols-13 gap-1 h-32 max-w-lg">
             <button onClick={() => addBet('NUMBER', 0)} className="row-span-3 bg-green-600 rounded-lg flex items-center justify-center font-black border border-white/10 active:scale-95">0</button>
             {Array.from({length: 36}).map((_, i) => {
                 const n = i + 1;
                 const color = REDS.includes(n) ? 'bg-red-600' : 'bg-slate-900';
                 const betOnNum = bets.find(b => b.type === 'NUMBER' && b.value === n);
                 return (
                     <button key={n} onClick={() => addBet('NUMBER', n)} className={`${color} rounded-lg flex flex-col items-center justify-center font-bold text-[10px] relative active:scale-95 border border-white/5`}>
                         {n}
                         {betOnNum && <div className="absolute inset-0 flex items-center justify-center bg-yellow-500/80 rounded-lg text-[8px] text-black font-black">₹{betOnNum.amount}</div>}
                     </button>
                 );
             })}
          </div>

          {/* Outside Bets */}
          <div className="grid grid-cols-3 gap-2 w-full px-4 max-w-lg">
              <OutsideBet label="1-18" onClick={() => addBet('RANGE', '1-18')} amount={bets.find(b=>b.value==='1-18')?.amount} />
              <OutsideBet label="EVEN" onClick={() => addBet('ODD_EVEN', 'EVEN')} amount={bets.find(b=>b.value==='EVEN')?.amount} />
              <OutsideBet label="RED" color="bg-red-600" onClick={() => addBet('COLOR', 'RED')} amount={bets.find(b=>b.value==='RED')?.amount} />
              <OutsideBet label="BLACK" color="bg-slate-900" onClick={() => addBet('COLOR', 'BLACK')} amount={bets.find(b=>b.value==='BLACK')?.amount} />
              <OutsideBet label="ODD" onClick={() => addBet('ODD_EVEN', 'ODD')} amount={bets.find(b=>b.value==='ODD')?.amount} />
              <OutsideBet label="19-36" onClick={() => addBet('RANGE', '19-36')} amount={bets.find(b=>b.value==='19-36')?.amount} />
          </div>
      </div>

      {/* Footer Controls */}
      <div className="bg-[#111] p-6 pb-12 border-t border-white/5 z-50">
          <div className="flex justify-between items-center mb-6">
              <div className="flex gap-2">
                  {[10, 50, 100, 500, 1000].map(amt => (
                      <button key={amt} onClick={() => setSelectedChip(amt)} className={`w-12 h-12 rounded-full border-4 flex items-center justify-center text-[10px] font-black transition-all ${selectedChip === amt ? 'bg-yellow-500 border-white text-black scale-110 shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>{amt >= 1000 ? `${amt/1000}k` : amt}</button>
                  ))}
              </div>
              <button onClick={clearBets} className="p-3 bg-red-600/10 text-red-500 rounded-2xl border border-red-500/20 active:scale-90 transition-transform"><Trash2 size={24}/></button>
          </div>

          <button onClick={spin} disabled={isSpinning || bets.length === 0} className={`w-full py-6 rounded-[2.5rem] font-black text-2xl uppercase tracking-[0.4em] shadow-xl transition-all border-t-2 border-white/10 ${isSpinning || bets.length === 0 ? 'bg-zinc-800 text-zinc-600' : 'bg-gradient-to-r from-yellow-500 to-orange-600 text-black'}`}>
            {isSpinning ? 'SPINNING...' : 'START SPIN'}
          </button>
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        .grid-cols-13 { grid-template-columns: repeat(13, minmax(0, 1fr)); }
      `}</style>
    </div>
  );
};

const OutsideBet = ({ label, color = 'bg-slate-800', onClick, amount }: any) => (
    <button onClick={onClick} className={`h-12 ${color} rounded-xl border border-white/5 font-black text-[10px] uppercase flex flex-col items-center justify-center relative active:scale-95 overflow-hidden`}>
        {label}
        {amount > 0 && <div className="absolute inset-0 bg-yellow-500 flex items-center justify-center text-black">₹{amount}</div>}
    </button>
);

