import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, Trash2, Volume2, VolumeX, Timer, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult, RouletteBet } from '../types';

const WHEEL_ORDER = [0, 32, 15, 19, 4, 21, 2, 25, 17, 34, 6, 27, 13, 36, 11, 30, 8, 23, 10, 5, 24, 16, 33, 1, 20, 14, 31, 9, 22, 18, 29, 7, 28, 12, 35, 3, 26];
const REDS = [1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36];

const Roulette: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bets, setBets] = useState<RouletteBet[]>([]);
  const [status, setStatus] = useState<'BETTING' | 'LOCKED' | 'SPINNING' | 'RESULT'>('BETTING');
  const [timeLeft, setTimeLeft] = useState(20);
  const [period, setPeriod] = useState(Date.now().toString().slice(-6));
  const [wheelRotation, setWheelRotation] = useState(0);
  const [history, setHistory] = useState<number[]>([]);
  const [selectedChip, setSelectedChip] = useState(10);
  const [lastResult, setLastResult] = useState<number | null>(null);
  const [muted, setMuted] = useState(getMuteStatus());

  const isMounted = useRef(true);
  const pendingBetsRef = useRef<RouletteBet[]>([]);

  useEffect(() => {
    isMounted.current = true;
    const interval = setInterval(() => {
        if (!isMounted.current) return;

        if (status === 'BETTING') {
            if (timeLeft > 0) {
                setTimeLeft(prev => prev - 1);
                if (timeLeft <= 5) playSound('tick');
            } else {
                setStatus('LOCKED');
                setTimeLeft(3);
            }
        } else if (status === 'LOCKED') {
            if (timeLeft > 0) setTimeLeft(prev => prev - 1);
            else spin();
        }
    }, 1000);

    return () => { isMounted.current = false; clearInterval(interval); stopAllSounds(); };
  }, [timeLeft, status]);

  const spin = () => {
    setStatus('SPINNING');
    playSound('spin');

    const result = WHEEL_ORDER[Math.floor(Math.random() * WHEEL_ORDER.length)];
    const resultIdx = WHEEL_ORDER.indexOf(result);
    const segmentAngle = 360 / WHEEL_ORDER.length;

    const extraRots = 360 * 10;
    const offset = resultIdx * segmentAngle;
    const finalRotation = wheelRotation + extraRots + (360 - (wheelRotation % 360)) - offset;

    setWheelRotation(finalRotation);

    setTimeout(() => finalize(result), 5000);
  };

  const finalize = (num: number) => {
    if (!isMounted.current) return;
    setStatus('RESULT');
    setLastResult(num);
    setHistory(prev => [num, ...prev].slice(0, 12));

    const currentBets = [...pendingBetsRef.current];
    let totalWin = 0;
    const isRed = REDS.includes(num);
    const isEven = num !== 0 && num % 2 === 0;

    currentBets.forEach(bet => {
        if (bet.type === 'NUMBER' && bet.value === num) totalWin += bet.amount * 36;
        if (bet.type === 'COLOR') {
            if (bet.value === 'RED' && isRed) totalWin += bet.amount * 2;
            if (bet.value === 'BLACK' && !isRed && num !== 0) totalWin += bet.amount * 2;
        }
        if (bet.type === 'ODD_EVEN') {
            if (bet.value === 'EVEN' && isEven) totalWin += bet.amount * 2;
            if (bet.value === 'ODD' && !isEven && num !== 0) totalWin += bet.amount * 2;
        }
        if (bet.type === 'RANGE') {
            if (bet.value === '1-18' && num >= 1 && num <= 18) totalWin += bet.amount * 2;
            if (bet.value === '19-36' && num >= 19 && num <= 36) totalWin += bet.amount * 2;
        }
    });

    if (totalWin > 0) {
        updateBalance(totalWin, 'WIN', 'Roulette Win');
        playSound('win');
        onResult({ win: true, amount: totalWin, game: 'Mafia Roulette', resultDetails: [{label: 'Number', value: num.toString()}] });
    } else if (currentBets.length > 0) {
        playSound('loss');
        onResult({ win: false, amount: currentBets.reduce((acc,b)=>acc+b.amount,0), game: 'Mafia Roulette' });
    }

    addGameHistory('Mafia Roulette', currentBets.reduce((acc,b)=>acc+b.amount,0), totalWin, `Period ${period} | Landed ${num}`);

    setTimeout(() => {
        if (isMounted.current) {
            setStatus('BETTING');
            setTimeLeft(20);
            setBets([]);
            pendingBetsRef.current = [];
            setPeriod(Date.now().toString().slice(-6));
        }
    }, 5000);
  };

  const addBet = (type: RouletteBet['type'], value: string | number) => {
    if (status !== 'BETTING') return;
    if (userBalance < selectedChip) return alert("Insufficient Balance");

    updateBalance(-selectedChip, 'BET', `Roulette: ${value}`);
    playSound('click');

    const newBet: RouletteBet = { type, value, amount: selectedChip };
    const existingIdx = bets.findIndex(b => b.type === type && b.value === value);

    let updated;
    if (existingIdx > -1) {
        updated = [...bets];
        updated[existingIdx].amount += selectedChip;
    } else {
        updated = [...bets, newBet];
    }
    setBets(updated);
    pendingBetsRef.current = updated;
  };

  const clearBets = () => {
    if (status !== 'BETTING') return;
    const total = bets.reduce((a, b) => a + b.amount, 0);
    if (total > 0) {
        updateBalance(total, 'GIFT', 'Roulette Clear');
        setBets([]);
        pendingBetsRef.current = [];
        playSound('click');
    }
  };

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white overflow-hidden relative select-none">
      {/* Top Header */}
      <div className="p-4 flex justify-between items-center bg-zinc-900 border-b border-yellow-500/20 z-50">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 bg-zinc-800 rounded-xl"><ArrowLeft size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20">
                <Wallet size={14} className="text-yellow-500" />
                <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
        <div className="flex flex-col items-center">
            <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">MAFIA ROULETTE</h1>
            <span className="text-[8px] text-zinc-500 font-bold uppercase tracking-widest">Period: {period}</span>
        </div>
        <button onClick={() => setMuted(toggleMute())} className="p-2 bg-zinc-800 rounded-xl">
            {muted ? <VolumeX size={18}/> : <Volume2 size={18}/>}
        </button>
      </div>

      {/* Main Arena */}
      <div className="flex-1 overflow-y-auto no-scrollbar flex flex-col items-center py-4 pb-24 gap-6">
          {/* Enhanced Visual Wheel */}
          <div className="relative w-64 h-64 flex items-center justify-center">
              <div className="absolute top-[-15px] left-1/2 -translate-x-1/2 z-50 w-10 h-12 flex flex-col items-center">
                   <div className="w-8 h-8 bg-yellow-500 shadow-xl" style={{ clipPath: 'polygon(50% 100%, 0 0, 100% 0)' }}></div>
              </div>
              <div 
                className="w-full h-full rounded-full border-[10px] border-zinc-800 shadow-[0_0_60px_rgba(0,0,0,1)] transition-transform duration-[5000ms] cubic-bezier(0.1, 0, 0.1, 1) relative"
                style={{ 
                    transform: `rotate(${wheelRotation}deg)`,
                    background: `conic-gradient(${WHEEL_ORDER.map((n, i) => `${n===0?'#16a34a':REDS.includes(n)?'#dc2626':'#111'} ${i*(360/37)}deg ${(i+1)*(360/37)}deg`).join(', ')})` 
                }}
              >
                 {WHEEL_ORDER.map((n, i) => (
                     <div key={i} className="absolute top-0 left-1/2 -translate-x-1/2 h-1/2 origin-bottom flex items-center justify-center pt-2" style={{ transform: `translateX(-50%) rotate(${i*(360/37) + (360/37/2)}deg)` }}>
                        <span className="text-[10px] font-black text-white/90 drop-shadow-lg">{n}</span>
                     </div>
                 ))}
              </div>
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="w-20 h-20 rounded-full bg-zinc-900 border-4 border-zinc-800 shadow-inner flex flex-col items-center justify-center">
                      <div className={`text-2xl font-black ${lastResult===0?'text-green-500':REDS.includes(lastResult||-1)?'text-red-500':'text-white'}`}>{lastResult !== null ? lastResult : '?'}</div>
                  </div>
              </div>
          </div>

          {/* Status/Timer Bar */}
          <div className="w-full px-6 flex justify-between items-center">
