import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, History, RotateCw, Trash2, Volume2, VolumeX, Timer } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

const DICE_FACES = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];

const SicBo: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [placedBets, setPlacedBets] = useState<{ zone: string; amount: number; type: string }[]>([]);
  const [gameState, setGameState] = useState<'BETTING' | 'SHAKING' | 'RESULT'>('BETTING');
  const [timeLeft, setTimeLeft] = useState(25);
  const [dice, setDice] = useState([1, 1, 1]);
  const [history, setHistory] = useState<number[]>([]);
  const [muted, setMuted] = useState(getMuteStatus());

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    const interval = setInterval(() => {
      if (!isMounted.current) return;
      if (gameState === 'BETTING') {
          if (timeLeft > 0) {
              setTimeLeft(prev => prev - 1);
              if (timeLeft <= 5) playSound('tick');
          } else {
              shakeDice();
          }
      }
    }, 1000);
    return () => { isMounted.current = false; clearInterval(interval); stopAllSounds(); };
  }, [timeLeft, gameState]);

  const shakeDice = () => {
    setGameState('SHAKING');
    playSound('spin');

    let count = 0;
    const shakeInterval = setInterval(() => {
        setDice([Math.floor(Math.random()*6)+1, Math.floor(Math.random()*6)+1, Math.floor(Math.random()*6)+1]);
        count++;
        if (count > 20) {
            clearInterval(shakeInterval);
            finalize();
        }
    }, 100);
  };

  const finalize = () => {
    if (!isMounted.current) return;
    const result = [Math.floor(Math.random()*6)+1, Math.floor(Math.random()*6)+1, Math.floor(Math.random()*6)+1];
    setDice(result);
    setGameState('RESULT');

    const sum = result.reduce((a, b) => a + b, 0);
    setHistory(prev => [sum, ...prev].slice(0, 15));

    let totalWin = 0;
    const isBig = sum >= 11 && sum <= 17;
    const isSmall = sum >= 4 && sum <= 10;
    const isTriple = result[0] === result[1] && result[1] === result[2];

    placedBets.forEach(bet => {
        if (bet.zone === 'BIG' && isBig && !isTriple) totalWin += bet.amount * 2;
        if (bet.zone === 'SMALL' && isSmall && !isTriple) totalWin += bet.amount * 2;
        if (bet.zone === 'TOTAL' && parseInt(bet.type) === sum) totalWin += bet.amount * 6; // simplified
    });

    if (totalWin > 0) {
        updateBalance(totalWin, 'WIN', 'Sic Bo Win');
        playSound('win');
        onResult({ win: true, amount: totalWin, game: 'Sic Bo' });
    } else if (placedBets.length > 0) {
        playSound('loss');
        onResult({ win: false, amount: placedBets.reduce((a,b)=>a+b.amount,0), game: 'Sic Bo' });
    }

    addGameHistory('Sic Bo', placedBets.reduce((a,b)=>a+b.amount,0), totalWin, `Dice: ${result.join(',')}`);

    setTimeout(() => {
        if (isMounted.current) {
            setGameState('BETTING');
            setTimeLeft(25);
            setPlacedBets([]);
        }
    }, 5000);
  };

  const placeBet = (zone: string, type: string) => {
    if (gameState !== 'BETTING') return;
    if (userBalance < betAmount) return alert("Insufficient Balance");
    updateBalance(-betAmount, 'BET', `SicBo: ${zone}`);
    playSound('click');
    setPlacedBets(prev => [...prev, { zone, amount: betAmount, type }]);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white overflow-hidden relative select-none">
      <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-yellow-500/20 z-50">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text italic tracking-widest uppercase">SIC BO ELITE</h1>
        <div className="bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 gap-8">
          {/* Shaking Dome Visual */}
          <div className="relative w-64 h-48 bg-gradient-to-b from-blue-900/40 to-black rounded-full border-4 border-white/10 flex items-center justify-center shadow-[0_0_50px_rgba(0,0,0,0.8)]">
               <div className="flex gap-4">
                  {dice.map((d, i) => (
                      <div key={i} className={`text-6xl ${gameState === 'SHAKING' ? 'animate-bounce' : ''} drop-shadow-lg`}>
                        {DICE_FACES[d-1]}
                      </div>
                  ))}
               </div>
               {gameState === 'BETTING' && (
                   <div className="absolute inset-0 bg-black/60 rounded-full flex flex-col items-center justify-center backdrop-blur-sm">
                        <Timer size={40} className="text-yellow-500 mb-2 animate-pulse" />
                        <span className="text-4xl font-black font-mono text-yellow-500">{timeLeft}s</span>
                   </div>
               )}
          </div>

          {/* Betting Grid */}
          <div className="grid grid-cols-2 gap-4 w-full max-w-md">
               <button onClick={() => placeBet('SMALL', '4-10')} className="h-24 bg-blue-900/40 rounded-3xl border-2 border-blue-500/30 flex flex-col items-center justify-center active:scale-95 transition-all">
                  <span className="text-xl font-black italic">SMALL</span>
                  <span className="text-[10px] opacity-60">4-10 (1.98X)</span>
                  {placedBets.filter(b=>b.zone==='SMALL').length > 0 && <div className="mt-1 bg-yellow-500 text-black px-3 py-0.5 rounded-full text-[10px] font-black">₹{placedBets.filter(b=>b.zone==='SMALL').reduce((a,b)=>a+b.amount,0)}</div>}
               </button>
               <button onClick={() => placeBet('BIG', '11-17')} className="h-24 bg-red-900/40 rounded-3xl border-2 border-red-500/30 flex flex-col items-center justify-center active:scale-95 transition-all">
                  <span className="text-xl font-black italic">BIG</span>
                  <span className="text-[10px] opacity-60">11-17 (1.98X)</span>
                  {placedBets.filter(b=>b.zone==='BIG').length > 0 && <div className="mt-1 bg-yellow-500 text-black px-3 py-0.5 rounded-full text-[10px] font-black">₹{placedBets.filter(b=>b.zone==='BIG').reduce((a,b)=>a+b.amount,0)}</div>}
               </button>
          </div>

          <div className="flex gap-2 overflow-x-auto no-scrollbar w-full pb-4">
              {Array.from({length: 14}).map((_, i) => {
                  const n = i + 4;
                  return (
                      <button key={n} onClick={() => placeBet('TOTAL', n.toString())} className="flex-shrink-0 w-14 h-16 bg-zinc-800 rounded-xl flex flex-col items-center justify-center border border-white/5 active:scale-90">
                          <span className="text-xs font-black">{n}</span>
                          <span className="text-[7px] text-zinc-500 uppercase">Total</span>
                          {placedBets.filter(b=>b.zone==='TOTAL' && b.type===n.toString()).length > 0 && <div className="mt-1 text-[8px] font-bold text-yellow-500">₹{placedBets.filter(b=>b.zone==='TOTAL' && b.type===n.toString()).reduce((a,b)=>a+b.amount,0)}</div>}
                      </button>
                  );
              })}
          </div>
      </div>

      <div className="bg-[#111] p-6 pb-12 border-t border-white/10 shadow-[0_-20px_60px_rgba(0,0,0,1)]">
          <div className="flex gap-3 mb-6 overflow-x-auto no-scrollbar py-2">
                {[10, 100, 500, 1000, 5000].map(amt => (
                    <button key={amt} onClick={() => setBetAmount(amt)} className={`flex-shrink-0 px-6 py-3 rounded-2xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-black border-white shadow-lg scale-110' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}>₹{amt}</button>
                ))}
          </div>
          <div className="flex items-center gap-2 text-zinc-500 overflow-x-auto no-scrollbar">
             <History size={14}/>
             {history.map((h, i) => <span key={i} className="text-xs font-bold px-2 py-1 bg-zinc-800 rounded-lg">{h}</span>)}
          </div>
      </div>

      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

