              </div>
              <div className="flex flex-col items-end">
                  <span className="text-[8px] text-zinc-500 font-black uppercase tracking-widest">Time Remaining</span>
                  <div className="flex items-center gap-1.5 text-2xl font-black font-mono text-yellow-500 drop-shadow-[0_0_10px_rgba(234,179,8,0.3)]">
