              </div>
              <button 
                onClick={clearBets} 
                disabled={status !== 'BETTING' || bets.length === 0}
                className="p-4 bg-red-600/10 text-red-500 rounded-2xl border border-red-500/30 active:scale-90 transition-all disabled:opacity-20"
              >
                <Trash2 size={24}/>
              </button>
          </div>

          <div className="flex justify-between items-center px-4 py-3 rounded-2xl bg-black/40 border border-white/5">
             <div className="flex flex-col">
                <span className="text-[7px] text-zinc-500 uppercase font-black tracking-widest">Active Stake</span>
                <span className="text-sm font-black text-yellow-500 font-mono italic">₹{bets.reduce((a,b)=>a+b.amount,0).toFixed(2)}</span>
             </div>
             <div className="text-right">
                <span className="text-[7px] text-zinc-500 uppercase font-black tracking-widest">Predicted Win</span>
                <span className="text-sm font-black text-green-500 font-mono italic">36x Payouts</span>
             </div>
          </div>
      </div>

      {/* BET CONFIRMATION DRAWER (Place Option) */}
      {confirmDrawer && confirmDrawer.open && (
          <div className="fixed inset-0 z-[200] flex items-end justify-center bg-black/80 backdrop-blur-md">
              <div className="bg-[#111] w-full max-w-md rounded-t-[3rem] p-8 border-t-2 border-yellow-500/30 animate-in slide-in-from-bottom duration-300">
                  <div className="flex justify-between items-center mb-8">
                      <div>
                          <p className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">Placing Payout Stake</p>
                          <h3 className="text-3xl font-black italic gold-text tracking-tighter">Stake on {confirmDrawer.value}</h3>
                      </div>
                      <button onClick={() => setConfirmDrawer(null)} className="p-3 bg-zinc-900 rounded-full border border-white/5"><X size={20}/></button>
                  </div>

                  <div className="bg-zinc-950 p-6 rounded-3xl border border-white/5 mb-8 shadow-inner flex items-center justify-between">
                       <div className="flex flex-col">
                            <span className="text-[9px] text-zinc-500 font-black uppercase">Selected Chip</span>
                            <span className="text-3xl font-black text-white">₹{selectedChip}</span>
