                       <div className="w-14 h-14 rounded-full bg-yellow-500 flex items-center justify-center text-black font-black shadow-xl ring-4 ring-white/20">
                            {selectedChip >= 1000 ? `${selectedChip/1000}k` : selectedChip}
                       </div>
