                  <button 
                    onClick={confirmBet}
                    className="w-full py-6 rounded-[2rem] bg-gradient-to-r from-yellow-400 to-yellow-600 text-black font-black uppercase tracking-[0.4em] text-xl shadow-2xl active:scale-95 transition-all"
                  >
