      {/* PAYTABLE MODAL (Detail Option) */}
      {showPaytable && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl">
               <div className="bg-zinc-900 border border-yellow-500/30 w-full max-w-sm p-8 rounded-[3rem] shadow-[0_0_80px_rgba(234,179,8,0.2)] animate-in zoom-in duration-300">
                    <div className="flex justify-between items-center mb-8">
                        <h2 className="text-2xl font-black gold-text italic uppercase tracking-tighter">MAFIA PAYTABLE</h2>
