                    </div>
                    <div className="space-y-3">
                        <PayoutRow label="Straight Up (1 Number)" mult="36.0x" color="text-yellow-500" />
                        <PayoutRow label="Red / Black" mult="2.0x" color="text-red-500" />
                        <PayoutRow label="Even / Odd" mult="2.0x" color="text-blue-500" />
                        <PayoutRow label="Low / High (1-18 / 19-36)" mult="2.0x" color="text-emerald-500" />
                    </div>
                    <div className="mt-10 p-4 bg-black/40 rounded-2xl border border-white/5">
                        <p className="text-[10px] text-zinc-500 leading-relaxed font-bold italic uppercase tracking-tighter text-center">
                            Maximum single number bet payout is ₹180,000. Mafia rules apply.
                        </p>
