        .grid-cols-13 { grid-template-columns: repeat(13, minmax(0, 1fr)); }
        .no-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

const OutsideBet = ({ label, color = 'bg-zinc-900', onClick, bet, status }: any) => (
    <button 
        onClick={onClick} 
        disabled={status !== 'BETTING'}
        className={`h-14 ${color} rounded-2xl border-2 border-white/5 font-black text-[11px] uppercase flex flex-col items-center justify-center relative active:scale-95 overflow-hidden shadow-lg transition-all disabled:opacity-30`}
