              </div>

              {/* The Wheel Disk - Enlarged to 100% of container */}
              <div 
                className="w-full h-full rounded-full border-[16px] border-zinc-900 shadow-[0_0_120px_rgba(0,0,0,1)] transition-transform duration-[5000ms] cubic-bezier(0.1, 0, 0.1, 1) relative"
                style={{ 
                    transform: `rotate(${wheelRotation}deg)`,
                    background: `conic-gradient(${WHEEL_ORDER.map((n, i) => `${n===0?'#16a34a':REDS.includes(n)?'#dc2626':'#1a1a1a'} ${i*(360/37)}deg ${(i+1)*(360/37)}deg`).join(', ')})` 
