  liveBets: []
};
const dragonTigerSubscribers: ((state: DragonTigerState) => void)[] = [];

export const subscribeToDragonTiger = (cb: (state: DragonTigerState) => void) => {
    dragonTigerSubscribers.push(cb);
    cb(dragonTigerState);
