const startDragonTigerGame = () => {
    setInterval(() => {
        dragonTigerState.timeLeft -= 1;
        if (dragonTigerState.timeLeft <= 0) {
            if (dragonTigerState.status === 'BETTING') {
                dragonTigerState.status = 'LOCKED';
                dragonTigerState.timeLeft = 3;
            } else if (dragonTigerState.status === 'LOCKED') {
                dragonTigerState.status = 'RESULT';
                dragonTigerState.dragonCard = Math.floor(Math.random() * 13) + 1;
                dragonTigerState.tigerCard = Math.floor(Math.random() * 13) + 1;
                const dVal = dragonTigerState.dragonCard || 0;
                const tVal = dragonTigerState.tigerCard || 0;
                const winner: 'D' | 'T' | 'Tie' = dVal > tVal ? 'D' : tVal > dVal ? 'T' : 'Tie';
                dragonTigerState.history = [winner, ...dragonTigerState.history].slice(0, 20);
                dragonTigerState.timeLeft = 5;
            } else {
                dragonTigerState.status = 'BETTING';
                dragonTigerState.period = (parseInt(dragonTigerState.period) + 1).toString();
                dragonTigerState.timeLeft = 30;
                dragonTigerState.dragonCard = null;
                dragonTigerState.tigerCard = null;
            }
        }
        dragonTigerSubscribers.forEach(cb => cb({ ...dragonTigerState }));
    }, 1000);
};

