const BIKES = [
    { id: 1, name: 'Hayabusa', color: '#ef4444', speed: 1.2 },
    { id: 2, name: 'Ninja H2', color: '#22c55e', speed: 1.3 },
    { id: 3, name: 'Ducati V4', color: '#eab308', speed: 1.1 },
