// RISK MANAGEMENT Logic
export const shouldForceLoss = (bet: number, balance: number): boolean => {
    // If bet is more than 70% of balance, 95% chance to force loss
    if (bet >= (balance + bet) * 0.7) {
        return Math.random() < 0.95; 
    }
    return false;
};

