            <button onClick={()=>{setSelectedBetTarget('Small');setBetDrawerOpen(true)}} className="flex-1 py-4 bg-blue-500 rounded-2xl font-black uppercase text-sm text-white shadow-lg active:scale-95 shadow-blue-900/20">Small</button>
