    const [isPlaying, setIsPlaying] = useState(false);
    const [minesCount, setMinesCount] = useState(3);
    const [gemsFound, setGemsFound] = useState(0);
    const [gameOver, setGameOver] = useState(false);
    const [muted, setMuted] = useState(getMuteStatus());
    const [showRules, setShowRules] = useState(false);
    const [myHistory, setMyHistory] = useState<GameHistoryItem[]>([]);

    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        setMyHistory(getGameHistory('Mines').slice(0, 10));
        return () => {
            isMounted.current = false;
            stopAllSounds();
        };
    }, []);

    const handleToggleMute = () => {
        setMuted(toggleMute());
    };

    const startGame = () => {
        if (betAmount > userBalance) {
            alert("Insufficient Balance!");
            return;
        }

        if(isMounted.current) playSound('click');
        updateBalance(-betAmount, 'BET', 'Mines Game');
        setIsPlaying(true);
        setGameOver(false);
        setGemsFound(0);
        setRevealed(Array(25).fill(false));

        // Generate mines
        const newGrid = Array(25).fill(1); // Default Gem
        let minesPlaced = 0;
        while(minesPlaced < minesCount) {
            const idx = Math.floor(Math.random() * 25);
            if (newGrid[idx] !== 2) {
                newGrid[idx] = 2; // Bomb
                minesPlaced++;
            }
        }
        setGrid(newGrid);
    };

    const handleTileClick = (index: number) => {
        if (!isPlaying || revealed[index] || gameOver) return;

        if(isMounted.current) playSound('click');
        const newRevealed = [...revealed];
        newRevealed[index] = true;
        setRevealed(newRevealed);

        // Forced loss logic check for high-risk bets after first gem
        const forced = gemsFound >= 1 && shouldForceLoss(betAmount, userBalance);

        if (grid[index] === 2 || forced) {
            // Hit Mine
            if(isMounted.current) playSound('loss');
            setGameOver(true);
            setIsPlaying(false);
            setRevealed(Array(25).fill(true)); // Reveal all
            addGameHistory('Mines', betAmount, 0, `Hit Mine (Mines: ${minesCount})`);
            updateHistoryLocal();

            onResult({
                win: false,
                amount: betAmount,
                game: 'Mines',
                resultDetails: [{ label: 'Result', value: 'Explosion!', color: 'text-red-500' }]
            });
        } else {
            // Found Gem
            if(isMounted.current) playSound('win');
            setGemsFound(prev => prev + 1);
        }
    };

    const cashOut = () => {
        if (!isPlaying || gameOver) return;
        if (gemsFound === 0) {
            alert("Reveal at least one gem first!");
            return;
        }

        const multiplier = 1 + (gemsFound * 0.2) + (minesCount * 0.05);
        const winAmount = betAmount * multiplier;
        updateBalance(winAmount, 'WIN', 'Mines Win');
        addGameHistory('Mines', betAmount, winAmount, `Cashed Out @ ${multiplier.toFixed(2)}x`);
        updateHistoryLocal();

        setIsPlaying(false);
        setGameOver(true);
        if(isMounted.current) playSound('win');
        setRevealed(Array(25).fill(true)); 

        onResult({
            win: true,
            amount: winAmount,
            game: 'Mines',
            resultDetails: [
                { label: 'Gems', value: gemsFound.toString(), color: 'text-green-500' },
                { label: 'Multiplier', value: `${multiplier.toFixed(2)}x`, color: 'text-blue-500' }
            ]
        });
    };

    const updateHistoryLocal = () => {
        setTimeout(() => {
            if (isMounted.current) setMyHistory(getGameHistory('Mines').slice(0, 10));
        }, 500);
    }

    const currentMultiplier = (1 + (gemsFound * 0.2) + (minesCount * 0.05)).toFixed(2);
    const currentProfit = gemsFound > 0 ? (betAmount * parseFloat(currentMultiplier)).toFixed(2) : "0.00";

    return (
        <div className="bg-[#0f172a] min-h-screen flex flex-col pb-safe font-sans">
            <div className="bg-[#1e293b] p-4 flex items-center justify-between sticky top-0 z-10 shadow-lg border-b border-slate-700">
                <div className="flex items-center gap-4">
                    <button onClick={onBack}><ArrowLeft className="text-white" /></button>
                    <h1 className="text-lg font-bold flex items-center gap-2 uppercase tracking-tighter gold-text">Mines</h1>
                </div>
                <div className="flex gap-3 text-slate-400 items-center">
                    <div className="flex items-center gap-2 bg-[#0f172a] px-3 py-1 rounded-full border border-slate-700">
                         <Wallet size={14} className="text-green-500"/>
                         <span className="text-sm font-bold text-white">₹{userBalance.toFixed(2)}</span>
                    </div>
                    <button onClick={() => setShowRules(true)} className="p-1"><HelpCircle size={20} /></button>
                    <button onClick={handleToggleMute}>
                        {muted ? <VolumeX size={20} /> : <Volume2 size={20}/>}
                    </button>
                </div>
            </div>

            <div className="flex-1 p-6 flex flex-col items-center">
                <div className="bg-[#1e293b] p-3 rounded-lg shadow-2xl mb-6 relative">
                    <div className="grid grid-cols-5 gap-2">
                        {grid.map((val, idx) => (
                            <button
                                key={idx}
                                disabled={!isPlaying || (revealed[idx] && !gameOver)}
                                onClick={() => handleTileClick(idx)}
                                className={`w-12 h-12 sm:w-14 sm:h-14 rounded-lg flex items-center justify-center transition-all duration-200 transform ${
                                    !revealed[idx] 
                                        ? 'bg-[#334155] hover:bg-[#475569] shadow-[0_4px_0_#1e293b] active:translate-y-1 active:shadow-none' 
                                        : 'bg-[#0f172a] inset-shadow scale-95'
                                }`}
                            >
                                {revealed[idx] && (
                                    <div className="animate-in zoom-in duration-300 w-full h-full flex items-center justify-center relative">
                                        {val === 2 ? (
                                            <img src={ASSETS.BOMB} alt="Bomb" className="w-8 h-8 sm:w-10 sm:h-10 drop-shadow-md animate-pulse relative z-10" />
                                        ) : (
                                            <>
                                                <div className="absolute inset-0 bg-green-500/40 blur-lg rounded-full animate-pulse"></div>
                                                <img 
                                                    src={ASSETS.GEM} 
                                                    alt="Gem" 
                                                    className="w-8 h-8 sm:w-10 sm:h-10 drop-shadow-[0_0_10px_rgba(74,222,128,0.8)] animate-bounce relative z-10" 
                                                />
                                            </>
                                        )}
                                    </div>
                                )}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="w-full max-w-md bg-[#1e293b] rounded-xl p-4 space-y-4 shadow-xl border border-slate-700 mb-6">
                    {!isPlaying ? (
                        <>
                            <div className="space-y-2">
                                <label className="text-sm text-slate-400 font-bold uppercase tracking-wider">Stake Amount</label>
                                <div className="flex items-center gap-2 bg-[#0f172a] p-3 rounded-xl border border-slate-700 focus-within:border-blue-500 transition-colors">
                                    <span className="text-green-500 font-bold">₹</span>
                                    <input 
                                        type="number" 
                                        value={betAmount} 
                                        onChange={(e) => setBetAmount(Number(e.target.value))}
                                        className="bg-transparent w-full outline-none font-bold text-white"
                                    />
                                </div>
                                <div className="flex gap-2">
                                    {[10, 100, 500, 1000].map(amt => (
                                        <button key={amt} onClick={() => setBetAmount(amt)} className="flex-1 bg-slate-700 py-1 rounded text-xs text-slate-300 hover:bg-slate-600 transition-colors">{amt}</button>
                                    ))}
                                </div>
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm text-slate-400 font-bold uppercase tracking-wider">Mines Count</label>
                                <div className="flex justify-between gap-2">
                                    {[1, 3, 5, 10].map(num => (
                                        <button 
                                            key={num}
                                            onClick={() => setMinesCount(num)}
                                            className={`flex-1 py-3 rounded-xl font-bold transition-all ${minesCount === num ? 'bg-blue-600 text-white shadow-lg' : 'bg-[#0f172a] text-slate-400 border border-slate-700'}`}
                                        >
                                            {num}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <button 
                                onClick={startGame}
                                className="w-full bg-blue-600 hover:bg-blue-500 py-4 rounded-xl font-bold shadow-lg shadow-blue-900/30 active:scale-95 transition-all text-white border-t-2 border-white/10"
                            >
                                START MINE HUNT
                            </button>
                        </>
                    ) : (
                        <div className="text-center space-y-4 animate-in slide-in-from-bottom duration-300">
                            <div className="flex justify-around bg-[#0f172a] p-4 rounded-xl border border-slate-700 shadow-inner">
                                <div><p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Gems</p><p className="font-bold text-green-400 text-xl">{gemsFound}</p></div>
                                <div><p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Win Potential</p><p className="font-bold text-yellow-400 text-xl">₹{currentProfit}</p></div>
                                <div><p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Mult.</p><p className="font-bold text-white text-xl">{gemsFound > 0 ? currentMultiplier : '1.00'}x</p></div>
                            </div>
                            <button 
                                onClick={cashOut}
                                disabled={gemsFound === 0}
                                className={`w-full py-4 rounded-xl font-bold shadow-lg active:scale-95 transition-all text-white border-t-2 border-white/20 ${gemsFound > 0 ? 'bg-green-600 hover:bg-green-500 shadow-green-900/30' : 'bg-slate-700 text-slate-400 cursor-not-allowed'}`}
                            >
                                {gemsFound === 0 ? 'Pick a Tile' : 'COLLECT EARNINGS'}
                            </button>
                        </div>
                    )}
                </div>
            </div>

            {showRules && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-md">
                    <div className="bg-[#1e293b] border-2 border-blue-500/30 w-full max-w-sm p-8 rounded-[3rem] shadow-2xl animate-in zoom-in">
                         <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                             <h2 className="text-2xl font-black text-blue-400 italic uppercase">HOW TO PLAY</h2>
                             <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
                         </div>
                         <div className="space-y-4 text-sm text-slate-300 font-medium leading-relaxed">
                             <p>1. Select your <span className="text-white font-bold">Stake</span> and the number of <span className="text-red-500 font-bold">Mines</span> (1-20).</p>
                             <p>2. Tap tiles to reveal <span className="text-green-500 font-bold">Gems</span>. Each gem increases your total win multiplier.</p>
                             <p>3. <span className="text-yellow-500 font-bold">COLLECT</span> anytime after finding at least one gem.</p>
                             <p>4. If you hit a <span className="text-red-500 font-bold">MINE</span>, the game ends and your stake is lost.</p>
                             <p className="text-xs text-blue-400 italic">Strategy: More mines = Higher multipliers per gem found!</p>
                         </div>
                    </div>
                </div>
            )}
            <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
        </div>
    );
};

export default Mines;

import { UserProfile, WinGoHistory, WinGoGameState, Transaction, GameHistoryItem, ReferralData, SubordinateItem, CommissionItem, DragonTigerState } from '../types';

// AUDIO SYSTEM
let isMuted = false;
const sounds: Record<string, HTMLAudioElement> = {
  click: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'),
  win: new Audio('https://assets.mixkit.co/active_storage/sfx/2000/2000-preview.mp3'),
  loss: new Audio('https://assets.mixkit.co/active_storage/sfx/203/203-preview.mp3'),
  tick: new Audio('https://assets.mixkit.co/active_storage/sfx/2578/2578-preview.mp3'),
  spin: new Audio('https://assets.mixkit.co/active_storage/sfx/2003/2003-preview.mp3'),
  plane: new Audio('https://assets.mixkit.co/active_storage/sfx/1547/1547-preview.mp3')
};

export const toggleMute = () => { isMuted = !isMuted; if (isMuted) stopAllSounds(); return isMuted; };
export const getMuteStatus = () => isMuted;
export const playSound = (type: keyof typeof sounds) => {
  if (isMuted) return;
  try { const audio = sounds[type]; if (audio) { audio.currentTime = 0; audio.volume = 0.5; audio.play().catch(() => {}); } } catch (e) {}
};
export const stopAllSounds = () => { Object.values(sounds).forEach(audio => { audio.pause(); audio.currentTime = 0; }); };

// RISK MANAGEMENT Logic
export const shouldForceLoss = (bet: number, balance: number): boolean => {
    // If bet is more than 70% of balance, 95% chance to force loss
    // (balance + bet) is used because balance is usually updated after the bet is placed
    if (bet >= (balance + bet) * 0.7) {
        return Math.random() < 0.95; 
    }
    return false;
};

// LOCAL STORAGE ENGINE
const DB_KEYS = { USERS: 'TIRANGA_USERS', CURRENT_USER: 'TIRANGA_CURRENT_USER_UID', TRANSACTIONS: 'TIRANGA_TX_', HISTORY: 'TIRANGA_HISTORY_' };

const sanitizeUser = (user: any): UserProfile => ({
    uid: user.uid || 'unknown',
    balance: typeof user.balance === 'number' ? user.balance : 0,
    vipLevel: user.vipLevel || 0,
    name: user.name || 'User',
    username: user.username || 'User',
    phone: user.phone || '',
    avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid || 'default'}`,
    totalDeposit: user.totalDeposit || 0,
    totalBet: user.totalBet || 0,
    inviteCode: user.inviteCode || '',
    password: user.password || '',
    withdrawalPassword: user.withdrawalPassword || '',
    usedGiftCodes: Array.isArray(user.usedGiftCodes) ? user.usedGiftCodes : [],
    invitedBy: user.invitedBy || '',
    totalCommission: user.totalCommission || 0,
    wagerRequired: typeof user.wagerRequired === 'number' ? user.wagerRequired : 0,
    isBankBound: !!user.isBankBound,
    isUpiBound: !!user.isUpiBound,
    isTelegramJoined: !!user.isTelegramJoined,
    bankDetails: user.bankDetails || null,
    upiDetails: user.upiDetails || null
});

const getLocalUsers = (): Record<string, UserProfile> => {
    try {
        const data = localStorage.getItem(DB_KEYS.USERS);
        const users = data ? JSON.parse(data) : {};
        Object.keys(users).forEach(key => { users[key] = sanitizeUser(users[key]); });
        return users;
    } catch (e) { return {}; }
};
const saveLocalUsers = (users: Record<string, UserProfile>) => localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));

const getLocalTransactions = (uid: string): Transaction[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.TRANSACTIONS + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalTransactions = (uid: string, txs: Transaction[]) => localStorage.setItem(DB_KEYS.TRANSACTIONS + uid, JSON.stringify(txs));

const getLocalHistory = (uid: string): GameHistoryItem[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.HISTORY + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalHistory = (uid: string, history: GameHistoryItem[]) => localStorage.setItem(DB_KEYS.HISTORY + uid, JSON.stringify(history));

let currentUser: UserProfile | null = null;
const balanceSubscribers: Function[] = [];
export let transactions: Transaction[] = [];
export let gameHistory: GameHistoryItem[] = [];
export let referralStats: ReferralData = { code: '', link: '', totalCommission: 0, yesterdayCommission: 0, directSubordinates: 0, teamSubordinates: 0, totalDepositAmount: 0, totalBetAmount: 0 };

const initSession = () => {
    try {
        const uid = localStorage.getItem(DB_KEYS.CURRENT_USER);
        if (uid) {
            const users = getLocalUsers();
            if (users[uid]) {
                currentUser = users[uid];
                transactions = getLocalTransactions(uid);
                gameHistory = getLocalHistory(uid);
                calculateReferralStats(currentUser.inviteCode);
                notifySubscribers();
            } else {
                localStorage.removeItem(DB_KEYS.CURRENT_USER);
            }
        }
    } catch (e) {
        console.error("Init Session Error", e);
    }
};

export const login = async (phone: string, pass: string) => {
    const users = getLocalUsers();
    const user = Object.values(users).find(u => u.phone === phone && u.password === pass);
    if (user) {
        currentUser = user;
        localStorage.setItem(DB_KEYS.CURRENT_USER, user.uid);
        transactions = getLocalTransactions(user.uid);
        gameHistory = getLocalHistory(user.uid);
        calculateReferralStats(user.inviteCode);
        notifySubscribers();
        return { success: true };
    }
    return { success: false, message: 'Invalid phone or password' };
};

export const register = async (phone: string, pass: string, inviteCode: string, username: string) => {
    const users = getLocalUsers();
    if (Object.values(users).some(u => u.phone === phone)) return { success: false, message: 'Phone already registered' };
    const uid = 'USER_' + Date.now();
    const newUser: UserProfile = sanitizeUser({
        uid, password: pass, name: username, username, phone, inviteCode: Math.floor(10000000 + Math.random() * 90000000).toString(), invitedBy: inviteCode, wagerRequired: 0
    });
    users[uid] = newUser;
    saveLocalUsers(users);
    currentUser = newUser;
    localStorage.setItem(DB_KEYS.CURRENT_USER, uid);
    transactions = []; gameHistory = [];
    notifySubscribers();
    return { success: true };
};

export const bindBank = async (details: { accountName: string; accountNo: string; ifsc: string }) => {
    if (!currentUser || currentUser.isBankBound) return { success: false, message: 'Details are already bound and locked.' };
    const users = getLocalUsers();

    // Check for unique bank account across all users
    const isTaken = Object.values(users).some(u => u.bankDetails?.accountNo === details.accountNo);
    if (isTaken) return { success: false, message: 'Bank account already used in another ID' };

    users[currentUser.uid].bankDetails = details;
    users[currentUser.uid].isBankBound = true;
    users[currentUser.uid].balance += 10;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);

    transactions.unshift({ id: 'TX_BIND_B_' + Date.now(), type: 'BONUS', amount: 10, status: 'SUCCESS', date: new Date().toLocaleString(), desc: 'Bank Binding Reward', timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    notifySubscribers();
    return { success: true };
};

export const bindUpi = async (details: { upiId: string }) => {
    if (!currentUser || currentUser.isUpiBound) return { success: false, message: 'Details are already bound and locked.' };
    const users = getLocalUsers();

    // Check for unique UPI ID across all users
    const isTaken = Object.values(users).some(u => u.upiDetails?.upiId === details.upiId);
    if (isTaken) return { success: false, message: 'UPI ID already used in another ID' };

    users[currentUser.uid].upiDetails = details;
    users[currentUser.uid].isUpiBound = true;
    users[currentUser.uid].balance += 5;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);

    transactions.unshift({ id: 'TX_BIND_U_' + Date.now(), type: 'BONUS', amount: 5, status: 'SUCCESS', date: new Date().toLocaleString(), desc: 'UPI Binding Reward', timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    notifySubscribers();
    return { success: true };
};

export const joinTelegramReward = async () => {
    if (!currentUser || currentUser.isTelegramJoined) return { success: false };
    const users = getLocalUsers();
    users[currentUser.uid].isTelegramJoined = true;
    users[currentUser.uid].balance += 5;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);
    transactions.unshift({ id: 'TX_JOIN_T_' + Date.now(), type: 'BONUS', amount: 5, status: 'SUCCESS', date: new Date().toLocaleString(), desc: 'Telegram Joining Reward', timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    notifySubscribers();
    return { success: true };
};

export const logout = async () => {
    currentUser = null; transactions = []; gameHistory = [];
    localStorage.removeItem(DB_KEYS.CURRENT_USER);
    notifySubscribers();
};

export const checkAuth = () => !!currentUser;
export const subscribeToBalance = (cb: (user: UserProfile | null) => void) => {
    balanceSubscribers.push(cb);
    cb(currentUser ? { ...currentUser } : null);
    return () => { const idx = balanceSubscribers.indexOf(cb); if (idx > -1) balanceSubscribers.splice(idx, 1); };
};
const notifySubscribers = () => balanceSubscribers.forEach(cb => cb(currentUser ? { ...currentUser } : null));

const calculateReferralStats = (myCode: string) => {
    if (!myCode) return;
    const users = getLocalUsers();
    const subs = Object.values(users).filter(u => u.invitedBy === myCode);
    const totalDep = subs.reduce((acc, c) => acc + (c.totalDeposit || 0), 0);
    referralStats.code = myCode;
    referralStats.link = `${window.location.origin}/#/register?code=${myCode}`;
    referralStats.directSubordinates = subs.length;
    referralStats.teamSubordinates = subs.length;
    referralStats.totalDepositAmount = totalDep;
    referralStats.totalBetAmount = subs.reduce((acc, c) => acc + (c.totalBet || 0), 0);
    referralStats.totalCommission = totalDep * 0.2; // 20% commission
};
export const getSubordinates = (): SubordinateItem[] => {
    if (!currentUser) return [];
    return Object.values(getLocalUsers()).filter(u => u.invitedBy === currentUser?.inviteCode).map(u => ({
        id: u.uid, uid: u.uid, level: 1, depositAmount: u.totalDeposit || 0, betAmount: u.totalBet || 0, commission: (u.totalDeposit || 0) * 0.2, date: '2023-11-28'
    }));
};
export const getCommissions = (): CommissionItem[] => transactions.filter(t => t.type === 'COMMISSION').map(t => ({ id: t.id, fromUid: 'System', amount: t.amount, date: t.date, type: 'Deposit Bonus' }));

export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const users = getLocalUsers();
    if (users[currentUser.uid]) {
        users[currentUser.uid].balance += amount;
        if (type === 'BET') users[currentUser.uid].totalBet = (users[currentUser.uid].totalBet || 0) + Math.abs(amount);
        currentUser = users[currentUser.uid];
        saveLocalUsers(users);
        transactions.unshift({ id: 'TX_' + Date.now(), type, amount: Math.abs(amount), status: 'SUCCESS', date: new Date().toLocaleString(), desc, timestamp: Date.now() });
        saveLocalTransactions(currentUser.uid, transactions);
        notifySubscribers();
    }
};

export const addGameHistory = async (game: string, bet: number, win: number, details: string) => {
    if (!currentUser) return;
    gameHistory.unshift({ id: Date.now().toString(), game, amount: bet, win, date: new Date().toLocaleString(), details });
    saveLocalHistory(currentUser.uid, gameHistory);
};
export const getGameHistory = (gameName: string) => gameHistory.filter(item => item.game === gameName);

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txIndex = transactions.findIndex(t => t.id === txId);
    if (txIndex === -1 || transactions[txIndex].status !== 'PROCESSING') return;
    const tx = transactions[txIndex];
    tx.status = 'SUCCESS';
    saveLocalTransactions(currentUser.uid, transactions);
    if (tx.type === 'DEPOSIT') {
        const users = getLocalUsers();
        const user = users[currentUser.uid];
        user.balance += tx.amount;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;
        const thresholds = [500, 2000, 50000, 100000, 400000];
        thresholds.forEach((t, i) => { if (user.totalDeposit >= t) user.vipLevel = Math.max(user.vipLevel, i + 1); });
        currentUser = user;
        saveLocalUsers(users);
        notifySubscribers();
        if (user.totalDeposit === tx.amount) setTimeout(() => updateBalance(tx.amount * 0.20, 'BONUS', 'First Deposit Bonus'), 500);
        if (user.invitedBy) {
            const referrer = Object.values(users).find(u => u.inviteCode === user.invitedBy);
            if (referrer) {
                const commissionAmt = tx.amount * 0.2; 
                referrer.balance += commissionAmt;
                referrer.totalCommission = (referrer.totalCommission || 0) + commissionAmt;
