                refTxs.unshift({ id: 'TX_REF_' + Date.now(), type: 'COMMISSION', amount: commissionAmt, status: 'SUCCESS', date: new Date().toLocaleString(), desc: '20% Referral Bonus' });
                saveLocalTransactions(referrer.uid, refTxs);
            }
        }
        playSound('win');
    }
};

