    notifySubscribers();
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Not logged in' };
    if (currentUser.withdrawalPassword !== password) return { success: false, message: 'Invalid Password' };
    if (currentUser.balance < amount) return { success: false, message: 'Insufficient balance' };

    // Strict binding enforcement
    if (!currentUser.isBankBound && method === 'BANK') return { success: false, message: 'Please bind bank details first in Rewards Hub' };
    if (!currentUser.isUpiBound && method === 'UPI') return { success: false, message: 'Please bind UPI details first in Rewards Hub' };

    const users = getLocalUsers();
    users[currentUser.uid].balance -= amount;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);
    notifySubscribers();

    // Force usage of bound details for withdrawals
    const actualDetails = method === 'BANK' ? currentUser.bankDetails : currentUser.upiDetails;

    transactions.unshift({ id: 'TX_' + Date.now(), type: 'WITHDRAW', amount, status: 'PROCESSING', date: new Date().toLocaleString(), desc: `Withdraw via ${method}`, method, accountDetails: actualDetails, timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    return { success: true };
};

