    if (!currentUser || currentUser.isBankBound) return { success: false, message: 'Details are already bound and locked.' };
    const users = getLocalUsers();
    users[currentUser.uid].bankDetails = details;
    users[currentUser.uid].isBankBound = true;
    users[currentUser.uid].balance += 10;
