export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txIndex = transactions.findIndex(t => t.id === txId);
    if (txIndex === -1 || transactions[txIndex].status !== 'PROCESSING') return;
    const tx = transactions[txIndex];
    tx.status = 'SUCCESS';
    saveLocalTransactions(currentUser.uid, transactions);

    if (tx.type === 'DEPOSIT') {
        const users = getLocalUsers();
        const user = users[currentUser.uid];

        // 5x Wager Requirement
        user.wagerRequired = (user.wagerRequired || 0) + (tx.amount * 5);

        // Check for 25% First Deposit Bonus
        let bonus = 0;
        if ((user.totalDeposit || 0) === 0) {
            bonus = tx.amount * 0.25;
            user.balance += bonus;
            // 25% bonus also gets 5x wager
            user.wagerRequired += (bonus * 5);
            transactions.unshift({ id: 'TX_FDB_' + Date.now(), type: 'BONUS', amount: bonus, status: 'SUCCESS', date: new Date().toLocaleString(), desc: '25% First Deposit Bonus', timestamp: Date.now() });
        }

        user.balance += tx.amount;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;

        // VIP Check
        const thresholds = [500, 2000, 50000, 100000, 400000];
        thresholds.forEach((t, i) => { if (user.totalDeposit >= t) user.vipLevel = Math.max(user.vipLevel, i + 1); });

        currentUser = user;
        saveLocalUsers(users);
        saveLocalTransactions(currentUser.uid, transactions);
        notifySubscribers();
        playSound('win');
    }
};

