import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Volume2, VolumeX, Wallet, HelpCircle, X, TrendingUp, TrendingDown } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, shouldForceLoss } from '../services/mockFirebase';
import { GameResult } from '../types';

const Aviator: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [phase, setPhase] = useState<'WAITING'|'FLYING'|'CRASHED'>('WAITING');
  const [multiplier, setMultiplier] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showRules, setShowRules] = useState(false);
  const [insufficientBalance, setInsufficientBalance] = useState(false);
  const [localResult, setLocalResult] = useState<{ win: boolean; amount: number; show: boolean } | null>(null);

  const activeBetRef = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const crashPointRef = useRef(0);
  const startTimeRef = useRef(0);
  const animRef = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    startWaiting();
    return () => { isMounted.current = false; cancelAnimationFrame(animRef.current); stopAllSounds(); };
  }, []);

  const triggerShake = () => { setInsufficientBalance(true); setTimeout(() => setInsufficientBalance(false), 400); };

  const startWaiting = () => {
      if (!isMounted.current) return;
      setPhase('WAITING'); setMultiplier(1.00); setLocalResult(null);
      if (activeBetRef.current) setActiveBet(false);
      setTimeout(() => { if (isMounted.current) startFlying(); }, 5000);
  };

  const startFlying = () => {
      setPhase('FLYING'); playSound('plane');
      let cp = 1.0;
      if (activeBetRef.current && shouldForceLoss(betAmount, userBalance)) cp = 1.0 + Math.random() * 0.1;
      else cp = 1.0 + Math.random() * 8;
      crashPointRef.current = parseFloat(cp.toFixed(2));
      startTimeRef.current = Date.now();
      animLoop();
  };

  const animLoop = () => {
      if (!isMounted.current) return;
      const elapsed = (Date.now() - startTimeRef.current) / 1000;
      const cur = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.08);
      if (cur >= crashPointRef.current) handleCrash(crashPointRef.current);
      else { setMultiplier(cur); animRef.current = requestAnimationFrame(animLoop); }
  };

  const handleCrash = (final: number) => {
      setPhase('CRASHED'); setMultiplier(final); playSound('loss');
      if (activeBetRef.current) {
          activeBetRef.current = false; setActiveBet(false);
          setLocalResult({ win: false, amount: betAmount, show: true });
          onResult({ win: false, amount: betAmount, game: 'Aviator', resultDetails: [{label: 'Crash', value: `${final.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, 0, `Crashed @ ${final.toFixed(2)}x`);
      }
      setTimeout(() => { if (isMounted.current) startWaiting(); }, 3000);
  };

  const handleAction = () => {
      if (phase === 'WAITING' || phase === 'CRASHED') {
          if (betAmount > userBalance) { triggerShake(); return; }
          activeBetRef.current = true; setActiveBet(true);
          updateBalance(-betAmount, 'BET', 'Aviator');
          playSound('click');
      } else if (phase === 'FLYING' && activeBetRef.current) {
          const win = betAmount * multiplier;
          updateBalance(win, 'WIN', 'Aviator');
          activeBetRef.current = false; setActiveBet(false);
          playSound('win');
          setLocalResult({ win: true, amount: win, show: true });
          onResult({ win: true, amount: win, game: 'Aviator', resultDetails: [{label: 'Cashout', value: `${multiplier.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, win, `Cashed @ ${multiplier.toFixed(2)}x`);
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white relative">
       {localResult && (
           <div className="absolute top-16 left-0 w-full z-[100] px-4 pointer-events-none animate-in slide-in-from-top">
               <div className={`flex items-center justify-between p-4 rounded-2xl shadow-2xl border backdrop-blur-md ${localResult.win ? 'bg-green-600/80 border-green-400' : 'bg-red-600/80 border-red-400'}`}>
                   <div className="flex items-center gap-3">
                       {localResult.win ? <TrendingUp size={24}/> : <TrendingDown size={24}/>}
                       <h4 className="text-xl font-black italic">{localResult.win ? 'WINNER' : 'CRASHED'}</h4>
                   </div>
                   <p className="text-2xl font-black font-mono">₹{localResult.amount.toFixed(2)}</p>
               </div>
           </div>
       )}

       <div className="bg-black p-4 flex items-center justify-between border-b border-gray-800 z-10">
        <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 bg-zinc-900 rounded-full"><ArrowLeft size={18}/></button>
            <span className="text-red-600 font-black italic text-2xl tracking-wider uppercase">Aviator</span>
        </div>
        <div className="flex gap-3 items-center">
             <div className={`flex items-center gap-2 bg-gray-900 px-3 py-1 rounded-full border border-gray-700 transition-all ${insufficientBalance ? 'animate-shake-red' : ''}`}>
                 <Wallet size={14} className={insufficientBalance ? 'text-red-500' : 'text-green-500'}/>
                 <span className={`text-sm font-bold ${insufficientBalance ? 'text-red-500' : ''}`}>₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={() => setShowRules(true)} className="p-1"><HelpCircle size={20}/></button>
             <button onClick={() => setMuted(toggleMute())} className="p-1">{muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}</button>
        </div>
      </div>

      <div className="relative flex-1 bg-black flex flex-col items-center justify-center">
          <div className={`text-7xl sm:text-9xl font-black drop-shadow-2xl font-mono tracking-tighter ${phase === 'CRASHED' ? 'text-red-600' : 'text-white'}`}>
              {multiplier.toFixed(2)}x
          </div>
          {phase === 'WAITING' && <div className="mt-4 text-xs font-black uppercase tracking-[0.4em] text-gray-500 animate-pulse">Wait for takeoff...</div>}
      </div>

      <div className="bg-[#151515] p-6 border-t-4 border-red-600 z-30 shadow-[0_-10px_30px_rgba(0,0,0,0.5)]">
            <div className="flex gap-4">
                <div className="flex-1 bg-[#1a1a1a] border border-gray-800 rounded-xl flex items-center justify-center h-16">
                    <button onClick={()=>setBetAmount(Math.max(10, betAmount-10))} disabled={activeBet} className="w-10 text-2xl font-black">-</button>
                    <span className="flex-1 text-center font-black text-xl">{betAmount}</span>
                    <button onClick={()=>setBetAmount(betAmount+10)} disabled={activeBet} className="w-10 text-2xl font-black">+</button>
                </div>
                <button onClick={handleAction} className={`flex-[2] py-4 rounded-xl font-black text-xl shadow-2xl transition-all active:scale-95 border-b-4 ${activeBet && phase === 'FLYING' ? 'bg-orange-500 border-orange-700' : activeBet ? 'bg-red-700 border-red-900' : 'bg-green-600 border-green-800'}`}>
                    {activeBet && phase === 'FLYING' ? 'CASH OUT' : activeBet ? 'WAITING' : 'PLACE STAKE'}
                </button>
            </div>
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 border border-red-500/30 w-full max-w-sm p-8 rounded-[2.5rem] animate-in zoom-in">
                   <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                       <h2 className="text-2xl font-black italic text-red-500 uppercase">HOW TO PLAY</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 leading-relaxed font-medium">
                       <p>1. Place your stake before the plane takes off.</p>
                       <p>2. <span className="text-white font-bold">CASH OUT</span> before the plane flies away to win.</p>
                       <p>3. If it crashes first, you lose.</p>
                       <p className="text-xs text-red-500 italic">Provably fair crash generation used.</p>
                   </div>
              </div>
          </div>
      )}
    </div>
  );
};
export default Aviator;

import React, { useState, useEffect } from 'react';
