import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Volume2, VolumeX, Wallet, HelpCircle, X } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, shouldForceLoss } from '../services/mockFirebase';
import { GameResult } from '../types';

const Aviator: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [phase, setPhase] = useState<'WAITING'|'FLYING'|'CRASHED'>('WAITING');
  const [multiplier, setMultiplier] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showRules, setShowRules] = useState(false);
  const [insufficientBalance, setInsufficientBalance] = useState(false);

  const activeBetRef = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const crashPointRef = useRef(0);
  const startTimeRef = useRef(0);
  const animRef = useRef(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    startWaiting();
    return () => { isMounted.current = false; cancelAnimationFrame(animRef.current); stopAllSounds(); };
  }, []);

  const startWaiting = () => {
      if (!isMounted.current) return;
      setPhase('WAITING'); setMultiplier(1.00);
      if (activeBetRef.current) setActiveBet(false);
      setTimeout(() => { if (isMounted.current) startFlying(); }, 5000);
  };

  const startFlying = () => {
      setPhase('FLYING'); playSound('plane');
      let cp = 1.0;
      if (activeBetRef.current && shouldForceLoss(betAmount, userBalance)) cp = 1.0 + Math.random() * 0.1;
      else cp = 1.0 + Math.random() * 8;
      crashPointRef.current = parseFloat(cp.toFixed(2));
      startTimeRef.current = Date.now();
      animLoop();
  };

  const animLoop = () => {
      if (!isMounted.current) return;
      const elapsed = (Date.now() - startTimeRef.current) / 1000;
      const cur = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.08);
      if (cur >= crashPointRef.current) handleCrash(crashPointRef.current);
      else { setMultiplier(cur); drawCanvas(cur, elapsed); animRef.current = requestAnimationFrame(animLoop); }
  };

  const drawCanvas = (cur: number, elapsed: number) => {
      const cvs = canvasRef.current; if(!cvs) return;
      const ctx = cvs.getContext('2d'); if(!ctx) return;
      cvs.width = cvs.offsetWidth; cvs.height = cvs.offsetHeight;
      ctx.clearRect(0,0,cvs.width,cvs.height);
      ctx.beginPath();
      ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4;
      ctx.moveTo(0, cvs.height);
      ctx.quadraticCurveTo(cvs.width/2, cvs.height, cvs.width * 0.8, cvs.height * 0.2);
      ctx.stroke();
  };

  const handleCrash = (final: number) => {
      setPhase('CRASHED'); setMultiplier(final); playSound('loss');
      if (activeBetRef.current) {
          activeBetRef.current = false; setActiveBet(false);
          onResult({ win: false, amount: betAmount, game: 'Aviator', resultDetails: [{label: 'Crash', value: `${final.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, 0, `Crashed @ ${final.toFixed(2)}x`);
      }
      setTimeout(() => { if (isMounted.current) startWaiting(); }, 3000);
  };

  const handleAction = () => {
      if (phase === 'WAITING' || phase === 'CRASHED') {
          if (betAmount > userBalance) { setInsufficientBalance(true); setTimeout(() => setInsufficientBalance(false), 400); return; }
          activeBetRef.current = true; setActiveBet(true);
          updateBalance(-betAmount, 'BET', 'Aviator');
          playSound('click');
      } else if (phase === 'FLYING' && activeBetRef.current) {
          const win = betAmount * multiplier;
          updateBalance(win, 'WIN', 'Aviator');
          activeBetRef.current = false; setActiveBet(false);
          playSound('win');
          onResult({ win: true, amount: win, game: 'Aviator', resultDetails: [{label: 'Cashout', value: `${multiplier.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, win, `Cashed @ ${multiplier.toFixed(2)}x`);
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white relative">
       <div className="p-4 flex items-center justify-between border-b border-zinc-900 z-10 bg-black">
        <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 bg-zinc-900 rounded-xl"><ArrowLeft size={18}/></button>
            <span className="text-red-600 font-black italic text-2xl tracking-wider">AVIATOR</span>
        </div>
        <div className="flex gap-3 items-center">
             <div className={`flex items-center gap-2 bg-zinc-900 px-3 py-1 rounded-full border border-white/5 transition-all ${insufficientBalance ? 'animate-shake-red' : ''}`}>
                 <Wallet size={14} className="text-green-500"/>
                 <span className="text-sm font-black">₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={() => setShowRules(true)}><HelpCircle size={20}/></button>
             <button onClick={() => setMuted(toggleMute())}>{muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}</button>
        </div>
      </div>

      <div className="relative flex-1 bg-[#0a0a0a] flex flex-col items-center justify-center">
          <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-30" />
          <div className={`text-8xl font-black font-mono tracking-tighter drop-shadow-2xl transition-all ${phase === 'CRASHED' ? 'text-red-600 scale-110' : 'text-white'}`}>
              {multiplier.toFixed(2)}x
          </div>
          {phase === 'WAITING' && <div className="mt-4 text-[10px] font-black uppercase tracking-[0.5em] text-zinc-600 animate-pulse">Wait for takeoff...</div>}
      </div>

      <div className="bg-[#151515] p-6 border-t-2 border-red-600 z-30 shadow-2xl">
            <div className="flex gap-4">
                <div className="flex-1 bg-zinc-900 border border-white/5 rounded-2xl flex items-center justify-center h-16">
                    <button onClick={()=>setBetAmount(Math.max(10, betAmount-10))} disabled={activeBet} className="w-12 text-2xl font-black">-</button>
                    <span className="flex-1 text-center font-black text-xl">{betAmount}</span>
                    <button onClick={()=>setBetAmount(betAmount+10)} disabled={activeBet} className="w-12 text-2xl font-black">+</button>
                </div>
                <button onClick={handleAction} className={`flex-[2] py-4 rounded-2xl font-black text-xl shadow-xl transition-all active:scale-95 ${activeBet && phase === 'FLYING' ? 'bg-orange-600' : activeBet ? 'bg-red-800 opacity-50' : 'bg-green-600'}`}>
                    {activeBet && phase === 'FLYING' ? 'CASH OUT' : activeBet ? 'STAKED' : 'BET'}
                </button>
            </div>
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95">
              <div className="bg-zinc-900 border border-white/10 w-full max-w-sm p-8 rounded-[2rem] animate-in zoom-in">
                   <div className="flex justify-between items-center mb-6 border-b border-white/5 pb-4">
                       <h2 className="text-xl font-black italic text-red-500 uppercase">Rules</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={16}/></button>
                   </div>
                   <div className="space-y-4 text-xs text-slate-300 font-medium">
                       <p>Stake before takeoff. Cash out as the multiplier rises. If it crashes, stake is lost.</p>
                       <p className="text-red-500 italic">Provably Fair Algorithm active.</p>
                   </div>
              </div>
          </div>
      )}
    </div>
  );
};
export default Aviator;

