import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Volume2, VolumeX, Wallet, HelpCircle, X, TrendingUp } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, shouldForceLoss } from '../services/mockFirebase';
import { GameResult } from '../types';

const Aviator: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [phase, setPhase] = useState<'WAITING'|'FLYING'|'CRASHED'>('WAITING');
  const [multiplier, setMultiplier] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [betAmount2, setBetAmount2] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showRules, setShowRules] = useState(false);
  const [insufficientBalance, setInsufficientBalance] = useState(false);

  const activeBetRef = useRef(false);
  const activeBetRef2 = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const [activeBet2, setActiveBet2] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const crashPointRef = useRef(0);
  const startTimeRef = useRef(0);
  const animRef = useRef(0);
  const isMounted = useRef(true);

  // Plane animation data
  const planeImg = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    isMounted.current = true;
    planeImg.current = new Image();
    planeImg.current.src = "https://cdn-icons-png.flaticon.com/512/3122/3122330.png"; // Premium plane icon
    startWaiting();
    return () => { isMounted.current = false; cancelAnimationFrame(animRef.current); stopAllSounds(); };
  }, []);

  const triggerShake = () => { setInsufficientBalance(true); setTimeout(() => setInsufficientBalance(false), 400); };

  const startWaiting = () => {
      if (!isMounted.current) return;
      setPhase('WAITING'); setMultiplier(1.00);
      if (activeBetRef.current) setActiveBet(false);
      if (activeBetRef2.current) setActiveBet2(false);
      setTimeout(() => { if (isMounted.current) startFlying(); }, 5000);
  };

  const startFlying = () => {
      setPhase('FLYING'); playSound('plane');
      let cp = 1.0;
      const totalBet = (activeBetRef.current ? betAmount : 0) + (activeBetRef2.current ? betAmount2 : 0);
      if (totalBet > 0 && shouldForceLoss(totalBet, userBalance)) cp = 1.0 + Math.random() * 0.1;
      else cp = 1.0 + Math.random() * 25; // High potential multiplier
      crashPointRef.current = parseFloat(cp.toFixed(2));
      startTimeRef.current = Date.now();
      animLoop();
  };

  const animLoop = () => {
      if (!isMounted.current) return;
      const elapsed = (Date.now() - startTimeRef.current) / 1000;
      // Exponentially growing multiplier
      const cur = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.05);

      if (cur >= crashPointRef.current) {
          handleCrash(crashPointRef.current);
      } else {
          setMultiplier(cur);
          drawCanvas(cur, elapsed);
          animRef.current = requestAnimationFrame(animLoop);
      }
  };

  const drawCanvas = (cur: number, elapsed: number) => {
      const cvs = canvasRef.current; if(!cvs) return;
      const ctx = cvs.getContext('2d'); if(!ctx) return;
      cvs.width = cvs.offsetWidth; cvs.height = cvs.offsetHeight;
      ctx.clearRect(0,0,cvs.width,cvs.height);

      const padding = 60;
      const width = cvs.width - padding * 2;
      const height = cvs.height - padding * 2;

      // Calculate curve points
      const progress = Math.min(1, elapsed / 10); // Normalizes over 10s
      const planeX = padding + progress * width;
      const planeY = (cvs.height - padding) - (Math.pow(progress, 2) * height);

      // Draw Trail
      ctx.beginPath();
      ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4;
      ctx.setLineDash([5, 5]);
      ctx.moveTo(padding, cvs.height - padding);
      ctx.quadraticCurveTo(cvs.width / 2, cvs.height - padding, planeX, planeY);
      ctx.stroke();
      ctx.setLineDash([]);

      // Draw Glow under plane
      const grad = ctx.createRadialGradient(planeX, planeY, 0, planeX, planeY, 40);
      grad.addColorStop(0, 'rgba(239, 68, 68, 0.4)');
      grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(planeX, planeY, 40, 0, Math.PI * 2); ctx.fill();

      // Draw Plane
      if (planeImg.current?.complete) {
          ctx.save();
          ctx.translate(planeX, planeY);
          ctx.rotate(-Math.PI / 8); // Slight upward tilt
          ctx.drawImage(planeImg.current, -25, -25, 50, 50);
          ctx.restore();
      }
  };

  const handleCrash = (final: number) => {
      setPhase('CRASHED'); setMultiplier(final); playSound('loss');
      if (activeBetRef.current) {
          activeBetRef.current = false; setActiveBet(false);
          onResult({ win: false, amount: betAmount, game: 'Aviator', resultDetails: [{label: 'Crash', value: `${final.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, 0, `Lost @ ${final.toFixed(2)}x`);
      }
      if (activeBetRef2.current) {
          activeBetRef2.current = false; setActiveBet2(false);
          onResult({ win: false, amount: betAmount2, game: 'Aviator', resultDetails: [{label: 'Crash', value: `${final.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount2, 0, `Lost @ ${final.toFixed(2)}x`);
      }
      setTimeout(() => { if (isMounted.current) startWaiting(); }, 3000);
  };

  const handleAction = (deck: 1 | 2) => {
      const amt = deck === 1 ? betAmount : betAmount2;
      const ref = deck === 1 ? activeBetRef : activeBetRef2;
      const set = deck === 1 ? setActiveBet : setActiveBet2;

      if (phase === 'WAITING' || phase === 'CRASHED') {
          if (amt > userBalance) { triggerShake(); return; }
          ref.current = true; set(true);
          updateBalance(-amt, 'BET', 'Aviator Stake');
          playSound('click');
      } else if (phase === 'FLYING' && ref.current) {
          const win = amt * multiplier;
          updateBalance(win, 'WIN', 'Aviator Cashout');
          ref.current = false; set(false);
          playSound('win');
          onResult({ win: true, amount: win, game: 'Aviator', resultDetails: [{label: 'Cashed', value: `${multiplier.toFixed(2)}x`}] });
          addGameHistory('Aviator', amt, win, `Won @ ${multiplier.toFixed(2)}x`);
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white relative select-none">
       <div className="p-4 flex items-center justify-between border-b border-zinc-900 bg-black z-[110] shadow-2xl">
        <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 border border-white/5"><ArrowLeft size={18}/></button>
            <span className="text-red-600 font-black italic text-3xl tracking-wider uppercase">AVIATOR</span>
        </div>
        <div className="flex gap-3 items-center">
             <div className={`flex items-center gap-2 bg-zinc-900 px-4 py-2 rounded-2xl border border-white/5 transition-all ${insufficientBalance ? 'animate-shake-red ring-2 ring-red-500' : ''}`}>
                 <Wallet size={16} className="text-green-500"/>
                 <span className="text-sm font-black font-mono">₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={() => setShowRules(true)} className="p-1"><HelpCircle size={24}/></button>
             <button onClick={() => setMuted(toggleMute())} className="p-1">{muted ? <VolumeX size={24}/> : <Volume2 size={24}/>}</button>
        </div>
      </div>

      <div className="relative flex-1 bg-[#050505] flex flex-col items-center justify-center overflow-hidden">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(220,38,38,0.05)_0%,_transparent_70%)]"></div>
          <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />
          <div className="relative z-10 flex flex-col items-center">
              <div className={`text-8xl md:text-9xl font-black font-mono tracking-tighter drop-shadow-[0_0_40px_rgba(255,255,255,0.2)] transition-all duration-300 ${phase === 'CRASHED' ? 'text-red-600 scale-110 blur-[1px]' : 'text-white'}`}>
                  {multiplier.toFixed(2)}x
              </div>
              {phase === 'WAITING' && <div className="mt-8 text-[10px] font-black uppercase tracking-[0.6em] text-zinc-600 animate-pulse">Ready for Launch...</div>}
              {phase === 'CRASHED' && <div className="mt-4 bg-red-600 px-4 py-1 rounded-full text-xs font-black uppercase tracking-widest animate-bounce shadow-lg">Flew Away!</div>}
          </div>
      </div>

      <div className="bg-[#0f0f0f] p-4 border-t-4 border-red-600 z-[120] shadow-[0_-20px_60px_rgba(0,0,0,1)] flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-zinc-950 p-4 rounded-[2rem] border border-white/5 shadow-2xl">
                    <div className="flex items-center justify-center gap-2 mb-4 bg-black/40 py-2 rounded-xl border border-white/5">
                        <button onClick={()=>setBetAmount(Math.max(10, betAmount-10))} disabled={activeBet} className="w-10 text-2xl font-black">-</button>
                        <span className="text-xl font-black font-mono min-w-[3rem] text-center">₹{betAmount}</span>
                        <button onClick={()=>setBetAmount(betAmount+10)} disabled={activeBet} className="w-10 text-2xl font-black">+</button>
                    </div>
                    <button onClick={() => handleAction(1)} className={`w-full py-4 rounded-2xl font-black text-lg transition-all active:scale-95 border-b-8 shadow-xl ${activeBet && phase === 'FLYING' ? 'bg-orange-500 border-orange-800' : activeBet ? 'bg-red-900 border-black opacity-60' : 'bg-green-600 border-green-800'}`}>
                        {activeBet && phase === 'FLYING' ? 'CASH OUT' : activeBet ? 'STAKED' : 'BET'}
                    </button>
                </div>
                <div className="bg-zinc-950 p-4 rounded-[2rem] border border-white/5 shadow-2xl">
                    <div className="flex items-center justify-center gap-2 mb-4 bg-black/40 py-2 rounded-xl border border-white/5">
                        <button onClick={()=>setBetAmount2(Math.max(10, betAmount2-10))} disabled={activeBet2} className="w-10 text-2xl font-black">-</button>
                        <span className="text-xl font-black font-mono min-w-[3rem] text-center">₹{betAmount2}</span>
                        <button onClick={()=>setBetAmount2(betAmount2+10)} disabled={activeBet2} className="w-10 text-2xl font-black">+</button>
                    </div>
                    <button onClick={() => handleAction(2)} className={`w-full py-4 rounded-2xl font-black text-lg transition-all active:scale-95 border-b-8 shadow-xl ${activeBet2 && phase === 'FLYING' ? 'bg-orange-500 border-orange-800' : activeBet2 ? 'bg-red-900 border-black opacity-60' : 'bg-green-600 border-green-800'}`}>
                        {activeBet2 && phase === 'FLYING' ? 'CASH OUT' : activeBet2 ? 'STAKED' : 'BET'}
                    </button>
                </div>
            </div>
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-md">
              <div className="bg-zinc-900 border border-white/10 w-full max-w-sm p-10 rounded-[3rem] shadow-2xl animate-in zoom-in">
                   <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                       <h2 className="text-2xl font-black italic text-red-500 uppercase tracking-tighter">HOW TO PLAY</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
