            user.balance += bonus;
            user.wagerRequired += (bonus * 5);
            transactions.unshift({ id: 'TX_FDB_' + Date.now(), type: 'BONUS', amount: bonus, status: 'SUCCESS', date: new Date().toLocaleString(), desc: 'First Deposit Bonus (5x Wager)', timestamp: Date.now() });
        }
        user.balance += tx.amount;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;
        currentUser = user;
        saveLocalUsers(users);
        notifySubscribers();
    }
};

