  const [insufficientBalance, setInsufficientBalance] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);

  const activeBetRef = useRef(false);
  const activeBetRef2 = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const [activeBet2, setActiveBet2] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const crashPointRef = useRef(0);
  const startTimeRef = useRef(0);
  const animRef = useRef(0);
  const isMounted = useRef(true);
  const planeImg = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    isMounted.current = true;
    planeImg.current = new Image();
    planeImg.current.src = "https://cdn-icons-png.flaticon.com/512/3122/3122330.png";
    startWaiting();
    return () => { isMounted.current = false; cancelAnimationFrame(animRef.current); stopAllSounds(); };
  }, []);

  const startWaiting = () => {
      if (!isMounted.current) return;
      setPhase('WAITING'); setMultiplier(1.00);
      setTimeLeft(10);
      const timer = setInterval(() => {
          setTimeLeft(prev => {
              if (prev <= 1) { clearInterval(timer); startFlying(); return 0; }
              return prev - 1;
          });
      }, 1000);
  };

  const startFlying = () => {
      if (!isMounted.current) return;
      setPhase('FLYING'); playSound('plane');
      let cp = 1.0;
      const totalBet = (activeBetRef.current ? betAmount : 0) + (activeBetRef2.current ? betAmount2 : 0);
      if (totalBet > 0 && shouldForceLoss(totalBet, userBalance)) cp = 1.0 + Math.random() * 0.15;
      else cp = 1.0 + Math.random() * 15;
      crashPointRef.current = parseFloat(cp.toFixed(2));
      startTimeRef.current = Date.now();
      animLoop();
  };

  const animLoop = () => {
      if (!isMounted.current) return;
      const elapsed = (Date.now() - startTimeRef.current) / 1000;
      const cur = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.05);
      if (cur >= crashPointRef.current) handleCrash(crashPointRef.current);
      else { setMultiplier(cur); drawCanvas(cur, elapsed); animRef.current = requestAnimationFrame(animLoop); }
  };

  const drawCanvas = (cur: number, elapsed: number) => {
      const cvs = canvasRef.current; if(!cvs) return;
      const ctx = cvs.getContext('2d'); if(!ctx) return;
      cvs.width = cvs.offsetWidth; cvs.height = cvs.offsetHeight;
      ctx.clearRect(0,0,cvs.width,cvs.height);
      const padding = 60; const width = cvs.width - padding * 2; const height = cvs.height - padding * 2;
      const progress = Math.min(1, elapsed / 8);
      const planeX = padding + progress * width;
      const planeY = (cvs.height - padding) - (Math.pow(progress, 2) * height);
      ctx.beginPath(); ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; ctx.setLineDash([5, 5]);
      ctx.moveTo(padding, cvs.height - padding); ctx.quadraticCurveTo(cvs.width/2, cvs.height - padding, planeX, planeY); ctx.stroke(); ctx.setLineDash([]);
      if (planeImg.current?.complete) { ctx.save(); ctx.translate(planeX, planeY); ctx.rotate(-Math.PI / 10); ctx.drawImage(planeImg.current, -25, -25, 50, 50); ctx.restore(); }
  };

  const handleCrash = (final: number) => {
      setPhase('CRASHED'); setMultiplier(final); playSound('loss');
      if (activeBetRef.current) { activeBetRef.current = false; setActiveBet(false); onResult({ win: false, amount: betAmount, game: 'Aviator' }); }
      if (activeBetRef2.current) { activeBetRef2.current = false; setActiveBet2(false); onResult({ win: false, amount: betAmount2, game: 'Aviator' }); }
      setTimeout(() => { if (isMounted.current) startWaiting(); }, 3000);
  };

  const handleAction = (deck: 1 | 2) => {
      const amt = deck === 1 ? betAmount : betAmount2;
      const ref = deck === 1 ? activeBetRef : activeBetRef2;
      const set = deck === 1 ? setActiveBet : setActiveBet2;
      if (phase === 'WAITING') {
          if (amt > userBalance) { setInsufficientBalance(true); setTimeout(()=>setInsufficientBalance(false), 400); return; }
          ref.current = true; set(true); updateBalance(-amt, 'BET', 'Aviator Stake'); playSound('click');
      } else if (phase === 'FLYING' && ref.current) {
          const win = amt * multiplier; updateBalance(win, 'WIN', 'Aviator Cashout');
          ref.current = false; set(false); playSound('win');
          onResult({ win: true, amount: win, game: 'Aviator', resultDetails: [{label: 'Cashed', value: `${multiplier.toFixed(2)}x`}] });
          addGameHistory('Aviator', amt, win, `Won @ ${multiplier.toFixed(2)}x`);
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white relative select-none">
       <div className="p-4 flex items-center justify-between border-b border-zinc-900 bg-black z-[110] shadow-2xl">
        <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 border border-white/5"><ArrowLeft size={18}/></button>
            <span className="text-red-600 font-black italic text-3xl tracking-wider uppercase">AVIATOR</span>
        </div>
        <div className="flex gap-3 items-center">
             <div className={`flex items-center gap-2 bg-zinc-900 px-4 py-2 rounded-2xl border border-white/5 transition-all ${insufficientBalance ? 'animate-shake-red' : ''}`}>
                 <Wallet size={16} className="text-green-500"/>
                 <span className="text-sm font-black font-mono">₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={() => setShowRules(true)}><HelpCircle size={24}/></button>
             <button onClick={() => setMuted(toggleMute())}>{muted ? <VolumeX size={24}/> : <Volume2 size={24}/>}</button>
        </div>
      </div>

      <div className="relative flex-1 bg-[#050505] flex flex-col items-center justify-center overflow-hidden">
          <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-60 pointer-events-none" />
          <div className="relative z-10 flex flex-col items-center">
              <div className={`text-8xl md:text-9xl font-black font-mono tracking-tighter transition-all duration-300 ${phase === 'CRASHED' ? 'text-red-600 scale-110' : 'text-white'}`}>
                  {multiplier.toFixed(2)}x
              </div>
              {phase === 'WAITING' && <div className="mt-8 flex flex-col items-center gap-2">
                  <div className="text-[10px] font-black uppercase tracking-[0.6em] text-zinc-600 animate-pulse">Wait for Round...</div>
                  <div className="text-2xl font-black text-yellow-500 font-mono">{timeLeft}s</div>
              </div>}
              {phase === 'CRASHED' && <div className="mt-4 bg-red-600 px-4 py-1 rounded-full text-xs font-black uppercase tracking-widest animate-bounce shadow-lg">Flew Away!</div>}
          </div>
      </div>

      <div className="bg-[#0f0f0f] p-4 border-t-4 border-red-600 z-[120] shadow-[0_-20px_60px_rgba(0,0,0,1)] flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-4">
                {[1, 2].map(deckIdx => {
                    const amt = deckIdx === 1 ? betAmount : betAmount2;
                    const set = deckIdx === 1 ? setBetAmount : setBetAmount2;
                    const isActive = deckIdx === 1 ? activeBet : activeBet2;
                    return (
                        <div key={deckIdx} className="bg-zinc-950 p-4 rounded-[2rem] border border-white/5 shadow-2xl">
                            <div className="flex items-center justify-center gap-2 mb-4 bg-black/40 py-2 rounded-xl border border-white/5">
                                <button onClick={()=>set(Math.max(10, amt-10))} disabled={isActive} className="w-10 text-2xl font-black">-</button>
                                <span className="text-xl font-black font-mono min-w-[3rem] text-center">₹{amt}</span>
                                <button onClick={()=>set(amt+10)} disabled={isActive} className="w-10 text-2xl font-black">+</button>
                            </div>
                            <button onClick={() => handleAction(deckIdx as 1|2)} className={`w-full py-4 rounded-2xl font-black text-lg transition-all active:scale-95 border-b-8 shadow-xl ${isActive && phase === 'FLYING' ? 'bg-orange-500 border-orange-800' : isActive ? 'bg-red-900 border-black opacity-60' : 'bg-green-600 border-green-800'}`}>
                                {isActive && phase === 'FLYING' ? 'CASH OUT' : isActive ? 'STAKED' : 'BET'}
                            </button>
                        </div>
                    );
                })}
            </div>
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-md">
              <div className="bg-zinc-900 border border-white/10 w-full max-w-sm p-10 rounded-[3rem] shadow-2xl animate-in zoom-in">
                   <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                       <h2 className="text-2xl font-black italic text-red-500 uppercase tracking-tighter">HOW TO PLAY</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 font-medium leading-relaxed">
                       <p>1. Place your stake using one or both betting decks.</p>
                       <p>2. Watch the plane take off and the multiplier climb.</p>
                       <p>3. <span className="text-white font-bold italic">CASH OUT</span> anytime before the plane flies away.</p>
                       <p>4. If the plane vanishes before you cash out, your stake is lost.</p>
                   </div>
              </div>
          </div>
      )}
    </div>
  );
};
export default Aviator;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, PlayCircle, HelpCircle, X } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Ball {
  id: string; x: number; y: number; row: number; col: number; bet: number;
  status: 'DROPPING' | 'DONE'; targetX: number; targetY: number; progress: number;
  startPos: { x: number; y: number };
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 9; const PIN_RADIUS = 5; const BALL_RADIUS = 8;
const CANVAS_WIDTH = 380; const CANVAS_HEIGHT = 540;

const Plinko: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showRules, setShowRules] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const pulsesRef = useRef<{row: number, col: number, startTime: number}[]>([]);
  const requestRef = useRef<number>(0);
  const [floatingResults, setFloatingResults] = useState<{ id: string; mult: number; amount: number }[]>([]);

  const startY = 110; const rowSpacing = 40; const colSpacing = 36;

  useEffect(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    const animate = () => { updatePhysics(); draw(ctx); requestRef.current = requestAnimationFrame(animate); };
    requestRef.current = requestAnimationFrame(animate);
    return () => { cancelAnimationFrame(requestRef.current); stopAllSounds(); };
  }, []);

  const getPinCoords = (row: number, col: number) => {
    const pinsInRow = row + 1; const rowWidth = (pinsInRow - 1) * colSpacing;
    const startX = (CANVAS_WIDTH - rowWidth) / 2;
    return { x: startX + col * colSpacing, y: startY + row * rowSpacing };
  };

  const updatePhysics = () => {
    const slotY = startY + ROWS * rowSpacing + 20; const speed = 0.12; 
    ballsRef.current = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;
      ball.progress += speed;
      if (ball.progress >= 1) {
        ball.x = ball.targetX; ball.y = ball.targetY; ball.progress = 0; ball.startPos = { x: ball.x, y: ball.y };
        if (ball.row < ROWS - 1) {
          pulsesRef.current.push({ row: ball.row, col: ball.col, startTime: Date.now() });
          playSound('tick');
          const nextRow = ball.row + 1; const moveRight = Math.random() > 0.49 ? 1 : 0;
          const nextCol = ball.col + moveRight; const coords = getPinCoords(nextRow, nextCol);
          return { ...ball, row: nextRow, col: nextCol, targetX: coords.x, targetY: coords.y };
        } else {
          if (ball.y < slotY) { playSound('tick'); return { ...ball, targetY: slotY + 25, targetX: ball.x, row: ROWS }; }
          else { handleBallLand(ball); return { ...ball, status: 'DONE' }; }
        }
      }
      const t = ball.progress; const arcHeight = 10; 
      ball.x = ball.startPos.x + (ball.targetX - ball.startPos.x) * t;
      const linearY = ball.startPos.y + (ball.targetY - ball.startPos.y) * t;
      ball.y = linearY - (-4 * arcHeight * t * (t - 1));
      return ball;
    }).filter(b => b.status === 'DROPPING');
    pulsesRef.current = pulsesRef.current.filter(p => Date.now() - p.startTime < 400);
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 1; const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;
      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing; const py = startY + r * rowSpacing;
        const pulse = pulsesRef.current.find(pulse => pulse.row === r && pulse.col === p);
        const scale = pulse ? 1 + 0.5 * Math.sin((Date.now() - pulse.startTime) / 40) : 1;
        ctx.beginPath(); ctx.arc(px, py, PIN_RADIUS * scale, 0, Math.PI * 2);
        ctx.fillStyle = pulse ? '#60A5FA' : 'rgba(203, 213, 225, 0.8)'; ctx.fill();
      }
    }
    const slotY = startY + ROWS * rowSpacing + 20; const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 4) / 2;
    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      ctx.fillStyle = m >= 5 ? '#ef4444' : m >= 1 ? '#22c55e' : '#3b82f6';
      ctx.beginPath(); ctx.roundRect(sx, slotY, colSpacing - 4, 40, 8); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + (colSpacing - 4) / 2, slotY + 25);
    });
    ballsRef.current.forEach(ball => {
      ctx.beginPath(); ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#fbbf24'; ctx.shadowBlur = 15; ctx.shadowColor = '#f59e0b'; ctx.fill(); ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;
    updateBalance(winAmount, 'WIN', `Plinko ${multiplier}x`);
    playSound(multiplier >= 1 ? 'win' : 'click');
    const rid = Math.random().toString(36).substr(2, 5);
    setFloatingResults(prev => [...prev, { id: rid, mult: multiplier, amount: winAmount }]);
    setTimeout(() => { setFloatingResults(prev => prev.filter(res => res.id !== rid)); }, 2500);
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) { playSound('loss'); return; }
    updateBalance(-betAmount, 'BET', 'Plinko Stake');
    const startCoords = getPinCoords(0, 0);
    ballsRef.current.push({
      id: Math.random().toString(36).substr(2, 9), x: CANVAS_WIDTH / 2, y: 30, row: 0, col: 0, bet: betAmount,
      status: 'DROPPING', targetX: startCoords.x, targetY: startCoords.y, progress: 0, startPos: { x: CANVAS_WIDTH / 2, y: 30 }
    });
    playSound('click');
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      {floatingResults.map(res => (
          <div key={res.id} className="fixed top-[40%] left-1/2 -translate-x-1/2 z-[100] w-full px-10 pointer-events-none animate-in fade-in zoom-in duration-300">
               <div className={`py-4 px-8 rounded-full border-4 shadow-2xl flex items-center justify-center gap-6 backdrop-blur-xl ${res.mult >= 1 ? 'bg-green-600/90 border-green-400' : 'bg-red-600/90 border-red-400'}`}>
                   <span className="font-black italic text-3xl">{res.mult}x</span>
                   <div className="w-[2px] h-10 bg-white/20"></div>
                   <span className="font-black text-4xl">₹{res.amount.toFixed(2)}</span>
               </div>
          </div>
      ))}
      <div className="p-4 flex justify-between items-center bg-[#111827]/95 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-slate-800 rounded-2xl active:scale-90"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">PLINKO</h1>
        <div className="flex gap-2">
            <button onClick={() => setShowRules(true)} className="p-2.5 bg-slate-800 rounded-xl active:scale-90"><HelpCircle size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20">
              <Wallet size={14} className="text-yellow-500" />
              <span className="text-sm font-black text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
      </div>
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">
        <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full rounded-[2.5rem] bg-[#111827]/60 border border-white/10 shadow-2xl" />
      </div>
      <div className="bg-[#111827] border-t border-white/5 p-6 pb-12 z-50">
        <div className="flex justify-between items-end mb-6">
            <div className="text-2xl font-black italic">₹{betAmount}</div>
            <button onClick={() => setMuted(toggleMute())} className="p-3 bg-slate-800 rounded-2xl">{muted ? <VolumeX size={22}/> : <Volume2 size={22}/>}</button>
        </div>
        <div className="grid grid-cols-4 gap-3 mb-8">
            {[10, 50, 100, 500].map(amt => <button key={amt} onClick={() => setBetAmount(amt)} className={`py-4 rounded-2xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-slate-950 border-white' : 'bg-slate-800/40 border-white/5 text-slate-400'}`}>₹{amt}</button>)}
        </div>
        <button onClick={dropBall} className="w-full py-6 rounded-[2rem] bg-gradient-to-r from-yellow-400 via-orange-500 to-yellow-600 text-slate-950 font-black uppercase tracking-[0.4em] shadow-2xl active:scale-95 flex items-center justify-center gap-4 text-lg border-t-2 border-white/20"><PlayCircle size={28}/> DROP BALL</button>
      </div>
      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/90">
              <div className="bg-slate-900 border-2 border-white/10 w-full max-w-sm p-10 rounded-[3.5rem] shadow-2xl">
                   <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                       <h2 className="text-2xl font-black text-blue-500 italic uppercase">RULES</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 leading-relaxed">
                       <p>1. Set your stake and drop the ball.</p>
                       <p>2. The multiplier slot the ball lands in determines your win.</p>
                       <p>3. High multipliers are on the edges.</p>
                   </div>
              </div>
          </div>
      )}
    </div>
  );
};
export default Plinko;

import { UserProfile, WinGoHistory, WinGoGameState, Transaction, GameHistoryItem, ReferralData, SubordinateItem, CommissionItem, DragonTigerState } from '../types';

// AUDIO SYSTEM
let isMuted = false;
const sounds: Record<string, HTMLAudioElement> = {
  click: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'),
  win: new Audio('https://assets.mixkit.co/active_storage/sfx/2000/2000-preview.mp3'),
  loss: new Audio('https://assets.mixkit.co/active_storage/sfx/203/203-preview.mp3'),
  tick: new Audio('https://assets.mixkit.co/active_storage/sfx/2578/2578-preview.mp3'),
  spin: new Audio('https://assets.mixkit.co/active_storage/sfx/2003/2003-preview.mp3'),
  plane: new Audio('https://assets.mixkit.co/active_storage/sfx/1547/1547-preview.mp3')
};

export const toggleMute = () => { isMuted = !isMuted; if (isMuted) stopAllSounds(); return isMuted; };
export const getMuteStatus = () => isMuted;
export const playSound = (type: keyof typeof sounds) => {
  if (isMuted) return;
  try { const audio = sounds[type]; if (audio) { audio.currentTime = 0; audio.volume = 0.5; audio.play().catch(() => {}); } } catch (e) {}
};
export const stopAllSounds = () => { Object.values(sounds).forEach(audio => { audio.pause(); audio.currentTime = 0; }); };

// RISK MANAGEMENT Logic
export const shouldForceLoss = (bet: number, balance: number): boolean => {
    if (bet >= (balance + bet) * 0.7) return Math.random() < 0.95; 
    return false;
};

// LOCAL STORAGE ENGINE
const DB_KEYS = { USERS: 'TIRANGA_USERS', CURRENT_USER: 'TIRANGA_CURRENT_USER_UID', TRANSACTIONS: 'TIRANGA_TX_', HISTORY: 'TIRANGA_HISTORY_' };

const sanitizeUser = (user: any): UserProfile => ({
    uid: user.uid || 'unknown',
    balance: typeof user.balance === 'number' ? user.balance : 0,
    vipLevel: user.vipLevel || 0,
    name: user.name || 'User',
    username: user.username || 'User',
    phone: user.phone || '',
    avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid || 'default'}`,
    totalDeposit: user.totalDeposit || 0,
    totalBet: user.totalBet || 0,
    inviteCode: user.inviteCode || '',
    password: user.password || '',
    withdrawalPassword: user.withdrawalPassword || '',
    usedGiftCodes: Array.isArray(user.usedGiftCodes) ? user.usedGiftCodes : [],
    invitedBy: user.invitedBy || '',
    totalCommission: user.totalCommission || 0,
    wagerRequired: typeof user.wagerRequired === 'number' ? user.wagerRequired : 0,
    isBankBound: !!user.isBankBound,
    isUpiBound: !!user.isUpiBound,
    isTelegramJoined: !!user.isTelegramJoined,
    bankDetails: user.bankDetails || null,
    upiDetails: user.upiDetails || null
});

const getLocalUsers = (): Record<string, UserProfile> => {
    try {
        const data = localStorage.getItem(DB_KEYS.USERS);
        const users = data ? JSON.parse(data) : {};
        Object.keys(users).forEach(key => { users[key] = sanitizeUser(users[key]); });
        return users;
    } catch (e) { return {}; }
};
const saveLocalUsers = (users: Record<string, UserProfile>) => localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));

const getLocalTransactions = (uid: string): Transaction[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.TRANSACTIONS + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalTransactions = (uid: string, txs: Transaction[]) => localStorage.setItem(DB_KEYS.TRANSACTIONS + uid, JSON.stringify(txs));

const getLocalHistory = (uid: string): GameHistoryItem[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.HISTORY + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalHistory = (uid: string, history: GameHistoryItem[]) => localStorage.setItem(DB_KEYS.HISTORY + uid, JSON.stringify(history));

