const WinGo: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; onDeposit: () => void; }> = ({ onBack, userBalance, onResult, onDeposit }) => {
  const [gameState, setGameState] = useState<WinGoGameState | null>(null);
