  const [level, setLevel] = useState(1);
  const [showRules, setShowRules] = useState(false);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const start = () => {
      if (userBalance < bet) return;
      updateBalance(-bet, 'BET', 'Vault Breaker');
      setGameState('PLAYING');
      generateLevel(1);
      setUserInput([]);
      playSound('click');
  };

  const generateLevel = (lv: number) => {
      const combo = Array.from({length: lv + 2}, () => Math.floor(Math.random() * 4) + 1);
      setCombination(combo);
      setLevel(lv);
  };

  const handleInput = (num: number) => {
      if (gameState !== 'PLAYING') return;
      const nextInput = [...userInput, num];
      setUserInput(nextInput);
      playSound('click');

      const currentIdx = nextInput.length - 1;
      if (nextInput[currentIdx] !== combination[currentIdx]) {
          finalize(false);
      } else if (nextInput.length === combination.length) {
          if (level === 3) {
              finalize(true);
          } else {
              playSound('win');
              generateLevel(level + 1);
              setUserInput([]);
          }
      }
  };

  const finalize = (success: boolean) => {
      const winAmt = success ? bet * 5 : 0;
      if (success) {
          updateBalance(winAmt, 'WIN', 'Vault Breaker Win');
          playSound('win');
      } else {
          playSound('loss');
      }
      setGameState('RESULT');
      onResult({ win: success, amount: success ? winAmt : bet, game: 'Vault Breaker' });
      addGameHistory('Vault Breaker', bet, winAmt, success ? 'Vault Cracked' : 'Alarm Triggered');
      setTimeout(() => isMounted.current && setGameState('IDLE'), 3000);
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white select-none">
        <div className="p-4 flex justify-between items-center bg-black/40 border-b border-blue-500/20 sticky top-0 z-50">
            <div className="flex items-center gap-3">
                <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl active:scale-90"><ArrowLeft size={18}/></button>
                <h1 className="text-xl font-black italic gold-text">VAULT BREAKER</h1>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowRules(true)} className="p-2 bg-slate-800 rounded-xl active:scale-90"><HelpCircle size={18}/></button>
                <div className="text-blue-400 font-mono text-sm bg-black/40 px-3 py-1.5 rounded-xl border border-blue-500/20">₹{userBalance.toFixed(2)}</div>
            </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-8 relative">
             <div className={`w-48 h-48 rounded-full border-[12px] flex items-center justify-center transition-all duration-500 ${gameState==='PLAYING' ? 'border-blue-500 shadow-[0_0_50px_rgba(59,130,246,0.3)]' : 'border-zinc-800'}`}>
                 {gameState === 'PLAYING' ? <Unlock size={64} className="text-blue-400 animate-pulse" /> : <Lock size={64} className="text-zinc-700" />}
             </div>

             <div className="mt-10 flex gap-3">
                 {combination.map((_, i) => (
                     <div key={i} className={`w-4 h-4 rounded-full border-2 ${userInput.length > i ? 'bg-blue-500 border-blue-300' : 'border-zinc-800'}`}></div>
                 ))}
             </div>

             {gameState === 'PLAYING' && (
                 <div className="mt-4 bg-blue-500/10 px-4 py-1 rounded-full border border-blue-500/20">
                     <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">Security Tier {level}/3</span>
                 </div>
             )}
        </div>

        <div className="bg-[#111] p-8 pb-12 border-t border-white/10 shadow-[0_-20px_60px_rgba(0,0,0,1)]">
            {gameState === 'IDLE' ? (
                <div className="space-y-6">
                    <div className="flex gap-2 overflow-x-auto no-scrollbar">
                        {[10, 50, 100, 500].map(a => <button key={a} onClick={() => setBet(a)} className={`px-5 py-3 rounded-xl font-black text-xs border transition-all ${bet === a ? 'bg-blue-600 text-white border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}>₹{a}</button>)}
                    </div>
                    <button onClick={start} className="w-full py-6 rounded-[2.5rem] bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-black text-xl shadow-xl active:scale-95 transition-all border-t-2 border-white/20">ATTEMPT BREAK-IN</button>
                </div>
            ) : (
                <div className="grid grid-cols-2 gap-4">
                    {[1, 2, 3, 4].map(num => (
                        <button key={num} onClick={() => handleInput(num)} disabled={gameState !== 'PLAYING'} className="h-24 bg-zinc-900 rounded-3xl border-b-4 border-zinc-950 text-3xl font-black active:scale-95 transition-all flex items-center justify-center active:bg-blue-900 shadow-xl">{num}</button>
                    ))}
                </div>
            )}
        </div>

        {showRules && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                <div className="bg-slate-900 border-2 border-blue-500/30 w-full max-w-sm p-10 rounded-[3rem] shadow-2xl animate-in zoom-in">
                     <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                         <h2 className="text-2xl font-black text-blue-500 italic uppercase">HOW TO PLAY</h2>
                         <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
                     </div>
                     <div className="space-y-4 text-sm text-slate-300 font-medium leading-relaxed">
                         <p>1. Set your <span className="text-white font-bold">Stake</span> and attempt to crack the combination.</p>
                         <p>2. Tap the numbers <span className="text-blue-400 font-bold">1-4</span> to guess the secret sequence.</p>
                         <p>3. Successfully guess all digits in a tier to advance. There are <span className="text-white font-bold">3 Tiers</span>.</p>
                         <p>4. Cracking all 3 tiers unlocks the vault for a <span className="text-yellow-500 font-bold">5.0x</span> payout.</p>
                         <p>5. One wrong guess triggers the alarm and the stake is lost.</p>
                     </div>
                </div>
            </div>
        )}
        <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};
export default VaultBreaker;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, shouldForceLoss } from '../services/mockFirebase';
import { GameResult } from '../types';

const Aviator: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [phase, setPhase] = useState<'WAITING' | 'FLYING' | 'CRASHED'>('WAITING');
  const [multiplier, setMultiplier] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [betAmount2, setBetAmount2] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [insufficientBalance, setInsufficientBalance] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);
  const [history, setHistory] = useState<number[]>([1.45, 2.10, 1.02, 5.67, 1.15, 3.40, 12.01, 1.00]);

  const [floatingResult, setFloatingResult] = useState<{ amount: number; isWin: boolean; id: number } | null>(null);

  const activeBetRef = useRef(false);
  const activeBetRef2 = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const [activeBet2, setActiveBet2] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const crashPointRef = useRef(0);
  const startTimeRef = useRef(0);
  const animRef = useRef(0);
  const isMounted = useRef(true);
  const planeImg = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    isMounted.current = true;
    planeImg.current = new Image();
    // High quality red plane icon
    planeImg.current.src = "https://cdn-icons-png.flaticon.com/512/3122/3122330.png";
    startWaiting();
    return () => { isMounted.current = false; cancelAnimationFrame(animRef.current); stopAllSounds(); };
  }, []);

  const triggerLocalResult = (amount: number, isWin: boolean) => {
      setFloatingResult({ amount, isWin, id: Date.now() });
      setTimeout(() => setFloatingResult(null), 2500);
  };

  const startWaiting = () => {
      if (!isMounted.current) return;
      setPhase('WAITING'); 
      setMultiplier(1.00);
      setTimeLeft(10);
      const timer = setInterval(() => {
          setTimeLeft(prev => {
              if (prev <= 1) { clearInterval(timer); startFlying(); return 0; }
              return prev - 1;
          });
      }, 1000);
  };

  const startFlying = () => {
      if (!isMounted.current) return;
      setPhase('FLYING'); 
      playSound('plane');
      let cp = 1.0;
      const totalBet = (activeBetRef.current ? betAmount : 0) + (activeBetRef2.current ? betAmount2 : 0);

      // Risk Management: Force crash early if high stakes are detected
      if (totalBet > 0 && shouldForceLoss(totalBet, userBalance)) cp = 1.0 + Math.random() * 0.18;
      else cp = 1.0 + Math.random() * 10;

      crashPointRef.current = parseFloat(cp.toFixed(2));
      startTimeRef.current = Date.now();
      animLoop();
  };

  const animLoop = () => {
      if (!isMounted.current) return;
      const elapsed = (Date.now() - startTimeRef.current) / 1000;
      // Exponential curve for multiplier growth
      const cur = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.06);

      if (cur >= crashPointRef.current) {
          handleCrash(crashPointRef.current);
      } else {
          setMultiplier(cur);
          drawCanvas(cur, elapsed);
          animRef.current = requestAnimationFrame(animLoop);
      }
  };

  const drawCanvas = (cur: number, elapsed: number) => {
      const cvs = canvasRef.current; if(!cvs) return;
      const ctx = cvs.getContext('2d'); if(!ctx) return;
      cvs.width = cvs.offsetWidth; cvs.height = cvs.offsetHeight;
      ctx.clearRect(0,0,cvs.width,cvs.height);

      const padding = 50;
      const w = cvs.width - padding * 2;
      const h = cvs.height - padding * 2;

      // Logic for curve: quadratic path representing the flight
      // We normalize elapsed time to 0-1 over a standard 10s flight window
      const progress = Math.min(1, elapsed / 8);
      const startX = padding;
      const startY = cvs.height - padding;
      const endX = startX + progress * w;
      const endY = startY - (Math.pow(progress, 2) * h);

      // Draw Grid for "Graph" feel
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
      ctx.lineWidth = 1;
      for (let x = 0; x < cvs.width; x += 50) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, cvs.height); ctx.stroke(); }
      for (let y = 0; y < cvs.height; y += 50) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(cvs.width, y); ctx.stroke(); }

      // 1. Draw Fill Area Under Curve (Gradient)
      const gradient = ctx.createLinearGradient(0, endY, 0, startY);
      gradient.addColorStop(0, 'rgba(239, 68, 68, 0.2)');
      gradient.addColorStop(1, 'rgba(239, 68, 68, 0)');

      ctx.beginPath();
      ctx.moveTo(startX, startY);
      ctx.quadraticCurveTo(cvs.width / 2, startY, endX, endY);
      ctx.lineTo(endX, startY);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.fill();

      // 2. Draw Solid Red Curve Line
      ctx.beginPath();
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      ctx.moveTo(startX, startY);
      ctx.quadraticCurveTo(cvs.width / 2, startY, endX, endY);
      ctx.stroke();

      // 3. Draw Plane
      if (planeImg.current?.complete) {
          ctx.save();
          ctx.translate(endX, endY);
          // Tilt plane upwards slightly
          ctx.rotate(-Math.PI / 12);
          ctx.shadowBlur = 15;
          ctx.shadowColor = 'rgba(239, 68, 68, 0.8)';
          ctx.drawImage(planeImg.current, -25, -25, 50, 50);
          ctx.restore();
      }
  };

  const handleCrash = (final: number) => {
      setPhase('CRASHED');
      setMultiplier(final);
      playSound('loss');
      setHistory(prev => [final, ...prev].slice(0, 15));

      if (activeBetRef.current) { 
          activeBetRef.current = false; 
          setActiveBet(false); 
          triggerLocalResult(betAmount, false); 
      }
      if (activeBetRef2.current) { 
          activeBetRef2.current = false; 
          setActiveBet2(false); 
          triggerLocalResult(betAmount2, false); 
      }

      setTimeout(() => { if (isMounted.current) startWaiting(); }, 3000);
  };

  const handleAction = (deck: 1 | 2) => {
      const amt = deck === 1 ? betAmount : betAmount2;
      const ref = deck === 1 ? activeBetRef : activeBetRef2;
      const set = deck === 1 ? setActiveBet : setActiveBet2;

      if (phase === 'WAITING') {
          if (amt > userBalance) { 
              setInsufficientBalance(true); 
              setTimeout(() => setInsufficientBalance(false), 400); 
              return; 
          }
          ref.current = true; 
          set(true); 
          updateBalance(-amt, 'BET', 'Aviator Stake'); 
          playSound('click');
      } else if (phase === 'FLYING' && ref.current) {
          const win = amt * multiplier; 
          updateBalance(win, 'WIN', 'Aviator Cashout');
          ref.current = false; 
          set(false); 
          playSound('win');
          triggerLocalResult(win, true);
          addGameHistory('Aviator', amt, win, `Won @ ${multiplier.toFixed(2)}x`);
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white relative select-none">
       {/* FLOATING RESULT ANIMATION */}
       {floatingResult && (
           <div key={floatingResult.id} className="fixed top-1/2 left-1/2 -translate-x-1/2 z-[200] pointer-events-none animate-in fade-in zoom-in duration-300">
               <div className={`py-4 px-10 rounded-full border-4 shadow-[0_0_80px_rgba(0,0,0,0.8)] flex items-center justify-center gap-6 backdrop-blur-xl ${floatingResult.isWin ? 'bg-green-600 border-green-400 shadow-green-500/40' : 'bg-red-600 border-red-400 shadow-red-500/40'} animate-bounce`}>
                    <span className="font-black text-4xl italic tracking-tighter">
                        {floatingResult.isWin ? '+' : '-'}₹{floatingResult.amount.toFixed(2)}
                    </span>
               </div>
           </div>
       )}

       <div className="p-4 flex items-center justify-between border-b border-zinc-900 bg-black z-[110] shadow-2xl">
        <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 border border-white/5"><ArrowLeft size={18}/></button>
            <span className="text-red-600 font-black italic text-3xl tracking-wider uppercase">AVIATOR</span>
        </div>
        <div className="flex gap-4 items-center">
             <div className={`flex items-center gap-2 bg-zinc-900 px-4 py-2 rounded-2xl border border-white/5 transition-all ${insufficientBalance ? 'animate-shake-red' : ''}`}>
                 <Wallet size={16} className="text-green-500"/>
                 <span className="text-sm font-black font-mono">₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={() => setMuted(toggleMute())} className="p-1">
                 {muted ? <VolumeX size={24} className="text-zinc-500"/> : <Volume2 size={24} className="text-zinc-300"/>}
             </button>
        </div>
      </div>

      {/* HISTORY BAR */}
      <div className="bg-zinc-950 p-2 flex items-center gap-2 overflow-x-auto no-scrollbar border-b border-white/5 relative z-40">
          <History size={14} className="text-zinc-700 shrink-0 ml-2"/>
          <div className="flex gap-2">
              {history.map((h, i) => (
                  <span key={i} className={`px-3 py-1 rounded-full text-[10px] font-black border border-white/5 whitespace-nowrap shadow-lg ${h >= 2 ? 'bg-purple-600 text-white border-purple-400' : 'bg-blue-900 text-blue-300 border-blue-700'}`}>{h.toFixed(2)}x</span>
              ))}
          </div>
      </div>

      <div className="relative flex-1 bg-[#050505] flex flex-col items-center justify-center overflow-hidden">
          <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-80 pointer-events-none" />
          <div className="relative z-10 flex flex-col items-center">
              <div className={`text-8xl md:text-9xl font-black font-mono tracking-tighter transition-all duration-300 ${phase === 'CRASHED' ? 'text-red-600 scale-110 drop-shadow-[0_0_30px_rgba(220,38,38,0.5)]' : 'text-white'}`}>
                  {multiplier.toFixed(2)}x
              </div>
              {phase === 'WAITING' && (
                <div className="mt-8 flex flex-col items-center gap-2 bg-black/40 p-4 rounded-3xl backdrop-blur-md border border-white/5">
                    <div className="text-[10px] font-black uppercase tracking-[0.6em] text-zinc-500 animate-pulse">Wait for Round...</div>
                    <div className="text-3xl font-black text-yellow-500 font-mono italic">{timeLeft}s</div>
                </div>
              )}
              {phase === 'CRASHED' && (
                <div className="mt-4 bg-red-600 px-6 py-2 rounded-full text-xs font-black uppercase tracking-widest animate-bounce shadow-[0_0_20px_rgba(220,38,38,0.6)]">Flew Away!</div>
              )}
          </div>
      </div>

      <div className="bg-[#0a0a0a] p-4 border-t-4 border-red-600 z-[120] shadow-[0_-20px_60px_rgba(0,0,0,1)] flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-4">
                {[1, 2].map(deckIdx => {
                    const amt = deckIdx === 1 ? betAmount : betAmount2;
                    const set = deckIdx === 1 ? setBetAmount : setBetAmount2;
                    const isActive = deckIdx === 1 ? activeBet : activeBet2;
                    return (
                        <div key={deckIdx} className="bg-zinc-950 p-4 rounded-[2rem] border border-white/5 shadow-2xl relative overflow-hidden">
                            <div className="flex items-center justify-center gap-2 mb-4 bg-black/60 py-3 rounded-2xl border border-white/5">
                                <button onClick={()=>set(Math.max(10, amt-10))} disabled={isActive} className="w-10 text-2xl font-black text-red-500 active:scale-90">-</button>
                                <span className="text-xl font-black font-mono min-w-[4rem] text-center">₹{amt}</span>
                                <button onClick={()=>set(amt+10)} disabled={isActive} className="w-10 text-2xl font-black text-green-500 active:scale-90">+</button>
                            </div>
                            <button onClick={() => handleAction(deckIdx as 1|2)} className={`w-full py-5 rounded-2xl font-black text-lg transition-all active:scale-95 border-b-[8px] shadow-2xl ${isActive && phase === 'FLYING' ? 'bg-orange-500 border-orange-800' : isActive ? 'bg-zinc-800 border-black opacity-50' : 'bg-green-600 border-green-800'}`}>
                                {isActive && phase === 'FLYING' ? 'CASH OUT' : isActive ? 'STAKED' : 'BET'}
                            </button>
                        </div>
                    );
                })}
            </div>
      </div>
    </div>
  );
};
export default Aviator;

import { UserProfile, WinGoHistory, WinGoGameState, Transaction, GameHistoryItem, ReferralData, SubordinateItem, CommissionItem, DragonTigerState } from '../types';

// AUDIO SYSTEM
let isMuted = false;
const sounds: Record<string, HTMLAudioElement> = {
  click: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'),
  win: new Audio('https://assets.mixkit.co/active_storage/sfx/2000/2000-preview.mp3'),
  loss: new Audio('https://assets.mixkit.co/active_storage/sfx/203/203-preview.mp3'),
  tick: new Audio('https://assets.mixkit.co/active_storage/sfx/2578/2578-preview.mp3'),
  spin: new Audio('https://assets.mixkit.co/active_storage/sfx/2003/2003-preview.mp3'),
  plane: new Audio('https://assets.mixkit.co/active_storage/sfx/1547/1547-preview.mp3')
};

export const toggleMute = () => { isMuted = !isMuted; if (isMuted) stopAllSounds(); return isMuted; };
export const getMuteStatus = () => isMuted;
export const playSound = (type: keyof typeof sounds) => {
  if (isMuted) return;
  try { const audio = sounds[type]; if (audio) { audio.currentTime = 0; audio.volume = 0.5; audio.play().catch(() => {}); } } catch (e) {}
};
export const stopAllSounds = () => { Object.values(sounds).forEach(audio => { audio.pause(); audio.currentTime = 0; }); };

// RISK MANAGEMENT Logic
export const shouldForceLoss = (bet: number, balance: number): boolean => {
    if (bet >= (balance + bet) * 0.7) return Math.random() < 0.95; 
    return false;
};

// LOCAL STORAGE ENGINE
const DB_KEYS = { USERS: 'TIRANGA_USERS', CURRENT_USER: 'TIRANGA_CURRENT_USER_UID', TRANSACTIONS: 'TIRANGA_TX_', HISTORY: 'TIRANGA_HISTORY_' };

const sanitizeUser = (user: any): UserProfile => ({
    uid: user.uid || 'unknown',
    balance: typeof user.balance === 'number' ? user.balance : 0,
    vipLevel: user.vipLevel || 0,
    name: user.name || 'User',
    username: user.username || 'User',
    phone: user.phone || '',
    avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid || 'default'}`,
    totalDeposit: user.totalDeposit || 0,
    totalBet: user.totalBet || 0,
    inviteCode: user.inviteCode || '',
    password: user.password || '',
    withdrawalPassword: user.withdrawalPassword || '',
    usedGiftCodes: Array.isArray(user.usedGiftCodes) ? user.usedGiftCodes : [],
    invitedBy: user.invitedBy || '',
    totalCommission: user.totalCommission || 0,
    wagerRequired: typeof user.wagerRequired === 'number' ? user.wagerRequired : 0,
    isBankBound: !!user.isBankBound,
    isUpiBound: !!user.isUpiBound,
    isTelegramJoined: !!user.isTelegramJoined,
    bankDetails: user.bankDetails || null,
    upiDetails: user.upiDetails || null
});

const getLocalUsers = (): Record<string, UserProfile> => {
    try {
        const data = localStorage.getItem(DB_KEYS.USERS);
        const users = data ? JSON.parse(data) : {};
        Object.keys(users).forEach(key => { users[key] = sanitizeUser(users[key]); });
        return users;
    } catch (e) { return {}; }
};
const saveLocalUsers = (users: Record<string, UserProfile>) => localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));

const getLocalTransactions = (uid: string): Transaction[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.TRANSACTIONS + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalTransactions = (uid: string, txs: Transaction[]) => localStorage.setItem(DB_KEYS.TRANSACTIONS + uid, JSON.stringify(txs));

const getLocalHistory = (uid: string): GameHistoryItem[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.HISTORY + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalHistory = (uid: string, history: GameHistoryItem[]) => localStorage.setItem(DB_KEYS.HISTORY + uid, JSON.stringify(history));

let currentUser: UserProfile | null = null;
const balanceSubscribers: Function[] = [];
export let transactions: Transaction[] = [];
export let gameHistory: GameHistoryItem[] = [];
export let referralStats: ReferralData = { code: '', link: '', totalCommission: 0, yesterdayCommission: 0, directSubordinates: 0, teamSubordinates: 0, totalDepositAmount: 0, totalBetAmount: 0 };

const initSession = () => {
    try {
        const uid = localStorage.getItem(DB_KEYS.CURRENT_USER);
        if (uid) {
            const users = getLocalUsers();
            if (users[uid]) {
                currentUser = users[uid];
                transactions = getLocalTransactions(uid);
                gameHistory = getLocalHistory(uid);
                calculateReferralStats(currentUser.inviteCode);
                notifySubscribers();
