export const subscribeToBalance = (cb: (user: UserProfile | null) => void) => {
    return onAuthStateChanged(auth, (authUser) => {
        if (authUser) {
            onSnapshot(doc(db, 'users', authUser.uid), (docSnap) => {
                if (docSnap.exists()) {
                    cb(docSnap.data() as UserProfile);
                } else {
                    cb(null);
                }
            });
        } else {
            cb(null);
        }
    });
};

export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    const user = auth.currentUser;
    if (!user) return;

    const userRef = doc(db, 'users', user.uid);
    const txRef = collection(db, 'users', user.uid, 'transactions');

    await runTransaction(db, async (transaction) => {
        const userDoc = await transaction.get(userRef);
        if (!userDoc.exists()) return;

        const currentBalance = userDoc.data().balance;
        const newBalance = currentBalance + amount;

        let updateData: any = { balance: newBalance };
        if (type === 'BET') {
            updateData.totalBet = increment(Math.abs(amount));
            updateData.wagerRequired = Math.max(0, userDoc.data().wagerRequired - Math.abs(amount));
        }

        transaction.update(userRef, updateData);
        transaction.set(doc(txRef), {
            id: 'TX_' + Date.now(),
            type,
            amount: Math.abs(amount),
            status: 'SUCCESS',
            date: new Date().toLocaleString(),
            desc,
            timestamp: Date.now()
        });
    });
};

