    const historyRef = collection(db, 'users', user.uid, 'game_history');
    await addDoc(historyRef, {
        game, amount: bet, win, date: new Date().toLocaleString(), details, timestamp: Date.now()
    });
};

export const getGameHistory = (gameName: string, cb: (history: GameHistoryItem[]) => void) => {
    const user = auth.currentUser;
    if (!user) return () => {};
    const q = query(
        collection(db, 'users', user.uid, 'game_history'),
        where('game', '==', gameName),
        orderBy('timestamp', 'desc'),
        limit(50)
    );
    return onSnapshot(q, (snap) => {
        cb(snap.docs.map(d => ({ ...d.data(), id: d.id } as GameHistoryItem)));
    });
};

