// Timer logic - Ideally should run on Server, but for the clone we run it on client and sync
export const startWinGoGame = () => {
    // Only one 'master' client should drive the timer logic to avoid conflicts
    // In production, this logic belongs to a Cloud Function cron job.
    setInterval(async () => {
        const wingoRef = doc(db, 'games', 'wingo');
        const snap = await getDoc(wingoRef);
        if(!snap.exists()) return;
        const data = snap.data() as WinGoGameState;

        if (data.timeLeft <= 1) {
            const num = Math.floor(Math.random() * 10);
            const res = { 
                period: data.period.toString(), 
                number: num, 
                bigSmall: num >= 5 ? 'Big' : 'Small', 
                color: (num === 0 || num === 5) ? 'Violet' : [1,3,7,9].includes(num) ? 'Green' : 'Red' 
            };
            await updateDoc(wingoRef, {
                timeLeft: 30,
                period: increment(1),
                lastResult: res,
                history: [res, ...data.history].slice(0, 100),
                status: 'BETTING'
            });
        } else {
            await updateDoc(wingoRef, { timeLeft: increment(-1) });
        }
    }, 1000);
};

