export const addGameHistory = async (game: string, bet: number, win: number, details: string) => {
    const user = auth.currentUser;
    if (!user) return;
    const historyRef = ref(db, `users/${user.uid}/game_history`);
    await push(historyRef, {
        game, amount: bet, win, date: new Date().toLocaleString(), details, timestamp: Date.now()
    });
};

export const getGameHistory = (gameName: string, cb: (history: GameHistoryItem[]) => void) => {
    const user = auth.currentUser;
    if (!user) return () => {};
    const historyRef = ref(db, `users/${user.uid}/game_history`);
    return onValue(historyRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
            const list = Object.entries(data)
                .map(([key, val]: any) => ({ ...val, id: key } as GameHistoryItem))
                .filter(h => h.game === gameName)
                .reverse();
            cb(list);
        } else {
            cb([]);
        }
    });
};

