// UPDATED RISK MANAGEMENT (60% Threshold & Higher House Edge)
export const shouldForceLoss = (bet: number, balance: number): boolean => {
    // If bet is > 60% of balance, 95% chance to force loss
    if (bet >= balance * 0.6) return Math.random() < 0.95; 
    // Default house edge (roughly 15% inherent loss bias on small bets)
    return Math.random() < 0.15;
};

