export const startWinGoGame = () => {
    setInterval(async () => {
        const wingoRef = ref(db, 'games/wingo');
        const snap = await get(wingoRef);
        if(!snap.exists()) return;
        const data = snap.val() as WinGoGameState;

        if (data.timeLeft <= 1) {
            const num = Math.floor(Math.random() * 10);
            const res = { 
                period: data.period.toString(), 
                number: num, 
                bigSmall: num >= 5 ? 'Big' : 'Small', 
                color: (num === 0 || num === 5) ? 'Violet' : [1,3,7,9].includes(num) ? 'Green' : 'Red' 
            };
            await update(wingoRef, {
                timeLeft: 30,
                period: data.period + 1,
                lastResult: res,
                history: [res, ...(data.history || [])].slice(0, 100),
                status: 'BETTING'
            });
        } else {
            await update(wingoRef, { timeLeft: data.timeLeft - 1 });
        }
    }, 1000);
};

