export const redeemGiftCode = async (code: string): Promise<number> => {
    const u = auth.currentUser;
    if (!u) return 0;
    const snap = await get(ref(db, `users/${u.uid}/usedGiftCodes`));
    const used = snap.val() || [];
    if (used.includes(code)) return 0;

    let amount = 0;
