export const shouldForceLoss = (bet: number, balance: number): boolean => {
    const threshold = balance * 0.1; // If betting more than 10% of balance, higher house edge
    const lossProbability = bet > threshold ? 0.85 : 0.70;
    return Math.random() < lossProbability;
};

