// RISK MANAGEMENT
export const shouldForceLoss = (bet: number, balance: number): boolean => {
    const threshold = balance * 0.15;
    const lossProbability = bet > threshold ? 0.88 : 0.72;
    return Math.random() < lossProbability;
};

// GLOBAL ACCOUNT UNIQUENESS CHECK
const checkIsAccountUnique = async (key: 'accountNo' | 'upiId', value: string, currentUid: string) => {
    const snapshot = await get(ref(db, 'users'));
    const users = snapshot.val() || {};
    return !Object.values(users).some((u: any) => {
        if (u.uid === currentUid) return false; // Ignore self
        // Check linked accounts
        if (key === 'accountNo' && u.bankDetails?.accountNo === value) return true;
        if (key === 'upiId' && u.upiDetails?.upiId === value) return true;
        // Check transaction history (used for withdrawal but not saved)
        if (u.transactions) {
            return Object.values(u.transactions).some((t: any) => {
                if (key === 'accountNo' && t.accountDetails?.accountNo === value) return true;
                if (key === 'upiId' && t.accountDetails?.upiId === value) return true;
                return false;
            });
        }
        return false;
    });
};

