export const handleWithdraw = async (amount: number, method: string, pin: string, details: any) => {
    const user = auth.currentUser;
    if (!user) return { success: false, message: 'Auth Required' };

    // Uniqueness check for new details provided during withdrawal
    if (method === 'BANK' && details.accountNo) {
        const isUnique = await checkIsAccountUnique('accountNo', details.accountNo, user.uid);
        if (!isUnique) return { success: false, message: 'Bank account already used elsewhere.' };
    }
    if (method === 'UPI' && details.upiId) {
        const isUnique = await checkIsAccountUnique('upiId', details.upiId, user.uid);
        if (!isUnique) return { success: false, message: 'UPI ID already used elsewhere.' };
    }

    const snapshot = await get(ref(db, `users/${user.uid}`));
    const userData = snapshot.val();
    if (userData?.withdrawalPassword !== pin) return { success: false, message: 'Invalid PIN' };
    if (userData?.balance < amount) return { success: false, message: 'Insufficient Balance' };
    if (userData?.wagerRequired > 0) return { success: false, message: `Turnover left: ₹${userData.wagerRequired.toFixed(2)}` };

    await updateBalance(-amount, 'WITHDRAW', `Withdrawal via ${method}`);
    // Save details in the transaction for global tracking
    const txId = Date.now().toString();
    await update(ref(db, `users/${user.uid}/transactions/${txId}`), { accountDetails: details });

    return { success: true };
};

export const approveTransaction = async (txId: string) => {
    const user = auth.currentUser;
    if (!user) return;
    const txsRef = ref(db, `users/${user.uid}/transactions`);
    const snapshot = await get(txsRef);
    const txData = snapshot.val();
    if (txData) {
        const key = Object.keys(txData).find(k => txData[k].id === txId);
        if (key && txData[key].status === 'PROCESSING') {
            await update(ref(db, `users/${user.uid}/transactions/${key}`), { status: 'SUCCESS' });
            if (txData[key].type === 'DEPOSIT') {
                const uSnap = await get(ref(db, `users/${user.uid}`));
                const currentU = uSnap.val();
                const newTotalDep = (currentU.totalDeposit || 0) + txData[key].amount;
                const newVIP = calculateVIP(newTotalDep);
                await update(ref(db, `users/${user.uid}`), { totalDeposit: newTotalDep, vipLevel: newVIP });
                await updateBalance(txData[key].amount, 'DEPOSIT', 'Deposit Verified', 6.8); // 6.8x Wager for deposits
            }
        }
    }
};

