export const getGameHistory = (gameName: string, cb: (history: GameHistoryItem[]) => void) => {
    const user = auth.currentUser;
    if (!user) return () => {};
    return onValue(ref(db, `users/${user.uid}/game_history`), (snapshot) => {
        const data = snapshot.val();
        if (data) {
            const list = Object.entries(data).map(([key, val]: any) => ({ ...val, id: key }));
            const filtered = gameName === 'ALL' ? list : list.filter((h: any) => h.game === gameName);
            cb(filtered.reverse());
        } else cb([]);
    });
};

