// LOCAL STORAGE ENGINE
const DB_KEYS = { USERS: 'MAFIA_USERS', CURRENT_USER: 'MAFIA_CURRENT_UID', TRANSACTIONS: 'MAFIA_TX_', HISTORY: 'MAFIA_HISTORY_' };

const sanitizeUser = (user: any): UserProfile => ({
    uid: user.uid || 'unknown',
    balance: typeof user.balance === 'number' ? user.balance : 0,
    vipLevel: user.vipLevel || 0,
    name: user.name || 'User',
    username: user.username || 'User',
    phone: user.phone || '',
    avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid || 'default'}`,
    totalDeposit: user.totalDeposit || 0,
    totalBet: user.totalBet || 0,
    inviteCode: user.inviteCode || '',
    password: user.password || '',
    withdrawalPassword: user.withdrawalPassword || '',
    usedGiftCodes: Array.isArray(user.usedGiftCodes) ? user.usedGiftCodes : [],
    invitedBy: user.invitedBy || '',
    totalCommission: user.totalCommission || 0,
    wagerRequired: user.wagerRequired || 0
});

const getLocalUsers = (): Record<string, UserProfile> => {
    try {
        const data = localStorage.getItem(DB_KEYS.USERS);
        const users = data ? JSON.parse(data) : {};
        Object.keys(users).forEach(key => { users[key] = sanitizeUser(users[key]); });
        return users;
    } catch (e) { return {}; }
};
const saveLocalUsers = (users: Record<string, UserProfile>) => localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));

const getLocalTransactions = (uid: string): Transaction[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.TRANSACTIONS + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalTransactions = (uid: string, txs: Transaction[]) => localStorage.setItem(DB_KEYS.TRANSACTIONS + uid, JSON.stringify(txs));

const getLocalHistory = (uid: string): GameHistoryItem[] => {
    try { return JSON.parse(localStorage.getItem(DB_KEYS.HISTORY + uid) || '[]'); } catch (e) { return []; }
};
const saveLocalHistory = (uid: string, history: GameHistoryItem[]) => localStorage.setItem(DB_KEYS.HISTORY + uid, JSON.stringify(history));

let currentUser: UserProfile | null = null;
const balanceSubscribers: Function[] = [];
export let transactions: Transaction[] = [];
export let gameHistory: GameHistoryItem[] = [];
export let referralStats: ReferralData = { code: '', link: '', totalCommission: 0, yesterdayCommission: 0, directSubordinates: 0, teamSubordinates: 0, totalDepositAmount: 0, totalBetAmount: 0 };

const initSession = () => {
    try {
        const uid = localStorage.getItem(DB_KEYS.CURRENT_USER);
        if (uid) {
            const users = getLocalUsers();
            if (users[uid]) {
                currentUser = users[uid];
                transactions = getLocalTransactions(uid);
                gameHistory = getLocalHistory(uid);
                calculateReferralStats(currentUser.inviteCode);
                notifySubscribers();
            } else { localStorage.removeItem(DB_KEYS.CURRENT_USER); }
        }
    } catch (e) {}
};

export const login = async (phone: string, pass: string) => {
    const users = getLocalUsers();
    const user = Object.values(users).find(u => u.phone === phone && u.password === pass);
    if (user) {
        currentUser = user;
        localStorage.setItem(DB_KEYS.CURRENT_USER, user.uid);
        transactions = getLocalTransactions(user.uid);
        gameHistory = getLocalHistory(user.uid);
        calculateReferralStats(user.inviteCode);
        notifySubscribers();
        return { success: true };
    }
    return { success: false, message: 'Invalid phone or password' };
};

export const register = async (phone: string, pass: string, inviteCode: string, username: string) => {
    const users = getLocalUsers();
    if (Object.values(users).some(u => u.phone === phone)) return { success: false, message: 'Phone already registered' };
    const uid = 'USER_' + Date.now();
    const newUser: UserProfile = sanitizeUser({
        uid, password: pass, name: username, username, phone, inviteCode: Math.floor(10000000 + Math.random() * 90000000).toString(), invitedBy: inviteCode
    });
    users[uid] = newUser;
    saveLocalUsers(users);
    currentUser = newUser;
    localStorage.setItem(DB_KEYS.CURRENT_USER, uid);
    transactions = []; gameHistory = [];
    notifySubscribers();
    return { success: true };
};

export const logout = async () => {
    currentUser = null; transactions = []; gameHistory = [];
    localStorage.removeItem(DB_KEYS.CURRENT_USER);
    notifySubscribers();
};

export const checkAuth = () => !!currentUser;
export const subscribeToBalance = (cb: (user: UserProfile | null) => void) => {
    balanceSubscribers.push(cb);
    cb(currentUser ? { ...currentUser } : null);
    return () => { const idx = balanceSubscribers.indexOf(cb); if (idx > -1) balanceSubscribers.splice(idx, 1); };
};
const notifySubscribers = () => balanceSubscribers.forEach(cb => cb(currentUser ? { ...currentUser } : null));

const calculateReferralStats = (myCode: string) => {
    if (!myCode) return;
    const users = getLocalUsers();
    const subs = Object.values(users).filter(u => u.invitedBy === myCode);
    const totalDep = subs.reduce((acc, c) => acc + (c.totalDeposit || 0), 0);
    referralStats.code = myCode;
    referralStats.link = `${window.location.origin}/#/register?code=${myCode}`;
    referralStats.directSubordinates = subs.length;
    referralStats.teamSubordinates = subs.length;
    referralStats.totalDepositAmount = totalDep;
    referralStats.totalBetAmount = subs.reduce((acc, c) => acc + (c.totalBet || 0), 0);
    referralStats.totalCommission = totalDep * 0.1;
};
export const getSubordinates = (): SubordinateItem[] => {
    if (!currentUser) return [];
    return Object.values(getLocalUsers()).filter(u => u.invitedBy === currentUser?.inviteCode).map(u => ({
        id: u.uid, uid: u.uid, level: 1, depositAmount: u.totalDeposit || 0, betAmount: u.totalBet || 0, commission: (u.totalDeposit || 0) * 0.1, date: '2023-11-28'
    }));
};
export const getCommissions = (): CommissionItem[] => transactions.filter(t => t.type === 'COMMISSION').map(t => ({ id: t.id, fromUid: 'System', amount: t.amount, date: t.date, type: 'Deposit Bonus' }));

export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const users = getLocalUsers();
    const user = users[currentUser.uid];
    if (user) {
        user.balance += amount;

        // Smart Wager Reset
        if (user.balance <= 0) user.wagerRequired = 0;

        if (type === 'BET') {
            user.totalBet = (user.totalBet || 0) + Math.abs(amount);
            user.wagerRequired = Math.max(0, (user.wagerRequired || 0) - Math.abs(amount));
        }

        currentUser = user;
        saveLocalUsers(users);
        transactions.unshift({ id: 'TX_' + Date.now(), type, amount: Math.abs(amount), status: 'SUCCESS', date: new Date().toLocaleString(), desc, timestamp: Date.now() });
        saveLocalTransactions(user.uid, transactions);
        notifySubscribers();
    }
};

export const addGameHistory = async (game: string, bet: number, win: number, details: string) => {
    if (!currentUser) return;
    gameHistory.unshift({ id: Date.now().toString(), game, amount: bet, win, date: new Date().toLocaleString(), details });
    saveLocalHistory(currentUser.uid, gameHistory);
};
export const getGameHistory = (gameName: string) => gameHistory.filter(item => item.game === gameName);

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txIndex = transactions.findIndex(t => t.id === txId);
    if (txIndex === -1 || transactions[txIndex].status !== 'PROCESSING') return;
    const tx = transactions[txIndex];
    tx.status = 'SUCCESS';
    saveLocalTransactions(currentUser.uid, transactions);
    if (tx.type === 'DEPOSIT') {
        const users = getLocalUsers();
        const user = users[currentUser.uid];
        user.balance += tx.amount;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;
        user.wagerRequired = (user.wagerRequired || 0) + (tx.amount * 1);
        currentUser = user;
        saveLocalUsers(users);
        notifySubscribers();
        playSound('win');
    }
};

export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    transactions.unshift({ id: 'TX_' + Date.now(), type: 'DEPOSIT', amount, status: 'PROCESSING', date: new Date().toLocaleString(), desc: `Deposit via ${method}`, utr, method, timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    notifySubscribers();
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Not logged in' };
    if (currentUser.withdrawalPassword !== password) return { success: false, message: 'Invalid Password' };
    if (currentUser.balance < amount) return { success: false, message: 'Insufficient balance' };
    if (currentUser.wagerRequired > 0) return { success: false, message: `Turnover left: ₹${currentUser.wagerRequired.toFixed(0)}` };

    const users = getLocalUsers();
    users[currentUser.uid].balance -= amount;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);
    notifySubscribers();
    transactions.unshift({ id: 'TX_' + Date.now(), type: 'WITHDRAW', amount, status: 'PROCESSING', date: new Date().toLocaleString(), desc: `Withdraw via ${method}`, method, accountDetails: details, timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    return { success: true };
};

export const setWithdrawalPassword = (password: string) => {
    if (!currentUser) return false;
    const users = getLocalUsers();
    users[currentUser.uid].withdrawalPassword = password;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);
    return true;
};

export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser || currentUser.usedGiftCodes?.includes(code)) return 0;
    let amount = 0;
    if (code === 'MAFIA100') amount = 100;
    if (code === 'ff') amount = 1000;

    if (amount > 0) {
        const users = getLocalUsers();
        users[currentUser.uid].usedGiftCodes = [...(users[currentUser.uid].usedGiftCodes || []), code];
        users[currentUser.uid].balance += amount;
        users[currentUser.uid].wagerRequired = (users[currentUser.uid].wagerRequired || 0) + (amount * 6.8);
        currentUser = users[currentUser.uid];
        saveLocalUsers(users);
        transactions.unshift({ id: 'TX_' + Date.now(), type: 'GIFT', amount, status: 'SUCCESS', date: new Date().toLocaleString(), desc: `Gift Code: ${code}`, timestamp: Date.now() });
        saveLocalTransactions(currentUser.uid, transactions);
        notifySubscribers();
        return amount;
    }
    return 0;
};

export const getGameStats = () => {
    const stats: Record<string, { bet: number, win: number }> = {};
    gameHistory.forEach(g => {
        if (!stats[g.game]) stats[g.game] = { bet: 0, win: 0 };
        stats[g.game].bet += g.amount;
        stats[g.game].win += g.win;
    });
    return Object.entries(stats).map(([name, data]) => ({ name, bet: data.bet, win: data.win, profit: data.win - data.bet }));
};

// GLOBAL GAME ENGINES
let winGoState: WinGoGameState = { timeLeft: 30, period: 202511261000, history: [], status: 'BETTING', lastResult: null };
const winGoSubscribers: Function[] = [];

let aviatorState: AviatorState = { phase: 'WAITING', multiplier: 1.0, timeLeft: 10, history: [], crashPoint: 0 };
const aviatorSubscribers: Function[] = [];

const generateWinGoResult = (period: string): WinGoHistory => {
  const num = Math.floor(Math.random() * 10);
  let color: 'Red'|'Green'|'Violet' = 'Red';
  if (num === 0 || num === 5) color = 'Violet';
  else if ([1,3,7,9].includes(num)) color = 'Green';
  return { period, number: num, bigSmall: num >= 5 ? 'Big' : 'Small', color };
};

export const startGlobalEngines = () => {
  // WinGo Engine
  if (winGoState.history.length === 0) for(let i=0; i<10; i++) winGoState.history.unshift(generateWinGoResult((winGoState.period - 10 + i).toString()));
  setInterval(() => {
    winGoState.timeLeft -= 1;
    if (winGoState.timeLeft <= 0) {
        winGoState.status = 'REVEALING';
        const res = generateWinGoResult(winGoState.period.toString());
        winGoState.lastResult = res;
        winGoState.history = [res, ...winGoState.history].slice(0, 50);
        winGoState.period += 1;
        winGoState.timeLeft = 30;
        setTimeout(() => { winGoState.status = 'BETTING'; winGoSubscribers.forEach(cb => cb({ ...winGoState })); }, 3000);
    }
    winGoSubscribers.forEach(cb => cb({ ...winGoState }));
  }, 1000);

  // Aviator Engine
  setInterval(() => {
      if (aviatorState.phase === 'WAITING') {
          aviatorState.timeLeft -= 1;
          if (aviatorState.timeLeft <= 0) {
              aviatorState.phase = 'FLYING';
              aviatorState.multiplier = 1.0;
              aviatorState.startTime = Date.now();
              aviatorState.crashPoint = 1 + Math.random() * 8;
          }
      } else if (aviatorState.phase === 'FLYING') {
          const elapsed = (Date.now() - (aviatorState.startTime || Date.now())) / 1000;
          aviatorState.multiplier = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.05);
          if (aviatorState.multiplier >= aviatorState.crashPoint) {
              aviatorState.phase = 'CRASHED';
              aviatorState.multiplier = aviatorState.crashPoint;
              aviatorState.history = [aviatorState.crashPoint, ...aviatorState.history].slice(0, 15);
              setTimeout(() => {
                  aviatorState.phase = 'WAITING';
                  aviatorState.timeLeft = 10;
                  aviatorState.multiplier = 1.0;
              }, 3000);
          }
      }
      aviatorSubscribers.forEach(cb => cb({ ...aviatorState }));
  }, 100);
};

export const subscribeToWinGo = (cb: (state: WinGoGameState) => void) => { winGoSubscribers.push(cb); cb(winGoState); return () => winGoSubscribers.splice(winGoSubscribers.indexOf(cb), 1); };
export const subscribeToAviator = (cb: (state: AviatorState) => void) => { aviatorSubscribers.push(cb); cb(aviatorState); return () => aviatorSubscribers.splice(aviatorSubscribers.indexOf(cb), 1); };

initSession();

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, subscribeToAviator } from '../services/mockFirebase';
import { GameResult, AviatorState } from '../types';

const Aviator: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [globalState, setGlobalState] = useState<AviatorState | null>(null);
  const [betAmount, setBetAmount] = useState(10);
  const activeBetRef = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef(0);
  const isMounted = useRef(true);
  const lastPhaseRef = useRef<string>('WAITING');

  useEffect(() => {
    isMounted.current = true;
    const unsub = subscribeToAviator((state) => {
        if (!isMounted.current) return;

        // Handle Auto-Loss on Crash
        if (state.phase === 'CRASHED' && lastPhaseRef.current === 'FLYING' && activeBetRef.current) {
            activeBetRef.current = false;
            setActiveBet(false);
            playSound('loss');
            onResult({ win: false, amount: betAmount, game: 'Aviator', resultDetails: [{label: 'Crashed', value: `${state.multiplier.toFixed(2)}x`}] });
        }

        if (state.phase === 'FLYING' && lastPhaseRef.current === 'WAITING') {
            playSound('plane');
        }

        lastPhaseRef.current = state.phase;
        setGlobalState(state);
    });

    return () => { 
        isMounted.current = false; 
        cancelAnimationFrame(animRef.current); 
        stopAllSounds(); 
        unsub(); 
    };
  }, [betAmount]);

  const handleAction = () => {
      if (!globalState) return;
      if (globalState.phase === 'WAITING') {
          if (betAmount > userBalance) return alert("Insufficient Balance");
          activeBetRef.current = true; setActiveBet(true);
          updateBalance(-betAmount, 'BET', 'Aviator Stake');
          playSound('click');
      } else if (globalState.phase === 'FLYING' && activeBetRef.current) {
          const win = betAmount * globalState.multiplier;
          updateBalance(win, 'WIN', 'Aviator Payout');
          activeBetRef.current = false; setActiveBet(false);
          playSound('win');
          onResult({ win: true, amount: win, game: 'Aviator', resultDetails: [{label: 'Cashout', value: `${globalState.multiplier.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, win, `Exited @ ${globalState.multiplier.toFixed(2)}x`);
      }
  };

  useEffect(() => {
      const draw = () => {
          if (!isMounted.current || !globalState) return;
          const cvs = canvasRef.current; if (!cvs) return;
          const ctx = cvs.getContext('2d'); if (!ctx) return;
          cvs.width = cvs.offsetWidth; cvs.height = 300;
          ctx.clearRect(0, 0, cvs.width, cvs.height);

          const mult = globalState.multiplier;
          const phase = globalState.phase;

          ctx.fillStyle = phase === 'CRASHED' ? '#ef4444' : '#ffffff';
          ctx.textAlign = 'center';
          ctx.font = 'black 60px monospace';
          ctx.fillText(`${mult.toFixed(2)}x`, cvs.width/2, cvs.height/2);

          if (phase === 'FLYING') {
              // Simple animated curve
              ctx.beginPath();
              ctx.strokeStyle = '#ef4444';
              ctx.lineWidth = 4;
              ctx.moveTo(0, cvs.height);
              ctx.quadraticCurveTo(cvs.width/2, cvs.height, cvs.width * 0.8, cvs.height * 0.2);
              ctx.stroke();
          }

          animRef.current = requestAnimationFrame(draw);
      };
      animRef.current = requestAnimationFrame(draw);
      return () => cancelAnimationFrame(animRef.current);
  }, [globalState]);

  if (!globalState) return <div className="min-h-screen bg-black flex items-center justify-center text-red-600 font-black italic tracking-widest animate-pulse uppercase">Syncing Arena...</div>;

  return (
    <div className="bg-black min-h-screen text-white flex flex-col font-sans select-none">
        <div className="p-4 flex justify-between items-center bg-[#111] border-b border-zinc-900 z-50">
            <div className="flex items-center gap-4">
                <button onClick={onBack} className="p-2 bg-zinc-900 rounded-xl"><ArrowLeft size={18}/></button>
                <span className="text-red-600 font-black italic text-2xl tracking-wider">AVIATOR</span>
            </div>
            <div className="flex gap-4 items-center">
                 <div className="flex items-center gap-2 bg-zinc-900 px-4 py-1.5 rounded-xl border border-white/5">
                     <Wallet size={16} className="text-green-500"/><span className="text-sm font-black font-mono">₹{userBalance.toFixed(2)}</span>
                 </div>
                 <button onClick={() => setMuted(toggleMute())}>{muted ? <VolumeX size={20} className="text-zinc-500"/> : <Volume2 size={20} className="text-zinc-300"/>}</button>
            </div>
        </div>

        <div className="bg-zinc-950 p-2 flex items-center gap-2 overflow-x-auto no-scrollbar border-b border-white/5">
            <History size={14} className="text-zinc-700 shrink-0 ml-2"/>
            <div className="flex gap-2">
                {(globalState.history || []).map((h, i) => (
                    <span key={i} className={`px-3 py-1 rounded-full text-[10px] font-black border border-white/5 whitespace-nowrap ${h >= 2 ? 'bg-purple-600 text-white' : 'bg-blue-900 text-blue-300'}`}>{h.toFixed(2)}x</span>
                ))}
            </div>
        </div>

        <div className="flex-1 relative flex flex-col items-center justify-center">
            <canvas ref={canvasRef} className="w-full max-w-md h-full opacity-80 pointer-events-none" />

            {globalState.phase === 'WAITING' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm z-20">
                    <div className="text-[10px] font-black uppercase tracking-[0.6em] text-zinc-500 mb-2">Next round in</div>
                    <div className="text-5xl font-black text-yellow-500 font-mono italic">{globalState.timeLeft}s</div>
                </div>
            )}
        </div>

        <div className="bg-[#0a0a0a] p-6 border-t-4 border-red-600 z-[60] shadow-[0_-20px_60px_rgba(0,0,0,1)]">
            <div className="flex gap-4 items-center">
                <div className="flex-1 bg-zinc-900 p-4 rounded-2xl border border-white/5 flex flex-col items-center gap-2 shadow-inner">
                    <div className="flex items-center gap-4">
                        <button onClick={()=>setBetAmount(Math.max(10, betAmount-10))} disabled={activeBet} className="w-8 h-8 rounded-full bg-zinc-800 flex items-center justify-center font-black">-</button>
                        <span className="text-xl font-black font-mono">₹{betAmount}</span>
                        <button onClick={()=>setBetAmount(betAmount+10)} disabled={activeBet} className="w-8 h-8 rounded-full bg-zinc-800 flex items-center justify-center font-black">+</button>
                    </div>
                </div>
                <button 
                  onClick={handleAction} 
                  disabled={globalState.phase === 'CRASHED' || (globalState.phase === 'FLYING' && !activeBet)}
                  className={`flex-[2] py-6 rounded-2xl font-black text-xl transition-all active:scale-95 border-b-[6px] shadow-2xl ${activeBet && globalState.phase === 'FLYING' ? 'bg-orange-500 border-orange-800' : activeBet ? 'bg-zinc-800 border-black opacity-50' : 'bg-green-600 border-green-800'}`}
                >
                    {activeBet && globalState.phase === 'FLYING' ? 'CASH OUT' : activeBet ? 'WAITING' : 'BET'}
                </button>
            </div>
        </div>
    </div>
  );
};
export default Aviator;

import React, { useState, useEffect } from 'react';
import NavBar from './components/NavBar';
import Home from './pages/Home';
import WinGo from './pages/WinGo';
import Aviator from './pages/Aviator';
import Mines from './pages/Mines';
import DogRoad from './pages/DogRoad';
import Vortex from './pages/Vortex';
import Profile from './pages/Profile';
import Referral from './pages/Referral';
import Promotion from './pages/Promotion';
import Deposit from './pages/Deposit';
import Withdraw from './pages/Withdraw';
import Wallet from './pages/Wallet';
import SafetyCenter from './pages/SafetyCenter';
import GameStatistics from './pages/GameStatistics';
import Auth from './pages/Auth';
import GameResultPopup from './components/GameResultPopup';
import { View, UserProfile, GameResult } from './types';
import { subscribeToBalance, startGlobalEngines, checkAuth, stopAllSounds } from './services/mockFirebase';

export default function App() {
  const [currentView, setCurrentView] = useState<View>('HOME');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [gameResult, setGameResult] = useState<GameResult | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => { 
      startGlobalEngines(); 
  }, []);

  useEffect(() => { 
      stopAllSounds(); 
  }, [currentView]);

  useEffect(() => {
    const unsubscribe = subscribeToBalance((updatedUser) => {
        setUser(updatedUser);
        setIsLoading(false);
    });
    const timer = setTimeout(() => { if (isLoading && !checkAuth()) setIsLoading(false); }, 3000);
    return () => { unsubscribe(); clearTimeout(timer); };
  }, []);

  if (isLoading) return <div className="min-h-screen bg-[#0f172a] flex items-center justify-center"><div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!user && currentView !== 'LOGIN' && currentView !== 'REGISTER') return <Auth />;

  const renderContent = () => {
    switch (currentView) {
      case 'HOME': return <Home setView={setCurrentView} />;
      case 'GAME_WINGO': return <WinGo onBack={() => setCurrentView('HOME')} userBalance={user!.balance} onResult={setGameResult} onDeposit={() => setCurrentView('DEPOSIT')} />;
      case 'GAME_AVIATOR': return <Aviator onBack={() => setCurrentView('HOME')} userBalance={user!.balance} onResult={setGameResult} />;
      case 'GAME_MINES': return <Mines onBack={() => setCurrentView('HOME')} userBalance={user!.balance} onResult={setGameResult} />;
      case 'GAME_DOG': return <DogRoad onBack={() => setCurrentView('HOME')} userBalance={user!.balance} onResult={setGameResult} />;
      case 'GAME_VORTEX': return <Vortex onBack={() => setCurrentView('HOME')} userBalance={user!.balance} onResult={setGameResult} />;
      case 'ACCOUNT': return <Profile user={user!} setView={setCurrentView} />;
      case 'REFERRAL': return <Referral />;
      case 'PROMOTION': return <Promotion />;
      case 'WALLET': return <Wallet setView={setCurrentView} userBalance={user!.balance} />;
      case 'DEPOSIT': return <Deposit onBack={() => setCurrentView('WALLET')} />;
      case 'WITHDRAW': return <Withdraw onBack={() => setCurrentView('WALLET')} userBalance={user!.balance} />;
      case 'SAFETY': return <SafetyCenter setView={setCurrentView} user={user!} />;
      case 'STATISTICS': return <GameStatistics setView={setCurrentView} />;
      default: return <Home setView={setCurrentView} />;
    }
  };

  const showNavBar = ['HOME', 'REFERRAL', 'PROMOTION', 'WALLET', 'ACCOUNT'].includes(currentView);

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f172a] shadow-2xl relative overflow-hidden font-sans border-x border-white/5">
      {renderContent()}
      <GameResultPopup result={gameResult} onClose={() => setGameResult(null)} />
      {showNavBar && <NavBar currentView={currentView} setView={setCurrentView} />}
    </div>
  );
}

