export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const users = getLocalUsers();
    const user = users[currentUser.uid];
    if (user) {
        user.balance += amount;

        // Smart Wager Reset
        if (user.balance <= 0) user.wagerRequired = 0;

        if (type === 'BET') {
            user.totalBet = (user.totalBet || 0) + Math.abs(amount);
            user.wagerRequired = Math.max(0, (user.wagerRequired || 0) - Math.abs(amount));
        }

        currentUser = user;
        saveLocalUsers(users);
        transactions.unshift({ id: 'TX_' + Date.now(), type, amount: Math.abs(amount), status: 'SUCCESS', date: new Date().toLocaleString(), desc, timestamp: Date.now() });
        saveLocalTransactions(user.uid, transactions);
        notifySubscribers();
    }
};

