        saveLocalUsers(users);
        transactions.unshift({ id: 'TX_G_' + Date.now(), type: 'GIFT', amount, status: 'SUCCESS', date: new Date().toLocaleString(), desc: `Gift: ${code}`, timestamp: Date.now() });
        saveLocalTransactions(user.uid, transactions);
        notifySubscribers();
        return amount;
    }
    return 0;
};

