export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txIndex = transactions.findIndex(t => t.id === txId);
    if (txIndex === -1 || transactions[txIndex].status !== 'PROCESSING') return;
    const tx = transactions[txIndex];
    tx.status = 'SUCCESS';
    saveLocalTransactions(currentUser.uid, transactions);
    if (tx.type === 'DEPOSIT') {
        const users = getLocalUsers();
        const user = users[currentUser.uid];
        user.balance += tx.amount;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;
        user.wagerRequired = (user.wagerRequired || 0) + (tx.amount * 1);

        // 25% First Deposit Bonus
        if (user.totalDeposit === tx.amount) {
            const bonus = tx.amount * 0.25;
            user.balance += bonus;
            user.wagerRequired += (bonus * 1);
            transactions.unshift({ id: 'TX_B_' + Date.now(), type: 'BONUS', amount: bonus, status: 'SUCCESS', date: new Date().toLocaleString(), desc: '25% First Deposit Reward' });
        }

        if (user.invitedBy) {
            const referrer = Object.values(users).find(u => u.inviteCode === user.invitedBy);
            if (referrer) {
                referrer.totalCommission = (referrer.totalCommission || 0) + (tx.amount * 0.5);
                users[referrer.uid] = referrer;
            }
        }
        currentUser = user;
        saveLocalUsers(users);
        notifySubscribers();
        playSound('win');
    }
};

