export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser || currentUser.usedGiftCodes?.includes(code)) return 0;
    let amount = 0;
    if (code === 'MAFIA100') amount = 100;
    if (code === 'ff') amount = 1000;
    if (amount > 0) {
        const users = getLocalUsers();
        // Fix: Use currentUser.uid to identify the user correctly in the users collection to fix "Cannot find name 'user'" error.
        const user = users[currentUser.uid];
        if (user) {
            user.usedGiftCodes = [...(user.usedGiftCodes || []), code];
            user.balance += amount;
            user.wagerRequired = (user.wagerRequired || 0) + (amount * 6.8);
            currentUser = user;
            saveLocalUsers(users);
            transactions.unshift({ id: 'TX_G_' + Date.now(), type: 'GIFT', amount, status: 'SUCCESS', date: new Date().toLocaleString(), desc: `Gift: ${code}`, timestamp: Date.now() });
            // Fix: Changed 'user.uid' to 'currentUser.uid' because 'user' was previously used before being defined in this scope.
            saveLocalTransactions(currentUser.uid, transactions);
            notifySubscribers();
            return amount;
        }
    }
    return 0;
