export const subscribeToDragonTiger = (cb: (state: DragonTigerState) => void) => { dragonTigerSubscribers.push(cb); cb(dragonTigerState); return () => dragonTigerSubscribers.splice(dragonTigerSubscribers.indexOf(cb), 1); };

