import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, subscribeToAviator } from '../services/mockFirebase';
import { GameResult, AviatorState } from '../types';

const Aviator: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [globalState, setGlobalState] = useState<AviatorState | null>(null);
  const [betAmount, setBetAmount] = useState(10);
  const activeBetRef = useRef(false);
  const [activeBet, setActiveBet] = useState(false);
  const [muted, setMuted] = useState(getMuteStatus());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef(0);
  const isMounted = useRef(true);
  const lastPhaseRef = useRef<string>('WAITING');

  // High fidelity visual states
  const flickerRef = useRef(0);

  useEffect(() => {
    isMounted.current = true;
    const unsub = subscribeToAviator((state) => {
        if (!isMounted.current) return;

        if (state.phase === 'CRASHED' && lastPhaseRef.current === 'FLYING') {
            playSound('plane_crash');
            if (activeBetRef.current) {
                activeBetRef.current = false;
                setActiveBet(false);
                onResult({ win: false, amount: betAmount, game: 'Aviator', resultDetails: [{label: 'Crashed', value: `${state.multiplier.toFixed(2)}x`}] });
            }
        }

        if (state.phase === 'FLYING' && lastPhaseRef.current === 'WAITING') {
            playSound('plane_engine');
        }

        lastPhaseRef.current = state.phase;
        setGlobalState(state);
    });

    return () => { 
        isMounted.current = false; 
        cancelAnimationFrame(animRef.current); 
        stopAllSounds(); 
        unsub(); 
    };
  }, [betAmount]);

  const handleAction = () => {
      if (!globalState) return;
      if (globalState.phase === 'WAITING') {
          if (betAmount > userBalance) return alert("Insufficient Balance");
          activeBetRef.current = true; setActiveBet(true);
          updateBalance(-betAmount, 'BET', 'Aviator Stake');
          playSound('click');
      } else if (globalState.phase === 'FLYING' && activeBetRef.current) {
          const win = betAmount * globalState.multiplier;
          updateBalance(win, 'WIN', 'Aviator Payout');
          activeBetRef.current = false; setActiveBet(false);
          playSound('win');
          onResult({ win: true, amount: win, game: 'Aviator', resultDetails: [{label: 'Cashout', value: `${globalState.multiplier.toFixed(2)}x`}] });
          addGameHistory('Aviator', betAmount, win, `Exited @ ${globalState.multiplier.toFixed(2)}x`);
      }
  };

  useEffect(() => {
      const draw = () => {
          if (!isMounted.current || !globalState) return;
          const cvs = canvasRef.current; if (!cvs) return;
          const ctx = cvs.getContext('2d'); if (!ctx) return;

          cvs.width = cvs.offsetWidth;
          cvs.height = cvs.offsetHeight;
          ctx.clearRect(0, 0, cvs.width, cvs.height);

          const phase = globalState.phase;
          const mult = globalState.multiplier;

          ctx.strokeStyle = 'rgba(255,255,255,0.03)';
          ctx.lineWidth = 1;
          for(let i=0; i<cvs.width; i+=40) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, cvs.height); ctx.stroke(); }
          for(let i=0; i<cvs.height; i+=40) { ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(cvs.width, i); ctx.stroke(); }

          if (phase === 'FLYING' || phase === 'CRASHED') {
              const padding = 60;
              const startX = padding;
              const startY = cvs.height - padding;
              const progress = Math.min(1, (mult - 1) / 8);
              const endX = startX + (cvs.width - padding * 2) * progress;
              const endY = startY - (cvs.height - padding * 2) * Math.pow(progress, 1.5);

              flickerRef.current += 0.2;
              const jitter = phase === 'FLYING' ? Math.sin(flickerRef.current) * 2 : 0;

              const gradient = ctx.createLinearGradient(0, endY, 0, startY);
              gradient.addColorStop(0, phase === 'CRASHED' ? 'rgba(153, 27, 27, 0.2)' : 'rgba(220, 38, 38, 0.3)');
              gradient.addColorStop(1, 'rgba(220, 38, 38, 0)');

              ctx.beginPath();
              ctx.moveTo(startX, startY);
              ctx.quadraticCurveTo(startX + (endX-startX)*0.5, startY, endX, endY + jitter);
              ctx.lineTo(endX, startY);
              ctx.closePath();
              ctx.fillStyle = gradient;
              ctx.fill();

              ctx.beginPath();
              ctx.lineWidth = 4;
              ctx.lineCap = 'round';
              ctx.strokeStyle = phase === 'CRASHED' ? '#7f1d1d' : '#ef4444';
              ctx.shadowBlur = phase === 'CRASHED' ? 0 : 15;
              ctx.shadowColor = '#ef4444';
              ctx.moveTo(startX, startY);
              ctx.quadraticCurveTo(startX + (endX-startX)*0.5, startY, endX, endY + jitter);
              ctx.stroke();
              ctx.shadowBlur = 0;

              if (phase === 'FLYING') {
                  ctx.fillStyle = '#ef4444';
                  ctx.beginPath();
                  ctx.arc(endX, endY + jitter, 6, 0, Math.PI * 2);
                  ctx.fill();
              }
          }

          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = '900 80px sans-serif';
          ctx.fillStyle = phase === 'CRASHED' ? '#ef4444' : '#ffffff';
          ctx.fillText(`${mult.toFixed(2)}x`, cvs.width/2, cvs.height/2);

          animRef.current = requestAnimationFrame(draw);
      };
      animRef.current = requestAnimationFrame(draw);
      return () => cancelAnimationFrame(animRef.current);
  }, [globalState]);

  if (!globalState) return <div className="min-h-screen bg-black flex items-center justify-center text-red-600 font-black italic tracking-widest animate-pulse uppercase">Syncing Arena...</div>;

  return (
    <div className="bg-black min-h-screen text-white flex flex-col font-sans select-none overflow-hidden">
        <div className="p-4 flex justify-between items-center bg-[#111] border-b border-zinc-900 z-50">
            <div className="flex items-center gap-4">
                <button onClick={onBack} className="p-2 bg-zinc-900 rounded-xl active:scale-90"><ArrowLeft size={18}/></button>
                <span className="text-red-600 font-black italic text-2xl tracking-wider">AVIATOR</span>
            </div>
            <div className="flex gap-4 items-center">
                 <div className="flex items-center gap-2 bg-zinc-900 px-4 py-1.5 rounded-xl border border-white/5 shadow-inner">
                     <Wallet size={16} className="text-green-500"/><span className="text-sm font-black font-mono">₹{userBalance.toFixed(2)}</span>
                 </div>
                 <button onClick={() => setMuted(toggleMute())} className="active:scale-90 transition-transform">{muted ? <VolumeX size={20} className="text-zinc-500"/> : <Volume2 size={20} className="text-zinc-300"/>}</button>
            </div>
        </div>

        <div className="bg-zinc-950 p-2 flex items-center gap-2 overflow-x-auto no-scrollbar border-b border-white/5">
            <History size={14} className="text-zinc-700 shrink-0 ml-2"/>
            <div className="flex gap-2">
                {(globalState.history || []).map((h, i) => (
                    <span key={i} className={`px-3 py-1 rounded-full text-[10px] font-black border border-white/5 whitespace-nowrap shadow-md ${h >= 2 ? 'bg-purple-600 text-white' : 'bg-blue-900 text-blue-300'}`}>{h.toFixed(2)}x</span>
                ))}
            </div>
        </div>

        <div className="flex-1 relative flex flex-col items-center justify-center bg-[#050505]">
            <canvas ref={canvasRef} className="w-full h-full pointer-events-none" />

            {globalState.phase === 'WAITING' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm z-20 animate-in fade-in duration-500">
                    <div className="text-[10px] font-black uppercase tracking-[0.6em] text-zinc-500 mb-2">Next Flight Departure</div>
                    <div className="text-6xl font-black text-yellow-500 font-mono italic drop-shadow-[0_0_20px_rgba(234,179,8,0.3)]">{globalState.timeLeft}s</div>
                </div>
            )}
        </div>

        <div className="bg-[#0a0a0a] p-6 border-t-4 border-red-600 z-[60] shadow-[0_-20px_60px_rgba(0,0,0,1)]">
            <div className="flex gap-4 items-center">
                <div className="flex-1 bg-zinc-900 p-4 rounded-2xl border border-white/5 flex flex-col items-center gap-2 shadow-inner">
                    <div className="flex items-center gap-4">
                        <button onClick={()=>setBetAmount(Math.max(10, betAmount-10))} disabled={activeBet} className="w-8 h-8 rounded-full bg-zinc-800 flex items-center justify-center font-black active:scale-90">-</button>
                        <span className="text-xl font-black font-mono">₹{betAmount}</span>
                        <button onClick={()=>setBetAmount(betAmount+10)} disabled={activeBet} className="w-8 h-8 rounded-full bg-zinc-800 flex items-center justify-center font-black active:scale-90">+</button>
                    </div>
                </div>
                <button 
                  onClick={handleAction} 
                  disabled={globalState.phase === 'CRASHED' || (globalState.phase === 'FLYING' && !activeBet)}
                  className={`flex-[2] py-6 rounded-2xl font-black text-xl transition-all active:scale-95 border-b-[6px] shadow-2xl ${activeBet && globalState.phase === 'FLYING' ? 'bg-orange-500 border-orange-800' : activeBet ? 'bg-zinc-800 border-black opacity-50' : 'bg-green-600 border-green-800'}`}
                >
                    {activeBet && globalState.phase === 'FLYING' ? 'CASH OUT' : activeBet ? 'WAITING' : 'BET'}
                </button>
            </div>
        </div>
    </div>
  );
};
export default Aviator;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Volume2, HelpCircle, Wallet, VolumeX, X } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, getGameHistory, shouldForceLoss } from '../services/mockFirebase';
import { GameResult, GameHistoryItem } from '../types';

const ASSETS = {
    GEM: "https://cdn-icons-png.flaticon.com/512/2276/2276931.png",
    BOMB: "https://cdn-icons-png.flaticon.com/512/112/112683.png",
};

interface MinesProps {
    onBack: () => void;
    userBalance: number;
    onResult: (result: GameResult) => void;
}

const Mines: React.FC<MinesProps> = ({ onBack, userBalance, onResult }) => {
    const [grid, setGrid] = useState<number[]>(Array(25).fill(0));
    const [revealed, setRevealed] = useState<boolean[]>(Array(25).fill(false));
    const [betAmount, setBetAmount] = useState(10);
    const [isPlaying, setIsPlaying] = useState(false);
    const [minesCount, setMinesCount] = useState(3);
    const [gemsFound, setGemsFound] = useState(0);
    const [gameOver, setGameOver] = useState(false);
    const [muted, setMuted] = useState(getMuteStatus());
    const [showRules, setShowRules] = useState(false);

    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        const unsubHistory = getGameHistory('Mines', (data) => {});
        return () => { isMounted.current = false; unsubHistory(); stopAllSounds(); };
    }, []);

    const startGame = () => {
        if (betAmount > userBalance) { alert("Insufficient Balance!"); return; }
        playSound('click');
        updateBalance(-betAmount, 'BET', 'Mines Game');
        setIsPlaying(true); setGameOver(false); setGemsFound(0); setRevealed(Array(25).fill(false));
        const newGrid = Array(25).fill(1);
        let minesPlaced = 0;
        while(minesPlaced < minesCount) {
            const idx = Math.floor(Math.random() * 25);
            if (newGrid[idx] !== 2) { newGrid[idx] = 2; minesPlaced++; }
        }
        setGrid(newGrid);
    };

    const handleTileClick = (index: number) => {
        if (!isPlaying || revealed[index] || gameOver) return;

        const newRevealed = [...revealed];
        newRevealed[index] = true;
        setRevealed(newRevealed);

        const forced = gemsFound >= 1 && shouldForceLoss(betAmount, userBalance);

        if (grid[index] === 2 || forced) {
            playSound('mine_bomb');
            setGameOver(true); setIsPlaying(false);
            setRevealed(Array(25).fill(true));
            addGameHistory('Mines', betAmount, 0, `Hit Mine`);
            onResult({ win: false, amount: betAmount, game: 'Mines', resultDetails: [{ label: 'Result', value: 'Boom!' }] });
        } else {
            playSound('mine_reveal');
            setGemsFound(prev => prev + 1);
        }
    };

    const cashOut = () => {
        if (!isPlaying || gameOver) return;
        const multiplier = 1 + (gemsFound * 0.2) + (minesCount * 0.05);
        const winAmount = betAmount * multiplier;
        updateBalance(winAmount, 'WIN', 'Mines Win');
        addGameHistory('Mines', betAmount, winAmount, `Cashed Out @ ${multiplier.toFixed(2)}x`);
        setIsPlaying(false); setGameOver(true);
        playSound('win');
        setRevealed(Array(25).fill(true)); 
        onResult({ win: true, amount: winAmount, game: 'Mines', resultDetails: [{ label: 'Multiplier', value: `${multiplier.toFixed(2)}x` }] });
    };

    return (
        <div className="bg-[#0f172a] min-h-screen flex flex-col pb-safe font-sans">
            <div className="bg-[#1e293b] p-4 flex items-center justify-between border-b border-slate-700 shadow-lg">
                <div className="flex items-center gap-4">
                    <button onClick={onBack}><ArrowLeft className="text-white" /></button>
                    <h1 className="text-lg font-bold gold-text uppercase">Mines</h1>
                </div>
                <div className="flex gap-3 text-slate-400 items-center">
                    <div className="flex items-center gap-2 bg-[#0f172a] px-3 py-1 rounded-full border border-slate-700">
                         <Wallet size={14} className="text-green-500"/>
                         <span className="text-sm font-bold text-white">₹{userBalance.toFixed(2)}</span>
                    </div>
                    <button onClick={() => setMuted(toggleMute())}>{muted ? <VolumeX size={20} /> : <Volume2 size={20}/>}</button>
                </div>
            </div>

            <div className="flex-1 p-6 flex flex-col items-center justify-center">
                <div className="grid grid-cols-5 gap-2 mb-8">
                    {grid.map((val, idx) => (
                        <button
                            key={idx}
                            disabled={!isPlaying || (revealed[idx] && !gameOver)}
                            onClick={() => handleTileClick(idx)}
                            className={`w-14 h-14 rounded-lg flex items-center justify-center transition-all ${!revealed[idx] ? 'bg-[#334155] shadow-[0_4px_0_#1e293b]' : 'bg-[#0f172a] inset-shadow scale-95'}`}
                        >
                            {revealed[idx] && (
                                <img src={val === 2 ? ASSETS.BOMB : ASSETS.GEM} className="w-10 h-10 animate-in zoom-in" />
                            )}
                        </button>
                    ))}
                </div>

                <div className="w-full max-w-md bg-[#1e293b] rounded-xl p-4 space-y-4 shadow-xl border border-slate-700">
                    {!isPlaying ? (
                        <>
                            <div className="flex gap-2">
                                {[1, 3, 5, 10].map(num => (
                                    <button key={num} onClick={() => setMinesCount(num)} className={`flex-1 py-3 rounded-xl font-bold ${minesCount === num ? 'bg-blue-600 text-white' : 'bg-[#0f172a] text-slate-400 border border-slate-700'}`}>{num} Mines</button>
                                ))}
                            </div>
                            <button onClick={startGame} className="w-full bg-blue-600 py-4 rounded-xl font-bold text-white shadow-lg active:scale-95 transition-all">START HUNT</button>
                        </>
                    ) : (
                        <button onClick={cashOut} disabled={gemsFound === 0} className={`w-full py-4 rounded-xl font-bold shadow-lg text-white ${gemsFound > 0 ? 'bg-green-600 shadow-green-900/30' : 'bg-slate-700 opacity-50'}`}>
                            {gemsFound === 0 ? 'Pick a Tile' : `COLLECT ₹${(betAmount * (1 + (gemsFound * 0.2) + (minesCount * 0.05))).toFixed(2)}`}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};
export default Mines;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, History, Loader2, X, RotateCcw, Trash2, HelpCircle, Trophy } from 'lucide-react';
import { updateBalance, subscribeToDragonTiger, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { DragonTigerState, GameResult } from '../types';

interface Props {
    onBack: () => void;
    userBalance: number;
    username: string;
    onResult: (r: GameResult) => void;
}

interface UserBet {
    id: string;
    target: 'D' | 'T' | 'Tie';
    amount: number;
}

const DragonTiger: React.FC<Props> = ({ onBack, userBalance, username, onResult }) => {
    const [gameState, setGameState] = useState<DragonTigerState | null>(null);
    const [selectedChip, setSelectedChip] = useState(10);
    const [myBets, setMyBets] = useState<UserBet[]>([]);
    const [showRules, setShowRules] = useState(false);
    const [showDragon, setShowDragon] = useState(false);
    const [showTiger, setShowTiger] = useState(false);
    const [confirmDrawerOpen, setConfirmDrawerOpen] = useState(false);
    const [confirmTarget, setConfirmTarget] = useState<'D' | 'T' | 'Tie' | null>(null);
    const [confirmAmount, setConfirmAmount] = useState(10);

    const isMounted = useRef(true);
    const resultHandledRef = useRef<string | null>(null);

    useEffect(() => {
        isMounted.current = true;
        const unsub = subscribeToDragonTiger((state) => {
            if (!isMounted.current) return;
            setGameState(state);
            if (state.status === 'BETTING') {
                setShowDragon(false); setShowTiger(false); resultHandledRef.current = null;
                if (state.timeLeft <= 5 && state.timeLeft > 0) playSound('wingo_tick');
            }
            if (state.status === 'RESULT' && resultHandledRef.current !== state.period) {
                resultHandledRef.current = state.period;
                handleRevealingSequence(state);
            }
        });
        return () => { isMounted.current = false; unsub(); stopAllSounds(); };
    }, []);

    const handleRevealingSequence = async (state: DragonTigerState) => {
        await new Promise(r => setTimeout(r, 800));
        if (!isMounted.current) return;
        setShowDragon(true);
        playSound('dt_card');
        await new Promise(r => setTimeout(r, 1200));
        if (!isMounted.current) return;
        setShowTiger(true);
        playSound('dt_card');
        await new Promise(r => setTimeout(r, 1000));
        if (isMounted.current && myBets.length > 0) {
            playSound('dt_draw');
            processMyResult(state);
        }
    };

    const processMyResult = (state: DragonTigerState) => {
        const dVal = state.dragonCard!;
        const tVal = state.tigerCard!;
        const winner = dVal > tVal ? 'D' : tVal > dVal ? 'T' : 'Tie';
        let totalWin = 0; let totalBet = 0;
        myBets.forEach(bet => {
            totalBet += bet.amount;
            if (bet.target === winner) totalWin += bet.amount * (winner === 'Tie' ? 9 : 2);
        });
        if (totalWin > 0) { updateBalance(totalWin, 'WIN', 'DT Win'); playSound('win'); onResult({ win: true, amount: totalWin, game: 'Dragon Tiger' }); }
        else { playSound('loss'); onResult({ win: false, amount: totalBet, game: 'Dragon Tiger' }); }
        addGameHistory('Dragon Tiger', totalBet, totalWin, `Result: ${winner}`);
        setMyBets([]);
    };

    const handleTargetClick = (target: 'D' | 'T' | 'Tie') => {
        if (gameState?.status !== 'BETTING') return;
        setConfirmTarget(target); setConfirmAmount(selectedChip); setConfirmDrawerOpen(true);
        playSound('click');
    };

    const confirmBetAction = () => {
        if (confirmAmount > userBalance) return alert("Low Balance");
        updateBalance(-confirmAmount, 'BET', `DT: ${confirmTarget}`);
        setMyBets(prev => [...prev, { id: Date.now().toString(), target: confirmTarget!, amount: confirmAmount }]);
        setConfirmDrawerOpen(false);
        playSound('click');
    };

    if (!gameState) return <div className="min-h-screen bg-black flex items-center justify-center font-black gold-text animate-pulse">Entering Arena...</div>;

    return (
        <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white select-none overflow-hidden relative">
            <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-yellow-500/20 shadow-2xl relative z-50">
                <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
                <div className="bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 text-yellow-500 font-mono">₹{userBalance.toFixed(2)}</div>
            </div>

            <div className="flex-1 bg-gradient-to-b from-[#064e3b] via-[#0a0f1d] to-[#0a0f1d] flex flex-col items-center justify-center gap-12">
                <div className={`w-24 h-24 rounded-full border-4 flex flex-col items-center justify-center font-black ${gameState.status === 'BETTING' ? 'border-green-500 text-green-500' : 'border-red-600 text-red-600 animate-pulse'}`}>
                    <span className="text-4xl italic">{gameState.timeLeft}</span>
                </div>

                <div className="flex justify-center items-center gap-8 w-full px-4">
                    <div className={`w-32 h-48 rounded-2xl border-4 transition-all duration-700 ${showDragon ? 'border-red-500 bg-white' : 'border-white/10 bg-slate-900'} flex items-center justify-center shadow-2xl overflow-hidden relative`}>
                        {showDragon ? <span className="text-7xl font-black text-red-600">{gameState.dragonCard}</span> : <span className="text-4xl opacity-10 font-black">D</span>}
                    </div>
                    <span className="text-4xl font-black italic gold-text animate-pulse">VS</span>
                    <div className={`w-32 h-48 rounded-2xl border-4 transition-all duration-700 ${showTiger ? 'border-orange-500 bg-white' : 'border-white/10 bg-slate-900'} flex items-center justify-center shadow-2xl overflow-hidden relative`}>
                        {showTiger ? <span className="text-7xl font-black text-slate-900">{gameState.tigerCard}</span> : <span className="text-4xl opacity-10 font-black">T</span>}
                    </div>
                </div>
            </div>

            <div className="bg-[#111] p-6 border-t border-white/10 shadow-2xl z-50">
                <div className="grid grid-cols-3 gap-4 mb-8">
                    <button onClick={() => handleTargetClick('D')} disabled={gameState.status !== 'BETTING'} className="h-32 rounded-3xl bg-red-950/40 border-red-700 border-b-8 flex flex-col items-center justify-center font-black italic text-xl text-red-500 disabled:opacity-40">DRAGON</button>
                    <button onClick={() => handleTargetClick('Tie')} disabled={gameState.status !== 'BETTING'} className="h-32 rounded-3xl bg-green-950/40 border-green-700 border-b-8 flex flex-col items-center justify-center font-black italic text-xl text-green-500 disabled:opacity-40">TIE</button>
                    <button onClick={() => handleTargetClick('T')} disabled={gameState.status !== 'BETTING'} className="h-32 rounded-3xl bg-orange-950/40 border-orange-700 border-b-8 flex flex-col items-center justify-center font-black italic text-xl text-orange-500 disabled:opacity-40">TIGER</button>
                </div>
                <button onClick={confirmBetAction} disabled={!confirmTarget} className="w-full py-6 bg-yellow-500 text-black rounded-[2rem] font-black uppercase text-xl shadow-xl border-t-2 border-white/20 active:scale-95 disabled:opacity-50">CONFIRM STAKE</button>
            </div>
        </div>
    );
};
export default DragonTiger;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, getMuteStatus, toggleMute } from '../services/mockFirebase';
import { GameResult } from '../types';

interface Props {
  onBack: () => void;
  userBalance: number;
  onResult: (r: GameResult) => void;
}

const POCKETS = [
    { mult: 50, color: '#facc15' }, { mult: 0, color: '#1e293b' }, { mult: 2, color: '#3b82f6' }, 
    { mult: 0, color: '#1e293b' }, { mult: 5, color: '#10b981' }, { mult: 0, color: '#1e293b' }, 
    { mult: 10, color: '#ef4444' }, { mult: 0, color: '#1e293b' }, { mult: 2, color: '#3b82f6' }, 
    { mult: 0, color: '#1e293b' }, { mult: 5, color: '#10b981' }, { mult: 0, color: '#1e293b' }
];

const Vortex: React.FC<Props> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [gameState, setGameState] = useState<'IDLE' | 'SPINNING' | 'LOCKED'>('IDLE');
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<string[]>(['10X', '0X', '5X', '2X', '0X']);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const isMounted = useRef(true);

  // Advanced Physics State
  const ringRotation = useRef(0);
  const ballAngle = useRef(0);
  const ballRadius = useRef(165); 
  const ballAngularVel = useRef(0);
  const spiralPhase = useRef(0); // 0: outer orbit, 1: spiraling, 2: drop

  useEffect(() => {
    isMounted.current = true;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
        updatePhysics();
        draw(ctx);
        requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => {
      isMounted.current = false;
      cancelAnimationFrame(requestRef.current);
      stopAllSounds();
    };
  }, [gameState]);

  const updatePhysics = () => {
    // Ring always spins slowly
    ringRotation.current += 0.015;

    if (gameState === 'SPINNING') {
        ballAngle.current += ballAngularVel.current;

        if (spiralPhase.current === 0) {
            // Ball is losing speed due to rim friction
            ballAngularVel.current *= 0.993; 
            if (ballAngularVel.current < 0.08) spiralPhase.current = 1;
        } else if (spiralPhase.current === 1) {
            // Ball starts spiraling inward towards pockets
            ballRadius.current -= 1.8;
            ballAngularVel.current *= 0.985;
            if (ballRadius.current <= 85) finalizeVortex();
        }
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const w = 400, h = 400;
    ctx.clearRect(0, 0, w, h);
    const cx = w/2, cy = h/2;

    // Draw Bowl Outer Edge (Depth Effect)
    const grad = ctx.createRadialGradient(cx, cy, 50, cx, cy, 180);
    grad.addColorStop(0, '#020617');
    grad.addColorStop(0.6, '#0f172a');
    grad.addColorStop(1, '#1e293b');
    ctx.beginPath();
    ctx.arc(cx, cy, 180, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 4;
    ctx.stroke();

    // Draw Rotating Center Pocket Ring
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(ringRotation.current);
    POCKETS.forEach((p, i) => {
        const angle = (Math.PI * 2 / POCKETS.length) * i;
        ctx.save();
        ctx.rotate(angle);

        // Pocket box
        ctx.beginPath();
        ctx.moveTo(45, -18); ctx.lineTo(85, -25); ctx.lineTo(85, 25); ctx.lineTo(45, 18);
        ctx.closePath();
        ctx.fillStyle = p.color;
        ctx.fill();
        ctx.strokeStyle = '#ffffff20';
        ctx.lineWidth = 1;
        ctx.stroke();

        // Label
        ctx.fillStyle = p.mult > 0 ? '#fff' : '#475569';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(p.mult === 50 ? 'JP' : p.mult + 'X', 65, 5);
        ctx.restore();
    });
    ctx.restore();

    // Center Cap
    ctx.beginPath();
    ctx.arc(cx, cy, 45, 0, Math.PI * 2);
    ctx.fillStyle = '#1e293b';
    ctx.fill();
    ctx.strokeStyle = '#fbbf2440';
    ctx.stroke();

    // Draw Ball (Physics based)
    if (gameState === 'SPINNING') {
        const bx = cx + Math.cos(ballAngle.current) * ballRadius.current;
        const by = cy + Math.sin(ballAngle.current) * ballRadius.current;

        // Ball Shadow
        ctx.beginPath();
        ctx.arc(bx + 4, by + 4, 7, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.fill();

        // Ball Body
        ctx.beginPath();
        ctx.arc(bx, by, 7, 0, Math.PI * 2);
        const ballGrad = ctx.createRadialGradient(bx-2, by-2, 1, bx, by, 7);
        ballGrad.addColorStop(0, '#ffffff');
        ballGrad.addColorStop(1, '#cbd5e1');
        ctx.fillStyle = ballGrad;
        ctx.shadowBlur = 10; ctx.shadowColor = '#fff';
        ctx.fill();
        ctx.shadowBlur = 0;
    }
  };

  const launch = () => {
    if (gameState !== 'IDLE' || userBalance < betAmount) return;
    setGameState('SPINNING');
    updateBalance(-betAmount, 'BET', 'Vortex Launch');
    // FIX: Changed invalid sound name 'spin' to 'wheel_spin'
    playSound('click'); playSound('wheel_spin');

    ballAngle.current = Math.random() * Math.PI * 2;
    ballRadius.current = 168;
    ballAngularVel.current = 0.28 + Math.random() * 0.08;
    spiralPhase.current = 0;
  };

  const finalizeVortex = () => {
    if (gameState !== 'SPINNING') return;
    setGameState('LOCKED');

    // Pocket match logic: find which pocket is under the ball's final angle
    const relativeAngle = (ballAngle.current - ringRotation.current) % (Math.PI * 2);
    const normalized = relativeAngle < 0 ? relativeAngle + Math.PI * 2 : relativeAngle;
    const idx = Math.floor( (normalized / (Math.PI * 2)) * POCKETS.length ) % POCKETS.length;

    const result = POCKETS[idx];
    const winAmt = betAmount * result.mult;

    setTimeout(() => {
        if (!isMounted.current) return;
        if (winAmt > 0) { updateBalance(winAmt, 'WIN', 'Vortex Win'); playSound('win'); } else { playSound('loss'); }
        setHistory(prev => [result.mult + 'X', ...prev].slice(0, 10));
        onResult({ 
            win: winAmt > 0, 
            amount: winAmt > 0 ? winAmt : betAmount, 
            game: 'Vortex',
            resultDetails: [{ label: 'Pocket', value: result.mult + 'X', color: result.mult > 0 ? 'text-yellow-400' : 'text-slate-500' }]
        });
        setGameState('IDLE');
    }, 1200);
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white select-none overflow-hidden relative">
      <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-white/5 z-50 shadow-2xl">
