    const sum = d1 + d2;
    setDice([d1, d2]);
    setIsRolling(false);

    const outcome = sum >= 7 ? 'BIG' : 'SMALL';
    const isWin = target === outcome;
    const winAmt = isWin ? bet * 1.95 : 0;

    if (isWin) {
        updateBalance(winAmt, 'WIN', 'Dice Win');
        playSound('win');
        triggerFloating(`+₹${winAmt.toFixed(2)}`, 'text-green-400');
    } else {
        playSound('loss');
        triggerFloating(`-₹${bet.toFixed(2)}`, 'text-red-500');
    }

    setHistory(prev => [sum, ...prev].slice(0, 10));
    onResult({ 
        win: isWin, 
        amount: isWin ? winAmt : bet, 
        game: 'Dice Duel', 
        resultDetails: [{label: 'Sum', value: sum.toString(), color: isWin ? 'text-green-400' : 'text-red-400'}] 
    });
    addGameHistory('Dice Duel', bet, winAmt, `Bet ${target} | Sum ${sum}`);
    setTarget(null);
  };

  return (
    <div className="bg-[#0f172a] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
        {floating && (
            <div key={floating.id} className={`fixed top-1/2 left-1/2 -translate-x-1/2 z-[100] font-black text-5xl italic pointer-events-none animate-float-up ${floating.color}`} style={{ textShadow: '0 0 20px rgba(0,0,0,0.5)' }}>
                {floating.text}
            </div>
        )}

        <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5 shadow-2xl relative z-50">
            <div className="flex items-center gap-3">
                <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl active:scale-90 transition-all"><ArrowLeft size={20}/></button>
                <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
                    <Wallet size={14} className="text-yellow-500" />
                    <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
                </div>
            </div>
            <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">DICE DUEL</h1>
            <button onClick={() => setShowRules(true)} className="p-2 bg-slate-800 rounded-xl active:scale-90 transition-all"><HelpCircle size={20}/></button>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center p-6 relative">
            <div className="flex gap-6 mb-16 relative">
                {dice.map((v, i) => (
                    <div key={i} className={`w-28 h-28 bg-white rounded-[2rem] flex items-center justify-center text-6xl text-slate-900 shadow-[0_20px_50px_rgba(0,0,0,0.5)] border-b-[10px] border-slate-300 transition-all duration-300 ${isRolling ? 'animate-bounce rotate-12 scale-90' : 'rotate-0'}`}>
                        {v}
                    </div>
                ))}
            </div>

            <div className="grid grid-cols-2 gap-6 w-full max-w-sm mb-8">
                <button 
                  onClick={() => !isRolling && setTarget('SMALL')} 
                  className={`py-8 rounded-3xl font-black text-2xl border-b-[8px] transition-all active:scale-95 ${target === 'SMALL' ? 'bg-blue-600 border-blue-800 scale-105 shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-slate-800 border-slate-900 opacity-60'}`}
                >
                    SMALL
                    <p className="text-[10px] font-bold opacity-60 mt-1 uppercase tracking-widest">(Sum 2-6)</p>
                </button>
                <button 
                  onClick={() => !isRolling && setTarget('BIG')} 
                  className={`py-8 rounded-3xl font-black text-2xl border-b-[8px] transition-all active:scale-95 ${target === 'BIG' ? 'bg-orange-600 border-orange-800 scale-105 shadow-[0_0_30px_rgba(234,88,12,0.4)]' : 'bg-slate-800 border-slate-900 opacity-60'}`}
                >
                    BIG
                    <p className="text-[10px] font-bold opacity-60 mt-1 uppercase tracking-widest">(Sum 7-12)</p>
                </button>
            </div>

            <div className="flex gap-2 overflow-x-auto no-scrollbar py-4 w-full justify-center">
                {history.map((h, i) => (
                    <span key={i} className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-black border border-white/10 ${h >= 7 ? 'bg-orange-500' : 'bg-blue-500'}`}>{h}</span>
                ))}
            </div>
        </div>

        <div className="bg-[#111] p-6 pb-12 border-t border-white/5 shadow-2xl">
            <div className="flex gap-2 mb-6 overflow-x-auto no-scrollbar pb-2">
                {[10, 50, 100, 500, 1000, 5000].map(a => (
                    <button key={a} onClick={() => !isRolling && setBet(a)} className={`flex-shrink-0 px-6 py-3 rounded-2xl font-black text-sm border transition-all ${bet === a ? 'bg-yellow-500 text-black border-white shadow-lg' : 'bg-zinc-900 text-zinc-500 border-white/5'}`}>₹{a >= 1000 ? (a/1000)+'K' : a}</button>
                ))}
            </div>
            <button 
                onClick={roll} 
                disabled={!target || isRolling} 
                className={`w-full py-6 rounded-[2.5rem] font-black text-2xl uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all border-t-2 border-white/10 ${!target || isRolling ? 'bg-zinc-800 text-zinc-600' : 'bg-gradient-to-r from-red-600 to-orange-600 text-white'}`}
            >
                {isRolling ? 'ROLLING...' : 'ROLL DICE'}
            </button>
        </div>

        {showRules && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
                <div className="bg-slate-900 border border-yellow-500/30 w-full max-w-sm p-8 rounded-[2.5rem] shadow-2xl">
                     <div className="flex justify-between items-center mb-8">
                         <h2 className="text-2xl font-black italic gold-text uppercase">DICE RULES</h2>
                         <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X/></button>
                     </div>
                     <div className="space-y-4 text-sm text-slate-300 leading-relaxed font-medium">
                         <p>1. Choose either <span className="text-blue-500 font-bold">SMALL</span> or <span className="text-orange-500 font-bold">BIG</span>.</p>
                         <p>2. Two dice are rolled and their sum is calculated.</p>
                         <p>3. <span className="text-blue-500 font-bold">SMALL</span> wins if the sum is between 2 and 6.</p>
                         <p>4. <span className="text-orange-500 font-bold">BIG</span> wins if the sum is between 7 and 12.</p>
                         <p>5. A successful prediction pays <span className="text-green-500 font-bold">1.95x</span> your stake.</p>
                     </div>
                </div>
            </div>
        )}

        <style>{`
            .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
            @keyframes float-up {
                0% { transform: translate(-50%, 0); opacity: 0; scale: 0.5; }
                15% { opacity: 1; scale: 1.2; }
                85% { opacity: 1; scale: 1.2; }
                100% { transform: translate(-50%, -150px); opacity: 0; scale: 1.5; }
            }
            .animate-float-up { animation: float-up 3s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
        `}</style>
    </div>
  );
};

export default DiceDuel;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, HelpCircle, X, ChevronUp, Lock, Sparkles } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const LEVELS = [1.5, 3.2, 6.8, 14.5, 32.0, 75.0, 200.0, 500.0];

const Tower: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [currentLv, setCurrentLv] = useState(-1);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'REVEALING' | 'LOST' | 'WON'>('IDLE');
  const [showRules, setShowRules] = useState(false);
  const [revealedIdx, setRevealedIdx] = useState<number | null>(null);

  const start = () => {
    if (userBalance < bet) return;
    updateBalance(-bet, 'BET', 'Tower of Fortune');
    playSound('click');
    setGameState('PLAYING');
    setCurrentLv(-1);
    setRevealedIdx(null);
  };

  const pick = async (idx: number) => {
    if (gameState !== 'PLAYING') return;
    setGameState('REVEALING');
    setRevealedIdx(idx);
    // FIX: Changed invalid sound name 'tick' to 'tower_step'
    playSound('tower_step');

    await new Promise(r => setTimeout(r, 800));

    const isWin = Math.random() > 0.35; // 65% win chance per floor

    if (isWin) {
        playSound('win');
        setCurrentLv(prev => prev + 1);
        setGameState('PLAYING');
        setRevealedIdx(null);
        if (currentLv + 1 === LEVELS.length - 1) cashout(true);
    } else {
        playSound('loss');
        setGameState('LOST');
        addGameHistory('Tower', bet, 0, `Floor ${currentLv + 1} Collapse`);
        setTimeout(() => {
            setGameState('IDLE');
            setCurrentLv(-1);
        }, 2000);
    }
  };

  const cashout = (auto = false) => {
    if (currentLv === -1) return;
    const winAmt = bet * LEVELS[currentLv];
    updateBalance(winAmt, 'WIN', 'Tower Cashout');
    playSound('win');
    onResult({ win: true, amount: winAmt, game: 'Tower of Fortune', resultDetails: [{label: 'Floors', value: `${currentLv + 1}`}]});
    setGameState('IDLE');
    setCurrentLv(-1);
  };

  return (
    <div className="bg-[#0c0a1a] min-h-screen flex flex-col font-sans text-white overflow-hidden relative">
      <div className="p-4 flex justify-between items-center bg-black/40 border-b border-white/5 relative z-50">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black gold-text italic tracking-widest uppercase">TOWER ELITE</h1>
        <button onClick={() => setShowRules(true)} className="p-2 bg-indigo-500/20 text-indigo-400 rounded-xl"><HelpCircle size={20}/></button>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar p-6 flex flex-col-reverse gap-4 bg-[url('https://img.freepik.com/free-vector/dark-blue-night-sky-background-with-clouds-stars_1017-26154.jpg')] bg-cover">
          {LEVELS.map((m, i) => (
              <div key={i} className={`h-16 w-full rounded-2xl border-2 flex items-center justify-between px-6 transition-all duration-500 ${currentLv === i ? 'bg-indigo-600 border-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.4)] scale-105' : i === currentLv + 1 ? 'bg-slate-800/80 border-slate-600' : 'bg-black/40 border-white/5 opacity-40'}`}>
                  <span className="font-black text-lg italic">{m}x</span>
                  {i === currentLv + 1 ? (
                      <div className="flex gap-2">
                          {[0,1,2].map(btn => (
                              <button key={btn} onClick={() => pick(btn)} className={`w-10 h-10 rounded-lg flex items-center justify-center transition-all ${revealedIdx === btn ? 'bg-yellow-500 text-black scale-110 shadow-lg' : 'bg-indigo-500/20 hover:bg-indigo-500 border border-indigo-400/30'}`}>
                                  ?
                              </button>
                          ))}
                      </div>
                  ) : currentLv >= i ? (
                      <Sparkles className="text-yellow-400" />
                  ) : (
                      <Lock size={16} className="text-slate-600" />
                  )}
              </div>
          ))}
      </div>

      <div className="bg-[#111] p-6 border-t border-white/5 pb-12 z-50">
        {gameState === 'IDLE' ? (
            <div className="space-y-4">
                <div className="flex gap-3 overflow-x-auto no-scrollbar py-2">
                    {[10, 50, 100, 500, 1000].map(a => <button key={a} onClick={() => setBet(a)} className={`flex-shrink-0 px-6 py-2 rounded-xl font-black border ${bet === a ? 'bg-yellow-500 text-black border-white' : 'bg-slate-900 text-slate-500 border-white/5'}`}>₹{a}</button>)}
                </div>
                <button onClick={start} className="w-full py-5 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-[2rem] font-black text-xl shadow-xl active:scale-95 transition-all">START CLIMB</button>
            </div>
        ) : (
            <div className="space-y-4">
                <div className="text-center mb-2">
                    <span className="text-[10px] text-slate-500 uppercase tracking-widest font-black">Current Win Potential</span>
                    <h3 className="text-3xl font-black gold-text">₹{(bet * (currentLv === -1 ? 1 : LEVELS[currentLv])).toFixed(2)}</h3>
                </div>
                <button onClick={() => cashout()} disabled={currentLv === -1 || gameState === 'REVEALING'} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-xl transition-all ${currentLv === -1 ? 'bg-zinc-800 text-zinc-600' : 'bg-yellow-500 text-black shadow-yellow-500/40 border-t-2 border-white/30'}`}>
                    {currentLv === -1 ? 'PICK A FLOOR' : `CASH OUT`}
                </button>
            </div>
        )}
      </div>

      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
              <div className="bg-slate-900 border border-indigo-500/30 w-full max-w-sm p-6 rounded-[2.5rem] animate-in zoom-in">
                   <div className="flex justify-between items-center mb-6">
                       <h2 className="text-xl font-black italic gold-text">TOWER RULES</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 leading-relaxed">
                       <p>1. Start your climb from the bottom floor.</p>
                       <p>2. Each floor has 3 tiles: <span className="text-green-400 font-bold">2 are safe</span>, <span className="text-red-500 font-bold">1 is a trap</span>.</p>
                       <p>3. Successfully picking a safe tile moves you up and increases your multiplier.</p>
                       <p>4. You can <span className="text-yellow-500 font-bold">Cash Out</span> at any level to take your winnings.</p>
                       <p>5. If you hit a trap, you lose your entire stake.</p>
                   </div>
              </div>
          </div>
      )}
      <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
    </div>
  );
};

