          @keyframes float-up {
              0% { transform: translate(-50%, 0); opacity: 0; scale: 0.5; }
              20% { opacity: 1; scale: 1.2; }
              100% { transform: translate(-50%, -150px); opacity: 0; scale: 1.5; }
          }
          .animate-float-up { animation: float-up 3s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
      `}</style>
    </div>
  );
};

export default Keno;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, HelpCircle, X, Lock, Flame, Sparkles, Trophy, Skull } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { GameResult } from '../types';

const LEVELS = [1.32, 1.76, 2.35, 3.12, 4.20, 5.60, 7.50, 10.0, 13.5, 18.0, 24.0, 32.0];

const DragonTower: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bet, setBet] = useState(10);
  const [currentLv, setCurrentLv] = useState(-1);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'REVEALING' | 'LOST' | 'WON'>('IDLE');
  const [revealedIdx, setRevealedIdx] = useState<number | null>(null);
  const [gridData, setGridData] = useState<number[]>([]); 
  const [revealedRows, setRevealedRows] = useState<number[]>([]); // Levels where we reveal the fire

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; stopAllSounds(); };
  }, []);

  const start = () => {
    if (userBalance < bet) return;
    updateBalance(-bet, 'BET', 'Dragon Tower');
    playSound('click');
    const newGrid = LEVELS.map(() => Math.floor(Math.random() * 4));
    setGridData(newGrid);
    setGameState('PLAYING');
    setCurrentLv(-1);
    setRevealedIdx(null);
    setRevealedRows([]);
  };

  const pick = async (idx: number) => {
    if (gameState !== 'PLAYING') return;
    setGameState('REVEALING');
    setRevealedIdx(idx);
    // FIX: Changed invalid sound name 'tick' to 'tower_step'
    playSound('tower_step');
    await new Promise(r => setTimeout(r, 800));

    const trapIdx = gridData[currentLv + 1];
    const isWin = idx !== trapIdx;

    if (isWin) {
        playSound('win');
        // When winning a row, we "reveal" the fire location of that row so the user sees it as they move up
        setRevealedRows(prev => [...prev, currentLv + 1]);
        setCurrentLv(prev => prev + 1);
        setGameState('PLAYING');
        setRevealedIdx(null);
        if (currentLv + 1 === LEVELS.length - 1) cashout(true);
    } else {
        playSound('loss');
        setGameState('LOST');
        setRevealedRows(prev => [...prev, currentLv + 1]); // Show where you died
        addGameHistory('Dragon Tower', bet, 0, `Burned at Level ${currentLv + 2}`);

        onResult({
            win: false,
            amount: bet,
            game: 'Dragon Tower',
            resultDetails: [{label: 'Level reached', value: (currentLv + 1).toString()}]
        });
    }
  };

  const cashout = (auto = false) => {
    if (gameState !== 'PLAYING' || currentLv === -1) return;
    const winAmt = bet * LEVELS[currentLv];
    updateBalance(winAmt, 'WIN', 'Dragon Tower Cashout');
    playSound('win');
    setGameState('WON');
    onResult({ win: true, amount: winAmt, game: 'Dragon Tower' });
  };

  const resetGame = () => {
      setGameState('IDLE');
      setCurrentLv(-1);
      setRevealedRows([]);
  };

  return (
    <div className="bg-[#0a0505] min-h-screen flex flex-col font-sans text-white overflow-hidden relative">
      {/* Full Screen Result Overlays */}
      {gameState === 'LOST' && (
          <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-red-950/90 backdrop-blur-md animate-in fade-in duration-500">
              <div className="bg-red-600 p-6 rounded-full shadow-[0_0_50px_rgba(220,38,38,0.8)] mb-6 animate-bounce">
                  <Skull size={64} className="text-white" />
              </div>
              <h2 className="text-5xl font-black italic gold-text uppercase mb-2">WASTED</h2>
              <p className="text-red-400 font-bold tracking-widest mb-10">YOU HIT THE FIRE</p>
              <div className="bg-black/40 px-10 py-4 rounded-2xl border border-red-500/30 mb-10 text-center">
                  <p className="text-[10px] text-red-500 font-black uppercase text-center mb-1">Loss</p>
                  <p className="text-3xl font-black text-white">₹{bet.toFixed(2)}</p>
              </div>
              <button onClick={resetGame} className="px-12 py-4 bg-white text-black font-black rounded-full shadow-2xl active:scale-95 transition-transform uppercase tracking-widest">Try Again</button>
          </div>
      )}

      {gameState === 'WON' && (
          <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-green-950/90 backdrop-blur-md animate-in fade-in duration-500">
              <div className="bg-yellow-500 p-6 rounded-full shadow-[0_0_50px_rgba(234,179,8,0.8)] mb-6 animate-pulse">
                  <Trophy size={64} className="text-black" />
              </div>
              <h2 className="text-5xl font-black italic gold-text uppercase mb-2">VICTORY</h2>
              <p className="text-green-400 font-bold tracking-widest mb-10">ELITE CLIMBER</p>
              <div className="bg-black/40 px-10 py-4 rounded-2xl border border-yellow-500/30 mb-10 text-center">
                  <p className="text-[10px] text-yellow-500 font-black uppercase mb-1">Winning Amount</p>
                  <p className="text-4xl font-black text-white italic">₹{(bet * LEVELS[currentLv]).toFixed(2)}</p>
              </div>
              <button onClick={resetGame} className="px-12 py-4 bg-yellow-500 text-black font-black rounded-full shadow-2xl active:scale-95 transition-transform uppercase tracking-widest">Collect & Close</button>
          </div>
      )}

      <div className="p-4 flex justify-between items-center bg-black/60 border-b border-orange-500/20 z-50 shadow-xl">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-orange-500/20 shadow-inner">
                <Wallet size={14} className="text-orange-500" />
                <span className="text-sm font-black font-mono text-orange-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
        <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">DRAGON TOWER</h1>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar p-4 flex flex-col-reverse gap-4 bg-[#0a0505] relative">
          {/* Background fire embers effect */}
          <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>

          {LEVELS.map((m, i) => (
              <div key={i} className={`h-20 w-full rounded-3xl border-2 flex items-center justify-between px-6 transition-all duration-500 relative z-10 ${currentLv === i ? 'bg-orange-950/40 border-orange-500 shadow-[0_0_30px_rgba(249,115,22,0.3)] scale-[1.03]' : i === currentLv + 1 ? 'bg-zinc-900 border-zinc-700' : 'bg-black/40 border-white/5 opacity-40'}`}>
                  <span className={`font-black text-xl italic w-14 ${currentLv >= i ? 'text-orange-400' : 'text-zinc-600'}`}>{m}x</span>
                  <div className="flex-1 flex justify-end gap-3">
                      {[0,1,2,3].map(tileIdx => {
                          const isCurrentRow = i === currentLv + 1;
                          const isTrap = gridData[i] === tileIdx;
                          const isPicked = isCurrentRow && revealedIdx === tileIdx;
                          const isFireRevealed = revealedRows.includes(i) && isTrap;

                          return (
                              <button 
                                key={tileIdx} 
                                onClick={() => pick(tileIdx)}
                                disabled={!isCurrentRow || gameState !== 'PLAYING'}
                                className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all border-2 relative overflow-hidden ${
                                    isFireRevealed 
                                        ? 'bg-orange-600/20 border-orange-500/40' 
                                        : isPicked 
                                            ? 'bg-green-600 border-green-400 shadow-[0_0_15px_rgba(34,197,94,0.5)]' 
                                            : isCurrentRow 
                                                ? 'bg-zinc-800 border-zinc-600 hover:border-orange-500 active:scale-90 shadow-lg' 
                                                : currentLv >= i 
                                                    ? 'bg-green-900/20 border-green-500/20'
                                                    : 'bg-black/20 border-white/5'
                                }`}
                              >
                                  {isFireRevealed ? (
                                      <div className="animate-fire-pulse">
                                        <Flame size={28} className="text-orange-500 fill-orange-500/20" />
                                      </div>
                                  ) : isCurrentRow ? (
                                      <span className="text-zinc-600 font-black text-xl">?</span>
                                  ) : currentLv >= i ? (
                                      <Sparkles size={20} className="text-green-400 opacity-60" />
                                  ) : (
                                      <Lock size={16} className="text-zinc-800"/>
                                  )}
                              </button>
                          );
                      })}
                  </div>
              </div>
          ))}
      </div>

      {/* Control Panel - Fix: Only show button if not LOST or WON */}
      <div className="bg-[#111] p-6 border-t border-white/10 pb-12 z-50">
        {gameState === 'IDLE' ? (
            <div className="space-y-4">
                <div className="flex gap-2 mb-2 overflow-x-auto no-scrollbar">
                    {[10, 100, 500, 1000, 5000].map(amt => (
                        <button key={amt} onClick={() => setBet(amt)} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all ${bet === amt ? 'bg-orange-600 text-white shadow-lg shadow-orange-900/40' : 'bg-zinc-900 text-zinc-600 border border-white/5'}`}>₹{amt}</button>
                    ))}
                </div>
                <button onClick={start} className="w-full py-6 bg-gradient-to-r from-orange-600 to-red-600 rounded-[2.5rem] font-black text-xl shadow-xl active:scale-95 transition-all uppercase tracking-widest border-t-2 border-white/10">Climb Tower</button>
            </div>
        ) : gameState === 'PLAYING' || gameState === 'REVEALING' ? (
            <button onClick={() => cashout()} disabled={currentLv === -1 || gameState !== 'PLAYING'} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-xl transition-all ${currentLv === -1 ? 'bg-zinc-800 text-zinc-600 cursor-not-allowed' : 'bg-yellow-500 text-black shadow-yellow-500/40 border-t-2 border-white/30'}`}>
                {currentLv === -1 ? 'PICK A TILE' : `CASH OUT ₹${(bet * LEVELS[currentLv]).toFixed(2)}`}
            </button>
        ) : null}
      </div>

      <style>{`
        .gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
        @keyframes fire-pulse {
          0%, 100% { transform: scale(1); filter: brightness(1); }
          50% { transform: scale(1.1); filter: brightness(1.3); }
        }
        .animate-fire-pulse { animation: fire-pulse 1s infinite ease-in-out; }
      `}</style>
    </div>
  );
};

export default DragonTower;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, RotateCw, Trash2, Volume2, VolumeX, Timer, History, HelpCircle, X, ShieldCheck } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult, RouletteBet } from '../types';

const WHEEL_ORDER = [0, 32, 15, 19, 4, 21, 2, 25, 17, 34, 6, 27, 13, 36, 11, 30, 8, 23, 10, 5, 24, 16, 33, 1, 20, 14, 31, 9, 22, 18, 29, 7, 28, 12, 35, 3, 26];
const REDS = [1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36];

const Roulette: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [bets, setBets] = useState<RouletteBet[]>([]);
  const [status, setStatus] = useState<'BETTING' | 'LOCKED' | 'SPINNING' | 'RESULT'>('BETTING');
  const [timeLeft, setTimeLeft] = useState(20);
  const [period, setPeriod] = useState(Date.now().toString().slice(-6));
  const [wheelRotation, setWheelRotation] = useState(0);
  const [history, setHistory] = useState<number[]>([]);
  const [selectedChip, setSelectedChip] = useState(10);
  const [lastResult, setLastResult] = useState<number | null>(null);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showPaytable, setShowPaytable] = useState(false);
  const [floating, setFloating] = useState<{ text: string; color: string; id: number } | null>(null);
  const [confirmDrawer, setConfirmDrawer] = useState<{ open: boolean; type: RouletteBet['type']; value: string | number } | null>(null);

  const isMounted = useRef(true);
  const pendingBetsRef = useRef<RouletteBet[]>([]);

  useEffect(() => {
    isMounted.current = true;
    const interval = setInterval(() => {
        if (!isMounted.current) return;

        if (status === 'BETTING') {
            if (timeLeft > 0) {
                setTimeLeft(prev => prev - 1);
                // FIX: Changed invalid sound name 'tick' to 'wingo_tick'
                if (timeLeft <= 5) playSound('wingo_tick');
            } else {
                setStatus('LOCKED');
                setConfirmDrawer(null);
                setTimeLeft(3);
            }
        } else if (status === 'LOCKED') {
            if (timeLeft > 0) setTimeLeft(prev => prev - 1);
            else spin();
        }
    }, 1000);

    return () => { isMounted.current = false; clearInterval(interval); stopAllSounds(); };
  }, [timeLeft, status]);

  const triggerFloating = (text: string, color: string) => {
      setFloating({ text, color, id: Date.now() });
      setTimeout(() => setFloating(null), 3000);
  };

  const spin = () => {
    setStatus('SPINNING');
    // FIX: Changed invalid sound name 'spin' to 'wheel_spin'
    playSound('wheel_spin');

    const result = WHEEL_ORDER[Math.floor(Math.random() * WHEEL_ORDER.length)];
    const resultIdx = WHEEL_ORDER.indexOf(result);
    const segmentAngle = 360 / WHEEL_ORDER.length;

    const extraRots = 360 * 20; 
    const offset = resultIdx * segmentAngle;
    const finalRotation = wheelRotation + extraRots + (360 - (wheelRotation % 360)) - offset;

    setWheelRotation(finalRotation);
    setTimeout(() => finalize(result), 5000);
  };

  const finalize = (num: number) => {
    if (!isMounted.current) return;
    setStatus('RESULT');
    setLastResult(num);
    setHistory(prev => [num, ...prev].slice(0, 15));

    const currentBets = [...pendingBetsRef.current];
    let totalWin = 0;
    const isRed = REDS.includes(num);
    const isEven = num !== 0 && num % 2 === 0;

    currentBets.forEach(bet => {
        if (bet.type === 'NUMBER' && bet.value === num) totalWin += bet.amount * 36;
        if (bet.type === 'COLOR') {
            if (bet.value === 'RED' && isRed) totalWin += bet.amount * 2;
            if (bet.value === 'BLACK' && !isRed && num !== 0) totalWin += bet.amount * 2;
        }
        if (bet.type === 'ODD_EVEN') {
            if (bet.value === 'EVEN' && isEven) totalWin += bet.amount * 2;
            if (bet.value === 'ODD' && !isEven && num !== 0) totalWin += bet.amount * 2;
        }
        if (bet.type === 'RANGE') {
            if (bet.value === '1-18' && num >= 1 && num <= 18) totalWin += bet.amount * 2;
            if (bet.value === '19-36' && num >= 19 && num <= 36) totalWin += bet.amount * 2;
        }
    });

    if (totalWin > 0) {
        updateBalance(totalWin, 'WIN', 'Roulette Win');
        playSound('win');
        triggerFloating(`+₹${totalWin.toFixed(2)}`, 'text-yellow-400');
        onResult({ win: true, amount: totalWin, game: 'Mafia Roulette', resultDetails: [{label: 'Number', value: num.toString()}] });
    } else if (currentBets.length > 0) {
        playSound('loss');
        triggerFloating(`-₹${currentBets.reduce((acc,b)=>acc+b.amount,0).toFixed(2)}`, 'text-red-500');
        onResult({ win: false, amount: currentBets.reduce((acc,b)=>acc+b.amount,0), game: 'Mafia Roulette' });
    }

    addGameHistory('Mafia Roulette', currentBets.reduce((acc,b)=>acc+b.amount,0), totalWin, `Period ${period} | Landed ${num}`);

    setTimeout(() => {
        if (isMounted.current) {
            setStatus('BETTING');
            setTimeLeft(20);
            setBets([]);
            pendingBetsRef.current = [];
            setPeriod(Date.now().toString().slice(-6));
        }
    }, 5000);
  };

  const openBetConfirm = (type: RouletteBet['type'], value: string | number) => {
    if (status !== 'BETTING') return;
    setConfirmDrawer({ open: true, type, value });
    playSound('click');
  };

  const confirmBet = () => {
    if (!confirmDrawer || status !== 'BETTING') return;
    const { type, value } = confirmDrawer;

    if (userBalance < selectedChip) {
        alert("Insufficient Balance");
        return;
    }

    updateBalance(-selectedChip, 'BET', `Roulette: ${value}`);
    playSound('click');

    const newBet: RouletteBet = { type, value, amount: selectedChip };
    const existingIdx = bets.findIndex(b => b.type === type && b.value === value);

    let updated;
    if (existingIdx > -1) {
        updated = [...bets];
        updated[existingIdx].amount += selectedChip;
    } else {
        updated = [...bets, newBet];
    }
    setBets(updated);
    pendingBetsRef.current = updated;
    setConfirmDrawer(null);
  };

  const clearBets = () => {
    if (status !== 'BETTING') return;
    const total = bets.reduce((a, b) => a + b.amount, 0);
    if (total > 0) {
        updateBalance(total, 'GIFT', 'Roulette Clear');
        setBets([]);
        pendingBetsRef.current = [];
        playSound('click');
    }
  };

  const rows = [];
  for (let i = 0; i < 6; i++) {
    rows.push(Array.from({ length: 6 }, (_, j) => i * 6 + j + 1));
  }

  return (
    <div className="bg-[#050505] min-h-screen flex flex-col font-sans text-white overflow-hidden relative select-none">
      {floating && (
          <div key={floating.id} className={`fixed top-1/2 left-1/2 -translate-x-1/2 z-[300] font-black text-6xl italic pointer-events-none animate-float-up ${floating.color}`} style={{ textShadow: '0 0 40px rgba(0,0,0,1)' }}>
              {floating.text}
          </div>
      )}

      {/* Header */}
      <div className="p-4 flex justify-between items-center bg-[#111] border-b border-yellow-500/20 z-[110] shadow-2xl">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2.5 bg-zinc-900 rounded-2xl active:scale-90 border border-white/5"><ArrowLeft size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 shadow-inner">
                <Wallet size={14} className="text-yellow-500" />
                <span className="text-sm font-black font-mono text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
        <h1 className="text-sm font-black gold-text italic tracking-widest uppercase">MAFIA ROULETTE</h1>
        <div className="flex gap-2">
            <button onClick={() => setShowPaytable(true)} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/5"><HelpCircle size={18}/></button>
            <button onClick={() => setMuted(toggleMute())} className="p-2.5 bg-zinc-900 rounded-2xl border border-white/5">
                {muted ? <VolumeX size={18}/> : <Volume2 size={18}/>}
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar flex flex-col items-center py-4 pb-64 gap-8">

          <div className="relative w-full max-w-lg aspect-square flex items-center justify-center transition-all px-4 mt-2">
              {/* TOP POINTER */}
              <div className="absolute top-[-8px] left-1/2 -translate-x-1/2 z-[80] flex flex-col items-center pointer-events-none">
                   <div 
                      className="w-14 h-16 bg-yellow-500 shadow-[0_0_50px_rgba(234,179,8,1)]" 
                      style={{ clipPath: 'polygon(50% 100%, 0 0, 100% 0)' }}
                   ></div>
              </div>

              {/* The Rotating Wheel Disk */}
              <div 
                className="w-full h-full rounded-full border-[14px] border-zinc-900 shadow-[0_0_150px_rgba(0,0,0,1)] transition-transform duration-[5000ms] cubic-bezier(0.1, 0, 0.1, 1) relative bg-zinc-900"
                style={{ 
                    transform: `rotate(${wheelRotation}deg)`,
                }}
              >
                 {/* Conic Gradient for Segment Colors */}
                 <div className="absolute inset-0 rounded-full" style={{ background: `conic-gradient(${WHEEL_ORDER.map((n, i) => `${n===0?'#16a34a':REDS.includes(n)?'#dc2626':'#1a1a1a'} ${i*(360/37)}deg ${(i+1)*(360/37)}deg`).join(', ')})` }}></div>

                 {/* Number Overlay - SHRUNK AND POSITIONED AT EXTREME OUTER RIM */}
                 {WHEEL_ORDER.map((n, i) => (
                     <div 
                        key={i} 
                        className="absolute top-0 left-1/2 -translate-x-1/2 h-1/2 origin-bottom flex items-center justify-center pt-1.5" 
                        style={{ transform: `translateX(-50%) rotate(${i*(360/37) + (360/37/2)}deg)` }}
                     >
                        <span className="text-[9px] md:text-[11px] font-black text-white/95 drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-tighter select-none leading-none">
                          {n}
                        </span>
                     </div>
                 ))}

                 {/* Inner rim overlay for realistic wheel depth */}
                 <div className="absolute inset-[12%] rounded-full border-[8px] border-zinc-800/60 shadow-[inset_0_0_30px_rgba(0,0,0,0.8)] pointer-events-none"></div>
              </div>

              {/* CENTRAL DISPLAY CORE */}
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-[70]">
                  <div className="w-36 h-36 md:w-52 md:h-52 rounded-full bg-[#0a0a0a] border-[12px] border-zinc-800 shadow-[inset_0_0_80px_rgba(0,0,0,1),0_0_60px_rgba(234,179,8,0.15)] flex flex-col items-center justify-center overflow-hidden relative">
                      <div className="absolute inset-0 bg-gradient-to-br from-white/10 to-transparent"></div>
                      <div className="absolute inset-3 rounded-full border border-yellow-500/10 shadow-[0_0_20px_rgba(234,179,8,0.1)]"></div>
                      <div className={`text-7xl md:text-8xl font-black italic tracking-tighter transition-all duration-500 ${status === 'RESULT' ? 'scale-110 drop-shadow-[0_0_20px_rgba(255,255,255,0.4)]' : 'scale-100'} ${lastResult===0?'text-green-500':REDS.includes(lastResult||-1)?'text-red-500':'text-white'}`}>
                          {lastResult !== null ? lastResult : '?'}
                      </div>
                      <div className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.4em] mt-3">TARGET HIT</div>
                  </div>
              </div>
          </div>

          {/* Game Info Bar */}
          <div className="w-full px-8 flex justify-between items-center bg-zinc-900/60 py-6 border-y border-white/5 backdrop-blur-xl">
              <div className="flex flex-col">
                  <span className="text-[10px] text-zinc-500 font-black uppercase tracking-widest opacity-60">Session State</span>
                  <div className={`text-lg font-black uppercase italic tracking-tighter ${status==='BETTING'?'text-green-500':'text-red-500'}`}>
                      {status === 'BETTING' ? 'Betting Active' : status === 'LOCKED' ? 'Bets Closed' : status === 'SPINNING' ? 'Spooling...' : 'Draw Ready'}
                  </div>
              </div>
              <div className="flex flex-col items-end">
