    const filter = () => cb(gameName === 'ALL' ? gameHistory : gameHistory.filter(item => item.game === gameName));
    filter();
    return subscribeToBalance(() => filter());
};

export const getTransactionHistory = (cb: (data: Transaction[]) => void) => {
