};

export const shouldForceLoss = (bet: number, balance: number) => Math.random() > 0.4;

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txIndex = transactions.findIndex(t => t.id === txId);
    if (txIndex === -1 || transactions[txIndex].status !== 'PROCESSING') return;
    const tx = transactions[txIndex];
    tx.status = 'SUCCESS';
    saveLocalTransactions(currentUser.uid, transactions);
    if (tx.type === 'DEPOSIT') {
        const users = getLocalUsers();
        const user = users[currentUser.uid];
        user.balance += tx.amount;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;
        user.wagerRequired = (user.wagerRequired || 0) + (tx.amount * 1);
        if (user.totalDeposit === tx.amount) {
            const bonus = tx.amount * 0.25;
            user.balance += bonus;
            user.wagerRequired += (bonus * 1);
            transactions.unshift({ id: 'TX_B_' + Date.now(), type: 'BONUS', amount: bonus, status: 'SUCCESS', date: new Date().toLocaleString(), desc: '25% First Deposit Reward' });
        }
        if (user.invitedBy) {
            const referrer = Object.values(users).find(u => u.inviteCode === user.invitedBy);
            if (referrer) {
                referrer.totalCommission = (referrer.totalCommission || 0) + (tx.amount * 0.5);
                users[referrer.uid] = referrer;
            }
        }
        currentUser = user;
        saveLocalUsers(users);
        notifySubscribers();
        playSound('win');
    }
};

export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    transactions.unshift({ id: 'TX_' + Date.now(), type: 'DEPOSIT', amount, status: 'PROCESSING', date: new Date().toLocaleString(), desc: `Deposit via ${method}`, utr, method, timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    notifySubscribers();
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Auth Required' };
    if (currentUser.withdrawalPassword !== password) return { success: false, message: 'Invalid PIN' };
    if (currentUser.balance < amount) return { success: false, message: 'Low Balance' };
    if (currentUser.wagerRequired > 0) return { success: false, message: `Wager left: ₹${currentUser.wagerRequired.toFixed(0)}` };
    const users = getLocalUsers();
    users[currentUser.uid].balance -= amount;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);
    transactions.unshift({ id: 'TX_' + Date.now(), type: 'WITHDRAW', amount, status: 'PROCESSING', date: new Date().toLocaleString(), desc: `Withdraw via ${method}`, method, accountDetails: details, timestamp: Date.now() });
    saveLocalTransactions(currentUser.uid, transactions);
    notifySubscribers();
    return { success: true };
};

export const setWithdrawalPassword = (password: string) => {
    if (!currentUser) return false;
    const users = getLocalUsers();
    users[currentUser.uid].withdrawalPassword = password;
    currentUser = users[currentUser.uid];
    saveLocalUsers(users);
    return true;
};

export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser || currentUser.usedGiftCodes?.includes(code)) return 0;
    let amount = 0;
    if (code === 'MAFIA100') amount = 100;
    if (code === 'ff') amount = 1000;
    if (amount > 0) {
        const users = getLocalUsers();
        const user = users[currentUser.uid];
        if (user) {
            user.usedGiftCodes = [...(user.usedGiftCodes || []), code];
            user.balance += amount;
            user.wagerRequired = (user.wagerRequired || 0) + (amount * 6.8);
            currentUser = user;
            saveLocalUsers(users);
            transactions.unshift({ id: 'TX_G_' + Date.now(), type: 'GIFT', amount, status: 'SUCCESS', date: new Date().toLocaleString(), desc: `Gift: ${code}`, timestamp: Date.now() });
            saveLocalTransactions(currentUser.uid, transactions);
            notifySubscribers();
            return amount;
        }
    }
    return 0;
};

