            wagerRequired: (currentUser.wagerRequired || 0) + (totalAdd * 1)
        });
        if (bonus > 0) await updateBalance(bonus, 'BONUS', '25% First Deposit Reward');
        if (currentUser.invitedBy) {
            const usersSnap = await get(ref(db, 'users'));
            const uData = usersSnap.val();
            if (uData) {
                const referrer = Object.values(uData).find((u: any) => u.inviteCode === currentUser?.invitedBy) as any;
