const initSession = async () => {
    const uid = localStorage.getItem(SESSION_KEY);
    if (uid) {
        try {
            const snapshot = await get(ref(db, `users/${uid}`));
            if (snapshot.exists()) {
                currentUser = sanitizeUser(snapshot.val());
                syncUserStats(uid);
                notifySubscribers();
            } else {
                localStorage.removeItem(SESSION_KEY);
            }
        } catch (e) {
            localStorage.removeItem(SESSION_KEY);
        }
    }
};

const syncUserStats = (uid: string) => {
    onValue(ref(db, `users/${uid}`), (snapshot) => {
        if (snapshot.exists()) {
            currentUser = sanitizeUser(snapshot.val());
            notifySubscribers();
        }
    });
    onValue(ref(db, `transactions/${uid}`), (snapshot) => {
        if (snapshot.exists()) {
            const val = snapshot.val();
            if (val) transactions = Object.values(val).reverse() as Transaction[];
            else transactions = [];
            notifySubscribers();
        }
    });
    onValue(ref(db, `gameHistory/${uid}`), (snapshot) => {
        if (snapshot.exists()) {
            const val = snapshot.val();
            if (val) gameHistory = Object.values(val).reverse() as GameHistoryItem[];
            else gameHistory = [];
            notifySubscribers();
        }
    });
};

export const login = async (phone: string, pass: string) => {
    try {
        const snapshot = await get(ref(db, 'users'));
        if (snapshot.exists()) {
            const users = snapshot.val();
            if (users) {
                const user = Object.values(users).find((u: any) => u.phone === phone && u.password === pass) as any;
                if (user) {
                    currentUser = sanitizeUser(user);
                    localStorage.setItem(SESSION_KEY, user.uid);
                    syncUserStats(user.uid);
                    return { success: true };
                }
            }
        }
    } catch (e) { console.error(e); }
    return { success: false, message: 'Invalid phone or password' };
};

export const register = async (phone: string, pass: string, inviteCode: string, username: string) => {
    try {
        const snapshot = await get(ref(db, 'users'));
        if (snapshot.exists()) {
            const users = snapshot.val();
            if (users && Object.values(users).some((u: any) => u.phone === phone)) {
                return { success: false, message: 'Phone already registered' };
