export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const users = getDB(STORAGE_KEYS.USERS);
    const user = users[currentUser.uid];

    user.balance = Math.max(0, user.balance + amount);
    if (amount < 0) {
        user.totalBet = (user.totalBet || 0) + Math.abs(amount);
        user.wagerRequired = Math.max(0, (user.wagerRequired || 0) - Math.abs(amount));
    }
    if (user.balance < 1.0) user.wagerRequired = 0;

    users[currentUser.uid] = user;
    saveDB(STORAGE_KEYS.USERS, users);
    currentUser = sanitizeUser(user);

    const txs = getDB(STORAGE_KEYS.TRANSACTIONS + currentUser.uid) || [];
    const newTx: Transaction = { id: 'TX_' + Date.now(), type, amount: Math.abs(amount), status: 'SUCCESS', date: new Date().toLocaleString(), desc, timestamp: Date.now() };
    txs.unshift(newTx);
    saveDB(STORAGE_KEYS.TRANSACTIONS + currentUser.uid, txs);
    transactions = txs;

    notifySubscribers();
};

