export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txs = getDB(STORAGE_KEYS.TRANSACTIONS + currentUser.uid) || [];
    const idx = txs.findIndex((t: any) => t.id === txId);
    if (idx === -1 || txs[idx].status !== 'PROCESSING') return;

    txs[idx].status = 'SUCCESS';
    saveDB(STORAGE_KEYS.TRANSACTIONS + currentUser.uid, txs);
    transactions = txs;

    if (txs[idx].type === 'DEPOSIT') {
        const users = getDB(STORAGE_KEYS.USERS);
        const user = users[currentUser.uid];
        const bonus = user.totalDeposit === 0 ? txs[idx].amount * 0.25 : 0;
        const totalAdd = txs[idx].amount + bonus;
        user.balance += totalAdd;
        user.totalDeposit = (user.totalDeposit || 0) + txs[idx].amount;
        user.wagerRequired = (user.wagerRequired || 0) + (totalAdd * 1);
        users[currentUser.uid] = user;
        saveDB(STORAGE_KEYS.USERS, users);
        currentUser = sanitizeUser(user);
        if (bonus > 0) await updateBalance(bonus, 'BONUS', 'First Deposit Reward');

        if (user.invitedBy) {
            const referrer = Object.values(users).find((u: any) => u.inviteCode === user.invitedBy) as any;
            if (referrer) {
                referrer.totalCommission = (referrer.totalCommission || 0) + (txs[idx].amount * 0.5);
                users[referrer.uid] = referrer;
                saveDB(STORAGE_KEYS.USERS, users);
            }
        }
        playSound('win');
    }
    notifySubscribers();
};

