        users[currentUser.uid] = user;
        saveDB(STORAGE_KEYS.USERS, users);
        currentUser = sanitizeUser(user);
        if (bonus > 0) await updateBalance(bonus, 'BONUS', 'First Deposit Reward');

        if (user.invitedBy) {
            const referrer = Object.values(users).find((u: any) => u.inviteCode === user.invitedBy) as any;
            if (referrer) {
                referrer.totalCommission = (referrer.totalCommission || 0) + (txs[idx].amount * 0.5);
