// GLOBAL GAME ENGINES (Shared via Firebase)
export const startGlobalEngines = () => {
  // Only the first client effectively manages the server-side state if it were a real backend
  // For this standalone app, we simulate shared state in a 'gameStates' node

  const manageWinGo = () => {
      const stateRef = ref(db, 'gameStates/wingo');
      onValue(stateRef, (snapshot) => {
          if (!snapshot.exists()) {
              set(stateRef, { timeLeft: 30, period: 202511261000, status: 'BETTING' });
          }
      });

      // Internal clock for this specific client to keep UI snappy
      setInterval(async () => {
          const snap = await get(stateRef);
          if (!snap.exists()) return;
          let data = snap.val();
          data.timeLeft -= 1;

          if (data.timeLeft <= 0) {
              const num = Math.floor(Math.random() * 10);
              let color: 'Red'|'Green'|'Violet' = 'Red';
              if (num === 0 || num === 5) color = 'Violet';
              else if ([1,3,7,9].includes(num)) color = 'Green';

              const res = { period: data.period.toString(), number: num, bigSmall: num >= 5 ? 'Big' : 'Small', color };
              const historyRef = ref(db, 'gameStates/wingo/history');
              const historySnap = await get(historyRef);
              const history = historySnap.exists() ? Object.values(historySnap.val()) : [];

              await set(stateRef, {
                  timeLeft: 30,
                  period: data.period + 1,
                  status: 'BETTING',
                  lastResult: res,
                  history: [res, ...history].slice(0, 50)
              });
          } else {
              await update(stateRef, { timeLeft: data.timeLeft });
          }
      }, 1000);
  };

  // Check if we should be the 'engine' (Simple lock mechanism)
  const engineLock = ref(db, 'engine_lock');
  get(engineLock).then(snap => {
      if (!snap.exists()) {
          set(engineLock, Date.now());
          onDisconnect(engineLock).remove();
          manageWinGo();
      }
  });
};

