        await update(ref(db, `users/${currentUser.uid}`), {
            balance: currentUser.balance + totalAdd,
            totalDeposit: (currentUser.totalDeposit || 0) + tx.amount,
            wagerRequired: (currentUser.wagerRequired || 0) + (totalAdd * 1)
        });

        if (bonus > 0) await updateBalance(bonus, 'BONUS', 'First Deposit Reward');

        if (currentUser.invitedBy) {
