};

export const toggleMute = () => { isMuted = !isMuted; if (isMuted) stopAllSounds(); return isMuted; };
export const getMuteStatus = () => isMuted;
export const playSound = (type: keyof typeof sounds) => {
  if (isMuted) return;
  try { const audio = sounds[type]; if (audio) { audio.currentTime = 0; audio.volume = 0.5; audio.play().catch(() => {}); } } catch (e) {}
};
export const stopAllSounds = () => { Object.values(sounds).forEach(audio => { audio.pause(); audio.currentTime = 0; }); };

// STATE REFS
let currentUser: UserProfile | null = null;
const balanceSubscribers: Function[] = [];
export let transactions: Transaction[] = [];
export let gameHistory: GameHistoryItem[] = [];
export let referralStats: ReferralData = { code: '', link: '', totalCommission: 0, yesterdayCommission: 0, directSubordinates: 0, teamSubordinates: 0, totalDepositAmount: 0, totalBetAmount: 0 };

const sanitizeUser = (user: any): UserProfile => ({
    uid: user.uid || 'unknown',
    balance: typeof user.balance === 'number' ? user.balance : 0,
    vipLevel: user.vipLevel || 0,
    name: user.name || 'User',
    username: user.username || 'User',
    phone: user.phone || '',
    avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid || 'default'}`,
    totalDeposit: user.totalDeposit || 0,
    totalBet: user.totalBet || 0,
    inviteCode: user.inviteCode || '',
    password: user.password || '',
    withdrawalPassword: user.withdrawalPassword || '',
    usedGiftCodes: Array.isArray(user.usedGiftCodes) ? user.usedGiftCodes : [],
    invitedBy: user.invitedBy || '',
    totalCommission: user.totalCommission || 0,
    wagerRequired: user.wagerRequired || 0,
    isBankBound: user.isBankBound || false,
    isUpiBound: user.isUpiBound || false,
    isTelegramJoined: user.isTelegramJoined || false,
    bankDetails: user.bankDetails || undefined,
    upiDetails: user.upiDetails || undefined
});

const notifySubscribers = () => {
    balanceSubscribers.forEach(cb => cb(currentUser ? { ...currentUser } : null));
    if (currentUser) calculateReferralStats(currentUser.inviteCode);
};

const calculateReferralStats = async (myCode: string) => {
    if (!myCode) return;
    try {
        const snapshot = await get(ref(db, 'users'));
        const allUsers = snapshot.exists() ? Object.values(snapshot.val()) as any[] : [];
        const subs = allUsers.filter(u => u.invitedBy === myCode);

        referralStats.code = myCode;
        referralStats.link = `${window.location.origin}/#/register?code=${myCode}`;
        referralStats.directSubordinates = subs.length;
        referralStats.teamSubordinates = subs.length;
        referralStats.totalDepositAmount = subs.reduce((acc, c) => acc + (c.totalDeposit || 0), 0);
        referralStats.totalBetAmount = subs.reduce((acc, c) => acc + (c.totalBet || 0), 0);
        if (currentUser) {
            referralStats.totalCommission = currentUser.totalCommission || 0;
            referralStats.yesterdayCommission = (currentUser.totalCommission || 0) * 0.15;
        }
    } catch (e) {
        console.error("Referral stats error:", e);
    }
};

// INITIALIZATION
const initSession = () => {
    const uid = localStorage.getItem('MAFIA_UID');
    if (uid) {
        onValue(ref(db, `users/${uid}`), (snapshot) => {
            if (snapshot.exists()) {
                currentUser = sanitizeUser(snapshot.val());
                notifySubscribers();
            }
        });
        onValue(ref(db, `transactions/${uid}`), (snapshot) => {
            if (snapshot.exists()) {
                transactions = Object.values(snapshot.val() as Record<string, Transaction>).reverse();
            }
        });
        onValue(ref(db, `gameHistory/${uid}`), (snapshot) => {
            if (snapshot.exists()) {
                gameHistory = Object.values(snapshot.val() as Record<string, GameHistoryItem>).reverse();
            }
        });
    }
};

// AUTH METHODS
export const login = async (phone: string, pass: string) => {
    const snapshot = await get(ref(db, 'users'));
    if (!snapshot.exists()) return { success: false, message: 'User not found' };

    const users = snapshot.val();
    const userEntry = Object.entries(users).find(([uid, u]: [string, any]) => u.phone === phone && u.password === pass);

    if (userEntry) {
        const [uid, userData] = userEntry;
        localStorage.setItem('MAFIA_UID', uid);
        currentUser = sanitizeUser(userData);
        initSession();
        return { success: true };
    }
    return { success: false, message: 'Invalid credentials' };
};

export const register = async (phone: string, pass: string, inviteCode: string, username: string) => {
    const snapshot = await get(ref(db, 'users'));
    const users = snapshot.exists() ? snapshot.val() : {};

    if (Object.values(users).some((u: any) => u.phone === phone)) {
        return { success: false, message: 'Phone already registered' };
    }

    const uid = 'USER_' + Date.now();
    const newUser: UserProfile = sanitizeUser({
        uid, password: pass, name: username, username, phone, 
        inviteCode: Math.floor(10000000 + Math.random() * 90000000).toString(), 
        invitedBy: inviteCode, balance: 0, wagerRequired: 0
    });

    await set(ref(db, `users/${uid}`), newUser);
    localStorage.setItem('MAFIA_UID', uid);
    currentUser = newUser;
    initSession();
    return { success: true };
};

export const logout = async () => {
    localStorage.removeItem('MAFIA_UID');
    currentUser = null;
    notifySubscribers();
};

export const checkAuth = () => !!localStorage.getItem('MAFIA_UID');

export const subscribeToBalance = (cb: (user: UserProfile | null) => void) => {
    balanceSubscribers.push(cb);
    cb(currentUser ? { ...currentUser } : null);
    return () => { const idx = balanceSubscribers.indexOf(cb); if (idx > -1) balanceSubscribers.splice(idx, 1); };
};

// DATA ENGINE UTILS (Firebase Wrappers)
export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const uid = currentUser.uid;
    const userRef = ref(db, `users/${uid}`);

    const currentBalance = currentUser.balance;
    const newBalance = Math.max(0, currentBalance + amount);

    let updates: any = { balance: newBalance };
    if (amount < 0) {
        updates.totalBet = (currentUser.totalBet || 0) + Math.abs(amount);
        updates.wagerRequired = Math.max(0, (currentUser.wagerRequired || 0) - Math.abs(amount));
    }
    if (newBalance < 1.0) updates.wagerRequired = 0;

    await update(userRef, updates);

    const txRef = push(ref(db, `transactions/${uid}`));
    await set(txRef, {
        id: txRef.key,
        type,
        amount: Math.abs(amount),
        status: 'SUCCESS',
        date: new Date().toLocaleString(),
        desc,
        timestamp: Date.now()
    });
};

export const addGameHistory = async (game: string, bet: number, win: number, details: string) => {
    if (!currentUser) return;
    const historyRef = push(ref(db, `gameHistory/${currentUser.uid}`));
    await set(historyRef, {
        id: historyRef.key,
        game,
        amount: bet,
        win,
        date: new Date().toLocaleString(),
        details
    });
};

export const getGameHistory = (gameName: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) return () => {};
    const historyRef = ref(db, `gameHistory/${currentUser.uid}`);
    return onValue(historyRef, (snapshot) => {
        if (snapshot.exists()) {
            const data = Object.values(snapshot.val() as Record<string, GameHistoryItem>).reverse();
            cb(gameName === 'ALL' ? data : data.filter(item => item.game === gameName));
        } else cb([]);
    });
};

export const getTransactionHistory = (cb: (data: Transaction[]) => void) => {
    if (!currentUser) return () => {};
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    return onValue(txRef, (snapshot) => {
        if (snapshot.exists()) {
            cb(Object.values(snapshot.val() as Record<string, Transaction>).reverse());
        } else cb([]);
    });
};

// ACCOUNT BINDING
export const bindBank = async (details: { accountName: string, accountNo: string, ifsc: string }) => {
    if (!currentUser) return { success: false, message: 'Auth Required' };

    const snapshot = await get(ref(db, 'users'));
    const allUsers = snapshot.exists() ? Object.values(snapshot.val()) : [];
    if (allUsers.some((u: any) => u.isBankBound && u.bankDetails?.accountNo === details.accountNo)) {
        return { success: false, message: 'Account already bound' };
    }

    await update(ref(db, `users/${currentUser.uid}`), {
        isBankBound: true,
        bankDetails: details
    });
    await updateBalance(10, 'GIFT', 'Bank Binding Bonus');
    return { success: true };
};

export const bindUpi = async (details: { upiId: string }) => {
    if (!currentUser) return { success: false, message: 'Auth Required' };

    const snapshot = await get(ref(db, 'users'));
    const allUsers = snapshot.exists() ? Object.values(snapshot.val()) : [];
    if (allUsers.some((u: any) => u.isUpiBound && u.upiDetails?.upiId === details.upiId)) {
        return { success: false, message: 'UPI ID already bound' };
    }

    await update(ref(db, `users/${currentUser.uid}`), {
        isUpiBound: true,
        upiDetails: details
    });
    await updateBalance(5, 'GIFT', 'UPI Binding Bonus');
    return { success: true };
};

export const joinTelegramReward = async () => {
    if (!currentUser || currentUser.isTelegramJoined) return { success: false };
    await update(ref(db, `users/${currentUser.uid}`), { isTelegramJoined: true });
    await updateBalance(5, 'GIFT', 'Telegram Reward');
    return { success: true };
};

export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser || currentUser.usedGiftCodes?.includes(code)) return 0;
    let amount = 0;
    if (code === 'MAFIA100') amount = 100;
    if (code === 'ff') amount = 1000;

    if (amount > 0) {
        const used = [...(currentUser.usedGiftCodes || []), code];
        await update(ref(db, `users/${currentUser.uid}`), {
            usedGiftCodes: used,
            wagerRequired: (currentUser.wagerRequired || 0) + (amount * 6.8)
        });
        await updateBalance(amount, 'GIFT', `Gift Code: ${code}`);
        return amount;
    }
    return 0;
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Auth Required' };
    if (currentUser.withdrawalPassword !== password) return { success: false, message: 'Invalid PIN' };
    if (currentUser.balance < amount) return { success: false, message: 'Low Balance' };
    if (currentUser.wagerRequired > 0) return { success: false, message: `Wager left: ₹${currentUser.wagerRequired.toFixed(0)}` };

    await updateBalance(-amount, 'WITHDRAW', `Withdraw via ${method}`);
    return { success: true };
};

export const setWithdrawalPassword = async (password: string) => {
    if (!currentUser) return false;
    await update(ref(db, `users/${currentUser.uid}`), { withdrawalPassword: password });
    return true;
};

export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    const txRef = push(ref(db, `transactions/${currentUser.uid}`));
    await set(txRef, {
        id: txRef.key,
        type: 'DEPOSIT',
        amount,
        status: 'PROCESSING',
        date: new Date().toLocaleString(),
        desc: `Deposit via ${method}`,
        utr,
        method,
        timestamp: Date.now()
    });
};

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txRef = ref(db, `transactions/${currentUser.uid}/${txId}`);
    const snapshot = await get(txRef);
    if (!snapshot.exists() || snapshot.val().status !== 'PROCESSING') return;

    const tx = snapshot.val();
    await update(txRef, { status: 'SUCCESS' });

    if (tx.type === 'DEPOSIT') {
        const bonus = currentUser.totalDeposit === 0 ? tx.amount * 0.25 : 0;
        const totalAdd = tx.amount + bonus;

        await update(ref(db, `users/${currentUser.uid}`), {
            balance: currentUser.balance + totalAdd,
            totalDeposit: (currentUser.totalDeposit || 0) + tx.amount,
            wagerRequired: (currentUser.wagerRequired || 0) + (totalAdd * 1)
        });

        if (bonus > 0) await updateBalance(bonus, 'BONUS', 'First Deposit Reward');

        if (currentUser.invitedBy) {
            const usersSnap = await get(ref(db, 'users'));
            const users = usersSnap.val();
            const referrerEntry = Object.entries(users).find(([_, u]: [string, any]) => u.inviteCode === currentUser?.invitedBy);
            if (referrerEntry) {
                const [rUid, rData] = referrerEntry;
                await update(ref(db, `users/${rUid}`), {
                    totalCommission: ((rData as any).totalCommission || 0) + (tx.amount * 0.5)
                });
            }
        }
        playSound('win');
    }
};

export const claimCommission = async () => {
    if (!currentUser || (currentUser.totalCommission || 0) <= 0) return { success: false, message: 'No assets' };
    const amount = currentUser.totalCommission || 0;
    await update(ref(db, `users/${currentUser.uid}`), { totalCommission: 0 });
    await updateBalance(amount, 'COMMISSION', 'Commission Claimed');
    return { success: true };
};

export const getSubordinates = (): SubordinateItem[] => []; 

export const getCommissions = (cb: (data: CommissionItem[]) => void) => {
    if (!currentUser) return () => {};
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    return onValue(txRef, (snapshot) => {
        if (snapshot.exists()) {
            const txs = Object.values(snapshot.val() as Record<string, Transaction>);
            cb(txs.filter(t => t.type === 'COMMISSION').map(t => ({ 
                id: t.id, 
                fromUid: 'Network', 
                amount: t.amount, 
                date: t.date, 
                type: 'Bonus' 
            })));
        } else cb([]);
    });
};

export const getGameStats = () => {
    const stats: Record<string, { bet: number, win: number }> = {};
    gameHistory.forEach(g => {
        if (!stats[g.game]) stats[g.game] = { bet: 0, win: 0 };
        stats[g.game].bet += g.amount;
        stats[g.game].win += g.win;
    });
    return Object.entries(stats).map(([name, data]) => ({ name, bet: data.bet, win: data.win, profit: data.win - data.bet }));
};

// WIN PROBABILITY CONTROL
export const shouldForceLoss = (bet: number, balance: number) => {
    return Math.random() > 0.33; 
};

// GLOBAL GAME ENGINES (Shared via Firebase)
export const startGlobalEngines = () => {
  const manageWinGo = () => {
      const stateRef = ref(db, 'gameStates/wingo');
      onValue(stateRef, (snapshot) => {
          if (!snapshot.exists()) {
              set(stateRef, { timeLeft: 30, period: 202511261000, status: 'BETTING' });
          }
      });

      setInterval(async () => {
          const snap = await get(stateRef);
          if (!snap.exists()) return;
          let data = snap.val();
          data.timeLeft -= 1;

          if (data.timeLeft <= 0) {
              const num = Math.floor(Math.random() * 10);
              let color: 'Red'|'Green'|'Violet' = 'Red';
              if (num === 0 || num === 5) color = 'Violet';
              else if ([1,3,7,9].includes(num)) color = 'Green';

              const res = { period: data.period.toString(), number: num, bigSmall: num >= 5 ? 'Big' : 'Small', color };
              const historyRef = ref(db, 'gameStates/wingo/history');
              const historySnap = await get(historyRef);
              const history = historySnap.exists() ? Object.values(historySnap.val()) : [];

              await set(stateRef, {
                  timeLeft: 30,
                  period: data.period + 1,
                  status: 'BETTING',
                  lastResult: res,
                  history: [res, ...history].slice(0, 50)
              });
          } else {
              await update(stateRef, { timeLeft: data.timeLeft });
          }
      }, 1000);
  };

  const engineLock = ref(db, 'engine_lock');
  get(engineLock).then(snap => {
      if (!snap.exists()) {
          set(engineLock, Date.now());
          onDisconnect(engineLock).remove();
          manageWinGo();
      }
  });
};

export const subscribeToWinGo = (cb: (state: WinGoGameState) => void) => {
    return onValue(ref(db, 'gameStates/wingo'), (snap) => {
        if (snap.exists()) cb(snap.val());
    });
};

export const subscribeToAviator = (cb: (state: AviatorState) => void) => {
    let state: AviatorState = { phase: 'WAITING', multiplier: 1.0, timeLeft: 10, history: [], crashPoint: 0 };
    setInterval(() => {
        if (state.phase === 'WAITING') {
            state.timeLeft -= 1;
            if (state.timeLeft <= 0) {
                state.phase = 'FLYING'; state.multiplier = 1.0; state.startTime = Date.now();
                const r = Math.random();
                if (r < 0.35) state.crashPoint = 1.01 + Math.random() * 0.27;
                else if (r < 0.70) state.crashPoint = 1.28 + Math.random() * 0.72;
                else state.crashPoint = 2.00 + Math.random() * 10.00;
            }
        } else if (state.phase === 'FLYING') {
            const elapsed = (Date.now() - (state.startTime || Date.now())) / 1000;
            state.multiplier = 1 + (elapsed * 0.08) + (Math.pow(elapsed, 2) * 0.015);
            if (state.multiplier >= state.crashPoint) {
                state.phase = 'CRASHED'; state.multiplier = state.crashPoint;
                state.history = [state.crashPoint, ...state.history].slice(0, 15);
                setTimeout(() => { state.phase = 'WAITING'; state.timeLeft = 10; state.multiplier = 1.0; }, 3000);
            }
        }
        cb({ ...state });
    }, 100);
    return () => {};
};

export const subscribeToDragonTiger = (cb: (state: DragonTigerState) => void) => {
    let state: DragonTigerState = { status: 'BETTING', timeLeft: 15, period: '20251128001', dragonCard: null, tigerCard: null, history: [] };
    setInterval(() => {
        state.timeLeft -= 1;
        if (state.timeLeft <= 0) {
            if (state.status === 'BETTING') { state.status = 'LOCKED'; state.timeLeft = 3; }
            else if (state.status === 'LOCKED') {
                state.status = 'RESULT';
                state.dragonCard = Math.floor(Math.random() * 13) + 1;
                state.tigerCard = Math.floor(Math.random() * 13) + 1;
                const res: "D" | "T" | "Tie" = state.dragonCard > state.tigerCard ? 'D' : state.tigerCard > state.dragonCard ? 'T' : 'Tie';
                state.history = [res, ...state.history].slice(0, 20);
                state.timeLeft = 5;
            } else {
                state.status = 'BETTING'; state.timeLeft = 15;
                state.period = (parseInt(state.period) + 1).toString();
                state.dragonCard = null; state.tigerCard = null;
            }
        }
        cb({ ...state });
    }, 1000);
    return () => {};
};

initSession();

