// Initialize Realtime Database and get a reference to the service
// Regional databases (like europe-west1) MUST have the URL explicitly passed here
const db = getDatabase(app, firebaseConfig.databaseURL);

// AUDIO SYSTEM
let isMuted = false;
const sounds = {
