export const login = async (phone: string, pass: string) => {
    const snapshot = await get(ref(db, 'users'));
    if (!snapshot.exists()) return { success: false, message: 'User not found' };

    const users = snapshot.val();
    const userEntry = Object.entries(users).find(([uid, u]: [string, any]) => u.phone === phone && u.password === pass);

    if (userEntry) {
        const [uid, userData] = userEntry;
        localStorage.setItem('MAFIA_UID', uid);
        currentUser = sanitizeUser(userData);
        initSession();
        return { success: true };
