};

export const joinTelegramReward = async () => {
    if (!currentUser || currentUser.isTelegramJoined) return { success: false };
    const users = getLocalUsers();
    users[currentUser.uid].isTelegramJoined = true;
    saveLocalUsers(users);
    currentUser = sanitizeUser(users[currentUser.uid]);
    await updateBalance(5, 'GIFT', 'Telegram Reward');
    return { success: true };
};

export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser || currentUser.usedGiftCodes?.includes(code)) return 0;
    let amount = 0;
    if (code === 'MAFIA100') amount = 100;
    if (code === 'ff') amount = 1000;

    if (amount > 0) {
        const users = getLocalUsers();
        const used = [...(currentUser.usedGiftCodes || []), code];
        users[currentUser.uid].usedGiftCodes = used;
        users[currentUser.uid].wagerRequired = (users[currentUser.uid].wagerRequired || 0) + (amount * 6.8);
        saveLocalUsers(users);
        currentUser = sanitizeUser(users[currentUser.uid]);
        await updateBalance(amount, 'GIFT', `Gift Code: ${code}`);
        return amount;
    }
    return 0;
};

// DEPOSIT / WITHDRAW HANDLING
export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    const uid = currentUser.uid;
    const txs = JSON.parse(localStorage.getItem(DB_KEYS.TX + uid) || '[]');
    const newTx = {
        id: 'D_' + Date.now(),
        type: 'DEPOSIT',
        amount,
        status: 'PROCESSING',
        date: new Date().toLocaleString(),
        desc: `Deposit via ${method}`,
        utr,
        method,
        timestamp: Date.now()
    };
    txs.push(newTx);
    localStorage.setItem(DB_KEYS.TX + uid, JSON.stringify(txs));
    transactions = [...txs].reverse();
    notifySubscribers();

    // Auto-approve deposit for mock/local version after 10 seconds
    setTimeout(() => approveTransaction(newTx.id), 10000);
};

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const uid = currentUser.uid;
    const txs = JSON.parse(localStorage.getItem(DB_KEYS.TX + uid) || '[]');
    const tx = txs.find((t: any) => t.id === txId);
    if (!tx || tx.status !== 'PROCESSING') return;

    tx.status = 'SUCCESS';
    localStorage.setItem(DB_KEYS.TX + uid, JSON.stringify(txs));
    transactions = [...txs].reverse();

    if (tx.type === 'DEPOSIT') {
        const users = getLocalUsers();
        const user = users[uid];
        const bonus = user.totalDeposit === 0 ? tx.amount * 0.25 : 0;
        const totalAdd = tx.amount + bonus;

        user.balance += totalAdd;
        user.totalDeposit = (user.totalDeposit || 0) + tx.amount;
        user.wagerRequired = (user.wagerRequired || 0) + (totalAdd * 1);

        saveLocalUsers(users);
        currentUser = sanitizeUser(user);

        if (bonus > 0) {
            const bTx = { id: 'B_'+Date.now(), type: 'BONUS', amount: bonus, status: 'SUCCESS', date: new Date().toLocaleString(), desc: 'First Deposit Bonus' };
            txs.push(bTx);
