export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const uid = currentUser.uid;
    const txRef = ref(db, `transactions/${uid}/${txId}`);
    const snap = await get(txRef);
    if (!snap.exists() || snap.val().status !== 'PROCESSING') return;

    const tx = snap.val();
    await update(txRef, { status: 'SUCCESS' });

    if (tx.type === 'DEPOSIT') {
        const userRef = ref(db, `users/${uid}`);
        const userSnap = await get(userRef);
        const user = userSnap.val();

        const bonus = (user.totalDeposit || 0) === 0 ? tx.amount * 0.25 : 0;
        const totalAdd = tx.amount + bonus;

        await update(userRef, {
            balance: (user.balance || 0) + totalAdd,
            totalDeposit: (user.totalDeposit || 0) + tx.amount,
            wagerRequired: (user.wagerRequired || 0) + (totalAdd * 1)
        });

