// AUTH
export const login = async (phone: string, pass: string) => {
    try {
        const snapshot = await get(ref(db, 'users'));
        if (!snapshot.exists()) return { success: false, message: 'No accounts found' };

        const users = snapshot.val();
        const userEntry = Object.entries(users).find(([_, u]: [string, any]) => u.phone === phone && u.password === pass);

        if (userEntry) {
            const [uid, userData] = userEntry;
            localStorage.setItem('MAFIA_SESSION_UID', uid);
            currentUser = sanitizeUser(userData);
            initSession();
            return { success: true };
        }
        return { success: false, message: 'Invalid credentials' };
    } catch (e) { return { success: false, message: 'Database Error' }; }
};

