// CASHIER
export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    const txRef = push(ref(db, `transactions/${currentUser.uid}`));
    const txId = txRef.key;
    await set(txRef, {
        id: txId, type: 'DEPOSIT', amount, status: 'PROCESSING',
        date: new Date().toLocaleString(), desc: `Deposit: ${method}`, utr, method, timestamp: Date.now()
    });
    // Auto-approve after 8 seconds for demo/mock purpose
    setTimeout(() => approveTransaction(txId!), 8000);
};

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const uid = currentUser.uid;
    const txRef = ref(db, `transactions/${uid}/${txId}`);
    const snap = await get(txRef);
    if (!snap.exists() || snap.val().status !== 'PROCESSING') return;

    const tx = snap.val();
    await update(txRef, { status: 'SUCCESS' });

    if (tx.type === 'DEPOSIT') {
        const userRef = ref(db, `users/${uid}`);
        const userSnap = await get(userRef);
        const user = userSnap.val();
        const bonus = (user.totalDeposit || 0) === 0 ? tx.amount * 0.25 : 0;

        await update(userRef, {
            balance: (user.balance || 0) + tx.amount + bonus,
            totalDeposit: (user.totalDeposit || 0) + tx.amount,
            wagerRequired: (user.wagerRequired || 0) + (tx.amount * 1)
        });
        if (bonus > 0) await updateBalance(bonus, 'BONUS', 'First Deposit Bonus');
        playSound('win');
    }
};

export const handleWithdraw = async (amount: number, method: string, pin: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Auth Required' };
    if (currentUser.withdrawalPassword !== pin) return { success: false, message: 'Invalid PIN' };
    if (currentUser.balance < amount) return { success: false, message: 'Low Balance' };
    if (currentUser.wagerRequired > 0) return { success: false, message: 'Turnover Incomplete' };

    await updateBalance(-amount, 'WITHDRAW', `Payout: ${method}`);
    return { success: true };
};

