// Map DB profile to UserProfile to fix id/uid mismatch
const mapProfile = (profile: any): UserProfile => ({
    ...profile,
    uid: profile.id, // Map database 'id' to 'uid' as required by UserProfile interface
    totalDeposit: profile.total_deposit || 0,
    totalBet: profile.total_bet || 0,
    inviteCode: profile.invite_code || '',
    wagerRequired: profile.wager_required || 0,
    isBankBound: profile.is_bank_bound || false,
    isUpiBound: profile.is_upi_bound || false,
    isTelegramJoined: profile.is_telegram_joined || false,
    bankDetails: profile.bank_details || null,
    upiDetails: profile.upi_details || null
});

// INITIALIZATION
const initSession = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user) {
        // Fetch custom user profile
        const { data: profile } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', session.user.id)
            .single();

        if (profile) {
            currentUser = mapProfile(profile);
            notifySubscribers();
            // Subscribe to real-time changes on the profile
            supabase
                .channel('profile_changes')
                .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'profiles', filter: `id=eq.${session.user.id}` }, payload => {
                    currentUser = mapProfile(payload.new);
                    notifySubscribers();
                })
                .subscribe();
        }
    }
};

