// INITIALIZATION
const initSession = async () => {
    const savedUid = localStorage.getItem('MAFIA_SESSION_UID');
    if (savedUid) {
        const { data: profile, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', savedUid)
            .maybeSingle();

        if (profile) {
            currentUser = mapProfile(profile);
            /* Calculate initial referral stats on session start */
            calculateReferralStats(currentUser.inviteCode);
            notifySubscribers();
            // Subscribe to real-time changes
            supabase
                .channel(`profile_${savedUid}`)
                .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'profiles', filter: `id=eq.${savedUid}` }, payload => {
                    currentUser = mapProfile(payload.new);
                    notifySubscribers();
                })
                .subscribe();
        } else {
            localStorage.removeItem('MAFIA_SESSION_UID');
        }
    }
};

