export const login = async (phone: string, email: string, pass: string) => {
    const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('phone', phone)
        .eq('email', email)
        .eq('password', pass)
        .maybeSingle();

    if (data) {
        currentUser = mapProfile(data);
        localStorage.setItem('MAFIA_SESSION_UID', data.id);
        /* Calculate referral stats after login */
        calculateReferralStats(currentUser.inviteCode);
        notifySubscribers();
        return { success: true };
    }
    return { success: false, message: 'Invalid Credentials (Check Phone, Email, or Password)' };
};

export const register = async (phone: string, email: string, pass: string, inviteCode: string, username: string) => {
    // Check if user exists
    const { data: existing } = await supabase.from('profiles').select('id').or(`phone.eq.${phone},email.eq.${email}`).maybeSingle();
    if (existing) return { success: false, message: 'Phone or Email already registered' };

    const invite_code = Math.floor(10000000 + Math.random() * 90000000).toString();
    const { data, error } = await supabase
        .from('profiles')
        .insert([{
            phone, email, password: pass, username, name: username, 
            invite_code, invited_by: inviteCode, balance: 0, wager_required: 0, vip_level: 0
        }])
        .select()
        .single();

    if (data) {
        currentUser = mapProfile(data);
        localStorage.setItem('MAFIA_SESSION_UID', data.id);
        notifySubscribers();
        return { success: true };
    }
    return { success: false, message: error?.message || 'Registration Failed' };
};

