export const getGameHistory = (gameName: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) return () => {};
    const query = supabase.from('game_history').select('*').eq('user_id', currentUser.uid).order('created_at', { ascending: false });
    if (gameName !== 'ALL') query.eq('game', gameName);
    query.then(({ data }) => cb(data?.map(item => ({
        id: item.id,
        game: item.game,
        amount: item.amount,
        win: item.win,
        date: new Date(item.created_at).toLocaleString(),
        details: item.details
    })) || []));
    return () => {};
};

